"""SNN-Transform / MSDL final cloud snapshot through P3-D.

Single-file, checkpoint-free scientific reproduction of the accepted cloud path:
  - resident linear-attention computation (H, g)
  - continuous local MSDL plasticity for WQ/WK/WV/WO/W1/W2/WR
  - continuously adaptive reciprocal populations BR/BO/B2
  - P3 scalable Q/K/V credit via resident sufficient states
  - continual A->B->C->A learning and autonomous generation
  - fixed-D sequence-length scaling and joint N/D scaling

The file contains frozen source snapshots internally and writes them only into a
TemporaryDirectory at runtime. It does not read project source, checkpoints,
calibration files, or saved learned weights.
"""
from __future__ import annotations

import argparse
import csv
import importlib
import json
import math
import os
