_EMBEDDED_FILES = {
    'SNN_TRANSFORM_P2E_FROM_ZERO_20261015.py': '#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\nfrom __future__ import annotations\n\nimport argparse\nimport copy\nimport csv\nimport importlib\nimport json\nimport math\nimport os\nfrom pathlib import Path\nimport sys\nimport tempfile\nimport time\nimport types\n\nimport numpy as np\nimport torch\n\n# This is a single-file snapshot of the implemented path through P2-E.\n# It creates its internal modules in a temporary directory at runtime; it does\n# not read checkpoints, calibration files, or project source files.\n\n_EMBEDDED = {}\n\n# ========================= p1a_msdl_token_generation.py =========================\n_EMBEDDED[\'p1a_msdl_token_generation\'] = r\'\'\'#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n"""P1-A: MSDL-trained categorical readout on a frozen SNN-Transform core.\n\nScientific scope\n----------------\nThis is the first generative interface gate after P0-E.\n\n- The SNN-Transform feature core is frozen.\n- Only the categorical token readout is plastic.\n- Candidate learning uses the frozen MSDL E/M Izhikevich population dynamics\n  and the directed local synaptic update dW ~ M_post E_pre^T.\n- No candidate autograd/backpropagation/BPTT is used.\n- A gradient-trained readout on the *same frozen features* is used only as an\n  attainable-performance reference.\n- Autonomous generation starts from an all-MASK sequence and feeds only sampled\n  model tokens back as explicit changed-token events.\n\nThis gate does NOT establish internal SNN-Transform credit assignment. That is\nreserved for P1-B/P1-C.\n"""\nfrom __future__ import annotations\n\nimport json\nimport math\nfrom collections import defaultdict, Counter\nfrom dataclasses import dataclass\nfrom pathlib import Path\nfrom typing import Dict, List, Optional, Sequence, Tuple\n\nimport numpy as np\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\nfrom numba import njit\n\n# -----------------------------------------------------------------------------\n# Reproducibility / task constants\n# -----------------------------------------------------------------------------\nV = 8\nN = 8\nMASK = V\nD = 24\nHEADS = 2\nFEATURES = 24\nFF = 48\nCORE_SEED = 17\nEMBED_SEED = 99\nTORCH_INIT_SEED = 1729\nOUT_DENSITY = 0.25\nFF1_DENSITY = 0.25\nFF2_DENSITY = 0.25\n\n# Frozen MSDL fast E/M dynamics from P0-E / current MSDL scientific core.\nFORCE_DT_MS = 80.0\nAF, AS = 0.62, 0.92\nWF, WS = 0.70, 0.30\nTAU_F_MS = -FORCE_DT_MS / math.log(AF)\nTAU_S_MS = -FORCE_DT_MS / math.log(AS)\nRF, RS = 1.0 / TAU_F_MS, 1.0 / TAU_S_MS\nA_IZH = 1e-3\nS_IZH = -(RF + RS)\nP_IZH = RF * RS\nQ_IZH = S_IZH + A_IZH\nB_IZH = Q_IZH + P_IZH / A_IZH\nV0 = (Q_IZH - 5.0) / 0.08\nU0 = B_IZH * V0\nI0 = -0.04 * V0 * V0 - 5.0 * V0 - 140.0 + U0\nNUM_S = WF * RF + WS * RS\nNUM_0 = RF * RS\nG_E = 1e-5\nG_M = 1e-6\nN_SUB = 80\nFORCE_STEPS = 27\n\n# P1-A development configuration. LR is selected by a separate dev sweep below;\n# final evaluation seeds do not participate in selection.\nDEV_SEED = 19\nLR_CANDIDATES = [0.4, 0.5, 0.6, 0.7, 0.8]\nDEV_PATHS = 12000\nFINAL_PATHS = 12000\nFINAL_SEEDS = [101, 211, 307, 401, 503]\nN_GENERATE = 20000\nGEN_BATCH = 5000\n\n# Gate thresholds are frozen after the gradient-reference difficulty curve and\n# before inspecting FINAL_SEEDS. P1-A is explicitly an interface sanity gate,\n# not the final internal-learning gate.\nGATE_THRESHOLDS = {\n    "candidate_nll_lt": 0.90,\n    "candidate_cond_js_lt": 0.08,\n    "candidate_token_support_gt": 0.94,\n    "candidate_generation_valid_gt": 0.60,\n    "candidate_vs_random_nll_fraction_lt": 0.50,\n    "candidate_nll_gap_to_gradient_lt": 0.25,\n    "gradient_long_range_mae_lt": 0.05,\n    "candidate_long_range_mae_lt": 0.20,\n    "candidate_generation_long_range_mae_lt": 0.20,\n    "all_true_modes_observed_fraction_gt": 0.95,\n    "m_off_nll_gt": 2.0,\n    "fresh_vs_persistent_max_abs_lt": 2e-6,\n}\n\n\ndef readout_coeff(gain: float) -> Tuple[float, float]:\n    cv = NUM_S / gain\n    cu = (NUM_0 / gain - cv * A_IZH) / (A_IZH * B_IZH)\n    return cv, cu\n\n\nCV_E, CU_E = readout_coeff(G_E)\nCV_M, CU_M = readout_coeff(G_M)\n\n\n# -----------------------------------------------------------------------------\n# Frozen SNN-Transform v1 mathematical core (PositiveRF path)\n# -----------------------------------------------------------------------------\n@dataclass\nclass State:\n    H: torch.Tensor\n    g: torch.Tensor\n    pk: torch.Tensor\n    v: torch.Tensor\n    pq: torch.Tensor\n\n\nclass PositiveRF(nn.Module):\n    def __init__(self, heads: int, head_dim: int, features: int, seed: int):\n        super().__init__()\n        self.heads = int(heads)\n        self.head_dim = int(head_dim)\n        self.features = int(features)\n        gen = torch.Generator(device="cpu")\n        gen.manual_seed(int(seed))\n        omega = torch.randn(self.heads, self.features, self.head_dim, generator=gen)\n        omega = omega / omega.norm(dim=-1, keepdim=True).clamp_min(1e-8)\n        omega = omega * math.sqrt(self.head_dim)\n        self.register_buffer("omega", omega)\n\n    def forward(self, x: torch.Tensor, *, is_query: bool) -> torch.Tensor:\n        xx = x * (self.head_dim ** -0.25)\n        dash = torch.einsum("bhnd,hmd->bhnm", xx, self.omega)\n        diag = 0.5 * (xx * xx).sum(-1, keepdim=True)\n        a = dash - diag\n        if is_query:\n            a = (a - a.amax(-1, keepdim=True).detach()).clamp(-30.0, 0.0)\n        else:\n            a = a.clamp(-30.0, 30.0)\n        return torch.exp(a) * (self.features ** -0.5) + 1e-6\n\n\nclass SparseLinear(nn.Module):\n    def __init__(self, inp: int, out: int, density: float, seed: int, bias: bool = True):\n        super().__init__()\n        self.weight = nn.Parameter(torch.empty(out, inp), requires_grad=False)\n        self.bias = nn.Parameter(torch.zeros(out), requires_grad=False) if bias else None\n        k = max(1, min(inp, int(round(float(density) * inp))))\n        gen = torch.Generator(device="cpu")\n        gen.manual_seed(int(seed))\n        mask = torch.zeros(out, inp)\n        for o in range(out):\n            idx = torch.randperm(inp, generator=gen)[:k]\n            mask[o, idx] = 1.0\n        self.register_buffer("mask", mask)\n        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5.0))\n        if self.bias is not None:\n            bound = 1.0 / math.sqrt(inp)\n            nn.init.uniform_(self.bias, -bound, bound)\n\n    def forward(self, x: torch.Tensor) -> torch.Tensor:\n        return F.linear(x, self.weight * self.mask, self.bias)\n\n\nclass FrozenSNNTransformBlock(nn.Module):\n    """Minimal frozen v1 operator graph required by P1-A.\n\n    This preserves the accepted v1 equations: Pre-LN, Q/K/V, PositiveRF,\n    persistent H/g, sparse output projection, residual, sparse FFN, residual.\n    P1-A intentionally uses the exact PositiveRF reference interface rather than\n    introducing a second Izh calibration variable into the first learning gate.\n    """\n\n    def __init__(self):\n        super().__init__()\n        if D % HEADS:\n            raise ValueError("D must be divisible by HEADS")\n        self.hd = D // HEADS\n        self.n1 = nn.LayerNorm(D)\n        self.q = nn.Linear(D, D)\n        self.k = nn.Linear(D, D)\n        self.v = nn.Linear(D, D)\n        self.phi_q = PositiveRF(HEADS, self.hd, FEATURES, CORE_SEED)\n        self.phi_k = PositiveRF(HEADS, self.hd, FEATURES, CORE_SEED)\n        self.out = SparseLinear(D, D, OUT_DENSITY, CORE_SEED + 101)\n        self.n2 = nn.LayerNorm(D)\n        self.f1 = SparseLinear(D, FF, FF1_DENSITY, CORE_SEED + 201)\n        self.f2 = SparseLinear(FF, D, FF2_DENSITY, CORE_SEED + 301)\n        self.theta = nn.Parameter(torch.zeros(FF), requires_grad=False)\n        for mod in (self.n1, self.q, self.k, self.v, self.n2):\n            for p in mod.parameters():\n                p.requires_grad_(False)\n\n    def _split(self, x: torch.Tensor) -> torch.Tensor:\n        B, NN, _ = x.shape\n        return x.reshape(B, NN, HEADS, self.hd).transpose(1, 2)\n\n    @torch.no_grad()\n    def step(\n        self,\n        x: torch.Tensor,\n        state: Optional[State],\n        changed: Optional[torch.Tensor] = None,\n    ) -> Tuple[torch.Tensor, State]:\n        B, NN, _ = x.shape\n        xn = self.n1(x)\n        if state is None:\n            q = self._split(self.q(xn))\n            k = self._split(self.k(xn))\n            value = self._split(self.v(xn))\n            pq = self.phi_q(q, is_query=True)\n            pk = self.phi_k(k, is_query=False)\n            H = torch.einsum("bhnm,bhnd->bhmd", pk, value)\n            g = pk.sum(dim=2)\n        else:\n            if changed is None:\n                raise ValueError("explicit changed mask required in persistent P1-A execution")\n            pq = state.pq.clone()\n            pk = state.pk.clone()\n            value = state.v.clone()\n            H = state.H.clone()\n            g = state.g.clone()\n            for b in range(B):\n                idx = torch.nonzero(changed[b], as_tuple=False).flatten()\n                if idx.numel() == 0:\n                    continue\n                xb = xn[b:b+1, idx]\n                new_pq = self.phi_q(self._split(self.q(xb)), is_query=True)\n                new_k = self._split(self.k(xb))\n                new_v = self._split(self.v(xb))\n                new_pk = self.phi_k(new_k, is_query=False)\n                old_pk = state.pk[b:b+1, :, idx, :]\n                old_v = state.v[b:b+1, :, idx, :]\n                H = H - torch.einsum("bhnm,bhnd->bhmd", old_pk, old_v)\n                H = H + torch.einsum("bhnm,bhnd->bhmd", new_pk, new_v)\n                g = g - old_pk.sum(dim=2) + new_pk.sum(dim=2)\n                pq[b, :, idx, :] = new_pq[0]\n                pk[b, :, idx, :] = new_pk[0]\n                value[b, :, idx, :] = new_v[0]\n\n        num = torch.einsum("bhnm,bhmd->bhnd", pq, H)\n        den = torch.einsum("bhnm,bhm->bhn", pq, g).unsqueeze(-1).clamp_min(1e-8)\n        attended = num / den\n        z = x + self.out(attended.transpose(1, 2).reshape(B, NN, D))\n        hidden = F.relu(self.f1(self.n2(z)) - self.theta)\n        y = z + self.f2(hidden)\n        return y, State(H=H, g=g, pk=pk, v=value, pq=pq)\n\n\n    @torch.no_grad()\n    def step_single_position(\n        self,\n        x: torch.Tensor,\n        state: State,\n        position: int,\n    ) -> Tuple[torch.Tensor, State]:\n        """Vectorized exact specialization when one token position changes in every batch item.\n\n        It is algebraically identical to ``step(..., changed[:,position]=True)`` but\n        avoids the Python per-batch loop in the generic engineering reference.\n        """\n        B, NN, _ = x.shape\n        xn = self.n1(x)\n        idx = int(position)\n        xb = xn[:, idx:idx+1, :]\n        new_pq = self.phi_q(self._split(self.q(xb)), is_query=True)\n        new_k = self._split(self.k(xb))\n        new_v = self._split(self.v(xb))\n        new_pk = self.phi_k(new_k, is_query=False)\n\n        old_pk = state.pk[:, :, idx:idx+1, :]\n        old_v = state.v[:, :, idx:idx+1, :]\n        H = state.H - torch.einsum("bhnm,bhnd->bhmd", old_pk, old_v)\n        H = H + torch.einsum("bhnm,bhnd->bhmd", new_pk, new_v)\n        g = state.g - old_pk.sum(dim=2) + new_pk.sum(dim=2)\n\n        pq = state.pq.clone(); pk = state.pk.clone(); value = state.v.clone()\n        pq[:, :, idx:idx+1, :] = new_pq\n        pk[:, :, idx:idx+1, :] = new_pk\n        value[:, :, idx:idx+1, :] = new_v\n\n        num = torch.einsum("bhnm,bhmd->bhnd", pq, H)\n        den = torch.einsum("bhnm,bhm->bhn", pq, g).unsqueeze(-1).clamp_min(1e-8)\n        attended = num / den\n        z = x + self.out(attended.transpose(1, 2).reshape(B, NN, D))\n        hidden = F.relu(self.f1(self.n2(z)) - self.theta)\n        y = z + self.f2(hidden)\n        return y, State(H=H, g=g, pk=pk, v=value, pq=pq)\n\n\n# -----------------------------------------------------------------------------\n# Synthetic stochastic grammar with exact probability\n# -----------------------------------------------------------------------------\ndef enumerate_true_distribution() -> List[Tuple[Tuple[int, ...], float]]:\n    """Enumerate all 256 true sequences.\n\n    Position 0 carries a 2-state latent context. Positions 1..7 are stochastic\n    binary branches with nonzero probabilities. Two late branches depend on\n    non-adjacent earlier branches, creating long-range conditional structure.\n    """\n    dd: Dict[Tuple[int, ...], float] = defaultdict(float)\n    for m, pm in ((0, 0.45), (1, 0.55)):\n        for bits in __import__("itertools").product((0, 1), repeat=7):\n            b1, b2, b3, b4, b5, b6, b7 = bits\n            ps = [\n                0.20 if m == 0 else 0.75,      # x1 depends on mode\n                0.65 if m == 0 else 0.35,      # x2 depends on mode\n                0.20 + 0.60 * b1,              # x3 depends on x1\n                0.20 + 0.60 * b2,              # x4 depends on x2\n                0.25 + 0.50 * m,               # x5 long-range mode dependence\n                0.20 + 0.60 * b1,              # x6 long-range dependence on x1\n                0.20 + 0.60 * b3,              # x7 long-range dependence on x3\n            ]\n            p = pm\n            for b, pr in zip(bits, ps):\n                p *= pr if b else (1.0 - pr)\n            seq = (\n                m,\n                3 if b1 else 2,\n                5 if b2 else 4,\n                7 if b3 else 6,\n                3 if b4 else 2,\n                5 if b5 else 4,\n                7 if b6 else 6,\n                3 if b7 else 2,\n            )\n            dd[seq] += p\n    items = sorted(dd.items())\n    total = sum(p for _, p in items)\n    if abs(total - 1.0) > 1e-12 or len(items) != 256:\n        raise AssertionError((len(items), total))\n    return items\n\n\ndef build_embeddings() -> Tuple[torch.Tensor, torch.Tensor]:\n    rng = np.random.default_rng(EMBED_SEED)\n    tok = rng.normal(size=(V + 1, D))\n    tok = tok / np.linalg.norm(tok, axis=1, keepdims=True) * math.sqrt(D) * 0.70\n    pos = rng.normal(size=(N, D))\n    pos = pos / np.linalg.norm(pos, axis=1, keepdims=True) * math.sqrt(D) * 0.35\n    return torch.tensor(tok, dtype=torch.float32), torch.tensor(pos, dtype=torch.float32)\n\n\ndef encode(arr: np.ndarray, tok: torch.Tensor, pos: torch.Tensor) -> torch.Tensor:\n    idx = torch.as_tensor(arr, dtype=torch.long)\n    return tok[idx] + pos.unsqueeze(0)\n\n\ndef normalize_readout_feature(f: torch.Tensor) -> torch.Tensor:\n    # Fixed local RMS normalization; no learned/readout-dependent parameters.\n    return f / (f.square().mean(dim=-1, keepdim=True).sqrt() + 1e-8) * 0.5\n\n\ndef build_exact_prefix_dataset(\n    block: FrozenSNNTransformBlock,\n    tok: torch.Tensor,\n    pos: torch.Tensor,\n    true_dist: Sequence[Tuple[Tuple[int, ...], float]],\n):\n    counts: Dict[Tuple[int, Tuple[int, ...]], np.ndarray] = defaultdict(lambda: np.zeros(V, dtype=np.float64))\n    mass: Dict[Tuple[int, Tuple[int, ...]], float] = defaultdict(float)\n    for seq, p in true_dist:\n        for t in range(N):\n            key = (t, seq[:t])\n            counts[key][seq[t]] += p\n            mass[key] += p\n\n    keys = list(counts.keys())\n    arrays = np.full((len(keys), N), MASK, dtype=np.int64)\n    targets = np.zeros((len(keys), V), dtype=np.float64)\n    weights = np.zeros(len(keys), dtype=np.float64)\n    target_pos = np.zeros(len(keys), dtype=np.int64)\n    for i, key in enumerate(keys):\n        t, prefix = key\n        arrays[i, :t] = prefix\n        targets[i] = counts[key] / mass[key]\n        weights[i] = mass[key] / N\n        target_pos[i] = t\n\n    with torch.no_grad():\n        x = encode(arrays, tok, pos)\n        y, _ = block.step(x, None)\n        f = y[torch.arange(len(keys)), torch.as_tensor(target_pos)]\n        f = normalize_readout_feature(f)\n        f = torch.cat([f, torch.full((len(keys), 1), 0.5)], dim=1)\n\n    if abs(weights.sum() - 1.0) > 1e-12:\n        raise AssertionError(weights.sum())\n    return keys, arrays, f.cpu().numpy().astype(np.float64), targets, weights\n\n\n# -----------------------------------------------------------------------------\n# MSDL E/M dynamics and directed local readout learning\n# -----------------------------------------------------------------------------\n@njit(cache=False)\ndef fast_izh_step(v, u, target_input, pred_input, gain, cv, cu):\n    spikes = 0\n    for _ in range(N_SUB):\n        for j in range(v.shape[0]):\n            I = I0 + gain * target_input[j] - gain * pred_input[j]\n            dv1 = 0.04*v[j]*v[j] + 5.0*v[j] + 140.0 - u[j] + I\n            du1 = A_IZH * (B_IZH*v[j] - u[j])\n            vm = v[j] + 0.5*dv1\n            um = u[j] + 0.5*du1\n            dv2 = 0.04*vm*vm + 5.0*vm + 140.0 - um + I\n            du2 = A_IZH * (B_IZH*vm - um)\n            v[j] += dv2\n            u[j] += du2\n            if v[j] >= 30.0:\n                v[j] = -65.0\n                u[j] += 8.0\n                spikes += 1\n    out = np.empty(v.shape[0], dtype=np.float64)\n    for j in range(v.shape[0]):\n        out[j] = cv*(v[j]-V0) + cu*(u[j]-U0)\n    return out, spikes\n\n\n@njit(cache=False)\ndef softmax_numba(z):\n    mx = np.max(z)\n    e = np.exp(z - mx)\n    return e / np.sum(e)\n\n\n@njit(cache=False)\ndef sample_categorical_numba(p):\n    u = np.random.random()\n    c = 0.0\n    for i in range(p.shape[0]):\n        c += p[i]\n        if u <= c:\n            return i\n    return p.shape[0] - 1\n\n\n@njit(cache=False)\ndef train_msdl_readout(features, targets, masses, n_paths, lr, seed, m_off=False):\n    """Train only the V x (D+1) categorical readout.\n\n    Each MSDL path freezes W at path start, as in the existing Phase-I semantics.\n    Every force step samples a fresh prefix/target exposure. The output M drive\n    is local: onehot(target) - softmax(W0 @ feature). No hidden gradient exists.\n    """\n    np.random.seed(seed)\n    nctx, nin = features.shape\n    W = np.zeros((V, nin), dtype=np.float64)\n    ve = np.full(nin, V0, dtype=np.float64)\n    ue = np.full(nin, U0, dtype=np.float64)\n    vm = np.full(V, V0, dtype=np.float64)\n    um = np.full(V, U0, dtype=np.float64)\n    cdf = np.cumsum(masses)\n    cdf[-1] = 1.0\n    spikes_e = 0\n    spikes_m = 0\n\n    for _p in range(n_paths):\n        W0 = W.copy()\n        accum = np.zeros_like(W)\n        for _k in range(FORCE_STEPS):\n            u = np.random.random()\n            ci = 0\n            while ci < nctx - 1 and u > cdf[ci]:\n                ci += 1\n            x = features[ci]\n            target = sample_categorical_numba(targets[ci])\n            probs = softmax_numba(W0 @ x)\n\n            zero_e = np.zeros(nin, dtype=np.float64)\n            E, sp_e = fast_izh_step(ve, ue, x, zero_e, G_E, CV_E, CU_E)\n            spikes_e += sp_e\n\n            if m_off:\n                M = np.zeros(V, dtype=np.float64)\n            else:\n                one = np.zeros(V, dtype=np.float64)\n                one[target] = 1.0\n                M, sp_m = fast_izh_step(vm, um, one, probs, G_M, CV_M, CU_M)\n                spikes_m += sp_m\n\n            accum += np.outer(M, E)\n\n        W += lr * accum / FORCE_STEPS\n\n    return W, spikes_e, spikes_m\n\n\n# -----------------------------------------------------------------------------\n# Evaluation / reference training\n# -----------------------------------------------------------------------------\ndef probs_from_W(W: np.ndarray, features: np.ndarray) -> np.ndarray:\n    z = features @ W.T\n    z = z - z.max(axis=1, keepdims=True)\n    e = np.exp(z)\n    return e / e.sum(axis=1, keepdims=True)\n\n\ndef expected_nll(P: np.ndarray, targets: np.ndarray, masses: np.ndarray) -> float:\n    return float(-(masses[:, None] * targets * np.log(P + 1e-30)).sum())\n\n\ndef conditional_js(P: np.ndarray, T: np.ndarray, masses: np.ndarray) -> float:\n    M = 0.5 * (P + T)\n    kl_t = np.sum(T * np.log((T + 1e-30) / (M + 1e-30)), axis=1)\n    kl_p = np.sum(P * np.log((P + 1e-30) / (M + 1e-30)), axis=1)\n    return float(np.sum(masses * 0.5 * (kl_t + kl_p)))\n\n\ndef true_conditional_entropy(T: np.ndarray, masses: np.ndarray) -> float:\n    return float(-(masses[:, None] * T * np.log(T + 1e-30)).sum())\n\n\ndef support_for_position(t: int) -> Tuple[int, ...]:\n    return ((0, 1), (2, 3), (4, 5), (6, 7), (2, 3), (4, 5), (6, 7), (2, 3))[t]\n\n\ndef expected_token_support(P: np.ndarray, keys, masses: np.ndarray) -> float:\n    out = 0.0\n    for i, (t, _) in enumerate(keys):\n        out += masses[i] * sum(P[i, v] for v in support_for_position(t))\n    return float(out)\n\n\ndef train_gradient_reference(features: np.ndarray, targets: np.ndarray, masses: np.ndarray):\n    F_t = torch.tensor(features, dtype=torch.float32)\n    T_t = torch.tensor(targets, dtype=torch.float32)\n    M_t = torch.tensor(masses, dtype=torch.float32)\n    W = torch.zeros(V, features.shape[1], dtype=torch.float32, requires_grad=True)\n    opt = torch.optim.LBFGS([W], lr=1.0, max_iter=700, line_search_fn="strong_wolfe")\n\n    def closure():\n        opt.zero_grad()\n        logp = F.log_softmax(F_t @ W.T, dim=1)\n        loss = -(M_t[:, None] * T_t * logp).sum()\n        loss.backward()\n        return loss\n\n    opt.step(closure)\n    return W.detach().cpu().numpy().astype(np.float64)\n\n\ndef sample_rows(probs: np.ndarray, rng: np.random.Generator) -> np.ndarray:\n    u = rng.random(probs.shape[0])\n    cs = np.cumsum(probs, axis=1)\n    return (u[:, None] > cs).sum(axis=1)\n\n\n@torch.no_grad()\ndef autonomous_generate(\n    block: FrozenSNNTransformBlock,\n    tok: torch.Tensor,\n    pos: torch.Tensor,\n    W: np.ndarray,\n    n_generate: int,\n    seed: int,\n    batch_size: int,\n) -> np.ndarray:\n    rng = np.random.default_rng(seed)\n    out_batches = []\n    Wt = torch.tensor(W, dtype=torch.float32)\n    for start in range(0, n_generate, batch_size):\n        B = min(batch_size, n_generate - start)\n        arr = np.full((B, N), MASK, dtype=np.int64)\n        x = encode(arr, tok, pos)\n        y, state = block.step(x, None)\n        for t in range(N):\n            feat = normalize_readout_feature(y[:, t, :])\n            feat = torch.cat([feat, torch.full((B, 1), 0.5)], dim=1)\n            probs = F.softmax(feat @ Wt.T, dim=1).cpu().numpy()\n            sampled = sample_rows(probs, rng)\n            arr[:, t] = sampled\n            if t < N - 1:\n                x[:, t, :] = tok[torch.as_tensor(sampled)] + pos[t]\n                y, state = block.step_single_position(x, state, t)\n        out_batches.append(arr)\n    return np.concatenate(out_batches, axis=0)\n\n\ndef empirical_js_with_invalid_bucket(samples: np.ndarray, true_dist) -> Tuple[float, float, float, int]:\n    true = dict(true_dist)\n    counter = Counter(map(tuple, samples.tolist()))\n    true_keys = list(true.keys())\n    p = np.array([true[s] for s in true_keys] + [0.0], dtype=np.float64)\n    q = np.array([counter.get(s, 0) / len(samples) for s in true_keys] + [0.0], dtype=np.float64)\n    invalid = 1.0 - q[:-1].sum()\n    q[-1] = max(0.0, invalid)\n    m = 0.5 * (p + q)\n    nzp = p > 0\n    nzq = q > 0\n    js = 0.5 * np.sum(p[nzp] * np.log(p[nzp] / m[nzp])) + 0.5 * np.sum(q[nzq] * np.log(q[nzq] / m[nzq]))\n    valid_fraction = float(1.0 - q[-1])\n    observed_true = int(sum(counter.get(s, 0) > 0 for s in true_keys))\n    mode_p0 = float(np.mean(samples[:, 0] == 0))\n    mode_tv = abs(mode_p0 - 0.45)\n    return float(js), valid_fraction, float(mode_tv), observed_true\n\n\ndef generated_support_rate(samples: np.ndarray) -> float:\n    ok = np.zeros_like(samples, dtype=bool)\n    for t in range(N):\n        ok[:, t] = np.isin(samples[:, t], support_for_position(t))\n    return float(ok.mean())\n\n\ndef long_range_branch_mae(samples: np.ndarray) -> float:\n    """Empirical error for three non-adjacent stochastic dependencies."""\n    errs = []\n    # x5 high token 5: P=0.75 for mode 1, 0.25 for mode 0.\n    for mode in (0, 1):\n        group = np.isin(samples[:, 0], (0, 1)) & (samples[:, 0] == mode) & np.isin(samples[:, 5], (4, 5))\n        if group.sum() > 20:\n            emp = float(np.mean(samples[group, 5] == 5))\n            errs.append(abs(emp - (0.75 if mode else 0.25)))\n    # x6 high token 7: P=0.8 if the distant x1 branch is high, else 0.2.\n    for b1 in (0, 1):\n        group = np.isin(samples[:, 1], (2, 3)) & ((samples[:, 1] == 3).astype(int) == b1) & np.isin(samples[:, 6], (6, 7))\n        if group.sum() > 20:\n            emp = float(np.mean(samples[group, 6] == 7))\n            errs.append(abs(emp - (0.8 if b1 else 0.2)))\n    # x7 high token 3: P=0.8 if the distant x3 branch is high, else 0.2.\n    for b3 in (0, 1):\n        group = np.isin(samples[:, 3], (6, 7)) & ((samples[:, 3] == 7).astype(int) == b3) & np.isin(samples[:, 7], (2, 3))\n        if group.sum() > 20:\n            emp = float(np.mean(samples[group, 7] == 3))\n            errs.append(abs(emp - (0.8 if b3 else 0.2)))\n    return float(np.mean(errs)) if errs else float("nan")\n\n\ndef exact_long_range_mae(P: np.ndarray, keys, masses: np.ndarray) -> float:\n    """Exact population-risk MAE of the same long-range conditional probabilities."""\n    specs = [\n        (5, 5, lambda pref: int(pref[0]), {0: 0.25, 1: 0.75}),\n        (6, 7, lambda pref: int(pref[1] == 3), {0: 0.20, 1: 0.80}),\n        (7, 3, lambda pref: int(pref[3] == 7), {0: 0.20, 1: 0.80}),\n    ]\n    errs = []\n    for t, high_token, cond_fn, target_map in specs:\n        for cond in (0, 1):\n            idx = [i for i, (tt, pref) in enumerate(keys) if tt == t and cond_fn(pref) == cond]\n            w = masses[idx].copy()\n            w /= w.sum()\n            pred = float(np.sum(w * P[idx, high_token]))\n            errs.append(abs(pred - target_map[cond]))\n    return float(np.mean(errs))\n\n\n\n@torch.no_grad()\ndef persistent_parity_check(block, tok, pos, true_dist, n_seq=8) -> float:\n    mx = 0.0\n    for seq, _ in true_dist[:n_seq]:\n        arr = np.full((1, N), MASK, dtype=np.int64)\n        x = encode(arr, tok, pos)\n        y_p, state = block.step(x, None)\n        for t in range(N):\n            # Compare current persistent state output with fresh recomputation.\n            y_f, _ = block.step(x, None)\n            mx = max(mx, float((y_f - y_p).abs().max().item()))\n            if t < N - 1:\n                arr[0, t] = seq[t]\n                x[:, t, :] = tok[seq[t]] + pos[t]\n                changed = torch.zeros(1, N, dtype=torch.bool)\n                changed[:, t] = True\n                y_p, state = block.step(x, state, changed)\n    return mx\n\n\ndef summarize(vals: Sequence[float]) -> Dict[str, float]:\n    a = np.asarray(vals, dtype=float)\n    return {"mean": float(a.mean()), "std": float(a.std()), "min": float(a.min()), "max": float(a.max())}\n\n\ndef evaluate_W(W, features, targets, masses, keys):\n    P = probs_from_W(W, features)\n    return {\n        "expected_nll": expected_nll(P, targets, masses),\n        "conditional_js": conditional_js(P, targets, masses),\n        "expected_token_support": expected_token_support(P, keys, masses),\n        "exact_long_range_branch_mae": exact_long_range_mae(P, keys, masses),\n    }\n\n\ndef main():\n    outdir = Path(__file__).resolve().parent\n    torch.set_num_threads(4)\n    torch.manual_seed(TORCH_INIT_SEED)\n    np.random.seed(123)\n\n    true_dist = enumerate_true_distribution()\n    tok, pos = build_embeddings()\n    block = FrozenSNNTransformBlock().eval()\n\n    keys, arrays, features, targets, masses = build_exact_prefix_dataset(block, tok, pos, true_dist)\n    entropy = true_conditional_entropy(targets, masses)\n    parity_max = persistent_parity_check(block, tok, pos, true_dist)\n\n    # References.\n    W_zero = np.zeros((V, features.shape[1]), dtype=np.float64)\n    random_metrics = evaluate_W(W_zero, features, targets, masses, keys)\n    W_grad = train_gradient_reference(features, targets, masses)\n    grad_metrics = evaluate_W(W_grad, features, targets, masses, keys)\n\n    # Development-only LR sweep, then freeze selected LR before final seeds.\n    dev = []\n    for lr in LR_CANDIDATES:\n        W_dev, sp_e, sp_m = train_msdl_readout(features, targets, masses, DEV_PATHS, lr, DEV_SEED, False)\n        met = evaluate_W(W_dev, features, targets, masses, keys)\n        dev.append({"lr": lr, **met, "E_spikes": int(sp_e), "M_spikes": int(sp_m)})\n    best = min(dev, key=lambda x: x["expected_nll"])\n    selected_lr = float(best["lr"])\n\n    # Final independent training seeds.\n    final_runs = []\n    saved_W = None\n    for ri, seed in enumerate(FINAL_SEEDS):\n        W, sp_e, sp_m = train_msdl_readout(features, targets, masses, FINAL_PATHS, selected_lr, seed, False)\n        met = evaluate_W(W, features, targets, masses, keys)\n        gen = autonomous_generate(block, tok, pos, W, N_GENERATE, 10000 + seed, GEN_BATCH)\n        js_joint, valid, mode_tv, observed = empirical_js_with_invalid_bucket(gen, true_dist)\n        met.update({\n            "seed": seed,\n            "E_spikes": int(sp_e),\n            "M_spikes": int(sp_m),\n            "generation_joint_js_with_invalid_bucket": js_joint,\n            "generation_valid_sequence_fraction": valid,\n            "generation_token_support_rate": generated_support_rate(gen),\n            "generation_mode_tv": mode_tv,\n            "generation_observed_true_sequences": observed,\n            "generation_true_mode_coverage_fraction": observed / len(true_dist),\n            "generation_long_range_branch_mae": long_range_branch_mae(gen),\n            "completion_rate": 1.0,\n        })\n        final_runs.append(met)\n        if ri == 0:\n            saved_W = W.copy()\n            np.savez_compressed(outdir / "P1A_GENERATED_EXAMPLE.npz", samples=gen[:2000], readout_W=W)\n\n    # M-off causal control; since M=0, W must remain exactly zero.\n    W_moff, se0, sm0 = train_msdl_readout(features, targets, masses, 300, selected_lr, 777, True)\n    moff_metrics = evaluate_W(W_moff, features, targets, masses, keys)\n    moff_metrics.update({\n        "max_abs_weight": float(np.max(np.abs(W_moff))),\n        "E_spikes": int(se0),\n        "M_spikes": int(sm0),\n    })\n\n    # Generate gradient reference and random baseline once for task difficulty context.\n    gen_grad = autonomous_generate(block, tok, pos, W_grad, N_GENERATE, 314159, GEN_BATCH)\n    gjs, gvalid, gmode, gobserved = empirical_js_with_invalid_bucket(gen_grad, true_dist)\n    grad_generation = {\n        "joint_js_with_invalid_bucket": gjs,\n        "valid_sequence_fraction": gvalid,\n        "token_support_rate": generated_support_rate(gen_grad),\n        "mode_tv": gmode,\n        "observed_true_sequences": gobserved,\n        "true_mode_coverage_fraction": gobserved / len(true_dist),\n        "long_range_branch_mae": long_range_branch_mae(gen_grad),\n    }\n    gen_zero = autonomous_generate(block, tok, pos, W_zero, N_GENERATE, 271828, GEN_BATCH)\n    zjs, zvalid, zmode, zobserved = empirical_js_with_invalid_bucket(gen_zero, true_dist)\n    random_generation = {\n        "joint_js_with_invalid_bucket": zjs,\n        "valid_sequence_fraction": zvalid,\n        "token_support_rate": generated_support_rate(gen_zero),\n        "mode_tv": zmode,\n        "observed_true_sequences": zobserved,\n        "true_mode_coverage_fraction": zobserved / len(true_dist),\n        "long_range_branch_mae": long_range_branch_mae(gen_zero),\n    }\n\n    # Aggregate final seed metrics.\n    agg = {}\n    metric_names = [\n        "expected_nll", "conditional_js", "expected_token_support", "exact_long_range_branch_mae",\n        "generation_joint_js_with_invalid_bucket", "generation_valid_sequence_fraction",\n        "generation_token_support_rate", "generation_mode_tv",\n        "generation_true_mode_coverage_fraction", "generation_long_range_branch_mae",\n    ]\n    for name in metric_names:\n        agg[name] = summarize([r[name] for r in final_runs])\n\n    gates = {\n        "persistent_fresh_parity": parity_max < GATE_THRESHOLDS["fresh_vs_persistent_max_abs_lt"],\n        "candidate_nll": agg["expected_nll"]["mean"] < GATE_THRESHOLDS["candidate_nll_lt"],\n        "candidate_conditional_js": agg["conditional_js"]["mean"] < GATE_THRESHOLDS["candidate_cond_js_lt"],\n        "candidate_expected_token_support": agg["expected_token_support"]["mean"] > GATE_THRESHOLDS["candidate_token_support_gt"],\n        "candidate_autonomous_validity": agg["generation_valid_sequence_fraction"]["mean"] > GATE_THRESHOLDS["candidate_generation_valid_gt"],\n        "candidate_beats_random_nll": agg["expected_nll"]["mean"] / random_metrics["expected_nll"] < GATE_THRESHOLDS["candidate_vs_random_nll_fraction_lt"],\n        "candidate_near_gradient_readout": agg["expected_nll"]["mean"] - grad_metrics["expected_nll"] < GATE_THRESHOLDS["candidate_nll_gap_to_gradient_lt"],\n        "gradient_reference_resolves_long_range": grad_metrics["exact_long_range_branch_mae"] < GATE_THRESHOLDS["gradient_long_range_mae_lt"],\n        "candidate_resolves_long_range": agg["exact_long_range_branch_mae"]["mean"] < GATE_THRESHOLDS["candidate_long_range_mae_lt"],\n        "candidate_generation_resolves_long_range": agg["generation_long_range_branch_mae"]["mean"] < GATE_THRESHOLDS["candidate_generation_long_range_mae_lt"],\n        "candidate_mode_coverage": agg["generation_true_mode_coverage_fraction"]["mean"] > GATE_THRESHOLDS["all_true_modes_observed_fraction_gt"],\n        "M_off_no_learning": moff_metrics["expected_nll"] > GATE_THRESHOLDS["m_off_nll_gt"] and moff_metrics["max_abs_weight"] == 0.0,\n    }\n\n    results = {\n        "gate": "P1-A MSDL -> frozen SNN-Transform categorical generative readout",\n        "scope": "host/cloud numerical scientific gate; no SpiNNaker engineering; no internal SNN-Transform plasticity",\n        "task": {\n            "vocab": V,\n            "length": N,\n            "mask_token": MASK,\n            "number_true_sequences": len(true_dist),\n            "number_exact_prefix_contexts": len(keys),\n            "true_conditional_entropy_nats": entropy,\n            "long_range_dependencies": ["x5 depends on x0", "x6 depends on x1", "x7 depends on x3"],\n            "generation_protocol": "all MASK -> sample token -> explicit changed-token event -> repeat; no teacher token after start",\n        },\n        "core": {\n            "d": D, "heads": HEADS, "features": FEATURES, "ff": FF,\n            "out_density": OUT_DENSITY, "ff1_density": FF1_DENSITY, "ff2_density": FF2_DENSITY,\n            "feature_interface": "PositiveRF exact/reference path",\n            "all_core_parameters_frozen": True,\n            "readout_feature": "normalized target-position final block output y + constant bias channel",\n            "persistent_fresh_max_abs": parity_max,\n        },\n        "candidate_learning": {\n            "rule": "dW = eta * outer(M_post, E_pre)",\n            "output_mismatch_drive": "onehot(target) - softmax(W_path_start @ feature)",\n            "force_steps": FORCE_STEPS,\n            "E_gain": G_E,\n            "M_gain": G_M,\n            "n_sub": N_SUB,\n            "weights_frozen_within_path": True,\n            "candidate_autograd": False,\n            "dev_seed": DEV_SEED,\n            "dev_paths": DEV_PATHS,\n            "lr_candidates": LR_CANDIDATES,\n            "dev_sweep": dev,\n            "selected_lr": selected_lr,\n            "final_paths": FINAL_PATHS,\n            "final_seeds": FINAL_SEEDS,\n        },\n        "random_untrained": random_metrics,\n        "random_generation": random_generation,\n        "gradient_readout_reference": grad_metrics,\n        "gradient_generation": grad_generation,\n        "final_runs": final_runs,\n        "final_aggregate": agg,\n        "M_off_control": moff_metrics,\n        "thresholds": GATE_THRESHOLDS,\n        "gates": gates,\n        "pass": bool(all(gates.values())),\n        "limitations": [\n            "Only the categorical readout is plastic; this is not internal SNN-Transform learning.",\n            "The PositiveRF reference interface is used; Izh Q/K replacement is not re-tested in P1-A.",\n            "Training still has explicit finite paths and is not yet the final continuous-operation regime.",\n            "The output mismatch is locally available at the categorical output population; internal mismatch populations remain unresolved.",\n        ],\n    }\n\n    (outdir / "P1A_RESULTS.json").write_text(json.dumps(results, indent=2), encoding="utf-8")\n\n    # Machine-readable grammar.\n    grammar = {"sequences": [{"tokens": list(s), "probability": p} for s, p in true_dist]}\n    (outdir / "P1A_GRAMMAR.json").write_text(json.dumps(grammar, indent=2), encoding="utf-8")\n\n    report = []\n    report.append("# P1-A — MSDL-trained generative readout on frozen SNN-Transform\\n")\n    report.append(f"Overall: **{\'PASS\' if results[\'pass\'] else \'FAIL\'}**\\n")\n    report.append("## Scientific question\\n")\n    report.append("Can the validated MSDL E/M population dynamics train a local categorical output population attached to a frozen SNN-Transform feature core, such that the resulting system defines a non-degenerate learned probability distribution and can generate autonomously?\\n")\n    report.append("## What is and is not trained\\n")\n    report.append("The SNN-Transform core is completely frozen. Only the directed categorical readout is plastic. Therefore P1-A is an interface/generative-definition gate, **not** a proof of internal SNN-Transform credit assignment.\\n")\n    report.append("## Task\\n")\n    report.append(f"Vocabulary={V}, length={N}, exact true sequences={len(true_dist)}, exact prefix contexts={len(keys)}. Every branch is stochastic; two late branches require non-adjacent context. True conditional entropy = **{entropy:.6f} nats/token**.\\n")\n    report.append("Autonomous generation starts from all MASK tokens and repeatedly samples from the model, then feeds only its sampled token back as an explicit changed-token event.\\n")\n    report.append("## Reference difficulty\\n")\n    report.append(f"- Random/untrained readout NLL: **{random_metrics[\'expected_nll\']:.6f}**; conditional JS: **{random_metrics[\'conditional_js\']:.6f}**.\\n")\n    report.append(f"- Gradient-trained readout-only reference NLL: **{grad_metrics[\'expected_nll\']:.6f}**; conditional JS: **{grad_metrics[\'conditional_js\']:.6f}**. This is a ceiling/reference only and is never used to supply the candidate with targets or weights.\\n")\n    report.append(f"- Gradient exact long-range probability MAE: **{grad_metrics[\'exact_long_range_branch_mae\']:.6f}**; autonomous valid-sequence fraction: **{grad_generation[\'valid_sequence_fraction\']:.4f}**.\\n")\n    report.append("## MSDL candidate\\n")\n    report.append(f"Development selected eta = **{selected_lr:g}** from {LR_CANDIDATES}; final evaluation used independent seeds {FINAL_SEEDS}.\\n")\n    report.append(f"- Exact expected NLL: **{agg[\'expected_nll\'][\'mean\']:.6f} ± {agg[\'expected_nll\'][\'std\']:.6f}**.\\n")\n    report.append(f"- Exact weighted conditional JS: **{agg[\'conditional_js\'][\'mean\']:.6f} ± {agg[\'conditional_js\'][\'std\']:.6f}**.\\n")\n    report.append(f"- Exact expected probability mass on position-valid token support: **{agg[\'expected_token_support\'][\'mean\']:.4f}**.\\n")\n    report.append(f"- Exact long-range conditional probability MAE: **{agg[\'exact_long_range_branch_mae\'][\'mean\']:.6f}**.\\n")\n    report.append(f"- Autonomous full-sequence validity: **{agg[\'generation_valid_sequence_fraction\'][\'mean\']:.4f} ± {agg[\'generation_valid_sequence_fraction\'][\'std\']:.4f}**.\\n")\n    report.append(f"- Autonomous per-token support rate: **{agg[\'generation_token_support_rate\'][\'mean\']:.4f}**.\\n")\n    report.append(f"- True-sequence mode coverage: **{agg[\'generation_true_mode_coverage_fraction\'][\'mean\']:.4f}**.\\n")\n    report.append(f"- Autonomous joint JS (256 true sequences + one invalid bucket): **{agg[\'generation_joint_js_with_invalid_bucket\'][\'mean\']:.6f}**.\\n")\n    report.append(f"- Long-range branch probability MAE: **{agg[\'generation_long_range_branch_mae\'][\'mean\']:.6f}**.\\n")\n    report.append("## Causal control\\n")\n    report.append(f"With M dynamics disabled, max |W| = **{moff_metrics[\'max_abs_weight\']:.3g}** and NLL = **{moff_metrics[\'expected_nll\']:.6f}**, i.e. the random/untrained level.\\n")\n    report.append("## Persistent execution check\\n")\n    report.append(f"Fresh recomputation versus explicit changed-token persistent execution max |difference| = **{parity_max:.3g}**.\\n")\n    report.append("## Gate table\\n")\n    for k, v in gates.items():\n        report.append(f"- `{k}`: **{\'PASS\' if v else \'FAIL\'}**")\n    report.append("\\n## Interpretation\\n")\n    report.append("If PASS, the claim is deliberately narrow: MSDL dynamics can train a local probabilistic generative readout on top of the frozen SNN-Transform dynamics, and the resulting system performs teacher-free autonomous sampling. It does **not** yet establish that MSDL can train W_O/W_2/Q/K/V or create endogenous internal mismatch populations.\\n")\n    (outdir / "P1A_REPORT.md").write_text("\\n".join(report) + "\\n", encoding="utf-8")\n\n    print(json.dumps({\n        "pass": results["pass"],\n        "selected_lr": selected_lr,\n        "entropy": entropy,\n        "random": random_metrics,\n        "gradient": grad_metrics,\n        "aggregate": agg,\n        "m_off": moff_metrics,\n        "gates": gates,\n    }, indent=2))\n\n\nif __name__ == "__main__":\n    main()\n\'\'\'\n\n# ========================= p1b_internal_w2_msdl.py =========================\n_EMBEDDED[\'p1b_internal_w2_msdl\'] = r\'\'\'#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n"""P1-B: first internal SNN-Transform synaptic learning by MSDL dynamics.\n\nScientific scope\n----------------\nP1-A established that MSDL E/M dynamics can train a local categorical\nprobabilistic readout on a frozen SNN-Transform core. P1-B moves plasticity one\nsynaptic population inward: the 25%-sparse FFN output projection W2.\n\nThe categorical readout W_R is frozen from the accepted P1-A seed-101 artifact.\nAll upstream SNN-Transform operators are frozen. Only W2 is plastic.\n\nInternal mismatch is generated by a *local reciprocal population coupling*:\n\n    categorical mismatch e_o = onehot(target) - p\n    block-output mismatch drive r_y = B e_o\n    B = W_R(feature-part)^T\n    M_y = MSDL_M_dynamics(r_y)\n    E_h = MSDL_E_dynamics(hidden_activity)\n    dW2 = eta * (M_y E_h^T) ⊙ structural_mask\n\nNo candidate autograd, BPTT, layerwise chain rule, derivative of RMS\nnormalization, derivative of ReLU, or attention backward pass is used.\nThe reciprocal feedback is an explicit local circuit assumption and is tested\ncausally against sign-reversed/random feedback controls. This gate therefore\nestablishes one-hop internal local credit, not yet deep/endogenous credit for\nW1 or Q/K/V.\n"""\nfrom __future__ import annotations\n\nimport json\nimport math\nimport copy\nfrom pathlib import Path\nfrom typing import Dict, Sequence, Tuple\n\nimport numpy as np\nimport torch\nimport torch.nn.functional as F\nfrom numba import njit\n\nimport p1a_msdl_token_generation as p1a\n\n# -----------------------------------------------------------------------------\n# Frozen P1-B protocol\n# -----------------------------------------------------------------------------\nREADOUT_SEED = 101  # accepted P1-A training protocol, regenerated deterministically here\nREADOUT_PATHS = 12000\nREADOUT_LR = 0.6\nDEV_SEEDS = [1901, 1903, 1907]\nDEV_PATHS = 4000\nLR_CANDIDATES = [0.25, 0.5, 0.75, 1.0]\nSELECTED_LR = 0.5  # frozen by P1B_DEV_CALIBRATION.json before definitive final seeds\nCONTROL_PATHS = 2000\nFINAL_PATHS = 5000\n# Untouched definitive seeds chosen after development calibration.\nFINAL_SEEDS = [1201, 1301, 1409]\nN_GENERATE = 10000\nGEN_BATCH = 5000\n\n# Gates are frozen before FINAL_SEEDS are evaluated. They are deliberately about\n# internal learning, not about solving all long-range structure at P1-B.\nGATE_THRESHOLDS = {\n    "mean_nll_improvement_gt": 0.025,\n    "mean_js_improvement_gt": 0.005,\n    "mean_long_range_mae_improvement_gt": 0.015,\n    "gradient_gap_closed_fraction_gt": 0.25,\n    "mean_generation_validity_improvement_gt": 0.05,\n    "mean_generation_joint_js_improvement_gt": 0.03,\n    "off_mask_max_abs_eq": 0.0,\n    "m_off_max_weight_change_eq": 0.0,\n    "m_off_nll_abs_diff_lt": 1e-12,\n    "wrong_sign_nll_gt_baseline_by": 0.25,\n}\n\n\ndef build_exact_prefix_states(block, tok, pos, true_dist):\n    """Return exact prefix targets plus the *upstream* W2 pre/post quantities.\n\n    z and hidden are independent of W2 in the one-block Pre-LN architecture:\n        z = x + attention(x)\n        h = ReLU(W1 LN2(z) - theta)\n        y = z + W2 h + b2\n\n    Hence z/h can be precomputed exactly while W2 is learned.\n    """\n    from collections import defaultdict\n\n    counts = defaultdict(lambda: np.zeros(p1a.V, dtype=np.float64))\n    mass = defaultdict(float)\n    for seq, prob in true_dist:\n        for t in range(p1a.N):\n            key = (t, seq[:t])\n            counts[key][seq[t]] += prob\n            mass[key] += prob\n\n    keys = list(counts.keys())\n    arrays = np.full((len(keys), p1a.N), p1a.MASK, dtype=np.int64)\n    targets = np.zeros((len(keys), p1a.V), dtype=np.float64)\n    masses = np.zeros(len(keys), dtype=np.float64)\n    target_pos = np.zeros(len(keys), dtype=np.int64)\n    for i, key in enumerate(keys):\n        t, prefix = key\n        arrays[i, :t] = prefix\n        targets[i] = counts[key] / mass[key]\n        masses[i] = mass[key] / p1a.N\n        target_pos[i] = t\n\n    with torch.no_grad():\n        x = p1a.encode(arrays, tok, pos)\n        xn = block.n1(x)\n        q = block._split(block.q(xn))\n        k = block._split(block.k(xn))\n        value = block._split(block.v(xn))\n        pq = block.phi_q(q, is_query=True)\n        pk = block.phi_k(k, is_query=False)\n        H = torch.einsum("bhnm,bhnd->bhmd", pk, value)\n        g = pk.sum(dim=2)\n        num = torch.einsum("bhnm,bhmd->bhnd", pq, H)\n        den = torch.einsum("bhnm,bhm->bhn", pq, g).unsqueeze(-1).clamp_min(1e-8)\n        attended = num / den\n        z_all = x + block.out(attended.transpose(1, 2).reshape(len(keys), p1a.N, p1a.D))\n        hidden_all = F.relu(block.f1(block.n2(z_all)) - block.theta)\n        row = torch.arange(len(keys))\n        col = torch.as_tensor(target_pos)\n        z = z_all[row, col].cpu().numpy().astype(np.float64)\n        hidden = hidden_all[row, col].cpu().numpy().astype(np.float64)\n\n    if abs(masses.sum() - 1.0) > 1e-12:\n        raise AssertionError(masses.sum())\n    return keys, arrays, targets, masses, z, hidden\n\n\ndef readout_features_from_w2(z, hidden, W2, b2):\n    y = z + hidden @ W2.T + b2[None, :]\n    rms = np.sqrt(np.mean(y * y, axis=1, keepdims=True)) + 1e-8\n    f = y / rms * 0.5\n    return np.concatenate([f, np.full((f.shape[0], 1), 0.5, dtype=np.float64)], axis=1)\n\n\ndef evaluate_w2(W2, z, hidden, b2, W_R, targets, masses, keys):\n    feat = readout_features_from_w2(z, hidden, W2, b2)\n    met = p1a.evaluate_W(W_R, feat, targets, masses, keys)\n    return met, feat\n\n\n@njit(cache=True)\ndef train_w2_local_feedback(\n    hidden,\n    z,\n    targets,\n    masses,\n    W_R,\n    B_feedback,\n    W2_init,\n    mask,\n    b2,\n    n_paths,\n    lr,\n    seed,\n    m_off=False,\n):\n    """MSDL-train W2 with one-hop local reciprocal mismatch coupling.\n\n    W2 is frozen within each 27-force-step path, matching the frozen MSDL\n    Phase-I semantics. W_R and B_feedback are fixed throughout P1-B.\n    """\n    np.random.seed(seed)\n    nctx, ff = hidden.shape\n    d = z.shape[1]\n    W2 = W2_init.copy()\n\n    ve = np.full(ff, p1a.V0, dtype=np.float64)\n    ue = np.full(ff, p1a.U0, dtype=np.float64)\n    vm = np.full(d, p1a.V0, dtype=np.float64)\n    um = np.full(d, p1a.U0, dtype=np.float64)\n    zero_e = np.zeros(ff, dtype=np.float64)\n    zero_m = np.zeros(d, dtype=np.float64)\n\n    cdf = np.cumsum(masses)\n    cdf[-1] = 1.0\n    spikes_e = 0\n    spikes_m = 0\n\n    for _p in range(n_paths):\n        W0 = W2.copy()\n        accum = np.zeros_like(W2)\n        for _k in range(p1a.FORCE_STEPS):\n            u = np.random.random()\n            ci = 0\n            while ci < nctx - 1 and u > cdf[ci]:\n                ci += 1\n\n            h = hidden[ci]\n            y = z[ci].copy()\n            for o in range(d):\n                y[o] += b2[o]\n                s = 0.0\n                for j in range(ff):\n                    s += W0[o, j] * h[j]\n                y[o] += s\n\n            rms2 = 0.0\n            for o in range(d):\n                rms2 += y[o] * y[o]\n            rms = math.sqrt(rms2 / d) + 1e-8\n\n            logits = np.empty(p1a.V, dtype=np.float64)\n            for v in range(p1a.V):\n                s = 0.5 * W_R[v, d]  # constant bias feature is exactly 0.5\n                for o in range(d):\n                    s += W_R[v, o] * (0.5 * y[o] / rms)\n                logits[v] = s\n            probs = p1a.softmax_numba(logits)\n\n            target = p1a.sample_categorical_numba(targets[ci])\n            one = np.zeros(p1a.V, dtype=np.float64)\n            one[target] = 1.0\n\n            # Local categorical mismatch is projected by an explicit feedback\n            # population/circuit. No chain rule or hidden gradient is computed.\n            drive = np.zeros(d, dtype=np.float64)\n            if not m_off:\n                for o in range(d):\n                    s = 0.0\n                    for v in range(p1a.V):\n                        s += B_feedback[o, v] * (one[v] - probs[v])\n                    drive[o] = s\n\n            E, se = p1a.fast_izh_step(\n                ve, ue, h, zero_e, p1a.G_E, p1a.CV_E, p1a.CU_E\n            )\n            spikes_e += se\n            if m_off:\n                M = np.zeros(d, dtype=np.float64)\n            else:\n                M, sm = p1a.fast_izh_step(\n                    vm, um, drive, zero_m, p1a.G_M, p1a.CV_M, p1a.CU_M\n                )\n                spikes_m += sm\n\n            for o in range(d):\n                for j in range(ff):\n                    if mask[o, j] != 0.0:\n                        accum[o, j] += M[o] * E[j]\n\n        for o in range(d):\n            for j in range(ff):\n                if mask[o, j] != 0.0:\n                    W2[o, j] += lr * accum[o, j] / p1a.FORCE_STEPS\n                else:\n                    W2[o, j] = 0.0\n\n    return W2, spikes_e, spikes_m\n\n\ndef train_gradient_w2_reference(z, hidden, b2, W2_init, mask, W_R, targets, masses):\n    """Attainable-performance reference only; never used by candidate learning."""\n    zt = torch.tensor(z, dtype=torch.float32)\n    ht = torch.tensor(hidden, dtype=torch.float32)\n    b = torch.tensor(b2, dtype=torch.float32)\n    mask_t = torch.tensor(mask, dtype=torch.float32)\n    WR = torch.tensor(W_R, dtype=torch.float32)\n    T = torch.tensor(targets, dtype=torch.float32)\n    M = torch.tensor(masses, dtype=torch.float32)\n    raw = torch.tensor(W2_init, dtype=torch.float32, requires_grad=True)\n    opt = torch.optim.LBFGS([raw], lr=0.5, max_iter=400, line_search_fn="strong_wolfe")\n\n    def closure():\n        opt.zero_grad()\n        W = raw * mask_t\n        y = zt + F.linear(ht, W, b)\n        feat = p1a.normalize_readout_feature(y)\n        feat = torch.cat([feat, torch.full((feat.shape[0], 1), 0.5)], dim=1)\n        logp = F.log_softmax(feat @ WR.T, dim=1)\n        loss = -(M[:, None] * T * logp).sum()\n        loss.backward()\n        return loss\n\n    opt.step(closure)\n    return (raw.detach() * mask_t).cpu().numpy().astype(np.float64)\n\n\ndef set_block_w2(block, W2):\n    with torch.no_grad():\n        block.f2.weight.copy_(torch.tensor(W2, dtype=block.f2.weight.dtype))\n\n\ndef generate_for_w2(block, tok, pos, W_R, W2, n_generate, seed):\n    set_block_w2(block, W2)\n    return p1a.autonomous_generate(block, tok, pos, W_R, n_generate, seed, GEN_BATCH)\n\n\ndef generation_metrics(samples, true_dist):\n    js, valid, mode_tv, observed = p1a.empirical_js_with_invalid_bucket(samples, true_dist)\n    return {\n        "joint_js_with_invalid_bucket": js,\n        "valid_sequence_fraction": valid,\n        "token_support_rate": p1a.generated_support_rate(samples),\n        "mode_tv": mode_tv,\n        "observed_true_sequences": observed,\n        "true_mode_coverage_fraction": observed / len(true_dist),\n        "long_range_branch_mae": p1a.long_range_branch_mae(samples),\n    }\n\n\ndef summarize(vals: Sequence[float]) -> Dict[str, float]:\n    a = np.asarray(vals, dtype=np.float64)\n    return {"mean": float(a.mean()), "std": float(a.std()), "min": float(a.min()), "max": float(a.max())}\n\n\ndef main():\n    outdir = Path(__file__).resolve().parent\n    torch.set_num_threads(4)\n    torch.manual_seed(p1a.TORCH_INIT_SEED)\n    np.random.seed(1234)\n\n    true_dist = p1a.enumerate_true_distribution()\n    tok, pos = p1a.build_embeddings()\n    block = p1a.FrozenSNNTransformBlock().eval()\n    keys, arrays, targets, masses, z, hidden = build_exact_prefix_states(block, tok, pos, true_dist)\n\n    mask = block.f2.mask.detach().cpu().numpy().astype(np.float64)\n    W2_init = (block.f2.weight * block.f2.mask).detach().cpu().numpy().astype(np.float64)\n    b2 = block.f2.bias.detach().cpu().numpy().astype(np.float64)\n\n    # Recreate the accepted P1-A readout deterministically on this exact frozen\n    # core, rather than trusting a possibly stale convenience artifact.\n    base_features = readout_features_from_w2(z, hidden, W2_init, b2)\n    W_R, readout_E_spikes, readout_M_spikes = p1a.train_msdl_readout(\n        base_features, targets, masses, READOUT_PATHS, READOUT_LR, READOUT_SEED, False\n    )\n    B_recip = W_R[:, :p1a.D].T.copy()\n    baseline, _ = evaluate_w2(W2_init, z, hidden, b2, W_R, targets, masses, keys)\n\n    # Gradient W2-only capacity/reference. Candidate never reads these weights.\n    W2_grad = train_gradient_w2_reference(z, hidden, b2, W2_init, mask, W_R, targets, masses)\n    grad_metrics, _ = evaluate_w2(W2_grad, z, hidden, b2, W_R, targets, masses, keys)\n    available_gap = baseline["expected_nll"] - grad_metrics["expected_nll"]\n\n    # Development calibration was completed before the definitive seeds and is\n    # stored verbatim beside this script. Loading it avoids re-running a costly\n    # calibration every time the definitive gate is reproduced.\n    dev_cal = json.loads((outdir / "P1B_DEV_CALIBRATION.json").read_text(encoding="utf-8"))\n    selected_lr = float(dev_cal["selected_lr"])\n    if selected_lr != SELECTED_LR:\n        raise AssertionError((selected_lr, SELECTED_LR))\n    dev = dev_cal["candidates"]\n\n    # Wrong-feedback causal controls use one development seed only.\n    rng = np.random.default_rng(424242)\n    B_random = rng.normal(size=B_recip.shape)\n    B_random *= np.linalg.norm(B_recip) / (np.linalg.norm(B_random) + 1e-30)\n    control_feedback = {}\n    for name, B in (("negative_reciprocal", -B_recip), ("random_same_norm", B_random)):\n        Wc, _, _ = train_w2_local_feedback(\n            hidden, z, targets, masses, W_R, B, W2_init, mask, b2,\n            CONTROL_PATHS, selected_lr, DEV_SEEDS[0], False\n        )\n        met, _ = evaluate_w2(Wc, z, hidden, b2, W_R, targets, masses, keys)\n        control_feedback[name] = met\n\n    # M-off: exact no-update control.\n    W_moff, se0, sm0 = train_w2_local_feedback(\n        hidden, z, targets, masses, W_R, B_recip, W2_init, mask, b2,\n        300, selected_lr, 7007, True\n    )\n    moff_metrics, _ = evaluate_w2(W_moff, z, hidden, b2, W_R, targets, masses, keys)\n    moff_metrics.update({\n        "max_abs_weight_change": float(np.max(np.abs(W_moff - W2_init))),\n        "off_mask_max_abs": float(np.max(np.abs(W_moff * (1.0 - mask)))),\n        "E_spikes": int(se0), "M_spikes": int(sm0),\n    })\n\n    # Baseline and gradient autonomous references once.\n    block_base = copy.deepcopy(block).eval()\n    base_gen = generate_for_w2(block_base, tok, pos, W_R, W2_init, 20000, 90001)\n    base_generation = generation_metrics(base_gen, true_dist)\n    block_grad = copy.deepcopy(block).eval()\n    grad_gen = generate_for_w2(block_grad, tok, pos, W_R, W2_grad, 20000, 90002)\n    grad_generation = generation_metrics(grad_gen, true_dist)\n\n    # Final independent W2 learning seeds.\n    final_runs = []\n    saved_W2 = None\n    saved_samples = None\n    for ri, seed in enumerate(FINAL_SEEDS):\n        W2, se, sm = train_w2_local_feedback(\n            hidden, z, targets, masses, W_R, B_recip, W2_init, mask, b2,\n            FINAL_PATHS, selected_lr, seed, False\n        )\n        met, _ = evaluate_w2(W2, z, hidden, b2, W_R, targets, masses, keys)\n        block_i = copy.deepcopy(block).eval()\n        gen = generate_for_w2(block_i, tok, pos, W_R, W2, N_GENERATE, 100000 + seed)\n        gmet = generation_metrics(gen, true_dist)\n        gap_closed = (\n            (baseline["expected_nll"] - met["expected_nll"]) / available_gap\n            if available_gap > 1e-12 else float("nan")\n        )\n        row = {\n            "seed": seed,\n            **met,\n            "nll_improvement_vs_frozen_W2": baseline["expected_nll"] - met["expected_nll"],\n            "conditional_js_improvement_vs_frozen_W2": baseline["conditional_js"] - met["conditional_js"],\n            "long_range_mae_improvement_vs_frozen_W2": baseline["exact_long_range_branch_mae"] - met["exact_long_range_branch_mae"],\n            "gradient_w2_nll_gap_closed_fraction": gap_closed,\n            "weight_change_rel_l2": float(np.linalg.norm(W2 - W2_init) / (np.linalg.norm(W2_init) + 1e-30)),\n            "off_mask_max_abs": float(np.max(np.abs(W2 * (1.0 - mask)))),\n            "E_spikes": int(se), "M_spikes": int(sm),\n            "generation": gmet,\n        }\n        final_runs.append(row)\n        if ri == 0:\n            saved_W2 = W2.copy()\n            saved_samples = gen[:2000].copy()\n\n    scalar_names = [\n        "expected_nll", "conditional_js", "expected_token_support", "exact_long_range_branch_mae",\n        "nll_improvement_vs_frozen_W2", "conditional_js_improvement_vs_frozen_W2",\n        "long_range_mae_improvement_vs_frozen_W2", "gradient_w2_nll_gap_closed_fraction",\n        "weight_change_rel_l2", "off_mask_max_abs",\n    ]\n    agg = {name: summarize([r[name] for r in final_runs]) for name in scalar_names}\n    gen_names = [\n        "joint_js_with_invalid_bucket", "valid_sequence_fraction", "token_support_rate",\n        "mode_tv", "true_mode_coverage_fraction", "long_range_branch_mae",\n    ]\n    gen_agg = {name: summarize([r["generation"][name] for r in final_runs]) for name in gen_names}\n\n    gates = {\n        "candidate_internal_W2_nll_improves": agg["nll_improvement_vs_frozen_W2"]["mean"] > GATE_THRESHOLDS["mean_nll_improvement_gt"],\n        "candidate_internal_W2_js_improves": agg["conditional_js_improvement_vs_frozen_W2"]["mean"] > GATE_THRESHOLDS["mean_js_improvement_gt"],\n        "candidate_internal_W2_long_range_improves": agg["long_range_mae_improvement_vs_frozen_W2"]["mean"] > GATE_THRESHOLDS["mean_long_range_mae_improvement_gt"],\n        "candidate_closes_gradient_W2_gap": agg["gradient_w2_nll_gap_closed_fraction"]["mean"] > GATE_THRESHOLDS["gradient_gap_closed_fraction_gt"],\n        "autonomous_validity_improves": gen_agg["valid_sequence_fraction"]["mean"] - base_generation["valid_sequence_fraction"] > GATE_THRESHOLDS["mean_generation_validity_improvement_gt"],\n        "autonomous_joint_js_improves": base_generation["joint_js_with_invalid_bucket"] - gen_agg["joint_js_with_invalid_bucket"]["mean"] > GATE_THRESHOLDS["mean_generation_joint_js_improvement_gt"],\n        "structural_sparse_mask_preserved": agg["off_mask_max_abs"]["max"] == GATE_THRESHOLDS["off_mask_max_abs_eq"],\n        "M_off_no_internal_learning": moff_metrics["max_abs_weight_change"] == GATE_THRESHOLDS["m_off_max_weight_change_eq"] and abs(moff_metrics["expected_nll"] - baseline["expected_nll"]) < GATE_THRESHOLDS["m_off_nll_abs_diff_lt"],\n        "wrong_sign_feedback_is_causally_wrong": control_feedback["negative_reciprocal"]["expected_nll"] > baseline["expected_nll"] + GATE_THRESHOLDS["wrong_sign_nll_gt_baseline_by"],\n    }\n\n    results = {\n        "gate": "P1-B MSDL internal sparse W2 learning",\n        "scientific_scope": "cloud/host numerical gate; first internal SNN-Transform plastic synaptic population; no SpiNNaker; no W1/QKV credit yet",\n        "task": {\n            "same_as_P1A": True,\n            "vocab": p1a.V,\n            "length": p1a.N,\n            "true_sequences": len(true_dist),\n            "exact_prefix_contexts": len(keys),\n        },\n        "frozen_components": {\n            "readout_source": "deterministically regenerated accepted P1-A MSDL readout protocol",\n            "readout_seed": READOUT_SEED,\n            "readout_paths": READOUT_PATHS,\n            "readout_lr": READOUT_LR,\n            "readout_E_spikes": int(readout_E_spikes),\n            "readout_M_spikes": int(readout_M_spikes),\n            "readout_frozen_during_P1B": True,\n            "QKV_attention_WO_W1": "frozen",\n            "W2_bias": "frozen",\n            "W2_structural_mask": "fixed 25%",\n            "feature_interface": "PositiveRF exact/reference, same P1-A",\n        },\n        "plastic_component": {\n            "name": "SNN-Transform FFN output projection W2",\n            "shape": list(W2_init.shape),\n            "density": float(mask.mean()),\n            "update": "dW2 = eta * outer(M_y, E_hidden) * mask",\n            "hidden_E": "frozen MSDL E Izh dynamics driven by local FFN hidden activity",\n            "output_M": "frozen MSDL M Izh dynamics driven by B @ (onehot(target)-p)",\n            "feedback": "explicit local reciprocal coupling B = W_R[:,:D]^T",\n            "candidate_autograd": False,\n            "chain_rule_derivatives": False,\n            "path_start_weights_frozen": True,\n        },\n        "baseline_frozen_W2": baseline,\n        "gradient_W2_only_reference": grad_metrics,\n        "gradient_W2_generation": grad_generation,\n        "gradient_available_nll_gap": available_gap,\n        "baseline_generation": base_generation,\n        "development": dev_cal,\n        "feedback_controls_dev": control_feedback,\n        "M_off_control": moff_metrics,\n        "final_paths": FINAL_PATHS,\n        "final_seeds": FINAL_SEEDS,\n        "final_runs": final_runs,\n        "final_aggregate": agg,\n        "generation_aggregate": gen_agg,\n        "thresholds": GATE_THRESHOLDS,\n        "gates": gates,\n        "pass": bool(all(gates.values())),\n        "claim_boundary": {\n            "verified_if_pass": [\n                "MSDL E/M dynamics can modify an actual internal SNN-Transform synaptic population W2 under the fixed sparse topology.",\n                "A one-hop reciprocal local mismatch circuit is sufficient to improve probabilistic generation metrics without candidate backpropagation/BPTT.",\n                "Learning causally depends on M dynamics and correctly signed feedback coupling.",\n            ],\n            "not_verified": [\n                "deep endogenous credit assignment for W1 or Q/K/V",\n                "learning without any explicit target/mismatch at the categorical output population",\n                "fully continuous learning/generation",\n                "SpiNNaker execution",\n            ],\n        },\n    }\n\n    (outdir / "P1B_RESULTS.json").write_text(json.dumps(results, indent=2), encoding="utf-8")\n    np.savez_compressed(\n        outdir / "P1B_INTERNAL_W2_EXAMPLE.npz",\n        W2=saved_W2,\n        samples=saved_samples,\n        W_R=W_R,\n        mask=mask,\n    )\n\n    report = []\n    report.append("# P1-B — MSDL learning of an internal SNN-Transform W2 population\\n")\n    report.append(f"Overall: **{\'PASS\' if results[\'pass\'] else \'FAIL\'}**\\n")\n    report.append("## Scientific question\\n")\n    report.append("Can the already validated MSDL E/M dynamics move one synaptic population *inside* SNN-Transform—its 25%-sparse FFN output projection W2—using only local population activity plus a one-hop reciprocal mismatch coupling from the categorical output population, without candidate backpropagation/BPTT?\\n")\n    report.append("## Architecture boundary\\n")\n    report.append("The accepted P1-A MSDL-trained categorical readout is frozen. Q/K/V, attention H/g dynamics, W_O and W1 are frozen. Only W2 is plastic; its structural 25% mask is unchanged. Therefore improvement relative to the frozen-W2 baseline is attributable to internal SNN-Transform synaptic learning.\\n")\n    report.append("## Local dynamical interface\\n")\n    report.append("For the target-position FFN hidden population h and categorical output mismatch e_o = onehot(target)-p, P1-B uses\\n")\n    report.append("\\\\[r_y = B e_o,\\\\qquad B=W_R^T,\\\\]\\n")\n    report.append("\\\\[E_h=\\\\mathcal D_E[h],\\\\qquad M_y=\\\\mathcal D_M[r_y],\\\\]\\n")\n    report.append("\\\\[\\\\Delta W_2=\\\\eta(M_yE_h^T)\\\\odot S_2.\\\\]\\n")\n    report.append("This is an explicit reciprocal population coupling, not a layerwise chain-rule gradient: no derivative of RMS normalization, ReLU, residual, attention, or Q/K/V is computed.\\n")\n    report.append("## Baseline and capacity reference\\n")\n    report.append(f"- Frozen-W2 baseline NLL = **{baseline[\'expected_nll\']:.6f}**, conditional JS = **{baseline[\'conditional_js\']:.6f}**, exact long-range MAE = **{baseline[\'exact_long_range_branch_mae\']:.6f}**.\\n")\n    report.append(f"- Gradient W2-only reference NLL = **{grad_metrics[\'expected_nll\']:.6f}**, conditional JS = **{grad_metrics[\'conditional_js\']:.6f}**, exact long-range MAE = **{grad_metrics[\'exact_long_range_branch_mae\']:.6f}**. This is capacity/reference only.\\n")\n    report.append("## Development and final candidate\\n")\n    report.append(f"Robust development across seeds {DEV_SEEDS} selected eta = **{selected_lr:g}** from {LR_CANDIDATES}; definitive untouched final seeds = {FINAL_SEEDS}.\\n")\n    report.append(f"- NLL = **{agg[\'expected_nll\'][\'mean\']:.6f} ± {agg[\'expected_nll\'][\'std\']:.6f}**; mean improvement over frozen W2 = **{agg[\'nll_improvement_vs_frozen_W2\'][\'mean\']:.6f}**.\\n")\n    report.append(f"- Conditional JS = **{agg[\'conditional_js\'][\'mean\']:.6f} ± {agg[\'conditional_js\'][\'std\']:.6f}**; improvement = **{agg[\'conditional_js_improvement_vs_frozen_W2\'][\'mean\']:.6f}**.\\n")\n    report.append(f"- Exact long-range MAE = **{agg[\'exact_long_range_branch_mae\'][\'mean\']:.6f}**; improvement = **{agg[\'long_range_mae_improvement_vs_frozen_W2\'][\'mean\']:.6f}**.\\n")\n    report.append(f"- Fraction of the W2-only gradient NLL opportunity closed = **{agg[\'gradient_w2_nll_gap_closed_fraction\'][\'mean\']:.3f}**.\\n")\n    report.append(f"- Structural off-mask max |W2| = **{agg[\'off_mask_max_abs\'][\'max\']:.3g}**.\\n")\n    report.append("## Autonomous generation\\n")\n    report.append(f"Frozen-W2 validity = **{base_generation[\'valid_sequence_fraction\']:.4f}**; learned-W2 validity = **{gen_agg[\'valid_sequence_fraction\'][\'mean\']:.4f} ± {gen_agg[\'valid_sequence_fraction\'][\'std\']:.4f}**.\\n")\n    report.append(f"Frozen-W2 joint JS = **{base_generation[\'joint_js_with_invalid_bucket\']:.6f}**; learned-W2 joint JS = **{gen_agg[\'joint_js_with_invalid_bucket\'][\'mean\']:.6f}**.\\n")\n    report.append(f"Learned-W2 autonomous long-range MAE = **{gen_agg[\'long_range_branch_mae\'][\'mean\']:.6f}**.\\n")\n    report.append("## Causal controls\\n")\n    report.append(f"- M-off: max |ΔW2| = **{moff_metrics[\'max_abs_weight_change\']:.3g}**, NLL = **{moff_metrics[\'expected_nll\']:.6f}**.\\n")\n    report.append(f"- Negative reciprocal feedback NLL = **{control_feedback[\'negative_reciprocal\'][\'expected_nll\']:.6f}**.\\n")\n    report.append(f"- Random same-norm feedback NLL = **{control_feedback[\'random_same_norm\'][\'expected_nll\']:.6f}**.\\n")\n    report.append("These controls test that an arbitrary hidden update is not sufficient: the sign/alignment of the local mismatch coupling matters.\\n")\n    report.append("## Gate table\\n")\n    for k, v in gates.items():\n        report.append(f"- `{k}`: **{\'PASS\' if v else \'FAIL\'}**")\n    report.append("\\n## Claim boundary\\n")\n    report.append("**Verified if PASS:** MSDL population dynamics can train an actual internal sparse SNN-Transform synaptic population, W2, and the resulting internal change causally improves the probabilistic generative model under a local reciprocal mismatch circuit.\\n")\n    report.append("**Still open:** W1 and Q/K/V require credit to travel deeper than one local reciprocal hop. P1-B therefore does not yet establish a fully endogenous multi-layer learning system.\\n")\n    (outdir / "P1B_REPORT.md").write_text("\\n".join(report) + "\\n", encoding="utf-8")\n\n    print(json.dumps({\n        "pass": results["pass"],\n        "selected_lr": selected_lr,\n        "baseline": baseline,\n        "gradient_W2": grad_metrics,\n        "aggregate": agg,\n        "generation": gen_agg,\n        "controls": control_feedback,\n        "gates": gates,\n    }, indent=2))\n\n\nif __name__ == "__main__":\n    main()\n\'\'\'\n\n# ========================= p1c2_trajectory_coherent_mismatch.py =========================\n_EMBEDDED[\'p1c2_trajectory_coherent_mismatch\'] = r\'\'\'#!/usr/bin/env python3\n"""Minimal helper retained by the current P1 implementation.\n\nHistorical P1-C2 experiments contained many diagnostics.  The current full\npipeline only needs this mapping from true sequences to exact prefix-context\nindices, so the historical experiment driver is intentionally not bundled.\n"""\nfrom __future__ import annotations\nimport numpy as np\n\n\ndef build_sequence_index(true_dist, keys):\n    """Return (sequence_context_idx, sequence_tokens, sequence_probs).\n\n    `keys` contains exact prefix contexts as `(position, prefix_tuple)`.\n    Each true sequence is mapped to the context index used at every position.\n    """\n    key_to_idx = {k: i for i, k in enumerate(keys)}\n    nseq = len(true_dist)\n    if nseq == 0:\n        raise ValueError("true_dist must not be empty")\n    n = len(true_dist[0][0])\n    sci = np.empty((nseq, n), dtype=np.int64)\n    st = np.empty((nseq, n), dtype=np.int64)\n    sp = np.empty(nseq, dtype=np.float64)\n    for si, (seq, prob) in enumerate(true_dist):\n        if len(seq) != n:\n            raise ValueError("all sequences must have equal length")\n        st[si] = np.asarray(seq, dtype=np.int64)\n        sp[si] = float(prob)\n        for t in range(n):\n            sci[si, t] = key_to_idx[(t, tuple(seq[:t]))]\n    s = float(sp.sum())\n    if not np.isclose(s, 1.0, atol=1e-12):\n        raise AssertionError(f"sequence probabilities sum to {s}, not 1")\n    return sci, st, sp\n\'\'\'\n\n# ========================= p1c_deep_local_mismatch.py =========================\n_EMBEDDED[\'p1c_deep_local_mismatch\'] = r\'\'\'#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n"""P1-C: deep local mismatch formation with learned reciprocal pathways.\n\nPurpose\n-------\nP1-B trained internal W2 using an exactly aligned reciprocal feedback matrix.\nP1-C removes explicit weight transport for a deeper W1 population.\n\nTwo feedback pathways are learned from zero using only local perturbations and\nMSDL E/M population dynamics:\n\n  B_R : categorical-logit population -> readout-feature/output population\n  B_2 : block-output population       -> FFN-hidden population\n\nThe feedback directions are *not copied* from forward weights in the candidate.\nLocal zero-mean perturbations are injected into the presynaptic population; the\nneighboring postsynaptic response is observed; MSDL E/M outer products slowly\nform a reciprocal pathway.  After this calibration, categorical mismatch flows\nthrough B_R then B_2 and trains sparse W1 by the same directed MSDL rule:\n\n  error_o = onehot(target) - p\n  drive_y = B_R error_o\n  drive_h = B_2 drive_y\n  E_u = D_E[u]\n  M_h = D_M[drive_h]\n  dW1 = eta (M_h E_u^T) * mask_W1\n\nNo candidate autograd, BPTT, chain-rule derivative, or explicit forward-weight\ntranspose is used. Exact-transpose feedback and gradient W1 optimization are\nreferences only.\n"""\nfrom __future__ import annotations\n\nimport copy\nimport json\nimport math\nfrom pathlib import Path\nfrom typing import Dict, Sequence\n\nimport numpy as np\nimport torch\nimport torch.nn.functional as F\nfrom numba import njit\n\nimport p1a_msdl_token_generation as p1a\nimport p1b_internal_w2_msdl as p1b\n\n# -----------------------------------------------------------------------------\n# Frozen protocol\n# -----------------------------------------------------------------------------\nREADOUT_SEED = 101\nREADOUT_PATHS = 12000\nREADOUT_LR = 0.6\n\nMIRROR_STEPS = 20000\nMIRROR_SIGMA = 0.1\nMIRROR_ETA_BR = 0.0338\nMIRROR_ETA_B2 = 0.0335\n\nDEV_SEEDS = [1901, 1903, 1907]\nDEV_PATHS = 5000\nDEV_LRS = [0.3, 0.5, 0.75]\nSELECTED_LR = 0.5\n\nFINAL_PATHS = 5000\nFINAL_SEEDS = [2201, 2309, 2411]\nN_GENERATE = 10000\nGEN_BATCH = 5000\n\nCONTROL_PATHS = 2500\n\nGATE_THRESHOLDS = {\n    "mean_nll_improvement_gt": 0.025,\n    "mean_js_improvement_gt": 0.006,\n    "mean_long_range_mae_improvement_gt": 0.010,\n    "mean_gradient_gap_closed_fraction_gt": 0.25,\n    "mean_feedback_BR_cos_gt": 0.995,\n    "mean_feedback_B2_cos_gt": 0.990,\n    "learned_feedback_fraction_of_exact_msdl_improvement_gt": 0.80,\n    "mean_generation_validity_improvement_gt": 0.05,\n    "mean_generation_joint_js_improvement_gt": 0.025,\n    "off_mask_max_abs_eq": 0.0,\n    "m_off_max_weight_change_eq": 0.0,\n    "random_feedback_nll_gt_baseline_by": 0.5,\n    "negative_feedback_nll_gt_baseline_by": 0.5,\n}\n\n\ndef build_prefix_internal(block, tok, pos, true_dist):\n    """Exact prefix targets and W1 local pre-activity u plus residual z."""\n    keys, arrays, targets, masses, z, hidden = p1b.build_exact_prefix_states(\n        block, tok, pos, true_dist\n    )\n    with torch.no_grad():\n        x = p1a.encode(arrays, tok, pos)\n        xn = block.n1(x)\n        q = block._split(block.q(xn))\n        k = block._split(block.k(xn))\n        value = block._split(block.v(xn))\n        pq = block.phi_q(q, is_query=True)\n        pk = block.phi_k(k, is_query=False)\n        H = torch.einsum("bhnm,bhnd->bhmd", pk, value)\n        g = pk.sum(dim=2)\n        num = torch.einsum("bhnm,bhmd->bhnd", pq, H)\n        den = torch.einsum("bhnm,bhm->bhn", pq, g).unsqueeze(-1).clamp_min(1e-8)\n        attended = num / den\n        z_all = x + block.out(attended.transpose(1, 2).reshape(len(keys), p1a.N, p1a.D))\n        u_all = block.n2(z_all)\n        row = torch.arange(len(keys))\n        col = torch.as_tensor([k_[0] for k_ in keys])\n        u = u_all[row, col].cpu().numpy().astype(np.float64)\n    return keys, arrays, targets, masses, z, hidden, u\n\n\ndef hidden_from_w1(u, W1, b1, theta):\n    return np.maximum(u @ W1.T + b1[None, :] - theta[None, :], 0.0)\n\n\ndef evaluate_w1(W1, u, z, b1, theta, W2, b2, W_R, targets, masses, keys):\n    h = hidden_from_w1(u, W1, b1, theta)\n    return p1b.evaluate_w2(W2, z, h, b2, W_R, targets, masses, keys)[0]\n\n\n@njit(cache=True)\ndef learn_feedback_BR_msdl(W_R, n_steps, sigma, eta, seed):\n    """Learn readout reciprocal pathway from local feature noise.\n\n    A perturbation df is generated in the normalized readout-feature population.\n    The adjacent categorical population responds with dlogit = W_R df, but the\n    candidate does not read W_R values to set feedback weights. It only observes\n    the local population response dlogit and forms B_R from M(df) E(dlogit)^T.\n    """\n    np.random.seed(seed)\n    d = W_R.shape[1] - 1  # exclude constant bias feature\n    V = W_R.shape[0]\n    B = np.zeros((d, V), dtype=np.float64)\n    vm = np.full(d, p1a.V0, dtype=np.float64)\n    um = np.full(d, p1a.U0, dtype=np.float64)\n    ve = np.full(V, p1a.V0, dtype=np.float64)\n    ue = np.full(V, p1a.U0, dtype=np.float64)\n    zd = np.zeros(d, dtype=np.float64)\n    zv = np.zeros(V, dtype=np.float64)\n    spikes_m = 0\n    spikes_e = 0\n\n    for _ in range(n_steps):\n        df = np.random.normal(0.0, sigma, d)\n        dlogit = np.zeros(V, dtype=np.float64)\n        # This multiplication is the physical forward response of the adjacent\n        # population to injected df; no transpose is exposed to the learner.\n        for v in range(V):\n            s = 0.0\n            for o in range(d):\n                s += W_R[v, o] * df[o]\n            dlogit[v] = s\n\n        M, sm = p1a.fast_izh_step(vm, um, df, zd, p1a.G_M, p1a.CV_M, p1a.CU_M)\n        E, se = p1a.fast_izh_step(ve, ue, dlogit, zv, p1a.G_E, p1a.CV_E, p1a.CU_E)\n        spikes_m += sm\n        spikes_e += se\n        for o in range(d):\n            for v in range(V):\n                B[o, v] += eta * M[o] * E[v]\n    return B, spikes_e, spikes_m\n\n\n@njit(cache=True)\ndef learn_feedback_B2_msdl(W2, n_steps, sigma, eta, seed):\n    """Learn W2 reciprocal pathway from hidden-population perturbations."""\n    np.random.seed(seed)\n    d = W2.shape[0]\n    ff = W2.shape[1]\n    B = np.zeros((ff, d), dtype=np.float64)\n    vm = np.full(ff, p1a.V0, dtype=np.float64)\n    um = np.full(ff, p1a.U0, dtype=np.float64)\n    ve = np.full(d, p1a.V0, dtype=np.float64)\n    ue = np.full(d, p1a.U0, dtype=np.float64)\n    zf = np.zeros(ff, dtype=np.float64)\n    zd = np.zeros(d, dtype=np.float64)\n    spikes_m = 0\n    spikes_e = 0\n\n    for _ in range(n_steps):\n        dh = np.random.normal(0.0, sigma, ff)\n        dy = np.zeros(d, dtype=np.float64)\n        # Physical forward response through W2; feedback learner sees only dy.\n        for o in range(d):\n            for i in range(ff):\n                dy[o] += W2[o, i] * dh[i]\n\n        M, sm = p1a.fast_izh_step(vm, um, dh, zf, p1a.G_M, p1a.CV_M, p1a.CU_M)\n        E, se = p1a.fast_izh_step(ve, ue, dy, zd, p1a.G_E, p1a.CV_E, p1a.CU_E)\n        spikes_m += sm\n        spikes_e += se\n        for i in range(ff):\n            for o in range(d):\n                B[i, o] += eta * M[i] * E[o]\n    return B, spikes_e, spikes_m\n\n\n@njit(cache=True)\ndef train_w1_deep_local(\n    u,\n    z,\n    targets,\n    masses,\n    W_R,\n    B_R,\n    B_2,\n    W1_init,\n    mask,\n    b1,\n    theta,\n    W2,\n    b2,\n    n_paths,\n    lr,\n    seed,\n    m_off=False,\n):\n    """Deep local W1 learning through two learned feedback populations."""\n    np.random.seed(seed)\n    nctx = u.shape[0]\n    ff, d = W1_init.shape\n    W1 = W1_init.copy()\n\n    ve = np.full(d, p1a.V0, dtype=np.float64)\n    ue = np.full(d, p1a.U0, dtype=np.float64)\n    vm = np.full(ff, p1a.V0, dtype=np.float64)\n    um = np.full(ff, p1a.U0, dtype=np.float64)\n    ze = np.zeros(d, dtype=np.float64)\n    zm = np.zeros(ff, dtype=np.float64)\n\n    cdf = np.cumsum(masses)\n    cdf[-1] = 1.0\n    spikes_e = 0\n    spikes_m = 0\n\n    for _p in range(n_paths):\n        # Frozen within the 27-force-step path, as in P0-E/P1-A/P1-B.\n        W0 = W1.copy()\n        accum = np.zeros_like(W1)\n        for _k in range(p1a.FORCE_STEPS):\n            r = np.random.random()\n            ci = 0\n            while ci < nctx - 1 and r > cdf[ci]:\n                ci += 1\n\n            pre = u[ci]\n            h = np.empty(ff, dtype=np.float64)\n            for i in range(ff):\n                s = b1[i] - theta[i]\n                for j in range(d):\n                    s += W0[i, j] * pre[j]\n                h[i] = s if s > 0.0 else 0.0\n\n            y = z[ci].copy()\n            for o in range(d):\n                s = b2[o]\n                for i in range(ff):\n                    s += W2[o, i] * h[i]\n                y[o] += s\n\n            ss = 0.0\n            for o in range(d):\n                ss += y[o] * y[o]\n            rms = math.sqrt(ss / d) + 1e-8\n\n            logits = np.empty(p1a.V, dtype=np.float64)\n            for v in range(p1a.V):\n                s = 0.5 * W_R[v, d]\n                for o in range(d):\n                    s += W_R[v, o] * (0.5 * y[o] / rms)\n                logits[v] = s\n            probs = p1a.softmax_numba(logits)\n\n            target = p1a.sample_categorical_numba(targets[ci])\n            err = np.zeros(p1a.V, dtype=np.float64)\n            err[target] = 1.0\n            for v in range(p1a.V):\n                err[v] -= probs[v]\n\n            drive_h = np.zeros(ff, dtype=np.float64)\n            if not m_off:\n                drive_y = np.zeros(d, dtype=np.float64)\n                for o in range(d):\n                    for v in range(p1a.V):\n                        drive_y[o] += B_R[o, v] * err[v]\n                for i in range(ff):\n                    for o in range(d):\n                        drive_h[i] += B_2[i, o] * drive_y[o]\n\n            E, se = p1a.fast_izh_step(\n                ve, ue, pre, ze, p1a.G_E, p1a.CV_E, p1a.CU_E\n            )\n            spikes_e += se\n            if m_off:\n                M = np.zeros(ff, dtype=np.float64)\n            else:\n                M, sm = p1a.fast_izh_step(\n                    vm, um, drive_h, zm, p1a.G_M, p1a.CV_M, p1a.CU_M\n                )\n                spikes_m += sm\n\n            for i in range(ff):\n                for j in range(d):\n                    if mask[i, j] != 0.0:\n                        accum[i, j] += M[i] * E[j]\n\n        for i in range(ff):\n            for j in range(d):\n                if mask[i, j] != 0.0:\n                    W1[i, j] += lr * accum[i, j] / p1a.FORCE_STEPS\n                else:\n                    W1[i, j] = 0.0\n\n    return W1, spikes_e, spikes_m\n\n\ndef train_gradient_w1_reference(\n    u, z, W1_init, mask, b1, theta, W2, b2, W_R, targets, masses\n):\n    """Capacity/reference only; candidate never reads these gradients/weights."""\n    ut = torch.tensor(u, dtype=torch.float32)\n    zt = torch.tensor(z, dtype=torch.float32)\n    raw = torch.tensor(W1_init, dtype=torch.float32, requires_grad=True)\n    mask_t = torch.tensor(mask, dtype=torch.float32)\n    b1_t = torch.tensor(b1, dtype=torch.float32)\n    th_t = torch.tensor(theta, dtype=torch.float32)\n    W2_t = torch.tensor(W2, dtype=torch.float32)\n    b2_t = torch.tensor(b2, dtype=torch.float32)\n    WR_t = torch.tensor(W_R, dtype=torch.float32)\n    T = torch.tensor(targets, dtype=torch.float32)\n    Mass = torch.tensor(masses, dtype=torch.float32)\n    opt = torch.optim.LBFGS([raw], lr=0.5, max_iter=500, line_search_fn="strong_wolfe")\n\n    def closure():\n        opt.zero_grad()\n        W = raw * mask_t\n        h = F.relu(F.linear(ut, W, b1_t) - th_t)\n        y = zt + F.linear(h, W2_t, b2_t)\n        feat = p1a.normalize_readout_feature(y)\n        feat = torch.cat([feat, torch.full((feat.shape[0], 1), 0.5)], dim=1)\n        logp = F.log_softmax(feat @ WR_t.T, dim=1)\n        loss = -(Mass[:, None] * T * logp).sum()\n        loss.backward()\n        return loss\n\n    opt.step(closure)\n    return (raw.detach() * mask_t).cpu().numpy().astype(np.float64)\n\n\ndef set_block_w1(block, W1):\n    with torch.no_grad():\n        block.f1.weight.copy_(torch.tensor(W1, dtype=block.f1.weight.dtype))\n\n\ndef generation_for_w1(block, tok, pos, W_R, W1, n_generate, seed):\n    set_block_w1(block, W1)\n    return p1a.autonomous_generate(block, tok, pos, W_R, n_generate, seed, GEN_BATCH)\n\n\ndef summarize(vals: Sequence[float]) -> Dict[str, float]:\n    a = np.asarray(vals, dtype=np.float64)\n    return {\n        "mean": float(a.mean()),\n        "std": float(a.std()),\n        "min": float(a.min()),\n        "max": float(a.max()),\n    }\n\n\ndef cosine(a, b):\n    return float(np.sum(a * b) / (np.linalg.norm(a) * np.linalg.norm(b) + 1e-30))\n\n\ndef main():\n    outdir = Path(__file__).resolve().parent\n    torch.set_num_threads(4)\n    torch.manual_seed(p1a.TORCH_INIT_SEED)\n    np.random.seed(1234)\n\n    true_dist = p1a.enumerate_true_distribution()\n    tok, pos = p1a.build_embeddings()\n    block = p1a.FrozenSNNTransformBlock().eval()\n    keys, arrays, targets, masses, z, hidden0, u = build_prefix_internal(\n        block, tok, pos, true_dist\n    )\n\n    W1_init = (block.f1.weight * block.f1.mask).detach().cpu().numpy().astype(np.float64)\n    mask1 = block.f1.mask.detach().cpu().numpy().astype(np.float64)\n    b1 = block.f1.bias.detach().cpu().numpy().astype(np.float64)\n    theta = block.theta.detach().cpu().numpy().astype(np.float64)\n    W2 = (block.f2.weight * block.f2.mask).detach().cpu().numpy().astype(np.float64)\n    b2 = block.f2.bias.detach().cpu().numpy().astype(np.float64)\n\n    # Regenerate accepted P1-A readout on the exact baseline feature core.\n    base_feat = p1b.readout_features_from_w2(z, hidden0, W2, b2)\n    W_R, readout_E_spikes, readout_M_spikes = p1a.train_msdl_readout(\n        base_feat, targets, masses, READOUT_PATHS, READOUT_LR, READOUT_SEED, False\n    )\n\n    baseline = evaluate_w1(\n        W1_init, u, z, b1, theta, W2, b2, W_R, targets, masses, keys\n    )\n\n    # Capacity references.\n    W1_grad = train_gradient_w1_reference(\n        u, z, W1_init, mask1, b1, theta, W2, b2, W_R, targets, masses\n    )\n    grad_metrics = evaluate_w1(\n        W1_grad, u, z, b1, theta, W2, b2, W_R, targets, masses, keys\n    )\n    available_gradient_gap = baseline["expected_nll"] - grad_metrics["expected_nll"]\n\n    # Development summary: frozen before definitive seeds below.\n    dev_rows = []\n    B_R_dev, _, _ = learn_feedback_BR_msdl(\n        W_R, MIRROR_STEPS, MIRROR_SIGMA, MIRROR_ETA_BR, 9101\n    )\n    B_2_dev, _, _ = learn_feedback_B2_msdl(\n        W2, MIRROR_STEPS, MIRROR_SIGMA, MIRROR_ETA_B2, 9103\n    )\n    for lr in DEV_LRS:\n        vals = []\n        for seed in DEV_SEEDS:\n            W1, _, _ = train_w1_deep_local(\n                u, z, targets, masses, W_R, B_R_dev, B_2_dev,\n                W1_init, mask1, b1, theta, W2, b2,\n                DEV_PATHS, lr, seed, False,\n            )\n            vals.append(evaluate_w1(\n                W1, u, z, b1, theta, W2, b2, W_R, targets, masses, keys\n            )["expected_nll"])\n        dev_rows.append({\n            "lr": lr,\n            "nlls": vals,\n            "mean_nll": float(np.mean(vals)),\n            "std_nll": float(np.std(vals)),\n        })\n    selected_by_dev = min(dev_rows, key=lambda r: r["mean_nll"])["lr"]\n    if abs(selected_by_dev - SELECTED_LR) > 1e-15:\n        raise AssertionError((selected_by_dev, SELECTED_LR))\n\n    # Exact reciprocal MSDL reference on the same W1 rule. This is a reference,\n    # not candidate execution.\n    exact_BR = W_R[:, :p1a.D].T.copy()\n    exact_B2 = W2.T.copy()\n    exact_runs = []\n    for seed in FINAL_SEEDS:\n        W1_exact, _, _ = train_w1_deep_local(\n            u, z, targets, masses, W_R, exact_BR, exact_B2,\n            W1_init, mask1, b1, theta, W2, b2,\n            FINAL_PATHS, SELECTED_LR, seed, False,\n        )\n        exact_runs.append(evaluate_w1(\n            W1_exact, u, z, b1, theta, W2, b2, W_R, targets, masses, keys\n        )["expected_nll"])\n    exact_msdl_mean_nll = float(np.mean(exact_runs))\n    exact_msdl_improvement = baseline["expected_nll"] - exact_msdl_mean_nll\n\n    # Causal controls on development feedback, before final seed evaluation.\n    rng = np.random.default_rng(777)\n    BR_random = rng.normal(size=B_R_dev.shape)\n    BR_random *= np.linalg.norm(B_R_dev) / (np.linalg.norm(BR_random) + 1e-30)\n    B2_random = rng.normal(size=B_2_dev.shape)\n    B2_random *= np.linalg.norm(B_2_dev) / (np.linalg.norm(B2_random) + 1e-30)\n    controls = {}\n    for name, BRc, B2c, moff in (\n        ("negative_BR", -B_R_dev, B_2_dev, False),\n        ("random_same_norm", BR_random, B2_random, False),\n        ("zero_feedback", np.zeros_like(B_R_dev), np.zeros_like(B_2_dev), False),\n        ("M_off", B_R_dev, B_2_dev, True),\n    ):\n        Wc, se, sm = train_w1_deep_local(\n            u, z, targets, masses, W_R, BRc, B2c,\n            W1_init, mask1, b1, theta, W2, b2,\n            CONTROL_PATHS, SELECTED_LR, DEV_SEEDS[0], moff,\n        )\n        met = evaluate_w1(\n            Wc, u, z, b1, theta, W2, b2, W_R, targets, masses, keys\n        )\n        controls[name] = {\n            **met,\n            "max_abs_weight_change": float(np.max(np.abs(Wc - W1_init))),\n            "off_mask_max_abs": float(np.max(np.abs(Wc * (1.0 - mask1)))),\n            "E_spikes": int(se),\n            "M_spikes": int(sm),\n        }\n\n    # Baseline autonomous generation.\n    base_block = copy.deepcopy(block).eval()\n    base_samples = generation_for_w1(base_block, tok, pos, W_R, W1_init, 20000, 88001)\n    base_gen = p1b.generation_metrics(base_samples, true_dist)\n\n    final_runs = []\n    saved = None\n    for ri, seed in enumerate(FINAL_SEEDS):\n        # Each definitive system learns its feedback pathways independently from\n        # zero using distinct perturbation streams.\n        B_R, se_br, sm_br = learn_feedback_BR_msdl(\n            W_R, MIRROR_STEPS, MIRROR_SIGMA, MIRROR_ETA_BR, 50000 + seed\n        )\n        B_2, se_b2, sm_b2 = learn_feedback_B2_msdl(\n            W2, MIRROR_STEPS, MIRROR_SIGMA, MIRROR_ETA_B2, 60000 + seed\n        )\n        br_cos = cosine(B_R, exact_BR)\n        b2_cos = cosine(B_2, exact_B2)\n\n        W1, se, sm = train_w1_deep_local(\n            u, z, targets, masses, W_R, B_R, B_2,\n            W1_init, mask1, b1, theta, W2, b2,\n            FINAL_PATHS, SELECTED_LR, seed, False,\n        )\n        met = evaluate_w1(\n            W1, u, z, b1, theta, W2, b2, W_R, targets, masses, keys\n        )\n        gap_closed = (\n            (baseline["expected_nll"] - met["expected_nll"]) / available_gradient_gap\n            if available_gradient_gap > 1e-12 else float("nan")\n        )\n        exact_fraction = (\n            (baseline["expected_nll"] - met["expected_nll"]) / exact_msdl_improvement\n            if exact_msdl_improvement > 1e-12 else float("nan")\n        )\n\n        block_i = copy.deepcopy(block).eval()\n        samples = generation_for_w1(\n            block_i, tok, pos, W_R, W1, N_GENERATE, 100000 + seed\n        )\n        gmet = p1b.generation_metrics(samples, true_dist)\n\n        row = {\n            "seed": seed,\n            **met,\n            "nll_improvement_vs_frozen_W1": baseline["expected_nll"] - met["expected_nll"],\n            "conditional_js_improvement_vs_frozen_W1": baseline["conditional_js"] - met["conditional_js"],\n            "long_range_mae_improvement_vs_frozen_W1": baseline["exact_long_range_branch_mae"] - met["exact_long_range_branch_mae"],\n            "gradient_W1_nll_gap_closed_fraction": gap_closed,\n            "learned_feedback_fraction_of_exact_msdl_improvement": exact_fraction,\n            "BR_cosine_to_transpose_reference": br_cos,\n            "B2_cosine_to_transpose_reference": b2_cos,\n            "BR_norm": float(np.linalg.norm(B_R)),\n            "B2_norm": float(np.linalg.norm(B_2)),\n            "weight_change_rel_l2": float(np.linalg.norm(W1 - W1_init) / (np.linalg.norm(W1_init) + 1e-30)),\n            "off_mask_max_abs": float(np.max(np.abs(W1 * (1.0 - mask1)))),\n            "feedback_E_spikes": int(se_br + se_b2),\n            "feedback_M_spikes": int(sm_br + sm_b2),\n            "learning_E_spikes": int(se),\n            "learning_M_spikes": int(sm),\n            "generation": gmet,\n        }\n        final_runs.append(row)\n        if ri == 0:\n            saved = {\n                "W1": W1,\n                "B_R": B_R,\n                "B_2": B_2,\n                "W_R": W_R,\n                "W2": W2,\n                "samples": samples[:2000],\n                "mask1": mask1,\n            }\n\n    scalar_names = [\n        "expected_nll", "conditional_js", "expected_token_support",\n        "exact_long_range_branch_mae", "nll_improvement_vs_frozen_W1",\n        "conditional_js_improvement_vs_frozen_W1",\n        "long_range_mae_improvement_vs_frozen_W1",\n        "gradient_W1_nll_gap_closed_fraction",\n        "learned_feedback_fraction_of_exact_msdl_improvement",\n        "BR_cosine_to_transpose_reference", "B2_cosine_to_transpose_reference",\n        "weight_change_rel_l2", "off_mask_max_abs",\n    ]\n    agg = {name: summarize([r[name] for r in final_runs]) for name in scalar_names}\n    gen_names = [\n        "joint_js_with_invalid_bucket", "valid_sequence_fraction",\n        "token_support_rate", "mode_tv", "true_mode_coverage_fraction",\n        "long_range_branch_mae",\n    ]\n    gen_agg = {name: summarize([r["generation"][name] for r in final_runs]) for name in gen_names}\n\n    gates = {\n        "deep_W1_nll_improves": agg["nll_improvement_vs_frozen_W1"]["mean"] > GATE_THRESHOLDS["mean_nll_improvement_gt"],\n        "deep_W1_js_improves": agg["conditional_js_improvement_vs_frozen_W1"]["mean"] > GATE_THRESHOLDS["mean_js_improvement_gt"],\n        "deep_W1_long_range_improves": agg["long_range_mae_improvement_vs_frozen_W1"]["mean"] > GATE_THRESHOLDS["mean_long_range_mae_improvement_gt"],\n        "deep_W1_closes_gradient_gap": agg["gradient_W1_nll_gap_closed_fraction"]["mean"] > GATE_THRESHOLDS["mean_gradient_gap_closed_fraction_gt"],\n        "BR_feedback_self_aligns": agg["BR_cosine_to_transpose_reference"]["mean"] > GATE_THRESHOLDS["mean_feedback_BR_cos_gt"],\n        "B2_feedback_self_aligns": agg["B2_cosine_to_transpose_reference"]["mean"] > GATE_THRESHOLDS["mean_feedback_B2_cos_gt"],\n        "learned_feedback_near_exact_msdl_credit": agg["learned_feedback_fraction_of_exact_msdl_improvement"]["mean"] > GATE_THRESHOLDS["learned_feedback_fraction_of_exact_msdl_improvement_gt"],\n        "autonomous_validity_improves": gen_agg["valid_sequence_fraction"]["mean"] - base_gen["valid_sequence_fraction"] > GATE_THRESHOLDS["mean_generation_validity_improvement_gt"],\n        "autonomous_joint_js_improves": base_gen["joint_js_with_invalid_bucket"] - gen_agg["joint_js_with_invalid_bucket"]["mean"] > GATE_THRESHOLDS["mean_generation_joint_js_improvement_gt"],\n        "W1_sparse_mask_preserved": agg["off_mask_max_abs"]["max"] == GATE_THRESHOLDS["off_mask_max_abs_eq"],\n        "M_off_no_learning": controls["M_off"]["max_abs_weight_change"] == GATE_THRESHOLDS["m_off_max_weight_change_eq"],\n        "random_feedback_fails": controls["random_same_norm"]["expected_nll"] > baseline["expected_nll"] + GATE_THRESHOLDS["random_feedback_nll_gt_baseline_by"],\n        "negative_feedback_fails": controls["negative_BR"]["expected_nll"] > baseline["expected_nll"] + GATE_THRESHOLDS["negative_feedback_nll_gt_baseline_by"],\n    }\n\n    results = {\n        "gate": "P1-C deep local mismatch formation with learned reciprocal pathways",\n        "scientific_scope": "cloud numerical gate; learned feedback pathways plus W1 plasticity; no Q/K/V credit, no continual regime, no SpiNNaker",\n        "task": {\n            "same_stochastic_token_task_as_P1A": True,\n            "vocab": p1a.V,\n            "length": p1a.N,\n            "true_sequences": len(true_dist),\n            "exact_prefix_contexts": len(keys),\n        },\n        "candidate": {\n            "plastic_forward_synapses": "W1 only, fixed 25% structural mask",\n            "feedback_synapses": "B_R and B_2 learned independently from zero by local perturbation-driven MSDL E/M outer products",\n            "feedback_weight_transport": False,\n            "candidate_autograd_or_BPTT": False,\n            "readout": "accepted P1-A MSDL readout regenerated deterministically",\n            "W2": "original frozen SNN-Transform W2, intentionally not P1-B learned W2 to isolate the deeper W1-credit question",\n        },\n        "mirror_protocol": {\n            "steps": MIRROR_STEPS,\n            "sigma": MIRROR_SIGMA,\n            "eta_BR": MIRROR_ETA_BR,\n            "eta_B2": MIRROR_ETA_B2,\n            "interpretation": "local perturbation/response self-calibration; transpose used only after training as an offline alignment diagnostic",\n        },\n        "development": {\n            "seeds": DEV_SEEDS,\n            "paths": DEV_PATHS,\n            "candidates": dev_rows,\n            "selected_lr": SELECTED_LR,\n        },\n        "baseline": baseline,\n        "gradient_W1_reference": grad_metrics,\n        "gradient_available_nll_gap": available_gradient_gap,\n        "exact_feedback_MSDL_reference": {\n            "final_seed_nlls": exact_runs,\n            "mean_nll": exact_msdl_mean_nll,\n            "nll_improvement": exact_msdl_improvement,\n        },\n        "controls": controls,\n        "baseline_generation": base_gen,\n        "final_paths": FINAL_PATHS,\n        "final_seeds": FINAL_SEEDS,\n        "final_runs": final_runs,\n        "final_aggregate": agg,\n        "generation_aggregate": gen_agg,\n        "thresholds": GATE_THRESHOLDS,\n        "gates": gates,\n        "pass": bool(all(gates.values())),\n        "claim_boundary": {\n            "verified_if_pass": [\n                "Two successive feedback pathways can self-align from local perturbation/response dynamics without copying forward transposes.",\n                "Those learned pathways can carry categorical mismatch two population hops inward and train actual sparse SNN-Transform W1 synapses by MSDL dynamics.",\n                "The resulting W1 change improves exact probabilistic metrics and autonomous generation relative to frozen W1.",\n            ],\n            "not_verified": [\n                "fully endogenous simultaneous formation of all forward and feedback pathways from zero",\n                "Q/K/V or attention-internal credit assignment",\n                "continuous never-stop learning/generation",\n                "SpiNNaker execution",\n            ],\n        },\n    }\n\n    (outdir / "P1C_RESULTS.json").write_text(json.dumps(results, indent=2), encoding="utf-8")\n    (outdir / "P1C_DEV_CALIBRATION.json").write_text(json.dumps({\n        "development_seeds": DEV_SEEDS,\n        "paths": DEV_PATHS,\n        "candidates": dev_rows,\n        "selected_lr": SELECTED_LR,\n        "mirror_protocol": results["mirror_protocol"],\n    }, indent=2), encoding="utf-8")\n    np.savez_compressed(outdir / "P1C_DEEP_W1_EXAMPLE.npz", **saved)\n\n    print(json.dumps({\n        "pass": results["pass"],\n        "baseline_nll": baseline["expected_nll"],\n        "gradient_nll": grad_metrics["expected_nll"],\n        "exact_feedback_msdl_nll": exact_msdl_mean_nll,\n        "candidate_nll": agg["expected_nll"],\n        "candidate_nll_improvement": agg["nll_improvement_vs_frozen_W1"],\n        "BR_cos": agg["BR_cosine_to_transpose_reference"],\n        "B2_cos": agg["B2_cosine_to_transpose_reference"],\n        "learned_feedback_fraction_exact": agg["learned_feedback_fraction_of_exact_msdl_improvement"],\n        "base_generation": base_gen,\n        "candidate_generation": gen_agg,\n        "gates": gates,\n    }, indent=2))\n\n\nif __name__ == "__main__":\n    main()\n\'\'\'\n\n# ========================= p1d2_self_experienced_msdl.py =========================\n_EMBEDDED[\'p1d2_self_experienced_msdl\'] = r\'\'\'#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n"""P1-D2: self-experienced / on-policy prefix learning for MSDL-plastic W_O.\n\nGoal\n----\nP1-D showed that local MSDL dynamics can train the sparse attention-output\nprojection W_O, but autonomous valid-sequence fraction did not improve. P1-D2\nchanges *experience sampling*, not the synaptic rule: a fraction of learning\npaths are generated by the model\'s own current policy. The learning populations\ntherefore visit prefixes induced by the current generator itself.\n\nThe local plasticity remains exactly\n    dW_O = eta * (M_z E_a^T) * mask_O\nwith the same learned B_R feedback as P1-D. No autograd/BPTT is used.\n\nImportant boundary\n------------------\nThe exact toy grammar defines targets only on valid prefixes. During an on-policy\npath, valid model-sampled tokens are committed and become the next context. If\nan out-of-support token is sampled, that generation attempt is counted and the\nself-experience episode restarts at the empty prefix. Thus this gate tests\non-policy *valid-prefix* exposure and pre-error decisions; it does not yet learn\nfrom arbitrary invalid-prefix states.\n"""\nfrom __future__ import annotations\nimport copy, json, math\nfrom pathlib import Path\nfrom typing import Sequence\nimport numpy as np\nfrom numba import njit\n\nimport p1a_msdl_token_generation as p1a\nimport p1b_internal_w2_msdl as p1b\nimport p1c_deep_local_mismatch as p1c\nimport p1d_attention_output_msdl as p1d\n\n# Frozen after development in explore_p1d2.py / explore_focus.py, before FINAL_SEEDS.\nSELECTED_LR = 0.20\nP_SELF = 0.30\nP_IID = 0.25\nP_TRUE_COHERENT = 0.45\nFINAL_PATHS = 5000\nFINAL_SEEDS = [7207, 7307, 7411]\nN_GENERATE = 10000\nCONTROL_PATHS = 2500\n\n# Frozen before definitive seeds.\nGATES = {\n    \'same_lr_nll_improvement_gt\': 0.005,\n    \'same_lr_conditional_js_improvement_gt\': 0.002,\n    \'same_lr_generation_validity_improvement_gt\': 0.020,\n    \'same_lr_generation_joint_js_improvement_gt\': 0.015,\n    \'long_range_mae_degradation_lt\': 0.010,\n    \'vs_p1d_generation_validity_improvement_gt\': 0.025,\n    \'vs_p1d_generation_joint_js_improvement_gt\': 0.015,\n    \'off_mask_max_abs_eq\': 0.0,\n    \'m_off_max_weight_change_eq\': 0.0,\n}\n\n\ndef build_transitions(keys):\n    key_to_idx={k:i for i,k in enumerate(keys)}\n    nxt=np.full((len(keys),p1a.V),-1,dtype=np.int64)\n    ctx_pos=np.zeros(len(keys),dtype=np.int64)\n    for i,(t,prefix) in enumerate(keys):\n        ctx_pos[i]=t\n        if t < p1a.N-1:\n            for token in p1a.support_for_position(t):\n                k=(t+1,prefix+(token,))\n                if k in key_to_idx:\n                    nxt[i,token]=key_to_idx[k]\n    return nxt,ctx_pos,key_to_idx[(0,())]\n\n\ndef context_probs(WO, attended,xres,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,WR):\n    feat=p1d.forward_features_wo(WO,attended,xres,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2)\n    return p1a.probs_from_W(WR,feat)\n\n@njit(cache=True)\ndef _sample_idx_probs(p):\n    r=np.random.random(); c=0.0\n    for i in range(p.shape[0]):\n        c+=p[i]\n        if r<=c: return i\n    return p.shape[0]-1\n\n@njit(cache=True)\ndef train_wo_self_experience(\n    attended,xres,targets,masses,WR,BR,WO_init,mask,bo,\n    gamma2,beta2,eps2,W1,b1,theta,W2,b2,\n    seq_context_idx,seq_tokens,seq_probs,next_ctx,ctx_pos,root_ctx,\n    static_policy_probs,\n    n_paths,lr,seed,p_self,p_iid,\n    use_static_self_policy=False,reset_every_force=False,m_off=False,\n):\n    np.random.seed(seed)\n    nctx=attended.shape[0]; d=WO_init.shape[0]; ff=W1.shape[0]\n    WO=WO_init.copy()\n    ve=np.full(d,p1a.V0,dtype=np.float64); ue=np.full(d,p1a.U0,dtype=np.float64)\n    vm=np.full(d,p1a.V0,dtype=np.float64); um=np.full(d,p1a.U0,dtype=np.float64)\n    ze=np.zeros(d,dtype=np.float64); zm=np.zeros(d,dtype=np.float64)\n    cdf=np.cumsum(masses); cdf[-1]=1.0\n    scdf=np.cumsum(seq_probs); scdf[-1]=1.0\n    sched=np.empty(p1a.FORCE_STEPS,dtype=np.int64); kk=0\n    for t in range(p1a.N):\n        for _ in range(p1d.POSITION_COUNTS[t]): sched[kk]=t; kk+=1\n\n    invalid_self_samples=0; total_self_samples=0; self_paths=0\n    spikes_e=0; spikes_m=0\n\n    for _p in range(n_paths):\n        rr=np.random.random()\n        is_self=rr < p_self\n        is_iid=(not is_self) and (rr < p_self+p_iid)\n        coherent=(not is_self) and (not is_iid)\n        if is_self: self_paths+=1\n        si=-1\n        if coherent:\n            r=np.random.random(); si=0\n            while si<scdf.shape[0]-1 and r>scdf[si]: si+=1\n        W0=WO.copy(); accum=np.zeros_like(WO)\n        ci_self=root_ctx; rep_self=0\n\n        for sk in range(p1a.FORCE_STEPS):\n            if reset_every_force:\n                for j in range(d):\n                    ve[j]=p1a.V0; ue[j]=p1a.U0; vm[j]=p1a.V0; um[j]=p1a.U0\n\n            if is_self:\n                ci=ci_self\n                target=p1a.sample_categorical_numba(targets[ci])\n            elif coherent:\n                t=int(sched[sk]); ci=int(seq_context_idx[si,t]); target=int(seq_tokens[si,t])\n            else:\n                r=np.random.random(); ci=0\n                while ci<nctx-1 and r>cdf[ci]: ci+=1\n                target=p1a.sample_categorical_numba(targets[ci])\n\n            a=attended[ci]\n            z=np.empty(d,dtype=np.float64)\n            for o in range(d):\n                s=xres[ci,o]+bo[o]\n                for j in range(d): s+=W0[o,j]*a[j]\n                z[o]=s\n            mu=0.0\n            for o in range(d): mu+=z[o]\n            mu/=d\n            var=0.0\n            for o in range(d):\n                q=z[o]-mu; var+=q*q\n            var/=d\n            inv=1.0/math.sqrt(var+eps2)\n            u=np.empty(d,dtype=np.float64)\n            for o in range(d): u[o]=(z[o]-mu)*inv*gamma2[o]+beta2[o]\n            h=np.empty(ff,dtype=np.float64)\n            for i in range(ff):\n                s=b1[i]-theta[i]\n                for j in range(d): s+=W1[i,j]*u[j]\n                h[i]=s if s>0.0 else 0.0\n            y=z.copy()\n            for o in range(d):\n                s=b2[o]\n                for i in range(ff): s+=W2[o,i]*h[i]\n                y[o]+=s\n            ss=0.0\n            for o in range(d): ss+=y[o]*y[o]\n            rms=math.sqrt(ss/d)+1e-8\n            logits=np.empty(p1a.V,dtype=np.float64)\n            for v in range(p1a.V):\n                s=0.5*WR[v,d]\n                for o in range(d): s+=WR[v,o]*(0.5*y[o]/rms)\n                logits[v]=s\n            probs=p1a.softmax_numba(logits)\n            err=np.empty(p1a.V,dtype=np.float64)\n            for v in range(p1a.V): err[v]=-probs[v]\n            err[target]+=1.0\n            drive=np.zeros(d,dtype=np.float64)\n            if not m_off:\n                for o in range(d):\n                    for v in range(p1a.V): drive[o]+=BR[o,v]*err[v]\n            E,se=p1a.fast_izh_step(ve,ue,a,ze,p1a.G_E,p1a.CV_E,p1a.CU_E); spikes_e+=se\n            if m_off:\n                M=np.zeros(d,dtype=np.float64)\n            else:\n                M,sm=p1a.fast_izh_step(vm,um,drive,zm,p1a.G_M,p1a.CV_M,p1a.CU_M); spikes_m+=sm\n            for o in range(d):\n                for j in range(d):\n                    if mask[o,j]!=0.0: accum[o,j]+=M[o]*E[j]\n\n            if is_self:\n                rep_self+=1\n                tcur=int(ctx_pos[ci_self]); need=int(p1d.POSITION_COUNTS[tcur])\n                if rep_self>=need:\n                    if use_static_self_policy:\n                        sampled=_sample_idx_probs(static_policy_probs[ci_self])\n                    else:\n                        sampled=_sample_idx_probs(probs)\n                    total_self_samples+=1\n                    if tcur==p1a.N-1:\n                        ci_self=root_ctx; rep_self=0\n                    else:\n                        ni=next_ctx[ci_self,sampled]\n                        if ni>=0:\n                            ci_self=int(ni); rep_self=0\n                        else:\n                            invalid_self_samples+=1\n                            ci_self=root_ctx; rep_self=0\n\n        for o in range(d):\n            for j in range(d):\n                if mask[o,j]!=0.0: WO[o,j]+=lr*accum[o,j]/p1a.FORCE_STEPS\n                else: WO[o,j]=0.0\n\n    return WO,invalid_self_samples,total_self_samples,self_paths,spikes_e,spikes_m\n\n\ndef summarize(x:Sequence[float]):\n    a=np.asarray(x,dtype=np.float64)\n    return {\'mean\':float(a.mean()),\'std\':float(a.std()),\'min\':float(a.min()),\'max\':float(a.max())}\n\n\ndef main():\n    outdir=Path(__file__).resolve().parent\n    data=p1d.setup()\n    (true_dist,tok,pos,block,keys,targets,masses,attended,xres,WO,mask,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,WR,sci,st,sp,baseline)=data\n    nxt,cpos,root=build_transitions(keys)\n    static_probs=context_probs(WO,attended,xres,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,WR)\n    p1d_results=json.loads((outdir.parent/\'P1D_ATTENTION_OUTPUT_MSDL_20261014\'/\'P1D_RESULTS.json\').read_text())\n    p1d_gen=p1d_results[\'generation_aggregate\']\n    rows=[]\n    for seed in FINAL_SEEDS:\n        BR,_,_=p1c.learn_feedback_BR_msdl(WR,p1d.MIRROR_STEPS,p1d.MIRROR_SIGMA,p1d.MIRROR_ETA_BR,97000+seed)\n        # same-lr no-self comparator: identical rule/path count/BR, only experience mixture differs\n        W0,inv0,tot0,_,_,_=train_wo_self_experience(attended,xres,targets,masses,WR,BR,WO,mask,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,sci,st,sp,nxt,cpos,root,static_probs,FINAL_PATHS,SELECTED_LR,seed,0.0,P_IID,False,False,False)\n        m0=p1d.evaluate_wo(W0,attended,xres,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,WR,targets,masses,keys)\n        s0=p1d.generation_for_wo(copy.deepcopy(block).eval(),tok,pos,WR,W0,N_GENERATE,610000+seed)\n        g0=p1b.generation_metrics(s0,true_dist)\n\n        W,inv,tot,spth,se,sm=train_wo_self_experience(attended,xres,targets,masses,WR,BR,WO,mask,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,sci,st,sp,nxt,cpos,root,static_probs,FINAL_PATHS,SELECTED_LR,seed,P_SELF,P_IID,False,False,False)\n        met=p1d.evaluate_wo(W,attended,xres,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,WR,targets,masses,keys)\n        sam=p1d.generation_for_wo(copy.deepcopy(block).eval(),tok,pos,WR,W,N_GENERATE,620000+seed)\n        gm=p1b.generation_metrics(sam,true_dist)\n        row={\'seed\':seed,\'candidate\':met,\'generation\':gm,\'same_lr_no_self\':m0,\'same_lr_no_self_generation\':g0,\n             \'nll_improvement_vs_same_lr_no_self\':m0[\'expected_nll\']-met[\'expected_nll\'],\n             \'conditional_js_improvement_vs_same_lr_no_self\':m0[\'conditional_js\']-met[\'conditional_js\'],\n             \'long_range_change_vs_same_lr_no_self\':met[\'exact_long_range_branch_mae\']-m0[\'exact_long_range_branch_mae\'],\n             \'generation_validity_improvement_vs_same_lr_no_self\':gm[\'valid_sequence_fraction\']-g0[\'valid_sequence_fraction\'],\n             \'generation_joint_js_improvement_vs_same_lr_no_self\':g0[\'joint_js_with_invalid_bucket\']-gm[\'joint_js_with_invalid_bucket\'],\n             \'self_training_invalid_sample_rate\':inv/max(1,tot),\'self_paths\':int(spth),\n             \'off_mask_max_abs\':float(np.max(np.abs(W*(1-mask)))),\'learning_E_spikes\':int(se),\'learning_M_spikes\':int(sm)}\n        rows.append(row)\n        (outdir/f\'P1D2_FINAL_SEED_{seed}.json\').write_text(json.dumps(row,indent=2))\n        np.savez_compressed(outdir/f\'P1D2_FINAL_SEED_{seed}.npz\',W_O=W,W_O_no_self=W0,B_R=BR,samples=sam[:2000],samples_no_self=s0[:2000])\n        print(json.dumps(row,indent=2),flush=True)\n\n    # Aggregate definitive rows before controls.\n    cagg={k:summarize([r[\'candidate\'][k] for r in rows]) for k in [\'expected_nll\',\'conditional_js\',\'expected_token_support\',\'exact_long_range_branch_mae\']}\n    gagg={k:summarize([r[\'generation\'][k] for r in rows]) for k in [\'joint_js_with_invalid_bucket\',\'valid_sequence_fraction\',\'token_support_rate\',\'mode_tv\',\'true_mode_coverage_fraction\',\'long_range_branch_mae\']}\n    bcmp={k:summarize([r[\'same_lr_no_self\'][k] for r in rows]) for k in [\'expected_nll\',\'conditional_js\',\'expected_token_support\',\'exact_long_range_branch_mae\']}\n    bgcmp={k:summarize([r[\'same_lr_no_self_generation\'][k] for r in rows]) for k in [\'joint_js_with_invalid_bucket\',\'valid_sequence_fraction\',\'token_support_rate\',\'mode_tv\',\'true_mode_coverage_fraction\',\'long_range_branch_mae\']}\n    diffs={k:summarize([r[k] for r in rows]) for k in [\'nll_improvement_vs_same_lr_no_self\',\'conditional_js_improvement_vs_same_lr_no_self\',\'long_range_change_vs_same_lr_no_self\',\'generation_validity_improvement_vs_same_lr_no_self\',\'generation_joint_js_improvement_vs_same_lr_no_self\',\'self_training_invalid_sample_rate\',\'off_mask_max_abs\']}\n\n    # Causal/diagnostic controls on independent seed, shorter path budget.\n    seed=8819\n    BR,_,_=p1c.learn_feedback_BR_msdl(WR,p1d.MIRROR_STEPS,p1d.MIRROR_SIGMA,p1d.MIRROR_ETA_BR,99000+seed)\n    Wstatic,_,_,_,_,_=train_wo_self_experience(attended,xres,targets,masses,WR,BR,WO,mask,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,sci,st,sp,nxt,cpos,root,static_probs,CONTROL_PATHS,SELECTED_LR,seed,P_SELF,P_IID,True,False,False)\n    mstatic=p1d.evaluate_wo(Wstatic,attended,xres,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,WR,targets,masses,keys)\n    sstatic=p1d.generation_for_wo(copy.deepcopy(block).eval(),tok,pos,WR,Wstatic,5000,630000+seed); gstatic=p1b.generation_metrics(sstatic,true_dist)\n    Wreset,_,_,_,_,_=train_wo_self_experience(attended,xres,targets,masses,WR,BR,WO,mask,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,sci,st,sp,nxt,cpos,root,static_probs,CONTROL_PATHS,SELECTED_LR,seed,P_SELF,P_IID,False,True,False)\n    mreset=p1d.evaluate_wo(Wreset,attended,xres,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,WR,targets,masses,keys)\n    Wm,_,_,_,_,_=train_wo_self_experience(attended,xres,targets,masses,WR,BR,WO,mask,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,sci,st,sp,nxt,cpos,root,static_probs,CONTROL_PATHS,SELECTED_LR,seed,P_SELF,P_IID,False,False,True)\n    moff=float(np.max(np.abs(Wm-WO)))\n\n    p1d_valid=float(p1d_gen[\'valid_sequence_fraction\'][\'mean\']); p1d_js=float(p1d_gen[\'joint_js_with_invalid_bucket\'][\'mean\'])\n    gates={\n      \'same_lr_nll_improvement\':diffs[\'nll_improvement_vs_same_lr_no_self\'][\'mean\']>GATES[\'same_lr_nll_improvement_gt\'],\n      \'same_lr_conditional_js_improvement\':diffs[\'conditional_js_improvement_vs_same_lr_no_self\'][\'mean\']>GATES[\'same_lr_conditional_js_improvement_gt\'],\n      \'same_lr_generation_validity_improvement\':diffs[\'generation_validity_improvement_vs_same_lr_no_self\'][\'mean\']>GATES[\'same_lr_generation_validity_improvement_gt\'],\n      \'same_lr_generation_joint_js_improvement\':diffs[\'generation_joint_js_improvement_vs_same_lr_no_self\'][\'mean\']>GATES[\'same_lr_generation_joint_js_improvement_gt\'],\n      \'long_range_noninferior\':diffs[\'long_range_change_vs_same_lr_no_self\'][\'mean\']<GATES[\'long_range_mae_degradation_lt\'],\n      \'vs_p1d_generation_validity_improvement\':gagg[\'valid_sequence_fraction\'][\'mean\']-p1d_valid>GATES[\'vs_p1d_generation_validity_improvement_gt\'],\n      \'vs_p1d_generation_joint_js_improvement\':p1d_js-gagg[\'joint_js_with_invalid_bucket\'][\'mean\']>GATES[\'vs_p1d_generation_joint_js_improvement_gt\'],\n      \'sparse_mask_preserved\':diffs[\'off_mask_max_abs\'][\'max\']==GATES[\'off_mask_max_abs_eq\'],\n      \'M_off_no_learning\':moff==GATES[\'m_off_max_weight_change_eq\'],\n    }\n    results={\'stage\':\'P1-D2\',\'candidate\':\'MSDL-plastic sparse W_O with 30% on-policy self-experienced valid-prefix paths +45% true coherent +25% IID; same local rule as P1-D\',\n      \'selected\':{\'lr\':SELECTED_LR,\'p_self\':P_SELF,\'p_true_coherent\':P_TRUE_COHERENT,\'p_iid\':P_IID,\'paths\':FINAL_PATHS},\n      \'baseline_frozen\':baseline,\'p1d_reference_generation_aggregate\':p1d_gen,\'final_rows\':rows,\n      \'candidate_aggregate\':cagg,\'generation_aggregate\':gagg,\'same_lr_no_self_aggregate\':bcmp,\'same_lr_no_self_generation_aggregate\':bgcmp,\'differences\':diffs,\n      \'controls\':{\'static_off_policy_self_experience\':{\'conditional\':mstatic,\'generation\':gstatic},\'reset_every_force\':mreset,\'m_off_max_weight_change\':moff},\n      \'thresholds\':GATES,\'gates\':gates,\'pass\':bool(all(gates.values())),\n      \'claim_boundary\':{\n        \'verified_if_pass\':[\'Model-induced valid-prefix experience improves autonomous generation over otherwise matched no-self MSDL W_O training.\',\'The synaptic rule itself is unchanged from P1-D.\',\'The candidate remains local/dynamical and preserves sparse W_O topology.\'],\n        \'not_verified\':[\'learning after arbitrary invalid-prefix states\',\'full never-stop continual operation\',\'Q/K/V learning\',\'simultaneous from-zero whole-block learning\',\'28x28 scaling\',\'SpiNNaker execution\']}}\n    (outdir/\'P1D2_RESULTS.json\').write_text(json.dumps(results,indent=2))\n\n    lines=[\'# P1-D2 — self-experienced dynamical learning\',\'\',f\'Status: **{"PASS" if results["pass"] else "PARTIAL/FAIL"}**\',\'\',\n      \'## Frozen protocol\',f\'- W_O-only MSDL plasticity, unchanged local rule.\',f\'- Experience mix: {P_SELF:.0%} current-policy self-generated valid-prefix paths, {P_TRUE_COHERENT:.0%} true coherent paths, {P_IID:.0%} IID paths.\',f\'- lr={SELECTED_LR}, paths={FINAL_PATHS}, final seeds={FINAL_SEEDS}.\',\'\',\n      \'## Main results\',f\'- Same-lr no-self NLL: **{bcmp["expected_nll"]["mean"]:.6f}**; P1-D2: **{cagg["expected_nll"]["mean"]:.6f} ± {cagg["expected_nll"]["std"]:.6f}**.\',f\'- Same-lr no-self autonomous validity: **{bgcmp["valid_sequence_fraction"]["mean"]:.4f}**; P1-D2: **{gagg["valid_sequence_fraction"]["mean"]:.4f} ± {gagg["valid_sequence_fraction"]["std"]:.4f}**.\',f\'- Same-lr no-self joint JS: **{bgcmp["joint_js_with_invalid_bucket"]["mean"]:.6f}**; P1-D2: **{gagg["joint_js_with_invalid_bucket"]["mean"]:.6f}**.\',f\'- Long-range MAE no-self: **{bcmp["exact_long_range_branch_mae"]["mean"]:.6f}**; P1-D2: **{cagg["exact_long_range_branch_mae"]["mean"]:.6f}**.\',\'\',\n      \'## Controls\',f\'- Static/off-policy self replay NLL: **{mstatic["expected_nll"]:.6f}**, generation validity **{gstatic["valid_sequence_fraction"]:.4f}**.\',f\'- Reset E/M every force sample NLL: **{mreset["expected_nll"]:.6f}**.\',f\'- M-off max |ΔW_O|: **{moff:.3e}**.\',\'\',\n      \'## Gates\']\n    lines += [f\'- {k}: **{"PASS" if v else "FAIL"}**\' for k,v in gates.items()]\n    lines += [\'\', \'## Boundary\',\'Self-experience here means current-policy valid prefixes. An invalid sampled token terminates/restarts that self-experience episode; arbitrary invalid-prefix recovery is not yet learned.\']\n    (outdir/\'P1D2_REPORT.md\').write_text(\'\\n\'.join(lines)+\'\\n\')\n    (outdir/\'README_P1D2.md\').write_text(\'P1-D2 artifacts. Run `python p1d2_self_experienced_msdl.py` from this folder.\\n\')\n    print(json.dumps({\'gates\':gates,\'pass\':results[\'pass\'],\'candidate\':cagg,\'generation\':gagg,\'diffs\':diffs,\'controls\':results[\'controls\']},indent=2),flush=True)\n\nif __name__==\'__main__\': main()\n\'\'\'\n\n# ========================= p1d_attention_output_msdl.py =========================\n_EMBEDDED[\'p1d_attention_output_msdl\'] = r\'\'\'#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n"""P1-D: MSDL learning of the SNN-Transform attention output projection W_O.\n\nScientific question\n-------------------\nCan the same directed MSDL E/M plasticity used in P0-E/P1-A/P1-B/P1-C train\nan actual sparse synaptic population on the *attention side* of the frozen\nSNN-Transform block, without autograd/BPTT or explicit forward-weight\ntransposes in the candidate learner?\n\nOnly W_O is plastic. Q/K/V, feature map, W1, W2, LayerNorm parameters, sparse\nmasks, token embeddings, and the categorical readout are frozen.  The fixed\nreadout is learned first by the accepted P1-A MSDL protocol on the baseline\nblock. A reciprocal readout-feedback pathway B_R is then learned from local\nperturbation responses exactly as in P1-C; B_R is not copied from W_R^T.\n\nLocal rule\n----------\n  e_o = onehot(target) - p(token | context)\n  drive_z = B_R e_o\n  E_a = D_E(attended_feature)\n  M_z = D_M(drive_z)\n  dW_O = eta (M_z E_a^T) * mask_O\n\nBecause z = x + W_O a and y = z + FFN(z), the identity residual supplies a\nlocal direct z->y pathway. The candidate does NOT differentiate through the\nFFN, RMS normalization, softmax, LayerNorm, or attention equations.\n\nExperience stream uses the accepted P1-C2 75% coherent / 25% IID hybrid to\nretain dynamical temporal structure without adding new learning state.\n"""\nfrom __future__ import annotations\nimport argparse, copy, json, math\nfrom pathlib import Path\nfrom typing import Sequence\n\nimport numpy as np\nimport torch\nimport torch.nn.functional as F\nfrom numba import njit\n\nimport p1a_msdl_token_generation as p1a\nimport p1b_internal_w2_msdl as p1b\nimport p1c_deep_local_mismatch as p1c\nimport p1c2_trajectory_coherent_mismatch as p1c2\n\nP_COHERENT = 0.75\nREADOUT_PATHS = 12000\nREADOUT_LR = 0.6\nREADOUT_SEED = 101\nMIRROR_STEPS = 20000\nMIRROR_SIGMA = 0.1\nMIRROR_ETA_BR = 0.0338\nDEV_SEEDS = [5101, 5107, 5113]\nDEV_PATHS = 3000\nDEV_LRS = [0.10, 0.25, 0.50, 0.75, 1.00]\nFINAL_PATHS = 5000\nFINAL_SEEDS = [5209, 5303, 5413]\nN_GENERATE = 10000\nGEN_BATCH = 5000\nCONTROL_PATHS = 2500\n\n# Frozen BEFORE definitive FINAL_SEEDS are run.\nGATES = {\n    "mean_nll_improvement_gt": 0.015,\n    "mean_js_improvement_gt": 0.003,\n    "mean_long_range_mae_improvement_gt": 0.003,\n    "gradient_gap_closed_fraction_gt": 0.15,\n    "mean_generation_validity_improvement_gt": 0.025,\n    "mean_generation_joint_js_improvement_gt": 0.015,\n    "feedback_BR_cos_gt": 0.995,\n    "learned_feedback_fraction_of_exact_msdl_improvement_gt": 0.80,\n    "off_mask_max_abs_eq": 0.0,\n    "m_off_max_weight_change_eq": 0.0,\n    "wrong_sign_nll_gt_baseline_by": 0.25,\n}\n\nPOSITION_COUNTS = np.asarray([4,4,4,3,3,3,3,3], dtype=np.int64)\nassert int(POSITION_COUNTS.sum()) == p1a.FORCE_STEPS\n\n\ndef build_prefix_wo_internal(block, tok, pos, true_dist):\n    """Exact context distribution plus quantities upstream of W_O.\n\n    Since Q/K/V and phi are frozen, attended features a are independent of W_O.\n    x_res is the residual token vector at the queried position.\n    """\n    from collections import defaultdict\n    counts = defaultdict(lambda: np.zeros(p1a.V, dtype=np.float64))\n    mass = defaultdict(float)\n    for seq, prob in true_dist:\n        for t in range(p1a.N):\n            key = (t, seq[:t])\n            counts[key][seq[t]] += prob\n            mass[key] += prob\n    keys = list(counts.keys())\n    arrays = np.full((len(keys), p1a.N), p1a.MASK, dtype=np.int64)\n    targets = np.zeros((len(keys), p1a.V), dtype=np.float64)\n    masses = np.zeros(len(keys), dtype=np.float64)\n    target_pos = np.zeros(len(keys), dtype=np.int64)\n    for i,key in enumerate(keys):\n        t,prefix=key\n        arrays[i,:t]=prefix\n        targets[i]=counts[key]/mass[key]\n        masses[i]=mass[key]/p1a.N\n        target_pos[i]=t\n    with torch.no_grad():\n        x = p1a.encode(arrays, tok, pos)\n        xn = block.n1(x)\n        q=block._split(block.q(xn)); k=block._split(block.k(xn)); v=block._split(block.v(xn))\n        pq=block.phi_q(q,is_query=True); pk=block.phi_k(k,is_query=False)\n        H=torch.einsum(\'bhnm,bhnd->bhmd\',pk,v); g=pk.sum(dim=2)\n        num=torch.einsum(\'bhnm,bhmd->bhnd\',pq,H)\n        den=torch.einsum(\'bhnm,bhm->bhn\',pq,g).unsqueeze(-1).clamp_min(1e-8)\n        a_all=(num/den).transpose(1,2).reshape(len(keys),p1a.N,p1a.D)\n        row=torch.arange(len(keys)); col=torch.as_tensor(target_pos)\n        attended=a_all[row,col].cpu().numpy().astype(np.float64)\n        xres=x[row,col].cpu().numpy().astype(np.float64)\n    if abs(masses.sum()-1.0)>1e-12: raise AssertionError(masses.sum())\n    return keys,arrays,targets,masses,attended,xres\n\n\ndef layernorm_np(z, gamma, beta, eps):\n    mu=z.mean(axis=1,keepdims=True); var=((z-mu)**2).mean(axis=1,keepdims=True)\n    return (z-mu)/np.sqrt(var+eps)*gamma[None,:]+beta[None,:]\n\n\ndef forward_features_wo(WO, attended, xres, bo, gamma2, beta2, eps2, W1,b1,theta,W2,b2):\n    z=xres + attended@WO.T + bo[None,:]\n    u=layernorm_np(z,gamma2,beta2,eps2)\n    h=np.maximum(u@W1.T + b1[None,:]-theta[None,:],0.0)\n    y=z+h@W2.T+b2[None,:]\n    rms=np.sqrt(np.mean(y*y,axis=1,keepdims=True))+1e-8\n    f=y/rms*0.5\n    return np.concatenate([f,np.full((f.shape[0],1),0.5,dtype=np.float64)],axis=1)\n\n\ndef evaluate_wo(WO, attended,xres,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,WR,targets,masses,keys):\n    feat=forward_features_wo(WO,attended,xres,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2)\n    return p1a.evaluate_W(WR,feat,targets,masses,keys)\n\n\n@njit(cache=True)\ndef _sample_index(cdf):\n    r=np.random.random(); i=0\n    while i<cdf.shape[0]-1 and r>cdf[i]: i+=1\n    return i\n\n\n@njit(cache=True)\ndef train_wo_hybrid(\n    attended,xres,targets,masses,WR,BR,WO_init,mask,bo,\n    gamma2,beta2,eps2,W1,b1,theta,W2,b2,\n    seq_context_idx,seq_tokens,seq_probs,n_paths,lr,seed,p_coherent,\n    reset_every_force=False,m_off=False,feedback_sign=1.0,\n):\n    np.random.seed(seed)\n    nctx=attended.shape[0]; d=WO_init.shape[0]; ff=W1.shape[0]\n    WO=WO_init.copy()\n    ve=np.full(d,p1a.V0,dtype=np.float64); ue=np.full(d,p1a.U0,dtype=np.float64)\n    vm=np.full(d,p1a.V0,dtype=np.float64); um=np.full(d,p1a.U0,dtype=np.float64)\n    ze=np.zeros(d,dtype=np.float64); zm=np.zeros(d,dtype=np.float64)\n    cdf=np.cumsum(masses); cdf[-1]=1.0\n    scdf=np.cumsum(seq_probs); scdf[-1]=1.0\n    sched=np.empty(p1a.FORCE_STEPS,dtype=np.int64); kk=0\n    for t in range(p1a.N):\n        for _ in range(POSITION_COUNTS[t]): sched[kk]=t; kk+=1\n    spikes_e=0; spikes_m=0\n    for _p in range(n_paths):\n        coherent=np.random.random()<p_coherent\n        si=_sample_index(scdf) if coherent else -1\n        W0=WO.copy(); accum=np.zeros_like(WO)\n        for sk in range(p1a.FORCE_STEPS):\n            if reset_every_force:\n                for j in range(d):\n                    ve[j]=p1a.V0; ue[j]=p1a.U0; vm[j]=p1a.V0; um[j]=p1a.U0\n            if coherent:\n                t=int(sched[sk]); ci=int(seq_context_idx[si,t]); target=int(seq_tokens[si,t])\n            else:\n                r=np.random.random(); ci=0\n                while ci<nctx-1 and r>cdf[ci]: ci+=1\n                target=p1a.sample_categorical_numba(targets[ci])\n            a=attended[ci]\n            # z = x + W_O a + b_O\n            z=np.empty(d,dtype=np.float64)\n            for o in range(d):\n                s=xres[ci,o]+bo[o]\n                for j in range(d): s+=W0[o,j]*a[j]\n                z[o]=s\n            # LayerNorm2\n            mu=0.0\n            for o in range(d): mu+=z[o]\n            mu/=d\n            var=0.0\n            for o in range(d):\n                q=z[o]-mu; var+=q*q\n            var/=d\n            inv=1.0/math.sqrt(var+eps2)\n            u=np.empty(d,dtype=np.float64)\n            for o in range(d): u[o]=(z[o]-mu)*inv*gamma2[o]+beta2[o]\n            # fixed FFN\n            h=np.empty(ff,dtype=np.float64)\n            for i in range(ff):\n                s=b1[i]-theta[i]\n                for j in range(d): s+=W1[i,j]*u[j]\n                h[i]=s if s>0.0 else 0.0\n            y=z.copy()\n            for o in range(d):\n                s=b2[o]\n                for i in range(ff): s+=W2[o,i]*h[i]\n                y[o]+=s\n            ss=0.0\n            for o in range(d): ss+=y[o]*y[o]\n            rms=math.sqrt(ss/d)+1e-8\n            logits=np.empty(p1a.V,dtype=np.float64)\n            for v in range(p1a.V):\n                s=0.5*WR[v,d]\n                for o in range(d): s+=WR[v,o]*(0.5*y[o]/rms)\n                logits[v]=s\n            probs=p1a.softmax_numba(logits)\n            err=np.empty(p1a.V,dtype=np.float64)\n            for v in range(p1a.V): err[v]=-probs[v]\n            err[target]+=1.0\n            drive=np.zeros(d,dtype=np.float64)\n            if not m_off:\n                for o in range(d):\n                    for v in range(p1a.V): drive[o]+=feedback_sign*BR[o,v]*err[v]\n            E,se=p1a.fast_izh_step(ve,ue,a,ze,p1a.G_E,p1a.CV_E,p1a.CU_E); spikes_e+=se\n            if m_off:\n                M=np.zeros(d,dtype=np.float64)\n            else:\n                M,sm=p1a.fast_izh_step(vm,um,drive,zm,p1a.G_M,p1a.CV_M,p1a.CU_M); spikes_m+=sm\n            for o in range(d):\n                for j in range(d):\n                    if mask[o,j]!=0.0: accum[o,j]+=M[o]*E[j]\n        for o in range(d):\n            for j in range(d):\n                if mask[o,j]!=0.0: WO[o,j]+=lr*accum[o,j]/p1a.FORCE_STEPS\n                else: WO[o,j]=0.0\n    return WO,spikes_e,spikes_m\n\n\ndef train_gradient_wo_reference(attended,xres,bo,gamma2,beta2,eps2,WO_init,mask,W1,b1,theta,W2,b2,WR,targets,masses):\n    A=torch.tensor(attended,dtype=torch.float32); X=torch.tensor(xres,dtype=torch.float32)\n    bo_t=torch.tensor(bo,dtype=torch.float32); g=torch.tensor(gamma2,dtype=torch.float32); be=torch.tensor(beta2,dtype=torch.float32)\n    m=torch.tensor(mask,dtype=torch.float32); raw=torch.tensor(WO_init,dtype=torch.float32,requires_grad=True)\n    W1t=torch.tensor(W1,dtype=torch.float32); b1t=torch.tensor(b1,dtype=torch.float32); th=torch.tensor(theta,dtype=torch.float32)\n    W2t=torch.tensor(W2,dtype=torch.float32); b2t=torch.tensor(b2,dtype=torch.float32); WRt=torch.tensor(WR,dtype=torch.float32)\n    T=torch.tensor(targets,dtype=torch.float32); Mass=torch.tensor(masses,dtype=torch.float32)\n    opt=torch.optim.LBFGS([raw],lr=1.0,max_iter=500,line_search_fn=\'strong_wolfe\')\n    def closure():\n        opt.zero_grad(); W=raw*m\n        z=X+A@W.T+bo_t\n        u=F.layer_norm(z,(p1a.D,),g,be,eps2)\n        h=F.relu(u@W1t.T+b1t-th)\n        y=z+h@W2t.T+b2t\n        feat=p1a.normalize_readout_feature(y)\n        feat=torch.cat([feat,torch.full((feat.shape[0],1),0.5)],dim=1)\n        logp=F.log_softmax(feat@WRt.T,dim=1)\n        loss=-(Mass[:,None]*T*logp).sum(); loss.backward(); return loss\n    opt.step(closure)\n    return (raw.detach()*m).cpu().numpy().astype(np.float64)\n\n\ndef set_block_wo(block,WO):\n    with torch.no_grad(): block.out.weight.copy_(torch.tensor(WO,dtype=block.out.weight.dtype))\n\n\ndef generation_for_wo(block,tok,pos,WR,WO,n_generate,seed):\n    set_block_wo(block,WO)\n    return p1a.autonomous_generate(block,tok,pos,WR,n_generate,seed,GEN_BATCH)\n\n\ndef cosine(a,b): return float(np.sum(a*b)/(np.linalg.norm(a)*np.linalg.norm(b)+1e-30))\n\ndef summarize(vals:Sequence[float]):\n    a=np.asarray(vals,dtype=np.float64); return {\'mean\':float(a.mean()),\'std\':float(a.std()),\'min\':float(a.min()),\'max\':float(a.max())}\n\n\ndef setup():\n    torch.set_num_threads(4); torch.manual_seed(p1a.TORCH_INIT_SEED); np.random.seed(1234)\n    true_dist=p1a.enumerate_true_distribution(); tok,pos=p1a.build_embeddings(); block=p1a.FrozenSNNTransformBlock().eval()\n    keys,arrays,targets,masses,attended,xres=build_prefix_wo_internal(block,tok,pos,true_dist)\n    WO=(block.out.weight*block.out.mask).detach().cpu().numpy().astype(np.float64); mask=block.out.mask.detach().cpu().numpy().astype(np.float64)\n    bo=block.out.bias.detach().cpu().numpy().astype(np.float64)\n    gamma2=block.n2.weight.detach().cpu().numpy().astype(np.float64); beta2=block.n2.bias.detach().cpu().numpy().astype(np.float64); eps2=float(block.n2.eps)\n    W1=(block.f1.weight*block.f1.mask).detach().cpu().numpy().astype(np.float64); b1=block.f1.bias.detach().cpu().numpy().astype(np.float64); theta=block.theta.detach().cpu().numpy().astype(np.float64)\n    W2=(block.f2.weight*block.f2.mask).detach().cpu().numpy().astype(np.float64); b2=block.f2.bias.detach().cpu().numpy().astype(np.float64)\n    feat0=forward_features_wo(WO,attended,xres,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2)\n    WR,_,_=p1a.train_msdl_readout(feat0,targets,masses,READOUT_PATHS,READOUT_LR,READOUT_SEED,False)\n    baseline=p1a.evaluate_W(WR,feat0,targets,masses,keys)\n    sci,st,sp=p1c2.build_sequence_index(true_dist,keys)\n    return true_dist,tok,pos,block,keys,targets,masses,attended,xres,WO,mask,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,WR,sci,st,sp,baseline\n\n\ndef run_dev(outdir:Path):\n    (*_,)=()\n    data=setup(); (true_dist,tok,pos,block,keys,targets,masses,attended,xres,WO,mask,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,WR,sci,st,sp,baseline)=data\n    BR,_,_=p1c.learn_feedback_BR_msdl(WR,MIRROR_STEPS,MIRROR_SIGMA,MIRROR_ETA_BR,9151)\n    rows=[]\n    for lr in DEV_LRS:\n        mets=[]\n        for seed in DEV_SEEDS:\n            W,_,_=train_wo_hybrid(attended,xres,targets,masses,WR,BR,WO,mask,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,sci,st,sp,DEV_PATHS,lr,seed,P_COHERENT,False,False,1.0)\n            mets.append(evaluate_wo(W,attended,xres,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,WR,targets,masses,keys))\n        row={\'lr\':lr,\'mean_nll\':float(np.mean([m[\'expected_nll\'] for m in mets])),\'mean_js\':float(np.mean([m[\'conditional_js\'] for m in mets])),\'mean_lr_mae\':float(np.mean([m[\'exact_long_range_branch_mae\'] for m in mets])),\'nll_improvement\':baseline[\'expected_nll\']-float(np.mean([m[\'expected_nll\'] for m in mets]))}\n        rows.append(row); print(row,flush=True)\n    # Select development LR by NLL, tie-breaking with long-range MAE.\n    best=sorted(rows,key=lambda r:(r[\'mean_nll\'],r[\'mean_lr_mae\']))[0]\n    (outdir/\'P1D_DEV_CALIBRATION.json\').write_text(json.dumps({\'baseline\':baseline,\'rows\':rows,\'selected_lr\':best[\'lr\']},indent=2),encoding=\'utf-8\')\n    print(\'SELECTED_LR\',best[\'lr\'])\n\n\ndef run_final_seed(seed:int,lr:float,outdir:Path):\n    data=setup(); (true_dist,tok,pos,block,keys,targets,masses,attended,xres,WO,mask,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,WR,sci,st,sp,baseline)=data\n    BR,sebr,smbr=p1c.learn_feedback_BR_msdl(WR,MIRROR_STEPS,MIRROR_SIGMA,MIRROR_ETA_BR,90000+seed)\n    W,se,sm=train_wo_hybrid(attended,xres,targets,masses,WR,BR,WO,mask,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,sci,st,sp,FINAL_PATHS,lr,seed,P_COHERENT,False,False,1.0)\n    met=evaluate_wo(W,attended,xres,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,WR,targets,masses,keys)\n    # exact-transpose MSDL diagnostic using same local dynamics, not gradient\n    Wex,_,_=train_wo_hybrid(attended,xres,targets,masses,WR,WR[:,:p1a.D].T.copy(),WO,mask,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,sci,st,sp,FINAL_PATHS,lr,seed,P_COHERENT,False,False,1.0)\n    mex=evaluate_wo(Wex,attended,xres,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,WR,targets,masses,keys)\n    samples=generation_for_wo(copy.deepcopy(block).eval(),tok,pos,WR,W,N_GENERATE,200000+seed)\n    gm=p1b.generation_metrics(samples,true_dist)\n    row={\'seed\':seed,\'lr\':lr,\'candidate\':met,\'exact_feedback_msdl\':mex,\n         \'nll_improvement_vs_frozen\':baseline[\'expected_nll\']-met[\'expected_nll\'],\n         \'js_improvement_vs_frozen\':baseline[\'conditional_js\']-met[\'conditional_js\'],\n         \'long_range_improvement_vs_frozen\':baseline[\'exact_long_range_branch_mae\']-met[\'exact_long_range_branch_mae\'],\n         \'exact_msdl_nll_improvement\':baseline[\'expected_nll\']-mex[\'expected_nll\'],\n         \'learned_feedback_fraction_of_exact_msdl_improvement\':(baseline[\'expected_nll\']-met[\'expected_nll\'])/(baseline[\'expected_nll\']-mex[\'expected_nll\']+1e-30),\n         \'BR_cosine\':cosine(BR,WR[:,:p1a.D].T),\n         \'off_mask_max_abs\':float(np.max(np.abs(W*(1-mask)))),\n         \'weight_change_rel_l2\':float(np.linalg.norm(W-WO)/(np.linalg.norm(WO)+1e-30)),\n         \'feedback_E_spikes\':int(sebr),\'feedback_M_spikes\':int(smbr),\'learning_E_spikes\':int(se),\'learning_M_spikes\':int(sm),\n         \'generation\':gm}\n    (outdir/f\'P1D_FINAL_SEED_{seed}.json\').write_text(json.dumps(row,indent=2),encoding=\'utf-8\')\n    np.savez_compressed(outdir/f\'P1D_FINAL_SEED_{seed}.npz\',W_O=W,B_R=BR,W_R=WR,mask_O=mask,samples=samples[:2000])\n    print(json.dumps(row,indent=2),flush=True)\n\n\ndef aggregate(lr:float,outdir:Path):\n    rows=[json.loads((outdir/f\'P1D_FINAL_SEED_{s}.json\').read_text()) for s in FINAL_SEEDS]\n    data=setup(); (true_dist,tok,pos,block,keys,targets,masses,attended,xres,WO,mask,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,WR,sci,st,sp,baseline)=data\n    WOgrad=train_gradient_wo_reference(attended,xres,bo,gamma2,beta2,eps2,WO,mask,W1,b1,theta,W2,b2,WR,targets,masses)\n    grad=evaluate_wo(WOgrad,attended,xres,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,WR,targets,masses,keys)\n    gradient_gap=baseline[\'expected_nll\']-grad[\'expected_nll\']\n    base_samples=generation_for_wo(copy.deepcopy(block).eval(),tok,pos,WR,WO,20000,88001)\n    base_gen=p1b.generation_metrics(base_samples,true_dist)\n    # causal controls with independent feedback calibration\n    BR,_,_=p1c.learn_feedback_BR_msdl(WR,MIRROR_STEPS,MIRROR_SIGMA,MIRROR_ETA_BR,9911)\n    Wm,_,_=train_wo_hybrid(attended,xres,targets,masses,WR,BR,WO,mask,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,sci,st,sp,CONTROL_PATHS,lr,1901,P_COHERENT,False,True,1.0)\n    moff=float(np.max(np.abs(Wm-WO)))\n    Wneg,_,_=train_wo_hybrid(attended,xres,targets,masses,WR,BR,WO,mask,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,sci,st,sp,CONTROL_PATHS,lr,1901,P_COHERENT,False,False,-1.0)\n    neg=evaluate_wo(Wneg,attended,xres,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,WR,targets,masses,keys)\n    # persistent-state control\n    Wr,_,_=train_wo_hybrid(attended,xres,targets,masses,WR,BR,WO,mask,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,sci,st,sp,CONTROL_PATHS,lr,1901,P_COHERENT,True,False,1.0)\n    reset=evaluate_wo(Wr,attended,xres,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,WR,targets,masses,keys)\n    cagg={k:summarize([r[\'candidate\'][k] for r in rows]) for k in [\'expected_nll\',\'conditional_js\',\'expected_token_support\',\'exact_long_range_branch_mae\']}\n    gagg={k:summarize([r[\'generation\'][k] for r in rows]) for k in [\'joint_js_with_invalid_bucket\',\'valid_sequence_fraction\',\'token_support_rate\',\'mode_tv\',\'true_mode_coverage_fraction\',\'long_range_branch_mae\']}\n    agg={k:summarize([r[k] for r in rows]) for k in [\'nll_improvement_vs_frozen\',\'js_improvement_vs_frozen\',\'long_range_improvement_vs_frozen\',\'learned_feedback_fraction_of_exact_msdl_improvement\',\'BR_cosine\',\'off_mask_max_abs\',\'weight_change_rel_l2\']}\n    gap_fraction=agg[\'nll_improvement_vs_frozen\'][\'mean\']/(gradient_gap+1e-30)\n    gates={\n      \'nll_improvement\':agg[\'nll_improvement_vs_frozen\'][\'mean\']>GATES[\'mean_nll_improvement_gt\'],\n      \'js_improvement\':agg[\'js_improvement_vs_frozen\'][\'mean\']>GATES[\'mean_js_improvement_gt\'],\n      \'long_range_improvement\':agg[\'long_range_improvement_vs_frozen\'][\'mean\']>GATES[\'mean_long_range_mae_improvement_gt\'],\n      \'gradient_gap_closed\':gap_fraction>GATES[\'gradient_gap_closed_fraction_gt\'],\n      \'generation_validity\':gagg[\'valid_sequence_fraction\'][\'mean\']-base_gen[\'valid_sequence_fraction\']>GATES[\'mean_generation_validity_improvement_gt\'],\n      \'generation_joint_js\':base_gen[\'joint_js_with_invalid_bucket\']-gagg[\'joint_js_with_invalid_bucket\'][\'mean\']>GATES[\'mean_generation_joint_js_improvement_gt\'],\n      \'BR_self_aligned\':agg[\'BR_cosine\'][\'mean\']>GATES[\'feedback_BR_cos_gt\'],\n      \'learned_feedback_near_exact\':agg[\'learned_feedback_fraction_of_exact_msdl_improvement\'][\'mean\']>GATES[\'learned_feedback_fraction_of_exact_msdl_improvement_gt\'],\n      \'sparse_mask_preserved\':agg[\'off_mask_max_abs\'][\'max\']==GATES[\'off_mask_max_abs_eq\'],\n      \'M_off_no_learning\':moff==GATES[\'m_off_max_weight_change_eq\'],\n      \'wrong_sign_fails\':neg[\'expected_nll\']>baseline[\'expected_nll\']+GATES[\'wrong_sign_nll_gt_baseline_by\'],\n    }\n    results={\'stage\':\'P1-D\',\'candidate\':\'MSDL-plastic sparse W_O only; learned B_R; 75% coherent + 25% IID experience; no derivatives\',\'selected_lr\':lr,\n      \'baseline\':baseline,\'gradient_WO_only\':grad,\'gradient_available_nll_gap\':gradient_gap,\'gradient_gap_closed_fraction\':gap_fraction,\n      \'baseline_generation\':base_gen,\'final_rows\':rows,\'candidate_aggregate\':cagg,\'generation_aggregate\':gagg,\'aggregate\':agg,\n      \'controls\':{\'m_off_max_weight_change\':moff,\'negative_feedback\':neg,\'reset_every_force\':reset},\n      \'thresholds\':GATES,\'gates\':gates,\'pass\':bool(all(gates.values())),\n      \'claim_boundary\':{\n        \'verified_if_pass\':[\'Directed MSDL can modify the sparse attention-output projection W_O of SNN-Transform and improve probabilistic generation.\',\'The candidate does not use autograd/BPTT or explicit forward transpose; its readout feedback is locally self-aligned.\',\'The sparse W_O topology is preserved.\'],\n        \'not_verified\':[\'Q/K/V learning\',\'phi or H/g plasticity\',\'simultaneous from-zero learning of all SNN-Transform layers\',\'continual never-stop learning\',\'28x28 scaling\',\'SpiNNaker execution\']}}\n    (outdir/\'P1D_RESULTS.json\').write_text(json.dumps(results,indent=2),encoding=\'utf-8\')\n    lines=[\n      \'# P1-D — MSDL learning of the sparse attention output projection $W_O$\\n\\n\',\n      f"Status: **{\'PASS\' if results[\'pass\'] else \'PARTIAL/FAIL\'}**\\n\\n",\n      \'## Question\\nCan MSDL cross from the FFN side into the attention side by training the actual 25%-sparse $W_O$ projection, while Q/K/V and the attention state remain frozen?\\n\\n\',\n      \'## Candidate\\nOnly $W_O$ is plastic. The local update is $\\\\Delta W_O=\\\\eta(M_zE_a^T)\\\\odot S_O$. $E_a$ is driven by the attended feature. $M_z$ is driven by categorical mismatch through a feedback pathway $B_R$ learned from zero by local perturbation responses. No candidate derivative is computed through the FFN, LayerNorm, RMS normalization, softmax, or attention. The experience stream is 75% trajectory-coherent and 25% IID, as frozen in P1-C2.\\n\\n\',\n      \'## Final results\\n\',\n      f"- Frozen W_O NLL: **{baseline[\'expected_nll\']:.6f}**. Candidate: **{cagg[\'expected_nll\'][\'mean\']:.6f} ± {cagg[\'expected_nll\'][\'std\']:.6f}**. Improvement: **{agg[\'nll_improvement_vs_frozen\'][\'mean\']:.6f}**.\\n",\n      f"- Conditional JS: {baseline[\'conditional_js\']:.6f} -> **{cagg[\'conditional_js\'][\'mean\']:.6f}**.\\n",\n      f"- Long-range MAE: {baseline[\'exact_long_range_branch_mae\']:.6f} -> **{cagg[\'exact_long_range_branch_mae\'][\'mean\']:.6f}**.\\n",\n      f"- W_O-only gradient reference NLL: **{grad[\'expected_nll\']:.6f}**; MSDL closes **{100*gap_fraction:.2f}%** of this available NLL gap.\\n",\n      f"- Mean learned $B_R$ alignment with $W_R^T$ (diagnostic only): **{agg[\'BR_cosine\'][\'mean\']:.6f}**.\\n",\n      f"- Learned-feedback fraction of exact-feedback MSDL improvement: **{100*agg[\'learned_feedback_fraction_of_exact_msdl_improvement\'][\'mean\']:.2f}%**.\\n",\n      f"- Autonomous valid-sequence fraction: {base_gen[\'valid_sequence_fraction\']:.4f} -> **{gagg[\'valid_sequence_fraction\'][\'mean\']:.4f}**.\\n",\n      f"- Autonomous joint JS: {base_gen[\'joint_js_with_invalid_bucket\']:.6f} -> **{gagg[\'joint_js_with_invalid_bucket\'][\'mean\']:.6f}**.\\n\\n",\n      \'## Causal controls\\n\',\n      f"- M off: max $|\\\\Delta W_O|$ = **{moff:.3e}**.\\n",\n      f"- Wrong-sign feedback NLL: **{neg[\'expected_nll\']:.6f}**.\\n",\n      f"- Reset E/M every force sample NLL: **{reset[\'expected_nll\']:.6f}**.\\n",\n      f"- Off-mask max absolute weight: **{agg[\'off_mask_max_abs\'][\'max\']:.3e}**.\\n\\n",\n      \'## Gates\\n\']\n    for k,v in gates.items(): lines.append(f"- {k}: **{\'PASS\' if v else \'FAIL\'}**\\n")\n    lines += [\'\\n## Boundary\\nPassing P1-D would establish plasticity of the attention-output projection, not learning of Q/K/V or of the attention feature dynamics/state themselves. Those remain the next scientific frontier.\\n\']\n    (outdir/\'P1D_REPORT.md\').write_text(\'\'.join(lines),encoding=\'utf-8\')\n    print(json.dumps({\'pass\':results[\'pass\'],\'gates\':gates,\'candidate\':cagg,\'gradient\':grad,\'generation\':gagg,\'controls\':results[\'controls\']},indent=2),flush=True)\n\n\ndef main():\n    ap=argparse.ArgumentParser(); ap.add_argument(\'--dev\',action=\'store_true\'); ap.add_argument(\'--seed\',type=int); ap.add_argument(\'--aggregate\',action=\'store_true\'); ap.add_argument(\'--lr\',type=float)\n    args=ap.parse_args(); outdir=Path(__file__).resolve().parent\n    if args.dev: run_dev(outdir); return\n    if args.seed is not None:\n        if args.lr is None: raise SystemExit(\'--lr required with --seed\')\n        run_final_seed(args.seed,args.lr,outdir); return\n    if args.aggregate:\n        if args.lr is None: raise SystemExit(\'--lr required with --aggregate\')\n        aggregate(args.lr,outdir); return\n    raise SystemExit(\'use --dev, --seed N --lr X, or --aggregate --lr X\')\n\nif __name__==\'__main__\': main()\n\'\'\'\n\n# ========================= p1e1_value_msdl.py =========================\n_EMBEDDED[\'p1e1_value_msdl\'] = r\'\'\'#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n"""P1-E1: MSDL learning of SNN-Transform value projection W_V.\n\nScientific scope\n----------------\nThis is the first Q/K/V-side gate. Q, K and all downstream operators remain\nfrozen; only W_V is plastic. Because Q/K are frozen, normalized linear-attention\nrouting coefficients are fixed for a given context. The attended value for head h\ncan therefore be written exactly as\n\n    a_h = W_V[h-rows] @ s_h + b_V[h-rows]\n    s_h = sum_j alpha_hj xnorm_j\n\nwhere alpha_hj is the current normalized Q/K routing coefficient. This lets the\nshared W_V synapses receive a local relation-weighted presynaptic eligibility.\n\nOutput mismatch is routed through two learned reciprocal population couplings:\n    categorical error -> learned B_R -> block-output mismatch\n                      -> learned B_O -> attended-value mismatch\nNo transpose matrix is read by the candidate during learning. B_R and B_O are\nformed from local perturbation/response MSDL dynamics; transpose cosines are\npost-hoc diagnostics only.\n\nPlasticity:\n    dW_V[row, col] ~ M_a[row] * E_s[head(row), col]\n\nNo autograd/BPTT is used in the candidate. A W_V-only gradient reference is used\nonly to measure attainable capacity.\n"""\nfrom __future__ import annotations\nimport copy, json, math, sys\nfrom pathlib import Path\nfrom typing import Sequence\nimport numpy as np\nimport torch\nimport torch.nn.functional as F\nfrom numba import njit\n\nimport p1a_msdl_token_generation as p1a\nimport p1b_internal_w2_msdl as p1b\nimport p1c_deep_local_mismatch as p1c\nimport p1d_attention_output_msdl as p1d\nimport p1d2_self_experienced_msdl as p1d2\n\n# Development first; final seeds are disjoint.\nDEV_SEEDS = [8101, 8111, 8123]\nDEV_PATHS = 1600\nDEV_LRS = [0.05, 0.10, 0.20, 0.35, 0.50, 0.75]\nFINAL_SEEDS = [8209, 8219, 8231]\nFINAL_PATHS = 3500\nCONTROL_PATHS = 1600\nN_GENERATE = 10000\n\n# Use P1-D2 experience mixture because it passed autonomous-generation gates.\nP_SELF = 0.30\nP_IID = 0.25\n\nMIRROR_STEPS = 20000\nMIRROR_SIGMA = 0.10\nMIRROR_ETA_BR = 0.0338\nMIRROR_ETA_BO = 0.0335\n\nGATES = {\n    \'mean_nll_improvement_gt\': 0.010,\n    \'mean_conditional_js_improvement_gt\': 0.003,\n    \'mean_long_range_improvement_gt\': 0.010,\n    \'mean_generation_joint_js_improvement_gt\': 0.010,\n    \'generation_validity_noninferiority_gt\': -0.015,\n    \'feedback_BR_cos_gt\': 0.995,\n    \'feedback_BO_cos_gt\': 0.98,\n    \'m_off_max_weight_change_eq\': 0.0,\n    \'wrong_sign_nll_gt_baseline_by\': 0.20,\n}\n\n\ndef build_value_dataset(block, tok, pos, true_dist):\n    """Exact prefix dataset plus fixed Q/K routing and relation-weighted V inputs."""\n    from collections import defaultdict\n    counts = defaultdict(lambda: np.zeros(p1a.V, dtype=np.float64))\n    mass = defaultdict(float)\n    for seq, prob in true_dist:\n        for t in range(p1a.N):\n            key = (t, seq[:t])\n            counts[key][seq[t]] += prob\n            mass[key] += prob\n    keys = list(counts.keys())\n    arrays = np.full((len(keys), p1a.N), p1a.MASK, dtype=np.int64)\n    targets = np.zeros((len(keys), p1a.V), dtype=np.float64)\n    masses = np.zeros(len(keys), dtype=np.float64)\n    tpos = np.zeros(len(keys), dtype=np.int64)\n    for i, (t, prefix) in enumerate(keys):\n        arrays[i, :t] = prefix\n        targets[i] = counts[(t,prefix)] / mass[(t,prefix)]\n        masses[i] = mass[(t,prefix)] / p1a.N\n        tpos[i] = t\n\n    with torch.no_grad():\n        x = p1a.encode(arrays, tok, pos)\n        xn = block.n1(x)\n        q = block._split(block.q(xn))\n        k = block._split(block.k(xn))\n        pq = block.phi_q(q, is_query=True)\n        pk = block.phi_k(k, is_query=False)\n        row = torch.arange(len(keys))\n        ti = torch.as_tensor(tpos)\n        pqt = pq[row[:,None], torch.arange(p1a.HEADS)[None,:], ti[:,None], :]  # [C,H,M]\n        # score [C,H,N], denominator normalizes rows.\n        score = torch.einsum(\'chm,chnm->chn\', pqt, pk)\n        alpha = score / score.sum(dim=2, keepdim=True).clamp_min(1e-8)\n        # Exact relation-weighted presynaptic state s_h = sum_j alpha_hj xn_j.\n        s = torch.einsum(\'chn,cnd->chd\', alpha, xn)\n        xres = x[row, ti]\n    if abs(masses.sum()-1.0) > 1e-12:\n        raise AssertionError(masses.sum())\n    return keys, arrays, targets, masses, s.cpu().numpy().astype(np.float64), xres.cpu().numpy().astype(np.float64), alpha.cpu().numpy().astype(np.float64)\n\n\ndef attended_from_wv(WV, bv, s):\n    C,H,D = s.shape\n    hd = p1a.D // p1a.HEADS\n    out = np.zeros((C,p1a.D), dtype=np.float64)\n    for h in range(p1a.HEADS):\n        r0=h*hd; r1=(h+1)*hd\n        out[:,r0:r1] = s[:,h,:] @ WV[r0:r1,:].T + bv[None,r0:r1]\n    return out\n\n\ndef forward_features_wv(WV,bv,s,xres,WO,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2):\n    a=attended_from_wv(WV,bv,s)\n    return p1d.forward_features_wo(WO,a,xres,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2)\n\n\ndef evaluate_wv(WV,bv,s,xres,WO,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,WR,targets,masses,keys):\n    feat=forward_features_wv(WV,bv,s,xres,WO,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2)\n    return p1a.evaluate_W(WR,feat,targets,masses,keys)\n\n\n@njit(cache=True)\ndef learn_feedback_matrix_msdl(Wf, n_steps, sigma, eta, seed):\n    """Learn reciprocal B ~= Wf^T from local input perturbation and forward response."""\n    np.random.seed(seed)\n    out_dim, in_dim = Wf.shape\n    B=np.zeros((in_dim,out_dim),dtype=np.float64)\n    vm=np.full(in_dim,p1a.V0,dtype=np.float64); um=np.full(in_dim,p1a.U0,dtype=np.float64)\n    ve=np.full(out_dim,p1a.V0,dtype=np.float64); ue=np.full(out_dim,p1a.U0,dtype=np.float64)\n    zi=np.zeros(in_dim,dtype=np.float64); zo=np.zeros(out_dim,dtype=np.float64)\n    se=0; sm=0\n    for _ in range(n_steps):\n        dx=np.random.normal(0.0,sigma,in_dim)\n        dy=np.zeros(out_dim,dtype=np.float64)\n        for o in range(out_dim):\n            for j in range(in_dim): dy[o]+=Wf[o,j]*dx[j]\n        M,smi=p1a.fast_izh_step(vm,um,dx,zi,p1a.G_M,p1a.CV_M,p1a.CU_M)\n        E,sei=p1a.fast_izh_step(ve,ue,dy,zo,p1a.G_E,p1a.CV_E,p1a.CU_E)\n        sm+=smi; se+=sei\n        for j in range(in_dim):\n            for o in range(out_dim): B[j,o]+=eta*M[j]*E[o]\n    return B,se,sm\n\n\n@njit(cache=True)\ndef _sample_index(cdf):\n    r=np.random.random(); i=0\n    while i<cdf.shape[0]-1 and r>cdf[i]: i+=1\n    return i\n\n\n@njit(cache=True)\ndef train_wv(\n    s,xres,targets,masses,WR,BR,BO,WV_init,bv,WO,bo,\n    gamma2,beta2,eps2,W1,b1,theta,W2,b2,\n    seq_context_idx,seq_tokens,seq_probs,next_ctx,ctx_pos,root_ctx,static_policy_probs,\n    n_paths,lr,seed,p_self,p_iid,reset_every_force=False,m_off=False,feedback_sign=1.0,\n):\n    np.random.seed(seed)\n    C=s.shape[0]; H=s.shape[1]; d=p1a.D; hd=d//H; ff=W1.shape[0]\n    WV=WV_init.copy()\n    # E population has one D-dimensional state per attention head.\n    ve=np.full(H*d,p1a.V0,dtype=np.float64); ue=np.full(H*d,p1a.U0,dtype=np.float64)\n    vm=np.full(d,p1a.V0,dtype=np.float64); um=np.full(d,p1a.U0,dtype=np.float64)\n    ze=np.zeros(H*d,dtype=np.float64); zm=np.zeros(d,dtype=np.float64)\n    cdf=np.cumsum(masses); cdf[-1]=1.0\n    scdf=np.cumsum(seq_probs); scdf[-1]=1.0\n    sched=np.empty(p1a.FORCE_STEPS,dtype=np.int64); kk=0\n    for t in range(p1a.N):\n        for _ in range(p1d.POSITION_COUNTS[t]): sched[kk]=t; kk+=1\n    se=0; sm=0\n    for _p in range(n_paths):\n        rr=np.random.random(); is_self=rr<p_self; is_iid=(not is_self) and rr<p_self+p_iid; coherent=(not is_self) and (not is_iid)\n        si=-1\n        if coherent:\n            si=_sample_index(scdf)\n        W0=WV.copy(); accum=np.zeros_like(WV)\n        ci_self=root_ctx; rep_self=0\n        for sk in range(p1a.FORCE_STEPS):\n            if reset_every_force:\n                for j in range(H*d): ve[j]=p1a.V0; ue[j]=p1a.U0\n                for j in range(d): vm[j]=p1a.V0; um[j]=p1a.U0\n            if is_self:\n                ci=ci_self; target=p1a.sample_categorical_numba(targets[ci])\n            elif coherent:\n                t=int(sched[sk]); ci=int(seq_context_idx[si,t]); target=int(seq_tokens[si,t])\n            else:\n                ci=_sample_index(cdf); target=p1a.sample_categorical_numba(targets[ci])\n\n            # attended value from current frozen-within-path W0\n            a=np.empty(d,dtype=np.float64)\n            for h in range(H):\n                for rrh in range(hd):\n                    r=h*hd+rrh; val=bv[r]\n                    for j in range(d): val+=W0[r,j]*s[ci,h,j]\n                    a[r]=val\n            # fixed downstream block\n            z=np.empty(d,dtype=np.float64)\n            for o in range(d):\n                val=xres[ci,o]+bo[o]\n                for j in range(d): val+=WO[o,j]*a[j]\n                z[o]=val\n            mu=0.0\n            for o in range(d): mu+=z[o]\n            mu/=d; var=0.0\n            for o in range(d):\n                qq=z[o]-mu; var+=qq*qq\n            var/=d; inv=1.0/math.sqrt(var+eps2)\n            u=np.empty(d,dtype=np.float64)\n            for o in range(d): u[o]=(z[o]-mu)*inv*gamma2[o]+beta2[o]\n            hvec=np.empty(ff,dtype=np.float64)\n            for i in range(ff):\n                val=b1[i]-theta[i]\n                for j in range(d): val+=W1[i,j]*u[j]\n                hvec[i]=val if val>0.0 else 0.0\n            y=z.copy()\n            for o in range(d):\n                val=b2[o]\n                for i in range(ff): val+=W2[o,i]*hvec[i]\n                y[o]+=val\n            ss=0.0\n            for o in range(d): ss+=y[o]*y[o]\n            rms=math.sqrt(ss/d)+1e-8\n            logits=np.empty(p1a.V,dtype=np.float64)\n            for v in range(p1a.V):\n                val=0.5*WR[v,d]\n                for o in range(d): val+=WR[v,o]*(0.5*y[o]/rms)\n                logits[v]=val\n            probs=p1a.softmax_numba(logits)\n            err=np.empty(p1a.V,dtype=np.float64)\n            for v in range(p1a.V): err[v]=-probs[v]\n            err[target]+=1.0\n            drive_z=np.zeros(d,dtype=np.float64)\n            if not m_off:\n                for o in range(d):\n                    for v in range(p1a.V): drive_z[o]+=feedback_sign*BR[o,v]*err[v]\n            drive_a=np.zeros(d,dtype=np.float64)\n            if not m_off:\n                for j in range(d):\n                    for o in range(d): drive_a[j]+=BO[j,o]*drive_z[o]\n\n            # Relation-weighted shared-synapse pre eligibility: one population/head.\n            sinput=np.empty(H*d,dtype=np.float64)\n            for hh in range(H):\n                for j in range(d): sinput[hh*d+j]=s[ci,hh,j]\n            E,sei=p1a.fast_izh_step(ve,ue,sinput,ze,p1a.G_E,p1a.CV_E,p1a.CU_E); se+=sei\n            if m_off:\n                M=np.zeros(d,dtype=np.float64)\n            else:\n                M,smi=p1a.fast_izh_step(vm,um,drive_a,zm,p1a.G_M,p1a.CV_M,p1a.CU_M); sm+=smi\n            for r in range(d):\n                hh=r//hd\n                base=hh*d\n                for j in range(d): accum[r,j]+=M[r]*E[base+j]\n\n            if is_self:\n                rep_self+=1; tcur=int(ctx_pos[ci_self]); need=int(p1d.POSITION_COUNTS[tcur])\n                if rep_self>=need:\n                    sampled=_sample_index(np.cumsum(static_policy_probs[ci_self]))\n                    if tcur==p1a.N-1:\n                        ci_self=root_ctx; rep_self=0\n                    else:\n                        ni=next_ctx[ci_self,sampled]\n                        if ni>=0: ci_self=int(ni); rep_self=0\n                        else: ci_self=root_ctx; rep_self=0\n        for r in range(d):\n            for j in range(d): WV[r,j]+=lr*accum[r,j]/p1a.FORCE_STEPS\n    return WV,se,sm\n\n\ndef set_block_wv(block,WV):\n    with torch.no_grad(): block.v.weight.copy_(torch.tensor(WV,dtype=block.v.weight.dtype))\n\n\ndef generation_for_wv(block,tok,pos,WR,WV,n_generate,seed):\n    set_block_wv(block,WV)\n    return p1a.autonomous_generate(block,tok,pos,WR,n_generate,seed,p1a.GEN_BATCH)\n\n\ndef train_gradient_wv_reference(s,xres,bv,WO,bo,gamma2,beta2,eps2,WV_init,W1,b1,theta,W2,b2,WR,targets,masses):\n    S=torch.tensor(s,dtype=torch.float32); X=torch.tensor(xres,dtype=torch.float32)\n    bv_t=torch.tensor(bv,dtype=torch.float32); WO_t=torch.tensor(WO,dtype=torch.float32); bo_t=torch.tensor(bo,dtype=torch.float32)\n    g=torch.tensor(gamma2,dtype=torch.float32); be=torch.tensor(beta2,dtype=torch.float32)\n    raw=torch.tensor(WV_init,dtype=torch.float32,requires_grad=True)\n    W1t=torch.tensor(W1,dtype=torch.float32); b1t=torch.tensor(b1,dtype=torch.float32); th=torch.tensor(theta,dtype=torch.float32)\n    W2t=torch.tensor(W2,dtype=torch.float32); b2t=torch.tensor(b2,dtype=torch.float32); WRt=torch.tensor(WR,dtype=torch.float32)\n    T=torch.tensor(targets,dtype=torch.float32); Mass=torch.tensor(masses,dtype=torch.float32)\n    hd=p1a.D//p1a.HEADS\n    opt=torch.optim.LBFGS([raw],lr=1.0,max_iter=350,line_search_fn=\'strong_wolfe\')\n    def closure():\n        opt.zero_grad(); pieces=[]\n        for h in range(p1a.HEADS):\n            r0=h*hd; r1=(h+1)*hd\n            pieces.append(S[:,h,:]@raw[r0:r1,:].T+bv_t[r0:r1])\n        a=torch.cat(pieces,dim=1)\n        z=X+a@WO_t.T+bo_t\n        u=F.layer_norm(z,(p1a.D,),g,be,eps2)\n        h=F.relu(u@W1t.T+b1t-th)\n        y=z+h@W2t.T+b2t\n        feat=p1a.normalize_readout_feature(y)\n        feat=torch.cat([feat,torch.full((feat.shape[0],1),0.5)],dim=1)\n        logp=F.log_softmax(feat@WRt.T,dim=1)\n        loss=-(Mass[:,None]*T*logp).sum(); loss.backward(); return loss\n    opt.step(closure)\n    return raw.detach().cpu().numpy().astype(np.float64)\n\n\ndef cosine(a,b): return float(np.sum(a*b)/(np.linalg.norm(a)*np.linalg.norm(b)+1e-30))\ndef summarize(v:Sequence[float]):\n    a=np.asarray(v,dtype=np.float64); return {\'mean\':float(a.mean()),\'std\':float(a.std()),\'min\':float(a.min()),\'max\':float(a.max())}\n\n\ndef setup():\n    torch.set_num_threads(4); torch.manual_seed(p1a.TORCH_INIT_SEED); np.random.seed(1234)\n    true_dist=p1a.enumerate_true_distribution(); tok,pos=p1a.build_embeddings(); block=p1a.FrozenSNNTransformBlock().eval()\n    keys,arrays,targets,masses,s,xres,alpha=build_value_dataset(block,tok,pos,true_dist)\n    WV=block.v.weight.detach().cpu().numpy().astype(np.float64); bv=block.v.bias.detach().cpu().numpy().astype(np.float64)\n    WO=(block.out.weight*block.out.mask).detach().cpu().numpy().astype(np.float64); bo=block.out.bias.detach().cpu().numpy().astype(np.float64)\n    gamma2=block.n2.weight.detach().cpu().numpy().astype(np.float64); beta2=block.n2.bias.detach().cpu().numpy().astype(np.float64); eps2=float(block.n2.eps)\n    W1=(block.f1.weight*block.f1.mask).detach().cpu().numpy().astype(np.float64); b1=block.f1.bias.detach().cpu().numpy().astype(np.float64); theta=block.theta.detach().cpu().numpy().astype(np.float64)\n    W2=(block.f2.weight*block.f2.mask).detach().cpu().numpy().astype(np.float64); b2=block.f2.bias.detach().cpu().numpy().astype(np.float64)\n    feat0=forward_features_wv(WV,bv,s,xres,WO,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2)\n    WR,_,_=p1a.train_msdl_readout(feat0,targets,masses,p1d.READOUT_PATHS,p1d.READOUT_LR,p1d.READOUT_SEED,False)\n    baseline=p1a.evaluate_W(WR,feat0,targets,masses,keys)\n    sci,st,sp=p1c.p1c2.build_sequence_index(true_dist,keys) if hasattr(p1c,\'p1c2\') else (None,None,None)\n    # robustly use imported p1d2 dependency\'s p1c2 module\n    if sci is None:\n        import p1c2_trajectory_coherent_mismatch as p1c2\n        sci,st,sp=p1c2.build_sequence_index(true_dist,keys)\n    nxt,cpos,root=p1d2.build_transitions(keys)\n    static_probs=p1a.probs_from_W(WR,feat0)\n    return true_dist,tok,pos,block,keys,targets,masses,s,xres,alpha,WV,bv,WO,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,WR,sci,st,sp,nxt,cpos,root,static_probs,baseline\n\n\ndef run_dev(outdir:Path):\n    data=setup(); (true_dist,tok,pos,block,keys,targets,masses,s,xres,alpha,WV,bv,WO,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,WR,sci,st,sp,nxt,cpos,root,static_probs,baseline)=data\n    BR,_,_=p1c.learn_feedback_BR_msdl(WR,MIRROR_STEPS,MIRROR_SIGMA,MIRROR_ETA_BR,8011)\n    BO,_,_=learn_feedback_matrix_msdl(WO,MIRROR_STEPS,MIRROR_SIGMA,MIRROR_ETA_BO,8017)\n    rows=[]\n    for lr in DEV_LRS:\n        mets=[]\n        for seed in DEV_SEEDS:\n            W,_,_=train_wv(s,xres,targets,masses,WR,BR,BO,WV,bv,WO,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,sci,st,sp,nxt,cpos,root,static_probs,DEV_PATHS,lr,seed,P_SELF,P_IID,False,False,1.0)\n            mets.append(evaluate_wv(W,bv,s,xres,WO,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,WR,targets,masses,keys))\n        row={\'lr\':lr,\'mean_nll\':float(np.mean([m[\'expected_nll\'] for m in mets])),\'mean_js\':float(np.mean([m[\'conditional_js\'] for m in mets])),\'mean_lr_mae\':float(np.mean([m[\'exact_long_range_branch_mae\'] for m in mets]))}\n        rows.append(row); print(row,flush=True)\n    best=sorted(rows,key=lambda r:(r[\'mean_nll\'],r[\'mean_lr_mae\']))[0]\n    obj={\'baseline\':baseline,\'BO_cosine\':cosine(BO,WO.T),\'BR_cosine\':cosine(BR,WR[:,:p1a.D].T),\'rows\':rows,\'selected_lr\':best[\'lr\']}\n    (outdir/\'P1E1_DEV_CALIBRATION.json\').write_text(json.dumps(obj,indent=2),encoding=\'utf-8\')\n    print(\'SELECTED_LR\',best[\'lr\'],flush=True)\n    return float(best[\'lr\'])\n\n\ndef run_final(lr:float,outdir:Path):\n    data=setup(); (true_dist,tok,pos,block,keys,targets,masses,s,xres,alpha,WV,bv,WO,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,WR,sci,st,sp,nxt,cpos,root,static_probs,baseline)=data\n    base_samples=generation_for_wv(copy.deepcopy(block).eval(),tok,pos,WR,WV,20000,88801)\n    base_gen=p1b.generation_metrics(base_samples,true_dist)\n    rows=[]\n    for seed in FINAL_SEEDS:\n        BR,_,_=p1c.learn_feedback_BR_msdl(WR,MIRROR_STEPS,MIRROR_SIGMA,MIRROR_ETA_BR,90000+seed)\n        BO,_,_=learn_feedback_matrix_msdl(WO,MIRROR_STEPS,MIRROR_SIGMA,MIRROR_ETA_BO,91000+seed)\n        W,se,sm=train_wv(s,xres,targets,masses,WR,BR,BO,WV,bv,WO,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,sci,st,sp,nxt,cpos,root,static_probs,FINAL_PATHS,lr,seed,P_SELF,P_IID,False,False,1.0)\n        met=evaluate_wv(W,bv,s,xres,WO,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,WR,targets,masses,keys)\n        samples=generation_for_wv(copy.deepcopy(block).eval(),tok,pos,WR,W,N_GENERATE,300000+seed)\n        gm=p1b.generation_metrics(samples,true_dist)\n        row={\'seed\':seed,\'candidate\':met,\'generation\':gm,\'nll_improvement\':baseline[\'expected_nll\']-met[\'expected_nll\'],\'js_improvement\':baseline[\'conditional_js\']-met[\'conditional_js\'],\'long_range_improvement\':baseline[\'exact_long_range_branch_mae\']-met[\'exact_long_range_branch_mae\'],\'BR_cosine\':cosine(BR,WR[:,:p1a.D].T),\'BO_cosine\':cosine(BO,WO.T),\'weight_change_rel_l2\':float(np.linalg.norm(W-WV)/(np.linalg.norm(WV)+1e-30)),\'E_spikes\':int(se),\'M_spikes\':int(sm)}\n        rows.append(row)\n        (outdir/f\'P1E1_FINAL_SEED_{seed}.json\').write_text(json.dumps(row,indent=2),encoding=\'utf-8\')\n        np.savez_compressed(outdir/f\'P1E1_FINAL_SEED_{seed}.npz\',W_V=W,B_R=BR,B_O=BO,W_R=WR,samples=samples[:2000])\n        print(json.dumps(row,indent=2),flush=True)\n\n    WVgrad=train_gradient_wv_reference(s,xres,bv,WO,bo,gamma2,beta2,eps2,WV,W1,b1,theta,W2,b2,WR,targets,masses)\n    grad=evaluate_wv(WVgrad,bv,s,xres,WO,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,WR,targets,masses,keys)\n    BR,_,_=p1c.learn_feedback_BR_msdl(WR,MIRROR_STEPS,MIRROR_SIGMA,MIRROR_ETA_BR,99001)\n    BO,_,_=learn_feedback_matrix_msdl(WO,MIRROR_STEPS,MIRROR_SIGMA,MIRROR_ETA_BO,99007)\n    Wm,_,_=train_wv(s,xres,targets,masses,WR,BR,BO,WV,bv,WO,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,sci,st,sp,nxt,cpos,root,static_probs,CONTROL_PATHS,lr,8801,P_SELF,P_IID,False,True,1.0)\n    m_off=float(np.max(np.abs(Wm-WV)))\n    Wneg,_,_=train_wv(s,xres,targets,masses,WR,BR,BO,WV,bv,WO,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,sci,st,sp,nxt,cpos,root,static_probs,CONTROL_PATHS,lr,8801,P_SELF,P_IID,False,False,-1.0)\n    neg=evaluate_wv(Wneg,bv,s,xres,WO,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,WR,targets,masses,keys)\n    Wr,_,_=train_wv(s,xres,targets,masses,WR,BR,BO,WV,bv,WO,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,sci,st,sp,nxt,cpos,root,static_probs,CONTROL_PATHS,lr,8801,P_SELF,P_IID,True,False,1.0)\n    reset=evaluate_wv(Wr,bv,s,xres,WO,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,WR,targets,masses,keys)\n    cagg={k:summarize([r[\'candidate\'][k] for r in rows]) for k in [\'expected_nll\',\'conditional_js\',\'exact_long_range_branch_mae\',\'expected_token_support\']}\n    gagg={k:summarize([r[\'generation\'][k] for r in rows]) for k in [\'joint_js_with_invalid_bucket\',\'valid_sequence_fraction\',\'mode_tv\',\'true_mode_coverage_fraction\',\'long_range_branch_mae\']}\n    aagg={k:summarize([r[k] for r in rows]) for k in [\'nll_improvement\',\'js_improvement\',\'long_range_improvement\',\'BR_cosine\',\'BO_cosine\',\'weight_change_rel_l2\']}\n    gates={\n        \'mean_nll_improvement\':aagg[\'nll_improvement\'][\'mean\']>GATES[\'mean_nll_improvement_gt\'],\n        \'mean_conditional_js_improvement\':aagg[\'js_improvement\'][\'mean\']>GATES[\'mean_conditional_js_improvement_gt\'],\n        \'mean_long_range_improvement\':aagg[\'long_range_improvement\'][\'mean\']>GATES[\'mean_long_range_improvement_gt\'],\n        \'generation_joint_js_improvement\':base_gen[\'joint_js_with_invalid_bucket\']-gagg[\'joint_js_with_invalid_bucket\'][\'mean\']>GATES[\'mean_generation_joint_js_improvement_gt\'],\n        \'generation_validity_noninferiority\':gagg[\'valid_sequence_fraction\'][\'mean\']-base_gen[\'valid_sequence_fraction\']>GATES[\'generation_validity_noninferiority_gt\'],\n        \'feedback_BR\':aagg[\'BR_cosine\'][\'mean\']>GATES[\'feedback_BR_cos_gt\'],\n        \'feedback_BO\':aagg[\'BO_cosine\'][\'mean\']>GATES[\'feedback_BO_cos_gt\'],\n        \'m_off\':m_off==GATES[\'m_off_max_weight_change_eq\'],\n        \'wrong_sign\':neg[\'expected_nll\']>baseline[\'expected_nll\']+GATES[\'wrong_sign_nll_gt_baseline_by\'],\n    }\n    result={\'stage\':\'P1-E1 W_V\',\'selected_lr\':lr,\'baseline\':baseline,\'baseline_generation\':base_gen,\'candidate_aggregate\':cagg,\'generation_aggregate\':gagg,\'improvement_aggregate\':aagg,\'gradient_WV_only_reference\':grad,\'gradient_nll_opportunity\':baseline[\'expected_nll\']-grad[\'expected_nll\'],\'candidate_fraction_gradient_nll_opportunity\':aagg[\'nll_improvement\'][\'mean\']/(baseline[\'expected_nll\']-grad[\'expected_nll\']+1e-30),\'controls\':{\'m_off_max_weight_change\':m_off,\'wrong_sign\':neg,\'reset_every_force\':reset},\'gates\':gates,\'all_gates_pass\':bool(all(gates.values())),\'rows\':rows}\n    (outdir/\'P1E1_RESULTS.json\').write_text(json.dumps(result,indent=2),encoding=\'utf-8\')\n    print(json.dumps(result,indent=2),flush=True)\n    return result\n\n\ndef main():\n    outdir=Path(__file__).resolve().parent\n    lr=run_dev(outdir)\n    run_final(lr,outdir)\n\nif __name__==\'__main__\': main()\n\'\'\'\n\n# ========================= p1e4_joint_qkv_msdl.py =========================\n_EMBEDDED[\'p1e4_joint_qkv_msdl\'] = r\'\'\'#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n"""P1-E4: simultaneous MSDL plasticity of Q/K/V in SNN-Transform attention.\n\nScientific question\n-------------------\nE1/E2/E3 established W_V, W_K and W_Q separately. E4 asks whether the three\ninteracting attention populations can co-adapt *simultaneously* under the same\nlocal mismatch signal without global backpropagation or weight transport.\n\nWithin one MSDL path, W_Q/W_K/W_V are frozen while local E/M population states\naccumulate evidence. At the end of the path all three synaptic matrices update.\nThis preserves the frozen-v5 MSDL path semantics and avoids within-path update\nordering artifacts.\n\nLocal plasticity mechanisms:\n- V: exact relation-weighted presynaptic state s_h = sum_j alpha_hj x_j;\n     dW_V ~ M_a E_s^T.\n- K: token-local counterfactual key perturbations estimate each key population\'s\n     effect on the attended state; dW_K ~ M_k E_x^T.\n- Q: current-query counterfactual perturbation estimates relation-read credit;\n     dW_Q ~ M_q E_xquery^T.\n\nThe same learned reciprocal population couplings BR and BO route categorical\nmismatch to block-output and attended-state mismatch. Candidate learning never\nreads W_R^T or W_O^T; transpose cosines are post-hoc diagnostics only.\n"""\nfrom __future__ import annotations\nimport copy, json, math, sys\nfrom pathlib import Path\nfrom typing import Sequence\nimport numpy as np\nimport torch\nimport torch.nn.functional as F\nfrom numba import njit\n\nHERE=Path(__file__).resolve().parent\nsys.path.insert(0,str(HERE))\nimport p1a_msdl_token_generation as p1a\nimport p1b_internal_w2_msdl as p1b\nimport p1c_deep_local_mismatch as p1c\nimport p1c2_trajectory_coherent_mismatch as p1c2\nimport p1d_attention_output_msdl as p1d\nimport p1d2_self_experienced_msdl as p1d2\nimport p1e1_value_msdl as e1\n\n# Individual-stage calibrated rates used as a relative scale; E4 development\n# selects one common multiplier to test co-adaptation, rather than independently\n# retuning three degrees of freedom.\nBASE_LR_V=0.35\nBASE_LR_K=1.00\nBASE_LR_Q=1.20\nSIGMA_K=0.05\nSIGMA_Q=0.05\nP_SELF=0.30\nP_IID=0.25\n\nDEV_MULTS=[0.20,0.35,0.50,0.70,1.00]\nDEV_SEEDS=[8801,8819]\nDEV_PATHS=450\nFINAL_SEEDS=[8909,8923,8933]\nFINAL_PATHS=1400\nCONTROL_PATHS=600\nN_GENERATE=12000\n\nMIRROR_STEPS=e1.MIRROR_STEPS\nMIRROR_SIGMA=e1.MIRROR_SIGMA\nMIRROR_ETA_BR=e1.MIRROR_ETA_BR\nMIRROR_ETA_BO=e1.MIRROR_ETA_BO\n\n# Frozen *before* final runs. These encode E4\'s purpose: simultaneous attention\n# plasticity must improve the frozen model and should not merely reproduce a\n# weaker single-projection result.\nGATES={\n    \'mean_nll_improvement_gt\':0.030,\n    \'mean_conditional_js_improvement_gt\':0.007,\n    \'mean_long_range_improvement_gt\':0.050,\n    \'generation_joint_js_improvement_gt\':0.030,\n    \'generation_validity_noninferiority_gt\':-0.015,\n    \'beat_best_single_nll_by_gt\':0.002,   # best E1 mean = 0.6596967\n    \'best_single_nll\':0.6596966759437933,\n    \'m_off_max_change_eq\':0.0,\n}\n\n\ndef summarize(xs:Sequence[float]):\n    a=np.asarray(xs,dtype=np.float64)\n    return {\'mean\':float(a.mean()),\'std\':float(a.std()),\'min\':float(a.min()),\'max\':float(a.max())}\n\ndef cosine(a,b):\n    return float(np.sum(a*b)/(np.linalg.norm(a)*np.linalg.norm(b)+1e-30))\n\n\ndef build_joint_dataset(block,tok,pos,true_dist):\n    from collections import defaultdict\n    counts=defaultdict(lambda:np.zeros(p1a.V,np.float64));mass=defaultdict(float)\n    for seq,prob in true_dist:\n        for t in range(p1a.N):\n            key=(t,seq[:t]);counts[key][seq[t]]+=prob;mass[key]+=prob\n    keys=list(counts.keys());C=len(keys)\n    arrays=np.full((C,p1a.N),p1a.MASK,np.int64);targets=np.zeros((C,p1a.V));masses=np.zeros(C);tpos=np.zeros(C,np.int64)\n    for i,(t,prefix) in enumerate(keys):\n        arrays[i,:t]=prefix;targets[i]=counts[(t,prefix)]/mass[(t,prefix)];masses[i]=mass[(t,prefix)]/p1a.N;tpos[i]=t\n    with torch.no_grad():\n        x=p1a.encode(arrays,tok,pos);xn=block.n1(x);row=torch.arange(C);ti=torch.tensor(tpos);xres=x[row,ti]\n    return keys,arrays,targets,masses,xn.numpy().astype(np.float64),xres.numpy().astype(np.float64),tpos\n\n\n@njit(cache=True)\ndef phi_q_vec(q,omega_h):\n    hd=q.shape[0];M=omega_h.shape[0];scale=hd**(-0.25);norm=M**-0.5\n    aa=np.empty(M,np.float64);diag=0.0\n    for c in range(hd):\n        xx=q[c]*scale;diag+=xx*xx\n    diag*=0.5;mx=-1e300\n    for m in range(M):\n        dash=0.0\n        for c in range(hd):dash+=(q[c]*scale)*omega_h[m,c]\n        aa[m]=dash-diag\n        if aa[m]>mx:mx=aa[m]\n    out=np.empty(M,np.float64)\n    for m in range(M):\n        a=aa[m]-mx\n        if a<-30.0:a=-30.0\n        elif a>0.0:a=0.0\n        out[m]=math.exp(a)*norm+1e-6\n    return out\n\n@njit(cache=True)\ndef phi_k_vec(k,omega_h):\n    hd=k.shape[0];M=omega_h.shape[0];scale=hd**(-0.25);norm=M**-0.5;diag=0.0\n    for c in range(hd):\n        xx=k[c]*scale;diag+=xx*xx\n    diag*=0.5;out=np.empty(M,np.float64)\n    for m in range(M):\n        dash=0.0\n        for c in range(hd):dash+=(k[c]*scale)*omega_h[m,c]\n        a=dash-diag\n        if a<-30.0:a=-30.0\n        elif a>30.0:a=30.0\n        out[m]=math.exp(a)*norm+1e-6\n    return out\n\n@njit(cache=True)\ndef score_qk(q,k,omega_h):\n    pq=phi_q_vec(q,omega_h);pk=phi_k_vec(k,omega_h);s=0.0\n    for m in range(pq.shape[0]):s+=pq[m]*pk[m]\n    return s\n\n@njit(cache=True)\ndef joint_attention_state(WQ,bq,WK,bk,WV,bv,xn,t,omega):\n    D=WQ.shape[0];H=omega.shape[0];hd=D//H;N=xn.shape[0]\n    q=np.empty((H,hd),np.float64);k=np.empty((H,N,hd),np.float64);v=np.empty((H,N,hd),np.float64)\n    # current query\n    for r in range(D):\n        z=bq[r]\n        for c in range(D):z+=WQ[r,c]*xn[t,c]\n        hh=r//hd;q[hh,r-hh*hd]=z\n    # all keys/values\n    for n in range(N):\n        for r in range(D):\n            zk=bk[r];zv=bv[r]\n            for c in range(D):\n                xx=xn[n,c];zk+=WK[r,c]*xx;zv+=WV[r,c]*xx\n            hh=r//hd;rr=r-hh*hd;k[hh,n,rr]=zk;v[hh,n,rr]=zv\n    scores=np.empty((H,N),np.float64);den=np.zeros(H,np.float64);num=np.zeros((H,hd),np.float64);alpha=np.empty((H,N),np.float64);a=np.empty(D,np.float64)\n    for hh in range(H):\n        for n in range(N):\n            s=score_qk(q[hh],k[hh,n],omega[hh]);scores[hh,n]=s;den[hh]+=s\n            for rr in range(hd):num[hh,rr]+=s*v[hh,n,rr]\n        dd=den[hh] if den[hh]>1e-8 else 1e-8\n        for n in range(N):alpha[hh,n]=scores[hh,n]/dd\n        for rr in range(hd):a[hh*hd+rr]=num[hh,rr]/dd\n    return a,q,k,v,scores,num,den,alpha\n\n@njit(cache=True)\ndef read_head_from_q(q, k_h, v_h, omega_h):\n    N=k_h.shape[0];hd=q.shape[0];num=np.zeros(hd,np.float64);den=0.0\n    for n in range(N):\n        s=score_qk(q,k_h[n],omega_h);den+=s\n        for r in range(hd):num[r]+=s*v_h[n,r]\n    if den<1e-8:den=1e-8\n    a=np.empty(hd,np.float64)\n    for r in range(hd):a[r]=num[r]/den\n    return a\n\n@njit(cache=True)\ndef _sample_index(cdf):\n    r=np.random.random();i=0\n    while i<cdf.shape[0]-1 and r>cdf[i]:i+=1\n    return i\n\n@njit(cache=True)\ndef train_joint_qkv(\n    xn,xres,tpos,targets,masses,WR,BR,BO,\n    WQ_init,bq,WK_init,bk,WV_init,bv,omega,WO,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2,\n    seq_context_idx,seq_tokens,seq_probs,next_ctx,ctx_pos,root_ctx,static_policy_probs,\n    n_paths,lrq,lrk,lrv,sigq,sigk,seed,p_self,p_iid,\n    reset_every_force=False,m_off=False,feedback_sign=1.0,dynamic_self=False,\n):\n    np.random.seed(seed);C=xn.shape[0];N=xn.shape[1];D=WQ_init.shape[0];H=omega.shape[0];hd=D//H;ff=W1.shape[0]\n    WQ=WQ_init.copy();WK=WK_init.copy();WV=WV_init.copy()\n    # Independent E/M populations per plastic projection.\n    veq=np.full(D,p1a.V0);ueq=np.full(D,p1a.U0);vmq=np.full(D,p1a.V0);umq=np.full(D,p1a.U0);zeq=np.zeros(D);zmq=np.zeros(D)\n    vek=np.full(N*D,p1a.V0);uek=np.full(N*D,p1a.U0);vmk=np.full(N*D,p1a.V0);umk=np.full(N*D,p1a.U0);zek=np.zeros(N*D);zmk=np.zeros(N*D)\n    vev=np.full(H*D,p1a.V0);uev=np.full(H*D,p1a.U0);vmv=np.full(D,p1a.V0);umv=np.full(D,p1a.U0);zev=np.zeros(H*D);zmv=np.zeros(D)\n    cdf=np.cumsum(masses);cdf[-1]=1.;scdf=np.cumsum(seq_probs);scdf[-1]=1.\n    sched=np.empty(p1a.FORCE_STEPS,np.int64);kk=0\n    for t in range(p1a.N):\n        for _ in range(p1d.POSITION_COUNTS[t]):sched[kk]=t;kk+=1\n    seqE=seqM=0\n    for _p in range(n_paths):\n        rr=np.random.random();is_self=rr<p_self;is_iid=(not is_self) and rr<p_self+p_iid;coherent=(not is_self) and not is_iid\n        si=-1\n        if coherent:si=_sample_index(scdf)\n        Q0=WQ.copy();K0=WK.copy();V0=WV.copy();aq=np.zeros_like(WQ);ak=np.zeros_like(WK);av=np.zeros_like(WV);ci_self=root_ctx;rep_self=0\n        for sk in range(p1a.FORCE_STEPS):\n            if reset_every_force:\n                for j in range(D):veq[j]=p1a.V0;ueq[j]=p1a.U0;vmq[j]=p1a.V0;umq[j]=p1a.U0;vmv[j]=p1a.V0;umv[j]=p1a.U0\n                for j in range(N*D):vek[j]=p1a.V0;uek[j]=p1a.U0;vmk[j]=p1a.V0;umk[j]=p1a.U0\n                for j in range(H*D):vev[j]=p1a.V0;uev[j]=p1a.U0\n            if is_self:\n                ci=ci_self;target=p1a.sample_categorical_numba(targets[ci])\n            elif coherent:\n                tt=int(sched[sk]);ci=int(seq_context_idx[si,tt]);target=int(seq_tokens[si,tt])\n            else:\n                ci=_sample_index(cdf);target=p1a.sample_categorical_numba(targets[ci])\n            t=int(tpos[ci]);a,q,k,v,scores,num,den,alpha=joint_attention_state(Q0,bq,K0,bk,V0,bv,xn[ci],t,omega)\n            # downstream frozen block and token readout\n            z=np.empty(D)\n            for o in range(D):\n                val=xres[ci,o]+bo[o]\n                for j in range(D):val+=WO[o,j]*a[j]\n                z[o]=val\n            mu=0.0\n            for o in range(D):mu+=z[o]\n            mu/=D;var=0.0\n            for o in range(D):qq=z[o]-mu;var+=qq*qq\n            var/=D;inv=1.0/math.sqrt(var+eps2);u=np.empty(D)\n            for o in range(D):u[o]=(z[o]-mu)*inv*gamma2[o]+beta2[o]\n            hvec=np.empty(ff)\n            for i in range(ff):\n                val=b1[i]-theta[i]\n                for j in range(D):val+=W1[i,j]*u[j]\n                hvec[i]=val if val>0.0 else 0.0\n            y=z.copy()\n            for o in range(D):\n                val=b2[o]\n                for i in range(ff):val+=W2[o,i]*hvec[i]\n                y[o]+=val\n            ss=0.0\n            for o in range(D):ss+=y[o]*y[o]\n            rms=math.sqrt(ss/D)+1e-8;logits=np.empty(p1a.V)\n            for vv in range(p1a.V):\n                val=0.5*WR[vv,D]\n                for o in range(D):val+=WR[vv,o]*(0.5*y[o]/rms)\n                logits[vv]=val\n            probs=p1a.softmax_numba(logits);err=np.empty(p1a.V)\n            for vv in range(p1a.V):err[vv]=-probs[vv]\n            err[target]+=1.0\n            drive_z=np.zeros(D);drive_a=np.zeros(D)\n            if not m_off:\n                for o in range(D):\n                    for vv in range(p1a.V):drive_z[o]+=feedback_sign*BR[o,vv]*err[vv]\n                for j in range(D):\n                    for o in range(D):drive_a[j]+=BO[j,o]*drive_z[o]\n\n            # --- V populations: exact relation-weighted input ---\n            sinput=np.empty(H*D)\n            for hh in range(H):\n                for c in range(D):\n                    sv=0.0\n                    for n in range(N):sv+=alpha[hh,n]*xn[ci,n,c]\n                    sinput[hh*D+c]=sv\n            EV,se=p1a.fast_izh_step(vev,uev,sinput,zev,p1a.G_E,p1a.CV_E,p1a.CU_E);seqE+=se\n            if m_off:MV=np.zeros(D)\n            else:\n                MV,sm=p1a.fast_izh_step(vmv,umv,drive_a,zmv,p1a.G_M,p1a.CV_M,p1a.CU_M);seqM+=sm\n            for r in range(D):\n                base=(r//hd)*D\n                for c in range(D):av[r,c]+=MV[r]*EV[base+c]\n\n            # --- K populations: token-local relation-writing perturbation ---\n            drive_k=np.zeros(N*D)\n            for hh in range(H):\n                for n in range(N):\n                    xi=np.empty(hd);kp=np.empty(hd);km=np.empty(hd)\n                    for rrh in range(hd):\n                        dd=1.0 if np.random.random()<0.5 else -1.0;xi[rrh]=dd;kp[rrh]=k[hh,n,rrh]+sigk*dd;km[rrh]=k[hh,n,rrh]-sigk*dd\n                    sp=score_qk(q[hh],kp,omega[hh]);smm=score_qk(q[hh],km,omega[hh]);s0=scores[hh,n]\n                    dp=den[hh]+sp-s0;dm=den[hh]+smm-s0\n                    if dp<1e-8:dp=1e-8\n                    if dm<1e-8:dm=1e-8\n                    scalar=0.0\n                    if not m_off:\n                        for rrh in range(hd):\n                            ap=(num[hh,rrh]+(sp-s0)*v[hh,n,rrh])/dp\n                            am=(num[hh,rrh]+(smm-s0)*v[hh,n,rrh])/dm\n                            scalar+=drive_a[hh*hd+rrh]*(ap-am)/(2.0*sigk)\n                    for rrh in range(hd):drive_k[n*D+hh*hd+rrh]=scalar*xi[rrh]\n            ein=np.empty(N*D)\n            for n in range(N):\n                for c in range(D):ein[n*D+c]=xn[ci,n,c]\n            EK,se=p1a.fast_izh_step(vek,uek,ein,zek,p1a.G_E,p1a.CV_E,p1a.CU_E);seqE+=se\n            if m_off:MK=np.zeros(N*D)\n            else:\n                MK,sm=p1a.fast_izh_step(vmk,umk,drive_k,zmk,p1a.G_M,p1a.CV_M,p1a.CU_M);seqM+=sm\n            for r in range(D):\n                for c in range(D):\n                    vv=0.0\n                    for n in range(N):vv+=MK[n*D+r]*EK[n*D+c]\n                    ak[r,c]+=vv/N\n\n            # --- Q populations: current relation-read perturbation ---\n            drive_q=np.zeros(D)\n            for hh in range(H):\n                xi=np.empty(hd);qp=np.empty(hd);qm=np.empty(hd)\n                for rrh in range(hd):\n                    dd=1.0 if np.random.random()<0.5 else -1.0;xi[rrh]=dd;qp[rrh]=q[hh,rrh]+sigq*dd;qm[rrh]=q[hh,rrh]-sigq*dd\n                ap=read_head_from_q(qp,k[hh],v[hh],omega[hh]);am=read_head_from_q(qm,k[hh],v[hh],omega[hh]);scalar=0.0\n                if not m_off:\n                    for rrh in range(hd):scalar+=drive_a[hh*hd+rrh]*(ap[rrh]-am[rrh])/(2.0*sigq)\n                for rrh in range(hd):drive_q[hh*hd+rrh]=scalar*xi[rrh]\n            EQ,se=p1a.fast_izh_step(veq,ueq,xn[ci,t],zeq,p1a.G_E,p1a.CV_E,p1a.CU_E);seqE+=se\n            if m_off:MQ=np.zeros(D)\n            else:\n                MQ,sm=p1a.fast_izh_step(vmq,umq,drive_q,zmq,p1a.G_M,p1a.CV_M,p1a.CU_M);seqM+=sm\n            for r in range(D):\n                for c in range(D):aq[r,c]+=MQ[r]*EQ[c]\n\n            # self-experience state transition; optional current-policy sampling\n            if is_self:\n                rep_self+=1;tcur=int(ctx_pos[ci_self]);need=int(p1d.POSITION_COUNTS[tcur])\n                if rep_self>=need:\n                    if dynamic_self:sampled=p1a.sample_categorical_numba(probs)\n                    else:sampled=_sample_index(np.cumsum(static_policy_probs[ci_self]))\n                    if tcur==p1a.N-1:ci_self=root_ctx;rep_self=0\n                    else:\n                        ni=next_ctx[ci_self,sampled];ci_self=int(ni) if ni>=0 else root_ctx;rep_self=0\n        invsteps=1.0/p1a.FORCE_STEPS\n        for r in range(D):\n            for c in range(D):\n                WQ[r,c]+=lrq*aq[r,c]*invsteps\n                WK[r,c]+=lrk*ak[r,c]*invsteps\n                WV[r,c]+=lrv*av[r,c]*invsteps\n    return WQ,WK,WV,seqE,seqM\n\n\ndef features_joint(WQ,bq,WK,bk,WV,bv,xn,xres,tpos,omega,WO,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2):\n    C=xn.shape[0];A=np.empty((C,p1a.D),np.float64)\n    for i in range(C):A[i]=joint_attention_state(WQ,bq,WK,bk,WV,bv,xn[i],int(tpos[i]),omega)[0]\n    return p1d.forward_features_wo(WO,A,xres,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2)\n\n\ndef setup():\n    torch.set_num_threads(4);torch.manual_seed(p1a.TORCH_INIT_SEED);np.random.seed(1234)\n    true_dist=p1a.enumerate_true_distribution();tok,pos=p1a.build_embeddings();block=p1a.FrozenSNNTransformBlock().eval()\n    keys,arrays,targets,masses,xn,xres,tpos=build_joint_dataset(block,tok,pos,true_dist)\n    WQ=block.q.weight.detach().numpy().astype(np.float64);bq=block.q.bias.detach().numpy().astype(np.float64)\n    WK=block.k.weight.detach().numpy().astype(np.float64);bk=block.k.bias.detach().numpy().astype(np.float64)\n    WV=block.v.weight.detach().numpy().astype(np.float64);bv=block.v.bias.detach().numpy().astype(np.float64)\n    omega=block.phi_q.omega.detach().numpy().astype(np.float64)\n    # Verify Q/K feature matrices use the same omega in this frozen block.\n    omega_k=block.phi_k.omega.detach().numpy().astype(np.float64)\n    if np.max(np.abs(omega-omega_k))>0:raise RuntimeError(\'phi_q and phi_k omega differ; joint implementation needs separate maps\')\n    WO=(block.out.weight*block.out.mask).detach().numpy().astype(np.float64);bo=block.out.bias.detach().numpy().astype(np.float64)\n    gamma2=block.n2.weight.detach().numpy().astype(np.float64);beta2=block.n2.bias.detach().numpy().astype(np.float64);eps2=float(block.n2.eps)\n    W1=(block.f1.weight*block.f1.mask).detach().numpy().astype(np.float64);b1=block.f1.bias.detach().numpy().astype(np.float64);theta=block.theta.detach().numpy().astype(np.float64)\n    W2=(block.f2.weight*block.f2.mask).detach().numpy().astype(np.float64);b2=block.f2.bias.detach().numpy().astype(np.float64)\n    feat0=features_joint(WQ,bq,WK,bk,WV,bv,xn,xres,tpos,omega,WO,bo,gamma2,beta2,eps2,W1,b1,theta,W2,b2)\n    WR,_,_=p1a.train_msdl_readout(feat0,targets,masses,p1d.READOUT_PATHS,p1d.READOUT_LR,p1d.READOUT_SEED,False)\n    baseline=p1a.evaluate_W(WR,feat0,targets,masses,keys)\n    sci,st,sp=p1c2.build_sequence_index(true_dist,keys);nxt,cpos,root=p1d2.build_transitions(keys);static=p1a.probs_from_W(WR,feat0)\n    return locals()\n\n\ndef evaluate(d,WQ,WK,WV):\n    f=features_joint(WQ,d[\'bq\'],WK,d[\'bk\'],WV,d[\'bv\'],d[\'xn\'],d[\'xres\'],d[\'tpos\'],d[\'omega\'],d[\'WO\'],d[\'bo\'],d[\'gamma2\'],d[\'beta2\'],d[\'eps2\'],d[\'W1\'],d[\'b1\'],d[\'theta\'],d[\'W2\'],d[\'b2\'])\n    return p1a.evaluate_W(d[\'WR\'],f,d[\'targets\'],d[\'masses\'],d[\'keys\'])\n\n\ndef set_block_qkv(block,WQ,WK,WV):\n    with torch.no_grad():\n        block.q.weight.copy_(torch.tensor(WQ,dtype=block.q.weight.dtype));block.k.weight.copy_(torch.tensor(WK,dtype=block.k.weight.dtype));block.v.weight.copy_(torch.tensor(WV,dtype=block.v.weight.dtype))\n\ndef generation(d,WQ,WK,WV,n,seed):\n    b=copy.deepcopy(d[\'block\']).eval();set_block_qkv(b,WQ,WK,WV);return p1a.autonomous_generate(b,d[\'tok\'],d[\'pos\'],d[\'WR\'],n,seed,p1a.GEN_BATCH)\n\n\ndef parity(d):\n    with torch.no_grad():\n        x=p1a.encode(d[\'arrays\'],d[\'tok\'],d[\'pos\']);y,_=d[\'block\'].step(x,None);idx=torch.arange(len(d[\'arrays\']));ti=torch.tensor(d[\'tpos\']);ft=p1a.normalize_readout_feature(y[idx,ti]).numpy()\n    fn=features_joint(d[\'WQ\'],d[\'bq\'],d[\'WK\'],d[\'bk\'],d[\'WV\'],d[\'bv\'],d[\'xn\'],d[\'xres\'],d[\'tpos\'],d[\'omega\'],d[\'WO\'],d[\'bo\'],d[\'gamma2\'],d[\'beta2\'],d[\'eps2\'],d[\'W1\'],d[\'b1\'],d[\'theta\'],d[\'W2\'],d[\'b2\'])\n    base=float(np.max(np.abs(ft-fn[:,:p1a.D])))\n    rng=np.random.default_rng(8841);Q=d[\'WQ\']+0.02*rng.normal(size=d[\'WQ\'].shape);K=d[\'WK\']+0.02*rng.normal(size=d[\'WK\'].shape);V=d[\'WV\']+0.02*rng.normal(size=d[\'WV\'].shape);b=copy.deepcopy(d[\'block\']).eval();set_block_qkv(b,Q,K,V)\n    with torch.no_grad():\n        x=p1a.encode(d[\'arrays\'],d[\'tok\'],d[\'pos\']);y,_=b.step(x,None);fp=p1a.normalize_readout_feature(y[idx,ti]).numpy()\n    fn2=features_joint(Q,d[\'bq\'],K,d[\'bk\'],V,d[\'bv\'],d[\'xn\'],d[\'xres\'],d[\'tpos\'],d[\'omega\'],d[\'WO\'],d[\'bo\'],d[\'gamma2\'],d[\'beta2\'],d[\'eps2\'],d[\'W1\'],d[\'b1\'],d[\'theta\'],d[\'W2\'],d[\'b2\'])\n    return {\'baseline_max_feature_error\':base,\'joint_perturbed_qkv_max_feature_error\':float(np.max(np.abs(fp-fn2[:,:p1a.D])))}\n\n\ndef gradient_joint_reference(d,steps=300):\n    # Exact differentiable Q/K/V-only reference using the same context tensors and\n    # frozen downstream block; candidate learning never calls this function.\n    XN=torch.tensor(d[\'xn\'],dtype=torch.float32); XRES=torch.tensor(d[\'xres\'],dtype=torch.float32)\n    TPOS=torch.tensor(d[\'tpos\'],dtype=torch.long); T=torch.tensor(d[\'targets\'],dtype=torch.float32); Mass=torch.tensor(d[\'masses\'],dtype=torch.float32)\n    Q=torch.tensor(d[\'WQ\'],dtype=torch.float32,requires_grad=True);K=torch.tensor(d[\'WK\'],dtype=torch.float32,requires_grad=True);Vv=torch.tensor(d[\'WV\'],dtype=torch.float32,requires_grad=True)\n    bq=torch.tensor(d[\'bq\'],dtype=torch.float32);bk=torch.tensor(d[\'bk\'],dtype=torch.float32);bv=torch.tensor(d[\'bv\'],dtype=torch.float32);OMG=torch.tensor(d[\'omega\'],dtype=torch.float32)\n    WO=torch.tensor(d[\'WO\'],dtype=torch.float32);bo=torch.tensor(d[\'bo\'],dtype=torch.float32);g=torch.tensor(d[\'gamma2\'],dtype=torch.float32);be=torch.tensor(d[\'beta2\'],dtype=torch.float32)\n    W1=torch.tensor(d[\'W1\'],dtype=torch.float32);b1=torch.tensor(d[\'b1\'],dtype=torch.float32);th=torch.tensor(d[\'theta\'],dtype=torch.float32);W2=torch.tensor(d[\'W2\'],dtype=torch.float32);b2=torch.tensor(d[\'b2\'],dtype=torch.float32);WR=torch.tensor(d[\'WR\'],dtype=torch.float32)\n    C,N,D=XN.shape;H=p1a.HEADS;hd=D//H;M=p1a.FEATURES;row=torch.arange(C)\n    opt=torch.optim.LBFGS([Q,K,Vv],lr=0.8,max_iter=steps,line_search_fn=\'strong_wolfe\')\n    def closure():\n        opt.zero_grad()\n        q=(XN[row,TPOS]@Q.T+bq).reshape(C,H,hd)\n        k=(XN@K.T+bk).reshape(C,N,H,hd).permute(0,2,1,3)\n        vv=(XN@Vv.T+bv).reshape(C,N,H,hd).permute(0,2,1,3)\n        # Q positive RF with per-query max stabilization.\n        xq=q*(hd**-0.25);dq=torch.einsum(\'chd,hmd->chm\',xq,OMG);diagq=0.5*(xq*xq).sum(-1,keepdim=True);aq=dq-diagq;aq=(aq-aq.amax(-1,keepdim=True).detach()).clamp(-30.,0.);pq=torch.exp(aq)*(M**-0.5)+1e-6\n        # K positive RF.\n        xk=k*(hd**-0.25);dk=torch.einsum(\'chnd,hmd->chnm\',xk,OMG);diagk=0.5*(xk*xk).sum(-1,keepdim=True);ak=(dk-diagk).clamp(-30.,30.);pk=torch.exp(ak)*(M**-0.5)+1e-6\n        score=torch.einsum(\'chm,chnm->chn\',pq,pk);alpha=score/score.sum(-1,keepdim=True).clamp_min(1e-8);a=torch.einsum(\'chn,chnd->chd\',alpha,vv).reshape(C,D)\n        z=XRES+a@WO.T+bo;u=F.layer_norm(z,(D,),g,be,d[\'eps2\']);h=F.relu(u@W1.T+b1-th);y=z+h@W2.T+b2\n        feat=p1a.normalize_readout_feature(y);feat=torch.cat([feat,torch.full((C,1),0.5)],1);logp=F.log_softmax(feat@WR.T,1);loss=-(Mass[:,None]*T*logp).sum();loss.backward();return loss\n    opt.step(closure)\n    return Q.detach().numpy().astype(np.float64),K.detach().numpy().astype(np.float64),Vv.detach().numpy().astype(np.float64)\n\n\ndef run_dev(outdir):\n    d=setup();BR,_,_=p1c.learn_feedback_BR_msdl(d[\'WR\'],MIRROR_STEPS,MIRROR_SIGMA,MIRROR_ETA_BR,188001);BO,_,_=e1.learn_feedback_matrix_msdl(d[\'WO\'],MIRROR_STEPS,MIRROR_SIGMA,MIRROR_ETA_BO,188007)\n    rows=[]\n    for mult in DEV_MULTS:\n        ms=[]\n        for seed in DEV_SEEDS:\n            Q,K,V,_,_=train_joint_qkv(d[\'xn\'],d[\'xres\'],d[\'tpos\'],d[\'targets\'],d[\'masses\'],d[\'WR\'],BR,BO,d[\'WQ\'],d[\'bq\'],d[\'WK\'],d[\'bk\'],d[\'WV\'],d[\'bv\'],d[\'omega\'],d[\'WO\'],d[\'bo\'],d[\'gamma2\'],d[\'beta2\'],d[\'eps2\'],d[\'W1\'],d[\'b1\'],d[\'theta\'],d[\'W2\'],d[\'b2\'],d[\'sci\'],d[\'st\'],d[\'sp\'],d[\'nxt\'],d[\'cpos\'],d[\'root\'],d[\'static\'],DEV_PATHS,BASE_LR_Q*mult,BASE_LR_K*mult,BASE_LR_V*mult,SIGMA_Q,SIGMA_K,seed,P_SELF,P_IID)\n            ms.append(evaluate(d,Q,K,V))\n        row={\'multiplier\':mult,\'lr_q\':BASE_LR_Q*mult,\'lr_k\':BASE_LR_K*mult,\'lr_v\':BASE_LR_V*mult,\'mean_nll\':float(np.mean([m[\'expected_nll\'] for m in ms])),\'mean_js\':float(np.mean([m[\'conditional_js\'] for m in ms])),\'mean_long_range_mae\':float(np.mean([m[\'exact_long_range_branch_mae\'] for m in ms]))}\n        rows.append(row);print(row,flush=True)\n    # primary NLL then long-range tie break\n    best=min(rows,key=lambda r:(r[\'mean_nll\'],r[\'mean_long_range_mae\']))\n    obj={\'baseline\':d[\'baseline\'],\'BR_cosine\':cosine(BR,d[\'WR\'][:,:p1a.D].T),\'BO_cosine\':cosine(BO,d[\'WO\'].T),\'rows\':rows,\'selected_multiplier\':best[\'multiplier\']}\n    (outdir/\'P1E4_DEV_CALIBRATION.json\').write_text(json.dumps(obj,indent=2));return float(best[\'multiplier\'])\n\n\ndef run_final(outdir,mult):\n    d=setup();par=parity(d);(outdir/\'P1E4_PARITY.json\').write_text(json.dumps(par,indent=2))\n    base_s=generation(d,d[\'WQ\'],d[\'WK\'],d[\'WV\'],20000,899001);base_g=p1b.generation_metrics(base_s,d[\'true_dist\'])\n    rows=[]\n    for seed in FINAL_SEEDS:\n        BR,_,_=p1c.learn_feedback_BR_msdl(d[\'WR\'],MIRROR_STEPS,MIRROR_SIGMA,MIRROR_ETA_BR,200000+seed);BO,_,_=e1.learn_feedback_matrix_msdl(d[\'WO\'],MIRROR_STEPS,MIRROR_SIGMA,MIRROR_ETA_BO,210000+seed)\n        Q,K,V,se,sm=train_joint_qkv(d[\'xn\'],d[\'xres\'],d[\'tpos\'],d[\'targets\'],d[\'masses\'],d[\'WR\'],BR,BO,d[\'WQ\'],d[\'bq\'],d[\'WK\'],d[\'bk\'],d[\'WV\'],d[\'bv\'],d[\'omega\'],d[\'WO\'],d[\'bo\'],d[\'gamma2\'],d[\'beta2\'],d[\'eps2\'],d[\'W1\'],d[\'b1\'],d[\'theta\'],d[\'W2\'],d[\'b2\'],d[\'sci\'],d[\'st\'],d[\'sp\'],d[\'nxt\'],d[\'cpos\'],d[\'root\'],d[\'static\'],FINAL_PATHS,BASE_LR_Q*mult,BASE_LR_K*mult,BASE_LR_V*mult,SIGMA_Q,SIGMA_K,seed,P_SELF,P_IID)\n        met=evaluate(d,Q,K,V);samp=generation(d,Q,K,V,N_GENERATE,600000+seed);gm=p1b.generation_metrics(samp,d[\'true_dist\'])\n        row={\'seed\':seed,\'candidate\':met,\'generation\':gm,\'nll_improvement\':d[\'baseline\'][\'expected_nll\']-met[\'expected_nll\'],\'js_improvement\':d[\'baseline\'][\'conditional_js\']-met[\'conditional_js\'],\'long_range_improvement\':d[\'baseline\'][\'exact_long_range_branch_mae\']-met[\'exact_long_range_branch_mae\'],\'BR_cosine\':cosine(BR,d[\'WR\'][:,:p1a.D].T),\'BO_cosine\':cosine(BO,d[\'WO\'].T),\'WQ_change_rel_l2\':float(np.linalg.norm(Q-d[\'WQ\'])/(np.linalg.norm(d[\'WQ\'])+1e-30)),\'WK_change_rel_l2\':float(np.linalg.norm(K-d[\'WK\'])/(np.linalg.norm(d[\'WK\'])+1e-30)),\'WV_change_rel_l2\':float(np.linalg.norm(V-d[\'WV\'])/(np.linalg.norm(d[\'WV\'])+1e-30)),\'E_spikes\':int(se),\'M_spikes\':int(sm)}\n        rows.append(row);print(json.dumps(row,indent=2),flush=True);(outdir/f\'P1E4_FINAL_SEED_{seed}.json\').write_text(json.dumps(row,indent=2));np.savez_compressed(outdir/f\'P1E4_FINAL_SEED_{seed}.npz\',W_Q=Q,W_K=K,W_V=V,B_R=BR,B_O=BO,samples=samp[:2000])\n    # capacity reference\n    Qg,Kg,Vg=gradient_joint_reference(d);grad=evaluate(d,Qg,Kg,Vg);np.savez_compressed(outdir/\'P1E4_QKV_GRAD_REF.npz\',W_Q=Qg,W_K=Kg,W_V=Vg)\n    # controls\n    BR,_,_=p1c.learn_feedback_BR_msdl(d[\'WR\'],MIRROR_STEPS,MIRROR_SIGMA,MIRROR_ETA_BR,299001);BO,_,_=e1.learn_feedback_matrix_msdl(d[\'WO\'],MIRROR_STEPS,MIRROR_SIGMA,MIRROR_ETA_BO,299007)\n    Qm,Km,Vm,_,_=train_joint_qkv(d[\'xn\'],d[\'xres\'],d[\'tpos\'],d[\'targets\'],d[\'masses\'],d[\'WR\'],BR,BO,d[\'WQ\'],d[\'bq\'],d[\'WK\'],d[\'bk\'],d[\'WV\'],d[\'bv\'],d[\'omega\'],d[\'WO\'],d[\'bo\'],d[\'gamma2\'],d[\'beta2\'],d[\'eps2\'],d[\'W1\'],d[\'b1\'],d[\'theta\'],d[\'W2\'],d[\'b2\'],d[\'sci\'],d[\'st\'],d[\'sp\'],d[\'nxt\'],d[\'cpos\'],d[\'root\'],d[\'static\'],CONTROL_PATHS,BASE_LR_Q*mult,BASE_LR_K*mult,BASE_LR_V*mult,SIGMA_Q,SIGMA_K,8991,P_SELF,P_IID,m_off=True)\n    moff=max(float(np.max(np.abs(Qm-d[\'WQ\']))),float(np.max(np.abs(Km-d[\'WK\']))),float(np.max(np.abs(Vm-d[\'WV\']))))\n    Qn,Kn,Vn,_,_=train_joint_qkv(d[\'xn\'],d[\'xres\'],d[\'tpos\'],d[\'targets\'],d[\'masses\'],d[\'WR\'],BR,BO,d[\'WQ\'],d[\'bq\'],d[\'WK\'],d[\'bk\'],d[\'WV\'],d[\'bv\'],d[\'omega\'],d[\'WO\'],d[\'bo\'],d[\'gamma2\'],d[\'beta2\'],d[\'eps2\'],d[\'W1\'],d[\'b1\'],d[\'theta\'],d[\'W2\'],d[\'b2\'],d[\'sci\'],d[\'st\'],d[\'sp\'],d[\'nxt\'],d[\'cpos\'],d[\'root\'],d[\'static\'],CONTROL_PATHS,BASE_LR_Q*mult,BASE_LR_K*mult,BASE_LR_V*mult,SIGMA_Q,SIGMA_K,8993,P_SELF,P_IID,feedback_sign=-1.0)\n    neg=evaluate(d,Qn,Kn,Vn)\n    Qr,Kr,Vr,_,_=train_joint_qkv(d[\'xn\'],d[\'xres\'],d[\'tpos\'],d[\'targets\'],d[\'masses\'],d[\'WR\'],BR,BO,d[\'WQ\'],d[\'bq\'],d[\'WK\'],d[\'bk\'],d[\'WV\'],d[\'bv\'],d[\'omega\'],d[\'WO\'],d[\'bo\'],d[\'gamma2\'],d[\'beta2\'],d[\'eps2\'],d[\'W1\'],d[\'b1\'],d[\'theta\'],d[\'W2\'],d[\'b2\'],d[\'sci\'],d[\'st\'],d[\'sp\'],d[\'nxt\'],d[\'cpos\'],d[\'root\'],d[\'static\'],CONTROL_PATHS,BASE_LR_Q*mult,BASE_LR_K*mult,BASE_LR_V*mult,SIGMA_Q,SIGMA_K,8997,P_SELF,P_IID,reset_every_force=True)\n    reset=evaluate(d,Qr,Kr,Vr)\n    controls={\'m_off_max_qkv_change\':moff,\'wrong_sign\':neg,\'reset_every_force\':reset};(outdir/\'P1E4_CONTROLS.json\').write_text(json.dumps(controls,indent=2))\n    cagg={k:summarize([r[\'candidate\'][k] for r in rows]) for k in [\'expected_nll\',\'conditional_js\',\'exact_long_range_branch_mae\',\'expected_token_support\']}\n    gagg={k:summarize([r[\'generation\'][k] for r in rows]) for k in [\'joint_js_with_invalid_bucket\',\'valid_sequence_fraction\',\'mode_tv\',\'true_mode_coverage_fraction\',\'long_range_branch_mae\']}\n    iagg={k:summarize([r[k] for r in rows]) for k in [\'nll_improvement\',\'js_improvement\',\'long_range_improvement\',\'WQ_change_rel_l2\',\'WK_change_rel_l2\',\'WV_change_rel_l2\',\'BR_cosine\',\'BO_cosine\']}\n    gates={\n        \'nll_improvement\':iagg[\'nll_improvement\'][\'mean\']>GATES[\'mean_nll_improvement_gt\'],\n        \'conditional_js_improvement\':iagg[\'js_improvement\'][\'mean\']>GATES[\'mean_conditional_js_improvement_gt\'],\n        \'long_range_improvement\':iagg[\'long_range_improvement\'][\'mean\']>GATES[\'mean_long_range_improvement_gt\'],\n        \'generation_joint_js_improvement\':base_g[\'joint_js_with_invalid_bucket\']-gagg[\'joint_js_with_invalid_bucket\'][\'mean\']>GATES[\'generation_joint_js_improvement_gt\'],\n        \'generation_validity_noninferior\':gagg[\'valid_sequence_fraction\'][\'mean\']-base_g[\'valid_sequence_fraction\']>GATES[\'generation_validity_noninferiority_gt\'],\n        \'beats_best_single_nll\':GATES[\'best_single_nll\']-cagg[\'expected_nll\'][\'mean\']>GATES[\'beat_best_single_nll_by_gt\'],\n        \'m_off_zero_change\':moff==GATES[\'m_off_max_change_eq\'],\n        \'wrong_sign_worse\':neg[\'expected_nll\']>d[\'baseline\'][\'expected_nll\'],\n    }\n    result={\'stage\':\'P1-E4 joint Q/K/V plasticity\',\'selected_multiplier\':mult,\'learning_rates\':{\'WQ\':BASE_LR_Q*mult,\'WK\':BASE_LR_K*mult,\'WV\':BASE_LR_V*mult},\'sigmas\':{\'Q\':SIGMA_Q,\'K\':SIGMA_K},\'final_paths\':FINAL_PATHS,\'parity\':par,\'baseline\':d[\'baseline\'],\'baseline_generation\':base_g,\'candidate_aggregate\':cagg,\'generation_aggregate\':gagg,\'improvement_aggregate\':iagg,\'gradient_joint_QKV_reference\':grad,\'gradient_nll_opportunity\':d[\'baseline\'][\'expected_nll\']-grad[\'expected_nll\'],\'candidate_fraction_gradient_nll_opportunity\':iagg[\'nll_improvement\'][\'mean\']/(d[\'baseline\'][\'expected_nll\']-grad[\'expected_nll\']+1e-30),\'best_single_projection_nll_reference\':GATES[\'best_single_nll\'],\'controls\':controls,\'gates\':gates,\'all_gates_pass\':bool(all(gates.values())),\'rows\':rows}\n    (outdir/\'P1E4_RESULTS.json\').write_text(json.dumps(result,indent=2));print(json.dumps(result,indent=2),flush=True);return result\n\n\ndef write_report(outdir,result):\n    c=result[\'candidate_aggregate\'];g=result[\'generation_aggregate\'];b=result[\'baseline\'];bg=result[\'baseline_generation\'];grad=result[\'gradient_joint_QKV_reference\'];ctrl=result[\'controls\'];gt=result[\'gates\']\n    status=\'PASS\' if result[\'all_gates_pass\'] else \'CORE PASS / FULL GATES NOT ALL PASS\' if (gt[\'nll_improvement\'] and gt[\'conditional_js_improvement\'] and gt[\'long_range_improvement\']) else \'FAIL\'\n    txt=f\'\'\' + "\\\'\\\'\\\'" + r\'\'\'# P1-E4 — Joint Q/K/V dynamical plasticity\\n\\n## Verdict\\n\\n**{status}**\\n\\nP1-E4 tests whether the separately validated Q-, K-, and V-side local MSDL mechanisms can co-adapt simultaneously inside one attention population. All three matrices are plastic during the same experience stream; there is no global gradient/BPTT in the candidate.\\n\\n## Frozen protocol\\n\\n- Q local relation-read perturbation: sigma={SIGMA_Q}\\n- K token-local relation-write perturbation: sigma={SIGMA_K}\\n- V relation-weighted local presynaptic eligibility\\n- Shared learned feedback populations BR and BO\\n- Experience mix: self={P_SELF}, IID={P_IID}, remainder coherent\\n- Selected common LR multiplier: {result[\'selected_multiplier\']}\\n- Learning rates: WQ={result[\'learning_rates\'][\'WQ\']}, WK={result[\'learning_rates\'][\'WK\']}, WV={result[\'learning_rates\'][\'WV\']}\\n- Final paths: {FINAL_PATHS}\\n\\n## Results\\n\\n| metric | frozen | joint QKV |\\n|---|---:|---:|\\n| NLL | {b[\'expected_nll\']:.6f} | {c[\'expected_nll\'][\'mean\']:.6f} ± {c[\'expected_nll\'][\'std\']:.6f} |\\n| conditional JS | {b[\'conditional_js\']:.6f} | {c[\'conditional_js\'][\'mean\']:.6f} |\\n| long-range MAE | {b[\'exact_long_range_branch_mae\']:.6f} | {c[\'exact_long_range_branch_mae\'][\'mean\']:.6f} |\\n| autonomous joint JS | {bg[\'joint_js_with_invalid_bucket\']:.6f} | {g[\'joint_js_with_invalid_bucket\'][\'mean\']:.6f} |\\n| autonomous validity | {bg[\'valid_sequence_fraction\']:.6f} | {g[\'valid_sequence_fraction\'][\'mean\']:.6f} |\\n\\nBest previous single-projection NLL was {result[\'best_single_projection_nll_reference\']:.6f} (P1-E1 W_V-only). Joint Q/K/V reaches {c[\'expected_nll\'][\'mean\']:.6f}.\\n\\nA QKV-only gradient capacity reference reaches NLL {grad[\'expected_nll\']:.6f}. The local dynamical candidate closes {100*result[\'candidate_fraction_gradient_nll_opportunity\']:.2f}% of the frozen-to-gradient NLL opportunity.\\n\\n## Causal controls\\n\\n- M-off maximum Q/K/V change: {ctrl[\'m_off_max_qkv_change\']:.3e}\\n- wrong-sign NLL: {ctrl[\'wrong_sign\'][\'expected_nll\']:.6f}\\n- reset-every-force NLL: {ctrl[\'reset_every_force\'][\'expected_nll\']:.6f}\\n- reset-every-force long-range MAE: {ctrl[\'reset_every_force\'][\'exact_long_range_branch_mae\']:.6f}\\n\\n## Gates\\n\\n```json\\n{json.dumps(gt,indent=2)}\\n```\\n\\n## Interpretation boundary\\n\\nThis stage verifies simultaneous plasticity of Q/K/V under local population mismatch dynamics. It does **not** yet verify the calibrated Izhikevich Q/K feature interface under moving Q/K distributions, and it does not establish long-duration continual stability. Those are subsequent gates.\\n\'\'\' + "\\\'\\\'\\\'" + r\'\'\'\n    (outdir/\'P1E4_REPORT.md\').write_text(txt)\n\nif __name__==\'__main__\':\n    out=HERE\n    mult=run_dev(out)\n    r=run_final(out,mult)\n    write_report(out,r)\n\'\'\'\n\n# ========================= p1f_full_block_msdl.py =========================\n_EMBEDDED[\'p1f_full_block_msdl\'] = r\'\'\'#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n"""P1-F: simultaneous MSDL plasticity of the full internal SNN-Transform block.\n\nPlastic forward synaptic populations:\n    W_Q, W_K, W_V, W_O, W_1, W_2\nFixed:\n    token/position embeddings, LayerNorm affine parameters, PositiveRF omega,\n    biases/thresholds, sparse masks, categorical readout W_R.\n\nCandidate learning uses only the local dynamical mechanisms already validated\nseparately in P1-B/C/D/E. No autograd/BPTT is used by candidate training.\nAll six forward matrices are frozen inside each 27-force-step MSDL path, then\nupdated simultaneously from accumulated E/M interactions.\n"""\nfrom __future__ import annotations\nimport copy, json, math, sys\nfrom pathlib import Path\nfrom typing import Sequence\nimport numpy as np\nimport torch\nfrom numba import njit\n\nHERE=Path(__file__).resolve().parent\nsys.path.insert(0,str(HERE))\nimport p1a_msdl_token_generation as p1a\nimport p1b_internal_w2_msdl as p1b\nimport p1c_deep_local_mismatch as p1c\nimport p1c2_trajectory_coherent_mismatch as p1c2\nimport p1d_attention_output_msdl as p1d\nimport p1d2_self_experienced_msdl as p1d2\nimport p1e1_value_msdl as e1\nimport p1e4_joint_qkv_msdl as e4\n\n# Component-wise validated base rates. P1-F selects one common multiplier so the\n# test adds only one co-adaptation degree of freedom.\nBASE_LR_Q=0.30\nBASE_LR_K=0.25\nBASE_LR_V=0.0875\nBASE_LR_O=0.25\nBASE_LR_1=0.50\nBASE_LR_2=0.50\nSIGMA_Q=0.05\nSIGMA_K=0.05\nP_SELF=0.30\nP_IID=0.25\n\nMIRROR_STEPS=e1.MIRROR_STEPS\nMIRROR_SIGMA=e1.MIRROR_SIGMA\nMIRROR_ETA_BR=e1.MIRROR_ETA_BR\nMIRROR_ETA_BO=e1.MIRROR_ETA_BO\nMIRROR_ETA_B2=p1c.MIRROR_ETA_B2  # exact frozen P1-C mirror-learning rate\n\n# Development first checks co-adaptation stability. Final settings are frozen\n# only after development; final seeds are untouched by selection.\nDEV_MULTS=[0.05,0.10,0.20,0.30,0.45]\nDEV_SEEDS=[9101,9119]\nDEV_PATHS=320\nLONGDEV_PATHS=900\nFINAL_SEEDS=[9209,9221,9239]\nFINAL_PATHS=1200\nCONTROL_PATHS=300\nN_GENERATE=12000\n\n# Predeclared scientific gates. A separate secondary comparison against E4 is\n# reported but is not required for the core full-block co-adaptation claim.\nGATES={\n    \'mean_nll_improvement_gt\':0.045,\n    \'mean_conditional_js_improvement_gt\':0.010,\n    \'mean_long_range_improvement_gt\':0.070,\n    \'generation_joint_js_improvement_gt\':0.050,\n    \'generation_validity_noninferiority_gt\':-0.020,\n    \'all_six_weight_groups_change_gt\':1e-5,\n    \'m_off_max_change_eq\':0.0,\n}\nE4_NLL_REFERENCE=0.6374757828208022\n\n\ndef summarize(xs:Sequence[float]):\n    a=np.asarray(xs,dtype=np.float64)\n    return {\'mean\':float(a.mean()),\'std\':float(a.std()),\'min\':float(a.min()),\'max\':float(a.max())}\n\ndef cosine(a,b):\n    return float(np.sum(a*b)/(np.linalg.norm(a)*np.linalg.norm(b)+1e-30))\n\n\ndef setup():\n    d=e4.setup()\n    b=d[\'block\']\n    d[\'maskO\']=b.out.mask.detach().numpy().astype(np.float64)\n    d[\'mask1\']=b.f1.mask.detach().numpy().astype(np.float64)\n    d[\'mask2\']=b.f2.mask.detach().numpy().astype(np.float64)\n    return d\n\n\n@njit(cache=True)\ndef train_full_block(\n    xn,xres,tpos,targets,masses,WR,BR,BO,B2,\n    WQ_init,bq,WK_init,bk,WV_init,bv,omega,\n    WO_init,maskO,bo,gamma2,beta2,eps2,\n    W1_init,mask1,b1,theta,W2_init,mask2,b2,\n    seq_context_idx,seq_tokens,seq_probs,next_ctx,ctx_pos,root_ctx,static_policy_probs,\n    n_paths,lrq,lrk,lrv,lro,lr1,lr2,sigq,sigk,seed,p_self,p_iid,\n    reset_every_force=False,m_off=False,feedback_sign=1.0,dynamic_self=False,\n):\n    np.random.seed(seed)\n    C=xn.shape[0];N=xn.shape[1];D=WQ_init.shape[0];H=omega.shape[0];hd=D//H;ff=W1_init.shape[0]\n    WQ=WQ_init.copy();WK=WK_init.copy();WV=WV_init.copy();WO=WO_init.copy();W1=W1_init.copy();W2=W2_init.copy()\n\n    # Independent E/M state pairs for the six plastic projection populations.\n    veq=np.full(D,p1a.V0);ueq=np.full(D,p1a.U0);vmq=np.full(D,p1a.V0);umq=np.full(D,p1a.U0);zeq=np.zeros(D);zmq=np.zeros(D)\n    vek=np.full(N*D,p1a.V0);uek=np.full(N*D,p1a.U0);vmk=np.full(N*D,p1a.V0);umk=np.full(N*D,p1a.U0);zek=np.zeros(N*D);zmk=np.zeros(N*D)\n    vev=np.full(H*D,p1a.V0);uev=np.full(H*D,p1a.U0);vmv=np.full(D,p1a.V0);umv=np.full(D,p1a.U0);zev=np.zeros(H*D);zmv=np.zeros(D)\n    veo=np.full(D,p1a.V0);ueo=np.full(D,p1a.U0);vmo=np.full(D,p1a.V0);umo=np.full(D,p1a.U0);zeo=np.zeros(D);zmo=np.zeros(D)\n    ve1=np.full(D,p1a.V0);ue1=np.full(D,p1a.U0);vm1=np.full(ff,p1a.V0);um1=np.full(ff,p1a.U0);ze1=np.zeros(D);zm1=np.zeros(ff)\n    ve2=np.full(ff,p1a.V0);ue2=np.full(ff,p1a.U0);vm2=np.full(D,p1a.V0);um2=np.full(D,p1a.U0);ze2=np.zeros(ff);zm2=np.zeros(D)\n\n    cdf=np.cumsum(masses);cdf[-1]=1.;scdf=np.cumsum(seq_probs);scdf[-1]=1.\n    sched=np.empty(p1a.FORCE_STEPS,np.int64);kk=0\n    for t in range(p1a.N):\n        for _ in range(p1d.POSITION_COUNTS[t]):sched[kk]=t;kk+=1\n    seqE=0;seqM=0\n\n    for _p in range(n_paths):\n        rr=np.random.random();is_self=rr<p_self;is_iid=(not is_self) and rr<p_self+p_iid;coherent=(not is_self) and not is_iid\n        si=-1\n        if coherent:si=e4._sample_index(scdf)\n        Q0=WQ.copy();K0=WK.copy();V0=WV.copy();O0=WO.copy();L10=W1.copy();L20=W2.copy()\n        aq=np.zeros_like(WQ);ak=np.zeros_like(WK);av=np.zeros_like(WV);ao=np.zeros_like(WO);a1=np.zeros_like(W1);a2=np.zeros_like(W2)\n        ci_self=root_ctx;rep_self=0\n\n        for sk in range(p1a.FORCE_STEPS):\n            if reset_every_force:\n                for j in range(D):\n                    veq[j]=p1a.V0;ueq[j]=p1a.U0;vmq[j]=p1a.V0;umq[j]=p1a.U0;vmv[j]=p1a.V0;umv[j]=p1a.U0\n                    veo[j]=p1a.V0;ueo[j]=p1a.U0;vmo[j]=p1a.V0;umo[j]=p1a.U0;ve1[j]=p1a.V0;ue1[j]=p1a.U0;vm2[j]=p1a.V0;um2[j]=p1a.U0\n                for j in range(N*D):vek[j]=p1a.V0;uek[j]=p1a.U0;vmk[j]=p1a.V0;umk[j]=p1a.U0\n                for j in range(H*D):vev[j]=p1a.V0;uev[j]=p1a.U0\n                for j in range(ff):vm1[j]=p1a.V0;um1[j]=p1a.U0;ve2[j]=p1a.V0;ue2[j]=p1a.U0\n\n            if is_self:\n                ci=ci_self;target=p1a.sample_categorical_numba(targets[ci])\n            elif coherent:\n                tt=int(sched[sk]);ci=int(seq_context_idx[si,tt]);target=int(seq_tokens[si,tt])\n            else:\n                ci=e4._sample_index(cdf);target=p1a.sample_categorical_numba(targets[ci])\n            t=int(tpos[ci])\n\n            a,q,k,v,scores,num,den,alpha=e4.joint_attention_state(Q0,bq,K0,bk,V0,bv,xn[ci],t,omega)\n\n            # Current full tail under path-frozen O0/L10/L20.\n            z=np.empty(D)\n            for o in range(D):\n                val=xres[ci,o]+bo[o]\n                for j in range(D):val+=O0[o,j]*a[j]\n                z[o]=val\n            mu=0.0\n            for o in range(D):mu+=z[o]\n            mu/=D;var=0.0\n            for o in range(D):qq=z[o]-mu;var+=qq*qq\n            var/=D;inv=1.0/math.sqrt(var+eps2);u=np.empty(D)\n            for o in range(D):u[o]=(z[o]-mu)*inv*gamma2[o]+beta2[o]\n            hvec=np.empty(ff)\n            for i in range(ff):\n                val=b1[i]-theta[i]\n                for j in range(D):val+=L10[i,j]*u[j]\n                hvec[i]=val if val>0.0 else 0.0\n            y=z.copy()\n            for o in range(D):\n                val=b2[o]\n                for i in range(ff):val+=L20[o,i]*hvec[i]\n                y[o]+=val\n            ss=0.0\n            for o in range(D):ss+=y[o]*y[o]\n            rms=math.sqrt(ss/D)+1e-8;logits=np.empty(p1a.V)\n            for vv in range(p1a.V):\n                val=0.5*WR[vv,D]\n                for o in range(D):val+=WR[vv,o]*(0.5*y[o]/rms)\n                logits[vv]=val\n            probs=p1a.softmax_numba(logits);err=np.empty(p1a.V)\n            for vv in range(p1a.V):err[vv]=-probs[vv]\n            err[target]+=1.0\n\n            # Learned local mismatch-routing populations.\n            drive_y=np.zeros(D)\n            if not m_off:\n                for o in range(D):\n                    for vv in range(p1a.V):drive_y[o]+=feedback_sign*BR[o,vv]*err[vv]\n            drive_h=np.zeros(ff)\n            if not m_off:\n                for i in range(ff):\n                    for o in range(D):drive_h[i]+=B2[i,o]*drive_y[o]\n            # Same local z mismatch used in the independently validated W_O rule.\n            drive_z=drive_y.copy()\n            drive_a=np.zeros(D)\n            if not m_off:\n                for j in range(D):\n                    for o in range(D):drive_a[j]+=BO[j,o]*drive_z[o]\n\n            # W2: hidden -> block output\n            E2,se=p1a.fast_izh_step(ve2,ue2,hvec,ze2,p1a.G_E,p1a.CV_E,p1a.CU_E);seqE+=se\n            if m_off:M2=np.zeros(D)\n            else:\n                M2,sm=p1a.fast_izh_step(vm2,um2,drive_y,zm2,p1a.G_M,p1a.CV_M,p1a.CU_M);seqM+=sm\n            for o in range(D):\n                for i in range(ff):\n                    if mask2[o,i]!=0.0:a2[o,i]+=M2[o]*E2[i]\n\n            # W1: LN2 population -> hidden\n            E1,se=p1a.fast_izh_step(ve1,ue1,u,ze1,p1a.G_E,p1a.CV_E,p1a.CU_E);seqE+=se\n            if m_off:M1=np.zeros(ff)\n            else:\n                M1,sm=p1a.fast_izh_step(vm1,um1,drive_h,zm1,p1a.G_M,p1a.CV_M,p1a.CU_M);seqM+=sm\n            for i in range(ff):\n                for j in range(D):\n                    if mask1[i,j]!=0.0:a1[i,j]+=M1[i]*E1[j]\n\n            # W_O: attended state -> z population\n            EO,se=p1a.fast_izh_step(veo,ueo,a,zeo,p1a.G_E,p1a.CV_E,p1a.CU_E);seqE+=se\n            if m_off:MO=np.zeros(D)\n            else:\n                MO,sm=p1a.fast_izh_step(vmo,umo,drive_z,zmo,p1a.G_M,p1a.CV_M,p1a.CU_M);seqM+=sm\n            for o in range(D):\n                for j in range(D):\n                    if maskO[o,j]!=0.0:ao[o,j]+=MO[o]*EO[j]\n\n            # W_V: relation-weighted presynaptic population -> attended state\n            sinput=np.empty(H*D)\n            for hh in range(H):\n                for c in range(D):\n                    sv=0.0\n                    for n in range(N):sv+=alpha[hh,n]*xn[ci,n,c]\n                    sinput[hh*D+c]=sv\n            EV,se=p1a.fast_izh_step(vev,uev,sinput,zev,p1a.G_E,p1a.CV_E,p1a.CU_E);seqE+=se\n            if m_off:MV=np.zeros(D)\n            else:\n                MV,sm=p1a.fast_izh_step(vmv,umv,drive_a,zmv,p1a.G_M,p1a.CV_M,p1a.CU_M);seqM+=sm\n            for r in range(D):\n                base=(r//hd)*D\n                for c in range(D):av[r,c]+=MV[r]*EV[base+c]\n\n            # W_K: token-local relation-writing perturbation\n            drive_k=np.zeros(N*D)\n            for hh in range(H):\n                for n in range(N):\n                    xi=np.empty(hd);kp=np.empty(hd);km=np.empty(hd)\n                    for rrh in range(hd):\n                        dd=1.0 if np.random.random()<0.5 else -1.0;xi[rrh]=dd;kp[rrh]=k[hh,n,rrh]+sigk*dd;km[rrh]=k[hh,n,rrh]-sigk*dd\n                    sp=e4.score_qk(q[hh],kp,omega[hh]);smm=e4.score_qk(q[hh],km,omega[hh]);s0=scores[hh,n]\n                    dp=den[hh]+sp-s0;dm=den[hh]+smm-s0\n                    if dp<1e-8:dp=1e-8\n                    if dm<1e-8:dm=1e-8\n                    scalar=0.0\n                    if not m_off:\n                        for rrh in range(hd):\n                            ap=(num[hh,rrh]+(sp-s0)*v[hh,n,rrh])/dp\n                            am=(num[hh,rrh]+(smm-s0)*v[hh,n,rrh])/dm\n                            scalar+=drive_a[hh*hd+rrh]*(ap-am)/(2.0*sigk)\n                    for rrh in range(hd):drive_k[n*D+hh*hd+rrh]=scalar*xi[rrh]\n            ein=np.empty(N*D)\n            for n in range(N):\n                for c in range(D):ein[n*D+c]=xn[ci,n,c]\n            EK,se=p1a.fast_izh_step(vek,uek,ein,zek,p1a.G_E,p1a.CV_E,p1a.CU_E);seqE+=se\n            if m_off:MK=np.zeros(N*D)\n            else:\n                MK,sm=p1a.fast_izh_step(vmk,umk,drive_k,zmk,p1a.G_M,p1a.CV_M,p1a.CU_M);seqM+=sm\n            for r in range(D):\n                for c in range(D):\n                    val=0.0\n                    for n in range(N):val+=MK[n*D+r]*EK[n*D+c]\n                    ak[r,c]+=val/N\n\n            # W_Q: current relation-reading perturbation\n            drive_q=np.zeros(D)\n            for hh in range(H):\n                xi=np.empty(hd);qp=np.empty(hd);qm=np.empty(hd)\n                for rrh in range(hd):\n                    dd=1.0 if np.random.random()<0.5 else -1.0;xi[rrh]=dd;qp[rrh]=q[hh,rrh]+sigq*dd;qm[rrh]=q[hh,rrh]-sigq*dd\n                ap=e4.read_head_from_q(qp,k[hh],v[hh],omega[hh]);am=e4.read_head_from_q(qm,k[hh],v[hh],omega[hh]);scalar=0.0\n                if not m_off:\n                    for rrh in range(hd):scalar+=drive_a[hh*hd+rrh]*(ap[rrh]-am[rrh])/(2.0*sigq)\n                for rrh in range(hd):drive_q[hh*hd+rrh]=scalar*xi[rrh]\n            EQ,se=p1a.fast_izh_step(veq,ueq,xn[ci,t],zeq,p1a.G_E,p1a.CV_E,p1a.CU_E);seqE+=se\n            if m_off:MQ=np.zeros(D)\n            else:\n                MQ,sm=p1a.fast_izh_step(vmq,umq,drive_q,zmq,p1a.G_M,p1a.CV_M,p1a.CU_M);seqM+=sm\n            for r in range(D):\n                for c in range(D):aq[r,c]+=MQ[r]*EQ[c]\n\n            if is_self:\n                rep_self+=1;tcur=int(ctx_pos[ci_self]);need=int(p1d.POSITION_COUNTS[tcur])\n                if rep_self>=need:\n                    if dynamic_self:sampled=p1a.sample_categorical_numba(probs)\n                    else:sampled=e4._sample_index(np.cumsum(static_policy_probs[ci_self]))\n                    if tcur==p1a.N-1:ci_self=root_ctx;rep_self=0\n                    else:\n                        ni=next_ctx[ci_self,sampled];ci_self=int(ni) if ni>=0 else root_ctx;rep_self=0\n\n        invsteps=1.0/p1a.FORCE_STEPS\n        for r in range(D):\n            for c in range(D):\n                WQ[r,c]+=lrq*aq[r,c]*invsteps\n                WK[r,c]+=lrk*ak[r,c]*invsteps\n                WV[r,c]+=lrv*av[r,c]*invsteps\n                if maskO[r,c]!=0.0:WO[r,c]+=lro*ao[r,c]*invsteps\n                else:WO[r,c]=0.0\n        for i in range(ff):\n            for c in range(D):\n                if mask1[i,c]!=0.0:W1[i,c]+=lr1*a1[i,c]*invsteps\n                else:W1[i,c]=0.0\n        for r in range(D):\n            for i in range(ff):\n                if mask2[r,i]!=0.0:W2[r,i]+=lr2*a2[r,i]*invsteps\n                else:W2[r,i]=0.0\n    return WQ,WK,WV,WO,W1,W2,seqE,seqM\n\n\ndef features_full(d,WQ,WK,WV,WO,W1,W2):\n    return e4.features_joint(WQ,d[\'bq\'],WK,d[\'bk\'],WV,d[\'bv\'],d[\'xn\'],d[\'xres\'],d[\'tpos\'],d[\'omega\'],WO,d[\'bo\'],d[\'gamma2\'],d[\'beta2\'],d[\'eps2\'],W1,d[\'b1\'],d[\'theta\'],W2,d[\'b2\'])\n\ndef evaluate(d,WQ,WK,WV,WO,W1,W2):\n    f=features_full(d,WQ,WK,WV,WO,W1,W2)\n    return p1a.evaluate_W(d[\'WR\'],f,d[\'targets\'],d[\'masses\'],d[\'keys\'])\n\ndef set_block_all(block,d,WQ,WK,WV,WO,W1,W2):\n    with torch.no_grad():\n        block.q.weight.copy_(torch.tensor(WQ,dtype=block.q.weight.dtype));block.k.weight.copy_(torch.tensor(WK,dtype=block.k.weight.dtype));block.v.weight.copy_(torch.tensor(WV,dtype=block.v.weight.dtype))\n        block.out.weight.copy_(torch.tensor(WO,dtype=block.out.weight.dtype));block.f1.weight.copy_(torch.tensor(W1,dtype=block.f1.weight.dtype));block.f2.weight.copy_(torch.tensor(W2,dtype=block.f2.weight.dtype))\n\ndef generation(d,WQ,WK,WV,WO,W1,W2,n,seed):\n    b=copy.deepcopy(d[\'block\']).eval();set_block_all(b,d,WQ,WK,WV,WO,W1,W2)\n    return p1a.autonomous_generate(b,d[\'tok\'],d[\'pos\'],d[\'WR\'],n,seed,p1a.GEN_BATCH)\n\n\ndef parity(d):\n    with torch.no_grad():\n        x=p1a.encode(d[\'arrays\'],d[\'tok\'],d[\'pos\']);y,_=d[\'block\'].step(x,None);idx=torch.arange(len(d[\'arrays\']));ti=torch.tensor(d[\'tpos\']);ft=p1a.normalize_readout_feature(y[idx,ti]).numpy()\n    fn=features_full(d,d[\'WQ\'],d[\'WK\'],d[\'WV\'],d[\'WO\'],d[\'W1\'],d[\'W2\'])\n    base=float(np.max(np.abs(ft-fn[:,:p1a.D])))\n    rng=np.random.default_rng(9191)\n    Q=d[\'WQ\']+0.01*rng.normal(size=d[\'WQ\'].shape);K=d[\'WK\']+0.01*rng.normal(size=d[\'WK\'].shape);V=d[\'WV\']+0.01*rng.normal(size=d[\'WV\'].shape)\n    O=(d[\'WO\']+0.01*rng.normal(size=d[\'WO\'].shape))*d[\'maskO\'];L1=(d[\'W1\']+0.01*rng.normal(size=d[\'W1\'].shape))*d[\'mask1\'];L2=(d[\'W2\']+0.01*rng.normal(size=d[\'W2\'].shape))*d[\'mask2\']\n    b=copy.deepcopy(d[\'block\']).eval();set_block_all(b,d,Q,K,V,O,L1,L2)\n    with torch.no_grad():\n        x=p1a.encode(d[\'arrays\'],d[\'tok\'],d[\'pos\']);y,_=b.step(x,None);fp=p1a.normalize_readout_feature(y[idx,ti]).numpy()\n    fn2=features_full(d,Q,K,V,O,L1,L2)\n    return {\'baseline_max_feature_error\':base,\'all_six_perturbed_max_feature_error\':float(np.max(np.abs(fp-fn2[:,:p1a.D])))}\n\n\ndef learn_feedbacks(d,seed):\n    BR,_,_=p1c.learn_feedback_BR_msdl(d[\'WR\'],MIRROR_STEPS,MIRROR_SIGMA,MIRROR_ETA_BR,seed+1)\n    BO,_,_=e1.learn_feedback_matrix_msdl(d[\'WO\'],MIRROR_STEPS,MIRROR_SIGMA,MIRROR_ETA_BO,seed+3)\n    B2,_,_=p1c.learn_feedback_B2_msdl(d[\'W2\'],MIRROR_STEPS,MIRROR_SIGMA,MIRROR_ETA_B2,seed+5)\n    return BR,BO,B2\n\n\ndef train_once(d,mult,paths,seed,**kwargs):\n    BR,BO,B2=learn_feedbacks(d,100000+seed)\n    args=(d[\'xn\'],d[\'xres\'],d[\'tpos\'],d[\'targets\'],d[\'masses\'],d[\'WR\'],BR,BO,B2,d[\'WQ\'],d[\'bq\'],d[\'WK\'],d[\'bk\'],d[\'WV\'],d[\'bv\'],d[\'omega\'],d[\'WO\'],d[\'maskO\'],d[\'bo\'],d[\'gamma2\'],d[\'beta2\'],d[\'eps2\'],d[\'W1\'],d[\'mask1\'],d[\'b1\'],d[\'theta\'],d[\'W2\'],d[\'mask2\'],d[\'b2\'],d[\'sci\'],d[\'st\'],d[\'sp\'],d[\'nxt\'],d[\'cpos\'],d[\'root\'],d[\'static\'])\n    ws=train_full_block(*args,paths,BASE_LR_Q*mult,BASE_LR_K*mult,BASE_LR_V*mult,BASE_LR_O*mult,BASE_LR_1*mult,BASE_LR_2*mult,SIGMA_Q,SIGMA_K,seed,P_SELF,P_IID,**kwargs)\n    return ws,BR,BO,B2\n\n\ndef run_dev(outdir):\n    d=setup();rows=[]\n    for mult in DEV_MULTS:\n        ms=[];align=[]\n        for seed in DEV_SEEDS:\n            ws,BR,BO,B2=train_once(d,mult,DEV_PATHS,seed);Q,K,V,O,L1,L2=ws[:6];met=evaluate(d,Q,K,V,O,L1,L2);ms.append(met)\n            align.append((cosine(BO,O.T),cosine(B2,L2.T)))\n        row={\'multiplier\':mult,\'mean_nll\':float(np.mean([m[\'expected_nll\'] for m in ms])),\'mean_js\':float(np.mean([m[\'conditional_js\'] for m in ms])),\'mean_long_range_mae\':float(np.mean([m[\'exact_long_range_branch_mae\'] for m in ms])),\'mean_final_BO_cosine\':float(np.mean([a[0] for a in align])),\'mean_final_B2_cosine\':float(np.mean([a[1] for a in align]))}\n        rows.append(row);print(row,flush=True)\n    # Conservative Pareto selection: among candidates within 0.01 NLL of dev best,\n    # prefer lower long-range error, then lower multiplier.\n    best_nll=min(r[\'mean_nll\'] for r in rows);eligible=[r for r in rows if r[\'mean_nll\']<=best_nll+0.01]\n    sel=min(eligible,key=lambda r:(r[\'mean_long_range_mae\'],r[\'multiplier\']))\n    # Long-horizon check selected and its immediate lower neighbor when available.\n    idx=DEV_MULTS.index(sel[\'multiplier\']);mset=[sel[\'multiplier\']]\n    if idx>0:mset.append(DEV_MULTS[idx-1])\n    longrows=[]\n    for mult in sorted(set(mset)):\n        metrows=[]\n        for seed in [9137,9151]:\n            ws,BR,BO,B2=train_once(d,mult,LONGDEV_PATHS,seed);Q,K,V,O,L1,L2=ws[:6];met=evaluate(d,Q,K,V,O,L1,L2);metrows.append(met)\n        longrows.append({\'multiplier\':mult,\'mean_nll\':float(np.mean([m[\'expected_nll\'] for m in metrows])),\'mean_js\':float(np.mean([m[\'conditional_js\'] for m in metrows])),\'mean_long_range_mae\':float(np.mean([m[\'exact_long_range_branch_mae\'] for m in metrows]))})\n    # choose best long-horizon NLL with LR tie-break, never increase beyond short-dev choice\n    longsel=min(longrows,key=lambda r:(r[\'mean_nll\'],r[\'mean_long_range_mae\']))\n    obj={\'baseline\':d[\'baseline\'],\'short_dev\':rows,\'short_selected\':sel[\'multiplier\'],\'long_dev\':longrows,\'selected_multiplier\':longsel[\'multiplier\']}\n    (outdir/\'P1F_DEV_CALIBRATION.json\').write_text(json.dumps(obj,indent=2));print(\'SELECTED\',longsel[\'multiplier\'],flush=True);return float(longsel[\'multiplier\'])\n\n\ndef run_final(outdir,mult):\n    d=setup();par=parity(d);(outdir/\'P1F_PARITY.json\').write_text(json.dumps(par,indent=2))\n    base_s=generation(d,d[\'WQ\'],d[\'WK\'],d[\'WV\'],d[\'WO\'],d[\'W1\'],d[\'W2\'],20000,929001);base_g=p1b.generation_metrics(base_s,d[\'true_dist\'])\n    rows=[]\n    for seed in FINAL_SEEDS:\n        ws,BR,BO,B2=train_once(d,mult,FINAL_PATHS,seed);Q,K,V,O,L1,L2,se,sm=ws;met=evaluate(d,Q,K,V,O,L1,L2);samp=generation(d,Q,K,V,O,L1,L2,N_GENERATE,700000+seed);gm=p1b.generation_metrics(samp,d[\'true_dist\'])\n        changes={\n            \'WQ_change_rel_l2\':float(np.linalg.norm(Q-d[\'WQ\'])/(np.linalg.norm(d[\'WQ\'])+1e-30)),\n            \'WK_change_rel_l2\':float(np.linalg.norm(K-d[\'WK\'])/(np.linalg.norm(d[\'WK\'])+1e-30)),\n            \'WV_change_rel_l2\':float(np.linalg.norm(V-d[\'WV\'])/(np.linalg.norm(d[\'WV\'])+1e-30)),\n            \'WO_change_rel_l2\':float(np.linalg.norm(O-d[\'WO\'])/(np.linalg.norm(d[\'WO\'])+1e-30)),\n            \'W1_change_rel_l2\':float(np.linalg.norm(L1-d[\'W1\'])/(np.linalg.norm(d[\'W1\'])+1e-30)),\n            \'W2_change_rel_l2\':float(np.linalg.norm(L2-d[\'W2\'])/(np.linalg.norm(d[\'W2\'])+1e-30)),\n        }\n        row={\'seed\':seed,\'candidate\':met,\'generation\':gm,\'nll_improvement\':d[\'baseline\'][\'expected_nll\']-met[\'expected_nll\'],\'js_improvement\':d[\'baseline\'][\'conditional_js\']-met[\'conditional_js\'],\'long_range_improvement\':d[\'baseline\'][\'exact_long_range_branch_mae\']-met[\'exact_long_range_branch_mae\'],\'BR_cosine\':cosine(BR,d[\'WR\'][:,:p1a.D].T),\'BO_initial_cosine\':cosine(BO,d[\'WO\'].T),\'BO_final_cosine\':cosine(BO,O.T),\'B2_initial_cosine\':cosine(B2,d[\'W2\'].T),\'B2_final_cosine\':cosine(B2,L2.T),\'off_mask_max_abs\':max(float(np.max(np.abs(O[d[\'maskO\']==0]))),float(np.max(np.abs(L1[d[\'mask1\']==0]))),float(np.max(np.abs(L2[d[\'mask2\']==0])))),\'E_spikes\':int(se),\'M_spikes\':int(sm),**changes}\n        rows.append(row);print(json.dumps(row,indent=2),flush=True);(outdir/f\'P1F_FINAL_SEED_{seed}.json\').write_text(json.dumps(row,indent=2));np.savez_compressed(outdir/f\'P1F_FINAL_SEED_{seed}.npz\',W_Q=Q,W_K=K,W_V=V,W_O=O,W_1=L1,W_2=L2,B_R=BR,B_O=BO,B_2=B2,samples=samp[:2000])\n\n    # Causal controls at shorter path count.\n    wsm,BR,BO,B2=train_once(d,mult,CONTROL_PATHS,9301,m_off=True);moff=max(float(np.max(np.abs(wsm[i]-[d[\'WQ\'],d[\'WK\'],d[\'WV\'],d[\'WO\'],d[\'W1\'],d[\'W2\']][i]))) for i in range(6))\n    wsn,_,_,_=train_once(d,mult,CONTROL_PATHS,9311,feedback_sign=-1.0);neg=evaluate(d,*wsn[:6])\n    wsr,_,_,_=train_once(d,mult,CONTROL_PATHS,9323,reset_every_force=True);reset=evaluate(d,*wsr[:6])\n    controls={\'m_off_max_all_weight_change\':moff,\'wrong_sign\':neg,\'reset_every_force\':reset};(outdir/\'P1F_CONTROLS.json\').write_text(json.dumps(controls,indent=2))\n\n    cagg={k:summarize([r[\'candidate\'][k] for r in rows]) for k in [\'expected_nll\',\'conditional_js\',\'exact_long_range_branch_mae\',\'expected_token_support\']}\n    gagg={k:summarize([r[\'generation\'][k] for r in rows]) for k in [\'joint_js_with_invalid_bucket\',\'valid_sequence_fraction\',\'mode_tv\',\'true_mode_coverage_fraction\',\'long_range_branch_mae\']}\n    ikeys=[\'nll_improvement\',\'js_improvement\',\'long_range_improvement\',\'WQ_change_rel_l2\',\'WK_change_rel_l2\',\'WV_change_rel_l2\',\'WO_change_rel_l2\',\'W1_change_rel_l2\',\'W2_change_rel_l2\',\'BR_cosine\',\'BO_initial_cosine\',\'BO_final_cosine\',\'B2_initial_cosine\',\'B2_final_cosine\',\'off_mask_max_abs\']\n    iagg={k:summarize([r[k] for r in rows]) for k in ikeys}\n    minchg=min(iagg[k][\'mean\'] for k in [\'WQ_change_rel_l2\',\'WK_change_rel_l2\',\'WV_change_rel_l2\',\'WO_change_rel_l2\',\'W1_change_rel_l2\',\'W2_change_rel_l2\'])\n    gates={\n        \'nll_improvement\':iagg[\'nll_improvement\'][\'mean\']>GATES[\'mean_nll_improvement_gt\'],\n        \'conditional_js_improvement\':iagg[\'js_improvement\'][\'mean\']>GATES[\'mean_conditional_js_improvement_gt\'],\n        \'long_range_improvement\':iagg[\'long_range_improvement\'][\'mean\']>GATES[\'mean_long_range_improvement_gt\'],\n        \'generation_joint_js_improvement\':base_g[\'joint_js_with_invalid_bucket\']-gagg[\'joint_js_with_invalid_bucket\'][\'mean\']>GATES[\'generation_joint_js_improvement_gt\'],\n        \'generation_validity_noninferior\':gagg[\'valid_sequence_fraction\'][\'mean\']-base_g[\'valid_sequence_fraction\']>GATES[\'generation_validity_noninferiority_gt\'],\n        \'all_six_weight_groups_changed\':minchg>GATES[\'all_six_weight_groups_change_gt\'],\n        \'sparse_masks_preserved\':iagg[\'off_mask_max_abs\'][\'max\']==0.0,\n        \'m_off_zero_change\':moff==GATES[\'m_off_max_change_eq\'],\n        \'wrong_sign_worse\':neg[\'expected_nll\']>d[\'baseline\'][\'expected_nll\'],\n    }\n    result={\'stage\':\'P1-F full-block joint plasticity\',\'selected_multiplier\':mult,\'learning_rates\':{\'WQ\':BASE_LR_Q*mult,\'WK\':BASE_LR_K*mult,\'WV\':BASE_LR_V*mult,\'WO\':BASE_LR_O*mult,\'W1\':BASE_LR_1*mult,\'W2\':BASE_LR_2*mult},\'final_paths\':FINAL_PATHS,\'parity\':par,\'baseline\':d[\'baseline\'],\'baseline_generation\':base_g,\'candidate_aggregate\':cagg,\'generation_aggregate\':gagg,\'improvement_aggregate\':iagg,\'P1E4_nll_reference\':E4_NLL_REFERENCE,\'beats_P1E4_nll\':cagg[\'expected_nll\'][\'mean\']<E4_NLL_REFERENCE,\'controls\':controls,\'gates\':gates,\'all_gates_pass\':bool(all(gates.values())),\'rows\':rows}\n    (outdir/\'P1F_RESULTS.json\').write_text(json.dumps(result,indent=2));print(json.dumps(result,indent=2),flush=True);return result\n\n\ndef write_report(outdir,r):\n    b=r[\'baseline\'];c=r[\'candidate_aggregate\'];bg=r[\'baseline_generation\'];g=r[\'generation_aggregate\'];i=r[\'improvement_aggregate\'];ctrl=r[\'controls\'];status=\'PASS\' if r[\'all_gates_pass\'] else \'CORE PASS / FULL GATES NOT ALL PASS\' if (r[\'gates\'][\'nll_improvement\'] and r[\'gates\'][\'conditional_js_improvement\'] and r[\'gates\'][\'long_range_improvement\']) else \'FAIL\'\n    txt=f\'\'\' + "\\\'\\\'\\\'" + r\'\'\'# P1-F — Full-block joint dynamical plasticity\\n\\n## Verdict\\n\\n**{status}**\\n\\nP1-F simultaneously opens the six internal forward synaptic populations of the small SNN-Transform block: W_Q, W_K, W_V, W_O, W_1 and W_2. The categorical readout remains fixed. Candidate learning uses the previously validated local MSDL E/M mechanisms and learned local feedback populations; no candidate autograd/BPTT is used.\\n\\n## Protocol\\n\\n- selected common multiplier: {r[\'selected_multiplier\']}\\n- learning rates: `{json.dumps(r[\'learning_rates\'])}`\\n- final paths per seed: {r[\'final_paths\']}\\n- experience mix: self={P_SELF}, IID={P_IID}, coherent={1-P_SELF-P_IID}\\n- Q/K perturbation sigma: {SIGMA_Q}/{SIGMA_K}\\n- sparse masks for W_O/W_1/W_2 are fixed\\n- all six forward matrices are frozen inside each 27-force-step path and update together at path end\\n\\n## Results\\n\\n| metric | frozen | full-block MSDL |\\n|---|---:|---:|\\n| NLL | {b[\'expected_nll\']:.6f} | {c[\'expected_nll\'][\'mean\']:.6f} ± {c[\'expected_nll\'][\'std\']:.6f} |\\n| conditional JS | {b[\'conditional_js\']:.6f} | {c[\'conditional_js\'][\'mean\']:.6f} |\\n| long-range MAE | {b[\'exact_long_range_branch_mae\']:.6f} | {c[\'exact_long_range_branch_mae\'][\'mean\']:.6f} |\\n| autonomous joint JS | {bg[\'joint_js_with_invalid_bucket\']:.6f} | {g[\'joint_js_with_invalid_bucket\'][\'mean\']:.6f} |\\n| autonomous validity | {bg[\'valid_sequence_fraction\']:.6f} | {g[\'valid_sequence_fraction\'][\'mean\']:.6f} |\\n\\nP1-E4 attention-only reference NLL = {r[\'P1E4_nll_reference\']:.6f}; full-block beats it: **{r[\'beats_P1E4_nll\']}**.\\n\\n## Forward / feedback diagnostics\\n\\n- specialized-vs-Torch parity, baseline max error: {r[\'parity\'][\'baseline_max_feature_error\']:.3e}\\n- all-six perturbed parity max error: {r[\'parity\'][\'all_six_perturbed_max_feature_error\']:.3e}\\n- BO cosine to W_O^T: initial {i[\'BO_initial_cosine\'][\'mean\']:.4f}, final-forward reference {i[\'BO_final_cosine\'][\'mean\']:.4f}\\n- B2 cosine to W_2^T: initial {i[\'B2_initial_cosine\'][\'mean\']:.4f}, final-forward reference {i[\'B2_final_cosine\'][\'mean\']:.4f}\\n- off-mask maximum: {i[\'off_mask_max_abs\'][\'max\']:.3e}\\n\\n## Controls\\n\\n- M-off max all-weight change: {ctrl[\'m_off_max_all_weight_change\']:.3e}\\n- wrong-sign NLL: {ctrl[\'wrong_sign\'][\'expected_nll\']:.6f}\\n- reset-every-force NLL: {ctrl[\'reset_every_force\'][\'expected_nll\']:.6f}\\n- reset-every-force long-range MAE: {ctrl[\'reset_every_force\'][\'exact_long_range_branch_mae\']:.6f}\\n\\n## Gates\\n\\n```json\\n{json.dumps(r[\'gates\'],indent=2)}\\n```\\n\\n## Interpretation boundary\\n\\nThis stage tests simultaneous plasticity of the full internal block under the exact PositiveRF reference interface. It does not yet establish moving-Q/K compatibility with the calibrated Izhikevich feature interface, and it does not test uninterrupted long-duration continual operation. Those remain subsequent gates.\\n\'\'\' + "\\\'\\\'\\\'" + r\'\'\'\n    (outdir/\'P1F_REPORT.md\').write_text(txt)\n\nif __name__==\'__main__\':\n    out=HERE\n    mult=run_dev(out)\n    r=run_final(out,mult)\n    write_report(out,r)\n\'\'\'\n\n# ========================= p1g_izh_reintegration.py =========================\n_EMBEDDED[\'p1g_izh_reintegration\'] = r\'\'\'#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n"""P1-G — reintegrate fixed per-head Izhikevich Q/K feature dynamics into P1-F.\n\nScientific question\n-------------------\nP1-F established finite-horizon MSDL learning of all six internal matrices using\nan exact PositiveRF Q/K feature interface. P1-G asks a stricter question:\n\n  (A) If a per-head Izhikevich RS trajectory decoder is calibrated ONLY on the\n      initial/pre-learning Q/K operating distribution and then frozen, does it\n      remain functionally valid after P1-F substantially changes W_Q/W_K?\n\n  (B) Does full-block MSDL still learn when the fixed Izh Q/K feature dynamics\n      are actually inside both the forward attention path and the local Q/K\n      perturbation-credit path throughout training?\n\nThe candidate learning path uses no autograd/BPTT.  The Izh operating points\nand decoders are fixed after pre-learning calibration; final P1-F weights and\nfinal P1-G seeds are not used for calibration.\n\nThis script is bundled with the frozen P1-F/P1-E/P1-A dependencies.  To avoid\nsilently forking the already-audited full-block update equation, the Izh-in-loop\ntrainer is mechanically derived from the bundled P1-F train_full_block source:\nonly the three exact PositiveRF attention calls are replaced by their Izh\ncounterparts.  The expanded derived trainer source is emitted for audit.\n"""\nfrom __future__ import annotations\n\nimport copy\nimport inspect\nimport json\nimport math\nimport sys\nimport subprocess\nimport zipfile\nfrom pathlib import Path\nfrom typing import Dict, List, Sequence, Tuple\n\nimport numpy as np\nimport torch\nimport torch.nn as nn\nfrom numba import njit\n\nHERE = Path(__file__).resolve().parent\nsys.path.insert(0, str(HERE))\n\nimport p1a_msdl_token_generation as p1a\nimport p1e4_joint_qkv_msdl as e4\nimport p1f_full_block_msdl as p1f\nimport p1d_attention_output_msdl as p1d\n\n# -----------------------------------------------------------------------------\n# Frozen P1-G protocol\n# -----------------------------------------------------------------------------\nFINAL_SEEDS = [9601, 9613, 9623]       # untouched by calibration/static audit\nFINAL_PATHS = p1f.FINAL_PATHS          # 1200; same frozen P1-F final exposure\nMULTIPLIER = 0.45                      # frozen P1-F value\nN_GENERATE = 6000\n\n# Calibration sees only the initial/pre-learning operating distribution.\nCALIBRATION_SEED = 9503\nCALIBRATION_CAP = 12000\nBIAS_GRID = (0., 1., 2., 3., 4., 5., 6., 8., 10.)\nGAIN_GRID = (.10, .15, .25, .35, .50, .75, 1.0, 1.4, 2.0)\nWINDOW_GRID = (6, 8, 10, 12, 16, 20, 24)\nRIDGE = 1e-5\n\n# These thresholds were frozen before the untouched in-loop final seeds were run.\n# The static conditional diagnostic had already been explored while designing P1-G,\n# so the report explicitly labels static results as a diagnostic rather than a\n# pristine preregistered final test.\nGATES = {\n    \'static_mean_abs_nll_delta_le\': 0.010,\n    \'static_mean_long_range_degradation_le\': 0.015,\n    \'static_mean_feature_rel_l2_le\': 0.060,\n    \'static_generation_joint_js_degradation_le\': 0.025,\n    \'static_generation_validity_drop_le\': 0.025,\n    \'inloop_mean_nll_le\': 0.665,\n    \'inloop_nll_gap_to_matched_exact_le\': 0.025,\n    \'inloop_long_range_gap_to_matched_exact_le\': 0.040,\n    \'inloop_generation_joint_js_gap_le\': 0.035,\n    \'inloop_generation_validity_drop_le\': 0.035,\n    \'inloop_nll_improvement_over_frozen_gt\': 0.040,\n    \'all_six_weight_groups_change_gt\': 1e-5,\n    \'sparse_offmask_max_eq\': 0.0,\n}\n\n\ndef summarize(xs: Sequence[float]) -> Dict[str, float]:\n    a = np.asarray(xs, dtype=np.float64)\n    return {\'mean\': float(a.mean()), \'std\': float(a.std()),\n            \'min\': float(a.min()), \'max\': float(a.max())}\n\n\ndef rel_l2(a: np.ndarray, b: np.ndarray) -> float:\n    return float(np.linalg.norm(a - b) / max(1e-30, np.linalg.norm(b)))\n\n\ndef cosine(a: np.ndarray, b: np.ndarray) -> float:\n    return float(np.sum(a*b) / (np.linalg.norm(a)*np.linalg.norm(b) + 1e-30))\n\n\n# -----------------------------------------------------------------------------\n# Izh RS scalar trajectory and fixed decoder calibration\n# -----------------------------------------------------------------------------\ndef izh_design_np(a: np.ndarray, bias: float, gain: float, window_ms: int) -> np.ndarray:\n    """Return [1, v_1, ..., v_T] for each scalar input a (vectorized NumPy)."""\n    x = np.asarray(a, dtype=np.float64).reshape(-1)\n    v = np.full_like(x, -65.0)\n    u = 0.2 * v\n    I = float(bias) + float(gain) * x\n    X = np.empty((x.size, int(window_ms)+1), dtype=np.float64)\n    X[:, 0] = 1.0\n    for t in range(int(window_ms)):\n        dv = 0.04*v*v + 5.0*v + 140.0 - u + I\n        v = v + 0.5*dv\n        dv = 0.04*v*v + 5.0*v + 140.0 - u + I\n        v = v + 0.5*dv\n        u = u + 0.02*(0.2*v - u)\n        fired = v >= 30.0\n        v = np.where(fired, -65.0, v)\n        u = np.where(fired, u + 8.0, u)\n        X[:, t+1] = v\n    return X\n\n\ndef fit_decoder_np(a: np.ndarray, y: np.ndarray, spec: Dict[str, float]) -> np.ndarray:\n    X = izh_design_np(a, spec[\'bias\'], spec[\'gain\'], int(spec[\'window_ms\']))\n    eye = np.eye(X.shape[1], dtype=np.float64)\n    eye[0, 0] = 0.0\n    return np.linalg.solve(X.T @ X + RIDGE*eye, X.T @ np.asarray(y, dtype=np.float64))\n\n\ndef calibration_pool_one_side(values: np.ndarray, features: int, seed: int) -> Tuple[Dict, np.ndarray, List[Dict]]:\n    """U4E/U4G-style fixed operating-point search using only scalar RF parity."""\n    a = np.asarray(values, dtype=np.float64).reshape(-1)\n    rng = np.random.default_rng(seed)\n    if a.size > CALIBRATION_CAP:\n        a = a[rng.choice(a.size, CALIBRATION_CAP, replace=False)]\n    p = rng.permutation(a.size)\n    nfit = max(200, min(int(0.70*a.size), a.size-200))\n    fit = a[p[:nfit]]; val = a[p[nfit:]]\n    norm = features**-0.5\n    yf = np.exp(np.clip(fit, -30.0, 30.0))*norm + 1e-6\n    yv = np.exp(np.clip(val, -30.0, 30.0))*norm + 1e-6\n\n    rows = []\n    best = None\n    for b in BIAS_GRID:\n        for g in GAIN_GRID:\n            for w in WINDOW_GRID:\n                spec = {\'bias\': float(b), \'gain\': float(g), \'window_ms\': int(w)}\n                dec = fit_decoder_np(fit, yf, spec)\n                raw = izh_design_np(val, b, g, w) @ dec\n                pred = np.maximum(raw, 1e-8)\n                rr = rel_l2(pred, yv)\n                clamp = float(np.mean(raw <= 1e-8))\n                # Favor parity first; tiny clamp/window penalties break near ties.\n                score = rr + 2e-3*clamp + 5e-6*w\n                row = {**spec, \'scalar_rel_l2\': rr, \'clamp_fraction\': clamp,\n                       \'score\': float(score)}\n                rows.append(row)\n                if best is None or score < best[0]:\n                    best = (score, spec, dec.copy(), row.copy())\n    rows.sort(key=lambda z: z[\'score\'])\n    return best[1], best[2], rows\n\n\ndef raw_qk_and_stable_a(d, WQ: np.ndarray, WK: np.ndarray) -> Tuple[List[np.ndarray], List[np.ndarray]]:\n    """Collect query-current and all-key stable-a values per head over all contexts."""\n    xn = d[\'xn\']; tpos = d[\'tpos\']; bq = d[\'bq\']; bk = d[\'bk\']; omega = d[\'omega\']\n    H = omega.shape[0]; D = WQ.shape[0]; hd = D//H; M = omega.shape[1]\n    qvals = [[] for _ in range(H)]; kvals = [[] for _ in range(H)]\n    scale = hd**-0.25\n    for ci in range(xn.shape[0]):\n        t = int(tpos[ci])\n        qflat = WQ @ xn[ci, t] + bq\n        for h in range(H):\n            q = qflat[h*hd:(h+1)*hd]\n            xx = q*scale\n            aa = omega[h] @ xx - 0.5*np.dot(xx, xx)\n            aa = np.clip(aa-aa.max(), -30.0, 0.0)\n            qvals[h].append(aa)\n        for n in range(xn.shape[1]):\n            kflat = WK @ xn[ci, n] + bk\n            for h in range(H):\n                k = kflat[h*hd:(h+1)*hd]\n                xx = k*scale\n                aa = omega[h] @ xx - 0.5*np.dot(xx, xx)\n                kvals[h].append(np.clip(aa, -30.0, 30.0))\n    return [np.concatenate(v) for v in qvals], [np.concatenate(v) for v in kvals]\n\n\ndef calibrate_initial_interface(d) -> Dict:\n    qvals, kvals = raw_qk_and_stable_a(d, d[\'WQ\'], d[\'WK\'])\n    qspec=[];kspec=[];qdec=[];kdec=[];reports=[]\n    for h in range(len(qvals)):\n        qs,qd,qr = calibration_pool_one_side(qvals[h], p1a.FEATURES, CALIBRATION_SEED+100*h+1)\n        ks,kd,kr = calibration_pool_one_side(kvals[h], p1a.FEATURES, CALIBRATION_SEED+100*h+2)\n        qspec.append(qs);kspec.append(ks);qdec.append(qd);kdec.append(kd)\n        reports.append({\'head\':h,\'Q_selected\':{**qs, **{k:qr[0][k] for k in (\'scalar_rel_l2\',\'clamp_fraction\',\'score\')}},\n                        \'K_selected\':{**ks, **{k:kr[0][k] for k in (\'scalar_rel_l2\',\'clamp_fraction\',\'score\')}},\n                        \'Q_top5\':qr[:5],\'K_top5\':kr[:5]})\n    return {\'q_specs\':qspec,\'k_specs\':kspec,\'q_decoders\':qdec,\'k_decoders\':kdec,\n            \'head_reports\':reports}\n\n\n\ndef calibration_from_json(obj):\n    return {\'q_specs\':obj[\'q_specs\'],\'k_specs\':obj[\'k_specs\'],\n            \'q_decoders\':[np.asarray(x,dtype=np.float64) for x in obj[\'q_decoders\']],\n            \'k_decoders\':[np.asarray(x,dtype=np.float64) for x in obj[\'k_decoders\']],\n            \'head_reports\':obj[\'head_reports\']}\n\ndef pack_calibration(cal: Dict) -> Tuple[np.ndarray,...]:\n    H = len(cal[\'q_specs\'])\n    maxw = max(max(int(s[\'window_ms\']) for s in cal[\'q_specs\']),\n               max(int(s[\'window_ms\']) for s in cal[\'k_specs\']))\n    qb=np.zeros(H);qg=np.zeros(H);qw=np.zeros(H,np.int64);qd=np.zeros((H,maxw+1))\n    kb=np.zeros(H);kg=np.zeros(H);kw=np.zeros(H,np.int64);kd=np.zeros((H,maxw+1))\n    for h in range(H):\n        qs=cal[\'q_specs\'][h];ks=cal[\'k_specs\'][h]\n        qb[h]=qs[\'bias\'];qg[h]=qs[\'gain\'];qw[h]=int(qs[\'window_ms\']);qd[h,:len(cal[\'q_decoders\'][h])]=cal[\'q_decoders\'][h]\n        kb[h]=ks[\'bias\'];kg[h]=ks[\'gain\'];kw[h]=int(ks[\'window_ms\']);kd[h,:len(cal[\'k_decoders\'][h])]=cal[\'k_decoders\'][h]\n    return qb,qg,qw,qd,kb,kg,kw,kd\n\n\n# -----------------------------------------------------------------------------\n# Numba Izh feature interface used inside the learning loop\n# -----------------------------------------------------------------------------\n@njit(cache=True)\ndef izh_scalar_map(a,bias,gain,window_ms,decoder):\n    v=-65.0;u=0.2*v;I=bias+gain*a;out=decoder[0]\n    for t in range(window_ms):\n        dv=0.04*v*v+5.0*v+140.0-u+I;v=v+0.5*dv\n        dv=0.04*v*v+5.0*v+140.0-u+I;v=v+0.5*dv\n        u=u+0.02*(0.2*v-u)\n        if v>=30.0:\n            v=-65.0;u=u+8.0\n        out+=decoder[t+1]*v\n    if out<1e-8:out=1e-8\n    return out\n\n@njit(cache=True)\ndef phi_q_izh_vec(q,omega_h,bias,gain,window_ms,decoder):\n    hd=q.shape[0];M=omega_h.shape[0];scale=hd**(-0.25);diag=0.0\n    for c in range(hd):\n        xx=q[c]*scale;diag+=xx*xx\n    diag*=0.5;aa=np.empty(M,np.float64);mx=-1e300\n    for m in range(M):\n        dash=0.0\n        for c in range(hd):dash+=(q[c]*scale)*omega_h[m,c]\n        aa[m]=dash-diag\n        if aa[m]>mx:mx=aa[m]\n    out=np.empty(M,np.float64)\n    for m in range(M):\n        a=aa[m]-mx\n        if a<-30.0:a=-30.0\n        elif a>0.0:a=0.0\n        out[m]=izh_scalar_map(a,bias,gain,window_ms,decoder)\n    return out\n\n@njit(cache=True)\ndef phi_k_izh_vec(k,omega_h,bias,gain,window_ms,decoder):\n    hd=k.shape[0];M=omega_h.shape[0];scale=hd**(-0.25);diag=0.0\n    for c in range(hd):\n        xx=k[c]*scale;diag+=xx*xx\n    diag*=0.5;out=np.empty(M,np.float64)\n    for m in range(M):\n        dash=0.0\n        for c in range(hd):dash+=(k[c]*scale)*omega_h[m,c]\n        a=dash-diag\n        if a<-30.0:a=-30.0\n        elif a>30.0:a=30.0\n        out[m]=izh_scalar_map(a,bias,gain,window_ms,decoder)\n    return out\n\n@njit(cache=True)\ndef score_qk_izh(q,k,omega_h,qbias,qgain,qwin,qdec,kbias,kgain,kwin,kdec):\n    pq=phi_q_izh_vec(q,omega_h,qbias,qgain,qwin,qdec)\n    pk=phi_k_izh_vec(k,omega_h,kbias,kgain,kwin,kdec)\n    s=0.0\n    for m in range(pq.shape[0]):s+=pq[m]*pk[m]\n    return s\n\n@njit(cache=True)\ndef joint_attention_state_izh(WQ,bq,WK,bk,WV,bv,xn,t,omega,qbias,qgain,qwin,qdec,kbias,kgain,kwin,kdec):\n    D=WQ.shape[0];H=omega.shape[0];hd=D//H;N=xn.shape[0]\n    q=np.empty((H,hd),np.float64);k=np.empty((H,N,hd),np.float64);v=np.empty((H,N,hd),np.float64)\n    for r in range(D):\n        z=bq[r]\n        for c in range(D):z+=WQ[r,c]*xn[t,c]\n        hh=r//hd;q[hh,r-hh*hd]=z\n    for n in range(N):\n        for r in range(D):\n            zk=bk[r];zv=bv[r]\n            for c in range(D):\n                xx=xn[n,c];zk+=WK[r,c]*xx;zv+=WV[r,c]*xx\n            hh=r//hd;rr=r-hh*hd;k[hh,n,rr]=zk;v[hh,n,rr]=zv\n    scores=np.empty((H,N),np.float64);den=np.zeros(H,np.float64);num=np.zeros((H,hd),np.float64);alpha=np.empty((H,N),np.float64);a=np.empty(D,np.float64)\n    for hh in range(H):\n        for n in range(N):\n            s=score_qk_izh(q[hh],k[hh,n],omega[hh],qbias[hh],qgain[hh],qwin[hh],qdec[hh],kbias[hh],kgain[hh],kwin[hh],kdec[hh])\n            scores[hh,n]=s;den[hh]+=s\n            for rr in range(hd):num[hh,rr]+=s*v[hh,n,rr]\n        dd=den[hh] if den[hh]>1e-8 else 1e-8\n        for n in range(N):alpha[hh,n]=scores[hh,n]/dd\n        for rr in range(hd):a[hh*hd+rr]=num[hh,rr]/dd\n    return a,q,k,v,scores,num,den,alpha\n\n@njit(cache=True)\ndef read_head_from_q_izh(q,k_h,v_h,omega_h,qbias,qgain,qwin,qdec,kbias,kgain,kwin,kdec):\n    N=k_h.shape[0];hd=q.shape[0];num=np.zeros(hd,np.float64);den=0.0\n    for n in range(N):\n        s=score_qk_izh(q,k_h[n],omega_h,qbias,qgain,qwin,qdec,kbias,kgain,kwin,kdec);den+=s\n        for r in range(hd):num[r]+=s*v_h[n,r]\n    if den<1e-8:den=1e-8\n    a=np.empty(hd,np.float64)\n    for r in range(hd):a[r]=num[r]/den\n    return a\n\n\n# -----------------------------------------------------------------------------\n# LUT-accelerated evaluation of the *same reset-per-call* frozen Izh operator.\n# The canonical PerHeadIzhPhi has no carried Izh membrane state between feature\n# evaluations: it starts each scalar trajectory from v=-65,u=.2v. Therefore its\n# calibrated feature map is a deterministic 1-D function F_h(a).  A dense LUT\n# is used only to make the in-loop audit tractable; direct recurrence is retained\n# for post-learning static/generation evaluation and LUT error is measured.\n# -----------------------------------------------------------------------------\nLUT_MIN=-30.0\nLUT_MAX=30.0\nLUT_N=12001\nLUT_STEP=(LUT_MAX-LUT_MIN)/(LUT_N-1)\n\ndef build_luts(cal):\n    grid=np.linspace(LUT_MIN,LUT_MAX,LUT_N,dtype=np.float64)\n    H=len(cal[\'q_specs\']);ql=np.empty((H,LUT_N),np.float64);kl=np.empty((H,LUT_N),np.float64)\n    for h in range(H):\n        qs=cal[\'q_specs\'][h];ks=cal[\'k_specs\'][h]\n        ql[h]=np.maximum(izh_design_np(grid,qs[\'bias\'],qs[\'gain\'],qs[\'window_ms\'])@cal[\'q_decoders\'][h],1e-8)\n        kl[h]=np.maximum(izh_design_np(grid,ks[\'bias\'],ks[\'gain\'],ks[\'window_ms\'])@cal[\'k_decoders\'][h],1e-8)\n    return ql,kl,float(LUT_STEP)\n\n@njit(cache=True)\ndef lut_scalar_map(a,table,step):\n    if a<=LUT_MIN:return table[0]\n    if a>=LUT_MAX:return table[table.shape[0]-1]\n    x=(a-LUT_MIN)/step;i=int(x);f=x-i\n    if i>=table.shape[0]-1:return table[table.shape[0]-1]\n    return table[i]*(1.0-f)+table[i+1]*f\n\n@njit(cache=True)\ndef phi_q_lut_vec(q,omega_h,table,step):\n    hd=q.shape[0];M=omega_h.shape[0];scale=hd**(-0.25);diag=0.0\n    for c in range(hd):\n        xx=q[c]*scale;diag+=xx*xx\n    diag*=0.5;aa=np.empty(M,np.float64);mx=-1e300\n    for m in range(M):\n        dash=0.0\n        for c in range(hd):dash+=(q[c]*scale)*omega_h[m,c]\n        aa[m]=dash-diag\n        if aa[m]>mx:mx=aa[m]\n    out=np.empty(M,np.float64)\n    for m in range(M):\n        a=aa[m]-mx\n        if a<-30.0:a=-30.0\n        elif a>0.0:a=0.0\n        out[m]=lut_scalar_map(a,table,step)\n    return out\n\n@njit(cache=True)\ndef phi_k_lut_vec(k,omega_h,table,step):\n    hd=k.shape[0];M=omega_h.shape[0];scale=hd**(-0.25);diag=0.0\n    for c in range(hd):\n        xx=k[c]*scale;diag+=xx*xx\n    diag*=0.5;out=np.empty(M,np.float64)\n    for m in range(M):\n        dash=0.0\n        for c in range(hd):dash+=(k[c]*scale)*omega_h[m,c]\n        a=dash-diag\n        if a<-30.0:a=-30.0\n        elif a>30.0:a=30.0\n        out[m]=lut_scalar_map(a,table,step)\n    return out\n\n@njit(cache=True)\ndef score_qk_lut(q,k,omega_h,qtable,ktable,step):\n    pq=phi_q_lut_vec(q,omega_h,qtable,step);pk=phi_k_lut_vec(k,omega_h,ktable,step);z=0.0\n    for m in range(pq.shape[0]):z+=pq[m]*pk[m]\n    return z\n\n@njit(cache=True)\ndef joint_attention_state_lut(WQ,bq,WK,bk,WV,bv,xn,t,omega,qlut,klut,step):\n    D=WQ.shape[0];H=omega.shape[0];hd=D//H;N=xn.shape[0]\n    q=np.empty((H,hd),np.float64);k=np.empty((H,N,hd),np.float64);v=np.empty((H,N,hd),np.float64)\n    for r in range(D):\n        z=bq[r]\n        for c in range(D):z+=WQ[r,c]*xn[t,c]\n        hh=r//hd;q[hh,r-hh*hd]=z\n    for n in range(N):\n        for r in range(D):\n            zk=bk[r];zv=bv[r]\n            for c in range(D):\n                xx=xn[n,c];zk+=WK[r,c]*xx;zv+=WV[r,c]*xx\n            hh=r//hd;rr=r-hh*hd;k[hh,n,rr]=zk;v[hh,n,rr]=zv\n    scores=np.empty((H,N),np.float64);den=np.zeros(H,np.float64);num=np.zeros((H,hd),np.float64);alpha=np.empty((H,N),np.float64);a=np.empty(D,np.float64)\n    for hh in range(H):\n        pq=phi_q_lut_vec(q[hh],omega[hh],qlut[hh],step)\n        for n in range(N):\n            pk=phi_k_lut_vec(k[hh,n],omega[hh],klut[hh],step);ss=0.0\n            for m in range(pq.shape[0]):ss+=pq[m]*pk[m]\n            scores[hh,n]=ss;den[hh]+=ss\n            for rr in range(hd):num[hh,rr]+=ss*v[hh,n,rr]\n        dd=den[hh] if den[hh]>1e-8 else 1e-8\n        for n in range(N):alpha[hh,n]=scores[hh,n]/dd\n        for rr in range(hd):a[hh*hd+rr]=num[hh,rr]/dd\n    return a,q,k,v,scores,num,den,alpha\n\n@njit(cache=True)\ndef score_pair_qk_lut(q,kp,km,omega_h,qtable,ktable,step):\n    pq=phi_q_lut_vec(q,omega_h,qtable,step)\n    pkp=phi_k_lut_vec(kp,omega_h,ktable,step);pkm=phi_k_lut_vec(km,omega_h,ktable,step)\n    sp=0.0;sm=0.0\n    for m in range(pq.shape[0]):sp+=pq[m]*pkp[m];sm+=pq[m]*pkm[m]\n    return sp,sm\n\n@njit(cache=True)\ndef read_pair_head_from_q_lut(qp,qm,k_h,v_h,omega_h,qtable,ktable,step):\n    N=k_h.shape[0];hd=qp.shape[0];pqp=phi_q_lut_vec(qp,omega_h,qtable,step);pqm=phi_q_lut_vec(qm,omega_h,qtable,step)\n    nump=np.zeros(hd,np.float64);numm=np.zeros(hd,np.float64);denp=0.0;denm=0.0\n    for n in range(N):\n        pk=phi_k_lut_vec(k_h[n],omega_h,ktable,step);sp=0.0;sm=0.0\n        for m in range(pk.shape[0]):sp+=pqp[m]*pk[m];sm+=pqm[m]*pk[m]\n        denp+=sp;denm+=sm\n        for r in range(hd):nump[r]+=sp*v_h[n,r];numm[r]+=sm*v_h[n,r]\n    if denp<1e-8:denp=1e-8\n    if denm<1e-8:denm=1e-8\n    ap=np.empty(hd,np.float64);am=np.empty(hd,np.float64)\n    for r in range(hd):ap[r]=nump[r]/denp;am[r]=numm[r]/denm\n    return ap,am\n\n@njit(cache=True)\ndef read_head_from_q_lut(q,k_h,v_h,omega_h,qtable,ktable,step):\n    N=k_h.shape[0];hd=q.shape[0];num=np.zeros(hd,np.float64);den=0.0\n    for n in range(N):\n        ss=score_qk_lut(q,k_h[n],omega_h,qtable,ktable,step);den+=ss\n        for r in range(hd):num[r]+=ss*v_h[n,r]\n    if den<1e-8:den=1e-8\n    a=np.empty(hd,np.float64)\n    for r in range(hd):a[r]=num[r]/den\n    return a\n\n# -----------------------------------------------------------------------------\n# Derive the Izh-in-loop full-block trainer from the audited P1-F trainer.\n# -----------------------------------------------------------------------------\ndef build_izh_trainer():\n    src = inspect.getsource(p1f.train_full_block.py_func)\n    src = src.replace(\'@njit(cache=True)\', \'@njit\')\n    src = src.replace(\'def train_full_block(\', \'def train_full_block_izh(\')\n    old = \'WQ_init,bq,WK_init,bk,WV_init,bv,omega,\\n\'\n    new = \'WQ_init,bq,WK_init,bk,WV_init,bv,omega,\\n    qlut,klut,lut_step,\\n\'\n    if old not in src: raise RuntimeError(\'P1-F signature anchor not found\')\n    src = src.replace(old,new,1)\n    r0=\'e4.joint_attention_state(Q0,bq,K0,bk,V0,bv,xn[ci],t,omega)\'\n    r1=\'joint_attention_state_lut(Q0,bq,K0,bk,V0,bv,xn[ci],t,omega,qlut,klut,lut_step)\'\n    if src.count(r0)!=1: raise RuntimeError(\'P1-F joint attention anchor count changed\')\n    src=src.replace(r0,r1)\n    kpair0=\'sp=e4.score_qk(q[hh],kp,omega[hh]);smm=e4.score_qk(q[hh],km,omega[hh]);s0=scores[hh,n]\'\n    kpair1=\'sp,smm=score_pair_qk_lut(q[hh],kp,km,omega[hh],qlut[hh],klut[hh],lut_step);s0=scores[hh,n]\'\n    if src.count(kpair0)!=1: raise RuntimeError(\'P1-F K perturbation pair anchor changed\')\n    src=src.replace(kpair0,kpair1)\n    qpair0=\'ap=e4.read_head_from_q(qp,k[hh],v[hh],omega[hh]);am=e4.read_head_from_q(qm,k[hh],v[hh],omega[hh]);scalar=0.0\'\n    qpair1=\'ap,am=read_pair_head_from_q_lut(qp,qm,k[hh],v[hh],omega[hh],qlut[hh],klut[hh],lut_step);scalar=0.0\'\n    if src.count(qpair0)!=1: raise RuntimeError(\'P1-F Q perturbation pair anchor changed\')\n    src=src.replace(qpair0,qpair1)\n    ns={\'njit\':njit,\'np\':np,\'math\':math,\'p1a\':p1a,\'e4\':e4,\'p1d\':p1f.p1d,\n        \'joint_attention_state_lut\':joint_attention_state_lut,\n        \'score_pair_qk_lut\':score_pair_qk_lut,\'read_pair_head_from_q_lut\':read_pair_head_from_q_lut}\n    exec(src,ns)\n    return ns[\'train_full_block_izh\'],src\n\nTRAIN_FULL_BLOCK_IZH, DERIVED_TRAINER_SOURCE = build_izh_trainer()\n\n\n# -----------------------------------------------------------------------------\n# Static/in-loop evaluation under the Izh interface\n# -----------------------------------------------------------------------------\n@njit(cache=True)\ndef attention_features_izh_numba(WQ,bq,WK,bk,WV,bv,xn,tpos,omega,qbias,qgain,qwin,qdec,kbias,kgain,kwin,kdec):\n    C=xn.shape[0];A=np.empty((C,p1a.D),np.float64)\n    for i in range(C):\n        A[i]=joint_attention_state_izh(WQ,bq,WK,bk,WV,bv,xn[i],int(tpos[i]),omega,qbias,qgain,qwin,qdec,kbias,kgain,kwin,kdec)[0]\n    return A\n\n\ndef features_full_izh(d,cal_pack,WQ,WK,WV,WO,W1,W2):\n    qb,qg,qw,qd,kb,kg,kw,kd=cal_pack\n    A=attention_features_izh_numba(WQ,d[\'bq\'],WK,d[\'bk\'],WV,d[\'bv\'],d[\'xn\'],d[\'tpos\'],d[\'omega\'],qb,qg,qw,qd,kb,kg,kw,kd)\n    return p1d.forward_features_wo(WO,A,d[\'xres\'],d[\'bo\'],d[\'gamma2\'],d[\'beta2\'],d[\'eps2\'],W1,d[\'b1\'],d[\'theta\'],W2,d[\'b2\'])\n\n\ndef evaluate_izh(d,cal_pack,WQ,WK,WV,WO,W1,W2):\n    f=features_full_izh(d,cal_pack,WQ,WK,WV,WO,W1,W2)\n    return p1a.evaluate_W(d[\'WR\'],f,d[\'targets\'],d[\'masses\'],d[\'keys\'])\n\n\nclass IzhPerHeadPhi(nn.Module):\n    """Torch generation interface matching the frozen P1-G calibration."""\n    def __init__(self, exact, specs, decoders):\n        super().__init__()\n        self.head_dim=exact.head_dim;self.features=exact.features;self.heads=len(specs)\n        self.register_buffer(\'omega\',exact.omega.detach().clone())\n        self.specs=[dict(s) for s in specs]\n        for h,d in enumerate(decoders):self.register_buffer(f\'decoder_{h}\',torch.tensor(d,dtype=torch.float32))\n\n    def stable_a(self,x,is_query):\n        xx=x*(self.head_dim**-0.25)\n        dash=torch.einsum(\'bhnd,hmd->bhnm\',xx,self.omega)\n        diag=0.5*(xx*xx).sum(-1,keepdim=True);a=dash-diag\n        return (a-a.amax(-1,keepdim=True).detach()).clamp(-30.,0.) if is_query else a.clamp(-30.,30.)\n\n    @staticmethod\n    def design(a,bias,gain,window_ms):\n        x=a.float().reshape(-1);v=torch.full_like(x,-65.);u=.2*v;I=float(bias)+float(gain)*x\n        cols=[torch.ones_like(x)]\n        for _ in range(int(window_ms)):\n            dv=.04*v*v+5*v+140-u+I;v=v+.5*dv\n            dv=.04*v*v+5*v+140-u+I;v=v+.5*dv\n            u=u+.02*(.2*v-u);fired=v>=30.\n            v=torch.where(fired,torch.full_like(v,-65.),v);u=torch.where(fired,u+8.,u)\n            cols.append(v)\n        return torch.stack(cols,dim=1)\n\n    def forward(self,x,*,is_query:bool):\n        a=self.stable_a(x,is_query);outs=[]\n        for h,spec in enumerate(self.specs):\n            ah=a[:,h];X=self.design(ah,spec[\'bias\'],spec[\'gain\'],spec[\'window_ms\'])\n            dec=getattr(self,f\'decoder_{h}\').to(device=X.device,dtype=X.dtype)\n            outs.append((X@dec).clamp_min(1e-8).reshape_as(ah))\n        return torch.stack(outs,dim=1)\n\n\nclass LUTPerHeadPhi(nn.Module):\n    """Vectorized Torch interpolation of the same fixed reset-per-call Izh map."""\n    def __init__(self, exact, tables, step):\n        super().__init__();self.head_dim=exact.head_dim;self.features=exact.features;self.heads=tables.shape[0];self.step=float(step)\n        self.register_buffer(\'omega\',exact.omega.detach().clone())\n        self.register_buffer(\'tables\',torch.tensor(tables,dtype=torch.float32))\n    def stable_a(self,x,is_query):\n        xx=x*(self.head_dim**-0.25);dash=torch.einsum(\'bhnd,hmd->bhnm\',xx,self.omega);diag=.5*(xx*xx).sum(-1,keepdim=True);a=dash-diag\n        return (a-a.amax(-1,keepdim=True).detach()).clamp(-30.,0.) if is_query else a.clamp(-30.,30.)\n    def forward(self,x,*,is_query:bool):\n        a=self.stable_a(x,is_query);outs=[];L=self.tables.shape[1]\n        for h in range(self.heads):\n            z=((a[:,h]-LUT_MIN)/self.step).clamp(0,L-1-1e-7);idx=torch.floor(z).long().clamp(0,L-2);f=z-idx.to(z.dtype)\n            tab=self.tables[h];y=tab[idx]*(1.0-f)+tab[idx+1]*f;outs.append(y)\n        return torch.stack(outs,dim=1)\n\n\ndef make_block_izh(d,cal,WQ,WK,WV,WO,W1,W2,direct=False):\n    b=copy.deepcopy(d[\'block\']).eval();p1f.set_block_all(b,d,WQ,WK,WV,WO,W1,W2)\n    if direct:\n        b.phi_q=IzhPerHeadPhi(b.phi_q,cal[\'q_specs\'],cal[\'q_decoders\'])\n        b.phi_k=IzhPerHeadPhi(b.phi_k,cal[\'k_specs\'],cal[\'k_decoders\'])\n    else:\n        qlut,klut,step=build_luts(cal)\n        b.phi_q=LUTPerHeadPhi(b.phi_q,qlut,step);b.phi_k=LUTPerHeadPhi(b.phi_k,klut,step)\n    return b\n\n\ndef generation_metrics(samples,d):\n    js,val,tv,cov=p1a.empirical_js_with_invalid_bucket(samples,p1a.enumerate_true_distribution())\n    return {\'joint_js\':float(js),\'valid_fraction\':float(val),\'mode_tv\':float(tv),\'true_mode_coverage\':int(cov),\n            \'token_support\':float(p1a.generated_support_rate(samples)),\n            \'long_range_mae\':float(p1a.long_range_branch_mae(samples))}\n\n\ndef generation_izh(d,cal,WQ,WK,WV,WO,W1,W2,n,seed):\n    b=make_block_izh(d,cal,WQ,WK,WV,WO,W1,W2)\n    samp=p1a.autonomous_generate(b,d[\'tok\'],d[\'pos\'],d[\'WR\'],n,seed,p1a.GEN_BATCH)\n    return samp,generation_metrics(samp,d)\n\n\ndef generation_exact(d,WQ,WK,WV,WO,W1,W2,n,seed):\n    samp=p1f.generation(d,WQ,WK,WV,WO,W1,W2,n,seed)\n    return samp,generation_metrics(samp,d)\n\n\ndef interface_diagnostics(d,cal_pack,WQ,WK,WV) -> Dict[str,float]:\n    qb,qg,qw,qd,kb,kg,kw,kd=cal_pack\n    xn=d[\'xn\'];tpos=d[\'tpos\'];omega=d[\'omega\'];bq=d[\'bq\'];bk=d[\'bk\'];bv=d[\'bv\'];Hh=omega.shape[0];D=WQ.shape[0];hd=D//Hh\n    sqe_q=sqn_q=sqe_k=sqn_k=sqe_H=sqn_H=sqe_g=sqn_g=sqe_a=sqn_a=0.0\n    for ci in range(xn.shape[0]):\n        ex=e4.joint_attention_state(WQ,bq,WK,bk,WV,bv,xn[ci],int(tpos[ci]),omega)\n        iz=joint_attention_state_izh(WQ,bq,WK,bk,WV,bv,xn[ci],int(tpos[ci]),omega,qb,qg,qw,qd,kb,kg,kw,kd)\n        ae,qe,ke,ve,se,nume,dene,alpe=ex;ai,qi,ki,vi,si,numi,deni,alpi=iz\n        for h in range(Hh):\n            pq_e=e4.phi_q_vec(qe[h],omega[h]);pq_i=phi_q_izh_vec(qi[h],omega[h],qb[h],qg[h],qw[h],qd[h])\n            dq=pq_i-pq_e;sqe_q+=float(np.dot(dq,dq));sqn_q+=float(np.dot(pq_e,pq_e))\n            # keys and H/g\n            M=omega.shape[1];He=np.zeros((M,hd));Hi=np.zeros((M,hd));ge=np.zeros(M);gi=np.zeros(M)\n            for n in range(xn.shape[1]):\n                pk_e=e4.phi_k_vec(ke[h,n],omega[h]);pk_i=phi_k_izh_vec(ki[h,n],omega[h],kb[h],kg[h],kw[h],kd[h])\n                dk=pk_i-pk_e;sqe_k+=float(np.dot(dk,dk));sqn_k+=float(np.dot(pk_e,pk_e))\n                ge+=pk_e;gi+=pk_i\n                for m in range(M):\n                    for r in range(hd):\n                        He[m,r]+=pk_e[m]*ve[h,n,r];Hi[m,r]+=pk_i[m]*vi[h,n,r]\n            dd=Hi-He;sqe_H+=float(np.sum(dd*dd));sqn_H+=float(np.sum(He*He))\n            dg=gi-ge;sqe_g+=float(np.dot(dg,dg));sqn_g+=float(np.dot(ge,ge))\n        da=ai-ae;sqe_a+=float(np.dot(da,da));sqn_a+=float(np.dot(ae,ae))\n    return {\'q_feature_rel_l2\':math.sqrt(sqe_q/max(sqn_q,1e-30)),\n            \'k_feature_rel_l2\':math.sqrt(sqe_k/max(sqn_k,1e-30)),\n            \'H_rel_l2\':math.sqrt(sqe_H/max(sqn_H,1e-30)),\n            \'g_rel_l2\':math.sqrt(sqe_g/max(sqn_g,1e-30)),\n            \'attended_rel_l2\':math.sqrt(sqe_a/max(sqn_a,1e-30))}\n\n\ndef stable_a_summary(d,WQ,WK):\n    q,k=raw_qk_and_stable_a(d,WQ,WK)\n    def one(vals):\n        a=np.concatenate(vals)\n        z=np.quantile(a,[0,.01,.1,.5,.9,.99,1.0])\n        return {\'min\':float(z[0]),\'p01\':float(z[1]),\'p10\':float(z[2]),\'median\':float(z[3]),\'p90\':float(z[4]),\'p99\':float(z[5]),\'max\':float(z[6])}\n    return {\'Q\':one(q),\'K\':one(k)}\n\n\ndef train_once_izh(d,lut_pack,paths,seed):\n    BR,BO,B2=p1f.learn_feedbacks(d,100000+seed)\n    qlut,klut,lut_step=lut_pack\n    args=(d[\'xn\'],d[\'xres\'],d[\'tpos\'],d[\'targets\'],d[\'masses\'],d[\'WR\'],BR,BO,B2,\n          d[\'WQ\'],d[\'bq\'],d[\'WK\'],d[\'bk\'],d[\'WV\'],d[\'bv\'],d[\'omega\'],\n          qlut,klut,lut_step,\n          d[\'WO\'],d[\'maskO\'],d[\'bo\'],d[\'gamma2\'],d[\'beta2\'],d[\'eps2\'],\n          d[\'W1\'],d[\'mask1\'],d[\'b1\'],d[\'theta\'],d[\'W2\'],d[\'mask2\'],d[\'b2\'],\n          d[\'sci\'],d[\'st\'],d[\'sp\'],d[\'nxt\'],d[\'cpos\'],d[\'root\'],d[\'static\'])\n    ws=TRAIN_FULL_BLOCK_IZH(*args,paths,\n        p1f.BASE_LR_Q*MULTIPLIER,p1f.BASE_LR_K*MULTIPLIER,p1f.BASE_LR_V*MULTIPLIER,\n        p1f.BASE_LR_O*MULTIPLIER,p1f.BASE_LR_1*MULTIPLIER,p1f.BASE_LR_2*MULTIPLIER,\n        p1f.SIGMA_Q,p1f.SIGMA_K,seed,p1f.P_SELF,p1f.P_IID)\n    return ws,BR,BO,B2\n\n\ndef load_p1f_weights(seed:int):\n    p=HERE/f\'P1F_FINAL_SEED_{seed}.npz\'\n    z=np.load(p)\n    names=[\'W_Q\',\'W_K\',\'W_V\',\'W_O\',\'W_1\',\'W_2\']\n    return tuple(z[n] for n in names)\n\n\ndef weight_deltas(d,ws):\n    names=[\'WQ\',\'WK\',\'WV\',\'WO\',\'W1\',\'W2\'];base=[d[n] for n in names]\n    return {n:rel_l2(w,b) for n,w,b in zip(names,ws,base)}\n\n\ndef sparse_offmask(d,ws):\n    _,_,_,O,L1,L2=ws\n    return float(max(np.max(np.abs(O*(1-d[\'maskO\']))),np.max(np.abs(L1*(1-d[\'mask1\']))),np.max(np.abs(L2*(1-d[\'mask2\'])))))\n\n\ndef jsonable_calibration(cal):\n    return {\'q_specs\':cal[\'q_specs\'],\'k_specs\':cal[\'k_specs\'],\n            \'q_decoders\':[x.tolist() for x in cal[\'q_decoders\']],\n            \'k_decoders\':[x.tolist() for x in cal[\'k_decoders\']],\n            \'head_reports\':cal[\'head_reports\']}\n\n\ndef main():\n    torch.set_num_threads(4)\n    out=HERE\n    print(\'[P1-G] setup\',flush=True)\n    d=p1f.setup();baseline=d[\'baseline\']\n\n    calfile=out/\'P1G_CALIBRATION.json\'\n    if calfile.exists():\n        print(\'[P1-G] loading frozen initial-distribution calibration\',flush=True)\n        calj=json.loads(calfile.read_text());cal=calibration_from_json(calj)\n    else:\n        print(\'[P1-G] calibrating fixed neuronal interface on initial distribution only\',flush=True)\n        cal=calibrate_initial_interface(d);calj=jsonable_calibration(cal)\n        calj[\'calibration_scope\']=\'initial/pre-learning WQ/WK distribution only; no P1-F final weights, task labels, or P1-G final seeds used\'\n        calfile.write_text(json.dumps(calj,indent=2))\n    cal_pack=pack_calibration(cal);lut_pack=build_luts(cal)\n    (out/\'P1G_DERIVED_TRAINER.py.txt\').write_text(DERIVED_TRAINER_SOURCE)\n\n    # Numerical parity of the custom Numba vs Torch Izh interface at initial weights.\n    fnum=features_full_izh(d,cal_pack,d[\'WQ\'],d[\'WK\'],d[\'WV\'],d[\'WO\'],d[\'W1\'],d[\'W2\'])\n    b=make_block_izh(d,cal,d[\'WQ\'],d[\'WK\'],d[\'WV\'],d[\'WO\'],d[\'W1\'],d[\'W2\'],direct=True)\n    with torch.no_grad():\n        x=p1a.encode(d[\'arrays\'],d[\'tok\'],d[\'pos\']);y,_=b.step(x,None);ii=torch.arange(len(d[\'arrays\']));tt=torch.tensor(d[\'tpos\']);ft=p1a.normalize_readout_feature(y[ii,tt]).numpy()\n    \n    # Validate LUT acceleration against direct recurrent Izh maps on a dense scalar grid.\n    qlut,klut,lstep=lut_pack;testa=np.linspace(-30.0,30.0,6001);luterrs=[]\n    for h in range(p1a.HEADS):\n        for side in (\'q\',\'k\'):\n            spec=cal[\'q_specs\'][h] if side==\'q\' else cal[\'k_specs\'][h];dec=cal[\'q_decoders\'][h] if side==\'q\' else cal[\'k_decoders\'][h];tab=qlut[h] if side==\'q\' else klut[h]\n            direct=np.maximum(izh_design_np(testa,spec[\'bias\'],spec[\'gain\'],spec[\'window_ms\'])@dec,1e-8)\n            approx=np.array([lut_scalar_map(float(a),tab,lstep) for a in testa])\n            luterrs.append(float(np.max(np.abs(direct-approx))))\n    parity={\'initial_numba_vs_torch_izh_max_feature_abs_error\':float(np.max(np.abs(fnum[:,:p1a.D]-ft))),\n            \'lut_vs_direct_izh_max_abs_error\':float(max(luterrs)),\'lut_step\':float(lstep)}\n    (out/\'P1G_PARITY.json\').write_text(json.dumps(parity,indent=2))\n\n    # ---------------------- static post-learning swap ----------------------\n    print(\'[P1-G] static post-learning swap audit\',flush=True)\n    static_rows=[]\n    for seed in p1f.FINAL_SEEDS:\n        ws=load_p1f_weights(seed);Q,K,V,O,L1,L2=ws\n        mex=p1f.evaluate(d,*ws);miz=evaluate_izh(d,cal_pack,*ws)\n        diag=interface_diagnostics(d,cal_pack,Q,K,V)\n        gseed=300000+seed\n        sx,gex=generation_exact(d,*ws,N_GENERATE,gseed)\n        si,giz=generation_izh(d,cal,*ws,N_GENERATE,gseed)\n        row={\'seed\':seed,\'exact\':mex,\'izh\':miz,\'diagnostics\':diag,\'generation_exact\':gex,\'generation_izh\':giz,\n             \'delta_nll\':float(miz[\'expected_nll\']-mex[\'expected_nll\']),\n             \'delta_long_range\':float(miz[\'exact_long_range_branch_mae\']-mex[\'exact_long_range_branch_mae\']),\n             \'delta_generation_joint_js\':float(giz[\'joint_js\']-gex[\'joint_js\']),\n             \'generation_validity_drop\':float(gex[\'valid_fraction\']-giz[\'valid_fraction\'])}\n        static_rows.append(row);print(\' static\',seed,row[\'delta_nll\'],row[\'delta_long_range\'],row[\'delta_generation_joint_js\'],flush=True)\n    static_agg={\n        \'mean_abs_nll_delta\':float(np.mean([abs(r[\'delta_nll\']) for r in static_rows])),\n        \'mean_long_range_degradation\':float(np.mean([r[\'delta_long_range\'] for r in static_rows])),\n        \'mean_q_feature_rel_l2\':float(np.mean([r[\'diagnostics\'][\'q_feature_rel_l2\'] for r in static_rows])),\n        \'mean_k_feature_rel_l2\':float(np.mean([r[\'diagnostics\'][\'k_feature_rel_l2\'] for r in static_rows])),\n        \'mean_max_qk_feature_rel_l2\':float(np.mean([max(r[\'diagnostics\'][\'q_feature_rel_l2\'],r[\'diagnostics\'][\'k_feature_rel_l2\']) for r in static_rows])),\n        \'mean_H_rel_l2\':float(np.mean([r[\'diagnostics\'][\'H_rel_l2\'] for r in static_rows])),\n        \'mean_g_rel_l2\':float(np.mean([r[\'diagnostics\'][\'g_rel_l2\'] for r in static_rows])),\n        \'mean_attended_rel_l2\':float(np.mean([r[\'diagnostics\'][\'attended_rel_l2\'] for r in static_rows])),\n        \'mean_generation_joint_js_degradation\':float(np.mean([r[\'delta_generation_joint_js\'] for r in static_rows])),\n        \'mean_generation_validity_drop\':float(np.mean([r[\'generation_validity_drop\'] for r in static_rows])),\n    }\n    op_shift={\'initial\':stable_a_summary(d,d[\'WQ\'],d[\'WK\']),\n              \'p1f_final\':{str(seed):stable_a_summary(d,*load_p1f_weights(seed)[:2]) for seed in p1f.FINAL_SEEDS}}\n\n    # ---------------------- Izh inside learning loop -----------------------\n    print(\'[P1-G] Izh-in-loop final workers\',flush=True)\n    inloop_rows=[]\n    for seed in FINAL_SEEDS:\n        worker_json=out/f\'P1G_FINAL_SEED_{seed}.json\'\n        if not worker_json.exists():\n            print(\'[P1-G] run isolated final worker directly: python p1g_seed_worker.py\',seed,FINAL_PATHS,N_GENERATE,flush=True)\n            raise RuntimeError(\'Missing isolated worker result. Run the printed command, then rerun this consolidator. This avoids BLAS/Numba child-process thread inheritance in the main process.\')\n        row=json.loads(worker_json.read_text())\n        inloop_rows.append(row)\n        print(\' inloop\',seed,\'NLL\',row[\'izh_inloop\'][\'expected_nll\'],\'gap\',row[\'nll_gap\'],\'genJSgap\',row[\'generation_joint_js_gap\'],flush=True)\n\n    inloop_agg={\n        \'nll\':summarize([r[\'izh_inloop\'][\'expected_nll\'] for r in inloop_rows]),\n        \'conditional_js\':summarize([r[\'izh_inloop\'][\'conditional_js\'] for r in inloop_rows]),\n        \'long_range_mae\':summarize([r[\'izh_inloop\'][\'exact_long_range_branch_mae\'] for r in inloop_rows]),\n        \'matched_exact_nll\':summarize([r[\'matched_exact\'][\'expected_nll\'] for r in inloop_rows]),\n        \'matched_exact_long_range_mae\':summarize([r[\'matched_exact\'][\'exact_long_range_branch_mae\'] for r in inloop_rows]),\n        \'mean_nll_gap_to_matched_exact\':float(np.mean([r[\'nll_gap\'] for r in inloop_rows])),\n        \'mean_long_range_gap_to_matched_exact\':float(np.mean([r[\'long_range_gap\'] for r in inloop_rows])),\n        \'generation_joint_js\':summarize([r[\'generation_izh_inloop\'][\'joint_js\'] for r in inloop_rows]),\n        \'generation_validity\':summarize([r[\'generation_izh_inloop\'][\'valid_fraction\'] for r in inloop_rows]),\n        \'mean_generation_joint_js_gap\':float(np.mean([r[\'generation_joint_js_gap\'] for r in inloop_rows])),\n        \'mean_generation_validity_drop\':float(np.mean([r[\'generation_validity_drop\'] for r in inloop_rows])),\n        \'mean_weight_relative_changes\':{n:float(np.mean([r[\'weight_relative_changes\'][n] for r in inloop_rows])) for n in [\'WQ\',\'WK\',\'WV\',\'WO\',\'W1\',\'W2\']},\n        \'max_sparse_offmask\':float(max(r[\'sparse_offmask_max\'] for r in inloop_rows)),\n        \'mean_final_interface_diagnostics\':{k:float(np.mean([r[\'diagnostics_final\'][k] for r in inloop_rows])) for k in inloop_rows[0][\'diagnostics_final\']},\n    }\n\n    gates={\n        \'static_mean_abs_nll_delta\':static_agg[\'mean_abs_nll_delta\']<=GATES[\'static_mean_abs_nll_delta_le\'],\n        \'static_mean_long_range_degradation\':static_agg[\'mean_long_range_degradation\']<=GATES[\'static_mean_long_range_degradation_le\'],\n        \'static_mean_feature_rel_l2\':static_agg[\'mean_max_qk_feature_rel_l2\']<=GATES[\'static_mean_feature_rel_l2_le\'],\n        \'static_generation_joint_js_degradation\':static_agg[\'mean_generation_joint_js_degradation\']<=GATES[\'static_generation_joint_js_degradation_le\'],\n        \'static_generation_validity_drop\':static_agg[\'mean_generation_validity_drop\']<=GATES[\'static_generation_validity_drop_le\'],\n        \'inloop_mean_nll\':inloop_agg[\'nll\'][\'mean\']<=GATES[\'inloop_mean_nll_le\'],\n        \'inloop_nll_gap_to_matched_exact\':inloop_agg[\'mean_nll_gap_to_matched_exact\']<=GATES[\'inloop_nll_gap_to_matched_exact_le\'],\n        \'inloop_long_range_gap_to_matched_exact\':inloop_agg[\'mean_long_range_gap_to_matched_exact\']<=GATES[\'inloop_long_range_gap_to_matched_exact_le\'],\n        \'inloop_generation_joint_js_gap\':inloop_agg[\'mean_generation_joint_js_gap\']<=GATES[\'inloop_generation_joint_js_gap_le\'],\n        \'inloop_generation_validity_drop\':inloop_agg[\'mean_generation_validity_drop\']<=GATES[\'inloop_generation_validity_drop_le\'],\n        \'inloop_nll_improvement_over_frozen\':(baseline[\'expected_nll\']-inloop_agg[\'nll\'][\'mean\'])>GATES[\'inloop_nll_improvement_over_frozen_gt\'],\n        \'all_six_weight_groups_change\':min(inloop_agg[\'mean_weight_relative_changes\'].values())>GATES[\'all_six_weight_groups_change_gt\'],\n        \'sparse_offmask_exact\':inloop_agg[\'max_sparse_offmask\']==GATES[\'sparse_offmask_max_eq\'],\n    }\n\n    result={\'stage\':\'P1G_IZHIKEVICH_NEURONAL_FEATURE_REINTEGRATION\',\'baseline\':baseline,\n            \'protocol\':{\'final_seeds\':FINAL_SEEDS,\'final_paths\':FINAL_PATHS,\'multiplier\':MULTIPLIER,\'n_generate\':N_GENERATE,\n                        \'calibration_scope\':calj[\'calibration_scope\'],\'thresholds\':GATES,\n                        \'note\':\'static conditional behavior was explored during stage design; untouched in-loop final seeds were not used for calibration or tuning\'},\n            \'calibration\':{\'head_reports\':cal[\'head_reports\']},\'parity\':parity,\'operating_point_shift\':op_shift,\n            \'static_postlearning_rows\':static_rows,\'static_aggregate\':static_agg,\n            \'inloop_rows\':inloop_rows,\'inloop_aggregate\':inloop_agg,\'gates\':gates,\'PASS\':bool(all(gates.values()))}\n    (out/\'P1G_RESULTS.json\').write_text(json.dumps(result,indent=2))\n    write_report(out,result)\n    write_readme(out,result)\n    print(json.dumps({\'PASS\':result[\'PASS\'],\'static\':static_agg,\'inloop\':inloop_agg,\'gates\':gates},indent=2),flush=True)\n\n\ndef write_report(out:Path,r:Dict):\n    s=r[\'static_aggregate\'];a=r[\'inloop_aggregate\'];g=r[\'gates\'];b=r[\'baseline\']\n    qsel=r[\'calibration\'][\'head_reports\']\n    lines=[]\n    lines.append(\'# P1-G — Izhikevich neuronal-feature reintegration\\n\')\n    lines.append(f"**Final verdict: {\'PASS\' if r[\'PASS\'] else \'NOT ALL GATES PASS\'}**\\n")\n    lines.append(\'## Question and protocol\\n\')\n    lines.append(\'P1-F learned all six internal matrices with exact PositiveRF Q/K features. P1-G freezes a per-head Izhikevich RS trajectory + linear decoder calibrated **only on the initial/pre-learning Q/K distribution**, then tests (i) post-learning substitution on the already learned P1-F weights and (ii) full-block MSDL with the Izh Q/K dynamics actually inside the forward and local perturbation-credit loops. No autograd/BPTT is used by the candidate.\\n\')\n    lines.append(\'The static conditional diagnostic was explored while designing this stage; therefore only the untouched in-loop final seeds should be treated as a clean final confirmation.\\n\')\n    lines.append(f"The clean in-loop confirmation uses **{r[\'protocol\'][\'final_paths\']} MSDL paths per seed**, exactly the frozen P1-F final exposure, with multiplier **{r[\'protocol\'][\'multiplier\']}** and new seeds `{r[\'protocol\'][\'final_seeds\']}`.\\n")\n    lines.append(\'For runtime only, the in-loop evaluator uses a dense lookup table compiled from the fixed reset-per-call Izh trajectory map. The canonical neuronal interface itself resets `v,u` for each feature evaluation, so this does not remove any carried Q/K neuronal state. LUT vs direct recurrent Izh maximum scalar-output error is reported in `P1G_PARITY.json` and is at numerical precision. Static and final readout diagnostics are evaluated against the direct recurrent map.\\n\')\n    lines.append(\'## Frozen calibration\\n\')\n    for h,row in enumerate(qsel):\n        lines.append(f"- head {h}: Q {row[\'Q_selected\']}; K {row[\'K_selected\']}")\n    lines.append(\'\\nNo P1-F final weights, labels, or P1-G final seeds enter this calibration.\\n\')\n    lines.append(\'## Static post-learning swap\\n\')\n    lines.append(f"- mean |ΔNLL| exact→Izh: **{s[\'mean_abs_nll_delta\']:.6f}**")\n    lines.append(f"- mean long-range degradation: **{s[\'mean_long_range_degradation\']:.6f}**")\n    lines.append(f"- mean Q-feature rel-L2: **{s[\'mean_q_feature_rel_l2\']:.6f}**")\n    lines.append(f"- mean K-feature rel-L2: **{s[\'mean_k_feature_rel_l2\']:.6f}**")\n    lines.append(f"- mean H/g rel-L2: **{s[\'mean_H_rel_l2\']:.6f} / {s[\'mean_g_rel_l2\']:.6f}**")\n    lines.append(f"- mean autonomous joint-JS degradation: **{s[\'mean_generation_joint_js_degradation\']:.6f}**")\n    lines.append(f"- mean autonomous validity drop: **{s[\'mean_generation_validity_drop\']:.6f}**\\n")\n    lines.append(\'This tests whether the **same fixed neuronal interface** remains usable after WQ/WK drift, not whether post-hoc recalibration can rescue it.\\n\')\n    lines.append(\'## Izh dynamics inside full-block learning\\n\')\n    lines.append(f"Frozen baseline NLL: **{b[\'expected_nll\']:.6f}**.")\n    lines.append(f"Izh-in-loop NLL: **{a[\'nll\'][\'mean\']:.6f} ± {a[\'nll\'][\'std\']:.6f}**.")\n    lines.append(f"Matched exact-RF P1-F NLL: **{a[\'matched_exact_nll\'][\'mean\']:.6f} ± {a[\'matched_exact_nll\'][\'std\']:.6f}**.")\n    lines.append(f"Mean Izh−exact NLL gap: **{a[\'mean_nll_gap_to_matched_exact\']:.6f}**.")\n    lines.append(f"Izh long-range MAE: **{a[\'long_range_mae\'][\'mean\']:.6f} ± {a[\'long_range_mae\'][\'std\']:.6f}**; gap to matched exact **{a[\'mean_long_range_gap_to_matched_exact\']:.6f}**.")\n    lines.append(f"Autonomous joint JS: **{a[\'generation_joint_js\'][\'mean\']:.6f} ± {a[\'generation_joint_js\'][\'std\']:.6f}**; gap to matched exact **{a[\'mean_generation_joint_js_gap\']:.6f}**.")\n    lines.append(f"Autonomous validity: **{a[\'generation_validity\'][\'mean\']:.6f} ± {a[\'generation_validity\'][\'std\']:.6f}**; validity drop vs matched exact **{a[\'mean_generation_validity_drop\']:.6f}**.")\n    lines.append(f"Mean six-group relative changes: `{json.dumps(a[\'mean_weight_relative_changes\'])}`.")\n    lines.append(f"Off-mask maximum: **{a[\'max_sparse_offmask\']:.3g}**.\\n")\n    lines.append(\'## Gates\\n\')\n    for k,v in g.items():lines.append(f"- {\'PASS\' if v else \'FAIL\'} — `{k}`")\n    lines.append(\'\\n## Interpretation\\n\')\n    if r[\'PASS\']:\n        lines.append(\'P1-G supports the strong finite-horizon claim: a **fixed pre-learning calibrated, reset-per-evaluation Izhikevich neuronal Q/K feature interface** remains functionally usable after learned Q/K operating-point drift, and full-block MSDL still improves the generative model when those neuronal dynamics are actually inside the learning loop. Thus P1 can be frozen as a finite-horizon proof of dynamical learning + generation in the current SNN-Transform block.\\n\')\n        lines.append(\'This is **not** yet continual/uninterrupted learning. P1-F already exposed stale reciprocal feedback as forward W_O/W_2 drift; continuous feedback adaptation and stability–plasticity belong to P2.\\n\')\n    else:\n        lines.append(\'P1-G does not justify closing P1. Inspect failed gates to distinguish a static representation-range problem from an in-loop credit-perturbation sensitivity. Do not recalibrate on final weights before making that diagnosis.\\n\')\n    (out/\'P1G_REPORT.md\').write_text(\'\\n\'.join(lines))\n\n\ndef write_readme(out:Path,r:Dict):\n    txt=f"""# P1-G reproducibility bundle\n\nVerdict: **{\'PASS\' if r[\'PASS\'] else \'NOT ALL PASS\'}**.\n\n## Recommended reproduction\n\nWith the frozen calibration already included:\n\n```bash\npython run_p1g_from_zero.py\n```\n\nTo rebuild the Izh calibration strictly from the initial/pre-learning Q/K distribution first:\n\n```bash\npython run_p1g_from_zero.py --recalibrate\n```\n\nThe driver deliberately runs each final seed in an isolated process. This avoids BLAS/Numba thread-state inheritance and does not change the scientific protocol.\n\n## Scientific protocol\n\n- fixed P1-F multiplier: 0.45\n- full final exposure: 1200 MSDL paths per seed\n- untouched final seeds: 9601, 9613, 9623\n- neuronal interface calibration uses only the initial/pre-learning Q/K operating distribution\n- the per-head Izh operating points and decoders remain frozen thereafter\n- static post-learning swap is also tested on the independent 1200-path P1-F final weights 9209/9221/9239\n- no autograd/BPTT is used by candidate learning\n\nFor runtime, the in-loop gate evaluates the same reset-per-call Izh feature function through a 0.005-spaced LUT. `P1G_PARITY.json` verifies LUT vs direct recurrent Izh at numerical precision. The original Izh interface has no membrane carry across feature evaluations, so the LUT preserves its state semantics; P1-G does **not** claim persistent Q/K Izh membrane state.\n\nMain files:\n- `P1G_REPORT.md`\n- `P1G_RESULTS.json`\n- `P1G_CALIBRATION.json`\n- `P1G_PARITY.json`\n- `P1G_DERIVED_TRAINER.py.txt`\n- `p1g_izh_reintegration.py`\n- `p1g_seed_worker.py`\n- `run_p1g_from_zero.py`\n"""\n    (out/\'README_P1G.md\').write_text(txt)\n\n\nif __name__==\'__main__\':\n    main()\n\'\'\'\n\n# ========================= p2a_continuous_reciprocal.py =========================\n_EMBEDDED[\'p2a_continuous_reciprocal\'] = r\'\'\'#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n"""P2-A prototype: continuous reciprocal adaptation during full-block MSDL learning.\n\nBuilds directly on the frozen P1-G implementation.  No P2-B persistent-H/g\ntraining semantics are introduced here.\n"""\nfrom __future__ import annotations\nimport inspect, math, json, copy\nfrom pathlib import Path\nimport numpy as np\nimport torch\nfrom numba import njit\n\nimport p1a_msdl_token_generation as p1a\nimport p1f_full_block_msdl as p1f\nimport p1g_izh_reintegration as p1g\nimport p1e4_joint_qkv_msdl as e4\n\nMIRROR_LEAK = 1.0 / float(p1f.MIRROR_STEPS)   # principled: matches old 20k accumulation scale\nMIRROR_SIGMA = p1f.MIRROR_SIGMA\nETA_BR = p1f.MIRROR_ETA_BR\nETA_BO = p1f.MIRROR_ETA_BO\nETA_B2 = p1f.MIRROR_ETA_B2\n\n@njit(cache=True)\ndef reciprocal_microsteps(\n    BR, BO, B2, WR, WO, W2,\n    vm_br,um_br,ve_br,ue_br,zm_br,ze_br,\n    vm_bo,um_bo,ve_bo,ue_bo,zm_bo,ze_bo,\n    vm_b2,um_b2,ve_b2,ue_b2,zm_b2,ze_b2,\n    nsteps,sigma,eta_br,eta_bo,eta_b2,leak,adapt,\n):\n    D=WO.shape[0]; ff=W2.shape[1]; V=WR.shape[0]\n    se=0; sm=0\n    for _ in range(nsteps):\n        # B_R: feature perturbation -> categorical forward response.\n        df=np.random.normal(0.0,sigma,D)\n        dlogit=np.zeros(V,np.float64)\n        for v in range(V):\n            for o in range(D): dlogit[v]+=WR[v,o]*df[o]\n        M,smi=p1a.fast_izh_step(vm_br,um_br,df,zm_br,p1a.G_M,p1a.CV_M,p1a.CU_M)\n        E,sei=p1a.fast_izh_step(ve_br,ue_br,dlogit,ze_br,p1a.G_E,p1a.CV_E,p1a.CU_E)\n        sm+=smi;se+=sei\n        if adapt:\n            for o in range(D):\n                for v in range(V): BR[o,v]=(1.0-leak)*BR[o,v]+eta_br*M[o]*E[v]\n\n        # B_O: attended-state perturbation -> z forward response through current W_O.\n        da=np.random.normal(0.0,sigma,D)\n        dz=np.zeros(D,np.float64)\n        for o in range(D):\n            for j in range(D): dz[o]+=WO[o,j]*da[j]\n        M,smi=p1a.fast_izh_step(vm_bo,um_bo,da,zm_bo,p1a.G_M,p1a.CV_M,p1a.CU_M)\n        E,sei=p1a.fast_izh_step(ve_bo,ue_bo,dz,ze_bo,p1a.G_E,p1a.CV_E,p1a.CU_E)\n        sm+=smi;se+=sei\n        if adapt:\n            for j in range(D):\n                for o in range(D): BO[j,o]=(1.0-leak)*BO[j,o]+eta_bo*M[j]*E[o]\n\n        # B_2: hidden perturbation -> output response through current W_2.\n        dh=np.random.normal(0.0,sigma,ff)\n        dy=np.zeros(D,np.float64)\n        for o in range(D):\n            for i in range(ff): dy[o]+=W2[o,i]*dh[i]\n        M,smi=p1a.fast_izh_step(vm_b2,um_b2,dh,zm_b2,p1a.G_M,p1a.CV_M,p1a.CU_M)\n        E,sei=p1a.fast_izh_step(ve_b2,ue_b2,dy,ze_b2,p1a.G_E,p1a.CV_E,p1a.CU_E)\n        sm+=smi;se+=sei\n        if adapt:\n            for i in range(ff):\n                for o in range(D): B2[i,o]=(1.0-leak)*B2[i,o]+eta_b2*M[i]*E[o]\n    return se,sm\n\n\ndef build_trainer():\n    src=p1g.DERIVED_TRAINER_SOURCE\n    src=src.replace(\'def train_full_block_izh(\', \'def train_p2a_continuous_feedback(\')\n    old=\'\'\' + "\\\'\\\'\\\'" + r\'\'\'    n_paths,lrq,lrk,lrv,lro,lr1,lr2,sigq,sigk,seed,p_self,p_iid,\\n    reset_every_force=False,m_off=False,feedback_sign=1.0,dynamic_self=False,\\n):\'\'\' + "\\\'\\\'\\\'" + r\'\'\'\n    new=\'\'\' + "\\\'\\\'\\\'" + r\'\'\'    n_paths,lrq,lrk,lrv,lro,lr1,lr2,sigq,sigk,seed,p_self,p_iid,\\n    adapt_feedback=False,mirror_per_force=1,mirror_leak=0.0,trace_every=100,\\n    reset_every_force=False,m_off=False,feedback_sign=1.0,dynamic_self=False,\\n):\'\'\' + "\\\'\\\'\\\'" + r\'\'\'\n    if old not in src: raise RuntimeError(\'signature anchor missing\')\n    src=src.replace(old,new,1)\n\n    anchor=\'\'\' + "\\\'\\\'\\\'" + r\'\'\'    WQ=WQ_init.copy();WK=WK_init.copy();WV=WV_init.copy();WO=WO_init.copy();W1=W1_init.copy();W2=W2_init.copy()\\n\'\'\' + "\\\'\\\'\\\'" + r\'\'\'\n    insert=anchor+\'\'\' + "\\\'\\\'\\\'" + r\'\'\'    BR=BR.copy();BO=BO.copy();B2=B2.copy()\\n    Vcat=WR.shape[0]\\n    # Persistent reciprocal-learning E/M populations.\\n    vm_br=np.full(D,p1a.V0);um_br=np.full(D,p1a.U0);ve_br=np.full(Vcat,p1a.V0);ue_br=np.full(Vcat,p1a.U0);zm_br=np.zeros(D);ze_br=np.zeros(Vcat)\\n    vm_bo=np.full(D,p1a.V0);um_bo=np.full(D,p1a.U0);ve_bo=np.full(D,p1a.V0);ue_bo=np.full(D,p1a.U0);zm_bo=np.zeros(D);ze_bo=np.zeros(D)\\n    vm_b2=np.full(ff,p1a.V0);um_b2=np.full(ff,p1a.U0);ve_b2=np.full(D,p1a.V0);ue_b2=np.full(D,p1a.U0);zm_b2=np.zeros(ff);ze_b2=np.zeros(D)\\n    mirrorE=0;mirrorM=0\\n    ntrace=n_paths//trace_every+2\\n    tr_path=np.full(ntrace,-1,np.int64)\\n    tr_WQ=np.empty((ntrace,D,D),np.float64);tr_WK=np.empty((ntrace,D,D),np.float64);tr_WV=np.empty((ntrace,D,D),np.float64);tr_WO=np.empty((ntrace,D,D),np.float64)\\n    tr_W1=np.empty((ntrace,ff,D),np.float64);tr_W2=np.empty((ntrace,D,ff),np.float64)\\n    tr_BR=np.empty((ntrace,D,Vcat),np.float64);tr_BO=np.empty((ntrace,D,D),np.float64);tr_B2=np.empty((ntrace,ff,D),np.float64)\\n    nti=0\\n    tr_path[nti]=0;tr_WQ[nti]=WQ;tr_WK[nti]=WK;tr_WV[nti]=WV;tr_WO[nti]=WO;tr_W1[nti]=W1;tr_W2[nti]=W2;tr_BR[nti]=BR;tr_BO[nti]=BO;tr_B2[nti]=B2;nti+=1\\n\'\'\' + "\\\'\\\'\\\'" + r\'\'\'\n    if src.count(anchor)!=1: raise RuntimeError(\'weight init anchor missing\')\n    src=src.replace(anchor,insert,1)\n\n    force_anchor=\'\'\' + "\\\'\\\'\\\'" + r\'\'\'        for sk in range(p1a.FORCE_STEPS):\\n\'\'\' + "\\\'\\\'\\\'" + r\'\'\'\n    force_insert=force_anchor+\'\'\' + "\\\'\\\'\\\'" + r\'\'\'            # Reciprocal populations evolve continuously inside the same force stream.\\n            mse,msm=reciprocal_microsteps(BR,BO,B2,WR,O0,L20,\\n                vm_br,um_br,ve_br,ue_br,zm_br,ze_br,\\n                vm_bo,um_bo,ve_bo,ue_bo,zm_bo,ze_bo,\\n                vm_b2,um_b2,ve_b2,ue_b2,zm_b2,ze_b2,\\n                mirror_per_force,MIRROR_SIGMA,ETA_BR,ETA_BO,ETA_B2,mirror_leak,adapt_feedback)\\n            mirrorE+=mse;mirrorM+=msm\\n\'\'\' + "\\\'\\\'\\\'" + r\'\'\'\n    if src.count(force_anchor)!=1: raise RuntimeError(\'force anchor missing\')\n    src=src.replace(force_anchor,force_insert,1)\n\n    # Record after the forward update at path end.\n    update_tail=\'\'\' + "\\\'\\\'\\\'" + r\'\'\'        for r in range(D):\\n            for i in range(ff):\\n                if mask2[r,i]!=0.0:W2[r,i]+=lr2*a2[r,i]*invsteps\\n                else:W2[r,i]=0.0\\n    return WQ,WK,WV,WO,W1,W2,seqE,seqM\\n\'\'\' + "\\\'\\\'\\\'" + r\'\'\'\n    repl=\'\'\' + "\\\'\\\'\\\'" + r\'\'\'        for r in range(D):\\n            for i in range(ff):\\n                if mask2[r,i]!=0.0:W2[r,i]+=lr2*a2[r,i]*invsteps\\n                else:W2[r,i]=0.0\\n        if ((_p+1)%trace_every)==0 or (_p+1)==n_paths:\\n            tr_path[nti]=_p+1;tr_WQ[nti]=WQ;tr_WK[nti]=WK;tr_WV[nti]=WV;tr_WO[nti]=WO;tr_W1[nti]=W1;tr_W2[nti]=W2;tr_BR[nti]=BR;tr_BO[nti]=BO;tr_B2[nti]=B2;nti+=1\\n    return WQ,WK,WV,WO,W1,W2,BR,BO,B2,seqE,seqM,mirrorE,mirrorM,tr_path[:nti],tr_WQ[:nti],tr_WK[:nti],tr_WV[:nti],tr_WO[:nti],tr_W1[:nti],tr_W2[:nti],tr_BR[:nti],tr_BO[:nti],tr_B2[:nti]\\n\'\'\' + "\\\'\\\'\\\'" + r\'\'\'\n    if update_tail not in src: raise RuntimeError(\'update return anchor missing\')\n    src=src.replace(update_tail,repl,1)\n    # Existing @njit from P1G derived source already present as @njit.\n    ns={\'njit\':njit,\'np\':np,\'math\':math,\'p1a\':p1a,\'e4\':e4,\'p1d\':p1f.p1d,\n        \'joint_attention_state_lut\':p1g.joint_attention_state_lut,\n        \'score_pair_qk_lut\':p1g.score_pair_qk_lut,\'read_pair_head_from_q_lut\':p1g.read_pair_head_from_q_lut,\n        \'reciprocal_microsteps\':reciprocal_microsteps,\n        \'MIRROR_SIGMA\':MIRROR_SIGMA,\'ETA_BR\':ETA_BR,\'ETA_BO\':ETA_BO,\'ETA_B2\':ETA_B2}\n    exec(src,ns)\n    return ns[\'train_p2a_continuous_feedback\'],src\n\nSOURCE = None\ntry:\n    from p2a_trainer_static import train_p2a_continuous_feedback as TRAIN_P2A\nexcept Exception:\n    TRAIN_P2A,SOURCE=build_trainer()\n\n\ndef cosine(a,b):\n    return float(np.sum(a*b)/(np.linalg.norm(a)*np.linalg.norm(b)+1e-30))\n\n\ndef run_one(d,lut_pack,paths,seed,mirror_per_force=4,adapt=True,warm_start=False,trace_every=100,B_init=None,mirror_leak=MIRROR_LEAK,m_off=False):\n    if B_init is not None:\n        BR0,BO0,B20=(B_init[0].copy(),B_init[1].copy(),B_init[2].copy())\n    elif warm_start or not adapt:\n        BR0,BO0,B20=p1f.learn_feedbacks(d,100000+seed)\n    else:\n        BR0=np.zeros((p1a.D,p1a.V),np.float64);BO0=np.zeros_like(d[\'WO\'].T);B20=np.zeros_like(d[\'W2\'].T)\n    qlut,klut,lut_step=lut_pack\n    args=(d[\'xn\'],d[\'xres\'],d[\'tpos\'],d[\'targets\'],d[\'masses\'],d[\'WR\'],BR0,BO0,B20,\n          d[\'WQ\'],d[\'bq\'],d[\'WK\'],d[\'bk\'],d[\'WV\'],d[\'bv\'],d[\'omega\'],qlut,klut,lut_step,\n          d[\'WO\'],d[\'maskO\'],d[\'bo\'],d[\'gamma2\'],d[\'beta2\'],d[\'eps2\'],d[\'W1\'],d[\'mask1\'],d[\'b1\'],d[\'theta\'],d[\'W2\'],d[\'mask2\'],d[\'b2\'],\n          d[\'sci\'],d[\'st\'],d[\'sp\'],d[\'nxt\'],d[\'cpos\'],d[\'root\'],d[\'static\'])\n    return TRAIN_P2A(*args,paths,\n        p1f.BASE_LR_Q*p1g.MULTIPLIER,p1f.BASE_LR_K*p1g.MULTIPLIER,p1f.BASE_LR_V*p1g.MULTIPLIER,\n        p1f.BASE_LR_O*p1g.MULTIPLIER,p1f.BASE_LR_1*p1g.MULTIPLIER,p1f.BASE_LR_2*p1g.MULTIPLIER,\n        p1f.SIGMA_Q,p1f.SIGMA_K,seed,p1f.P_SELF,p1f.P_IID,\n        adapt,mirror_per_force,mirror_leak,trace_every,False,m_off)\n\n\ndef summarize_trace(d,cal_pack,res):\n    WQ,WK,WV,WO,W1,W2,BR,BO,B2=res[:9]\n    paths=res[13];trWQ,trWK,trWV,trWO,trW1,trW2,trBR,trBO,trB2=res[14:23]\n    rows=[]\n    for i,p in enumerate(paths):\n        met=p1g.evaluate_izh(d,cal_pack,trWQ[i],trWK[i],trWV[i],trWO[i],trW1[i],trW2[i])\n        rows.append({\'path\':int(p),\'nll\':met[\'expected_nll\'],\'js\':met[\'conditional_js\'],\'long_range_mae\':met[\'exact_long_range_branch_mae\'],\n                     \'BR_cos\':cosine(trBR[i],d[\'WR\'][:,:p1a.D].T),\'BO_cos\':cosine(trBO[i],trWO[i].T),\'B2_cos\':cosine(trB2[i],trW2[i].T),\n                     \'BR_norm_ratio\':float(np.linalg.norm(trBR[i])/(np.linalg.norm(d[\'WR\'][:,:p1a.D].T)+1e-30)),\n                     \'BO_norm_ratio\':float(np.linalg.norm(trBO[i])/(np.linalg.norm(trWO[i].T)+1e-30)),\n                     \'B2_norm_ratio\':float(np.linalg.norm(trB2[i])/(np.linalg.norm(trW2[i].T)+1e-30))})\n    return rows\n\nif __name__==\'__main__\':\n    d=p1f.setup();cal=p1g.calibrate_initial_interface(d);lut=p1g.build_luts(cal);pack=p1g.pack_calibration(cal)\n    for mode,adapt,warm in [(\'zero_adapt\',True,False),(\'warm_adapt\',True,True),(\'fixed\',False,True)]:\n        print(\'RUN\',mode,flush=True)\n        r=run_one(d,lut,200,9701,mirror_per_force=4,adapt=adapt,warm_start=warm,trace_every=50)\n        rows=summarize_trace(d,pack,r)\n        print(mode,rows[-1],flush=True)\n\'\'\'\n\n# ========================= p2a_trainer_static.py =========================\n_EMBEDDED[\'p2a_trainer_static\'] = r\'\'\'#!/usr/bin/env python3\nimport math\nimport numpy as np\nfrom numba import njit\nimport p1a_msdl_token_generation as p1a\nimport p1e4_joint_qkv_msdl as e4\nimport p1d_attention_output_msdl as p1d\nfrom p1g_izh_reintegration import joint_attention_state_lut, score_pair_qk_lut, read_pair_head_from_q_lut\nMIRROR_SIGMA = 0.1\nETA_BR = 0.0338\nETA_BO = 0.0335\nETA_B2 = 0.0335\n\n@njit(cache=True)\ndef reciprocal_microsteps(\n    BR, BO, B2, WR, WO, W2,\n    vm_br,um_br,ve_br,ue_br,zm_br,ze_br,\n    vm_bo,um_bo,ve_bo,ue_bo,zm_bo,ze_bo,\n    vm_b2,um_b2,ve_b2,ue_b2,zm_b2,ze_b2,\n    nsteps,sigma,eta_br,eta_bo,eta_b2,leak,adapt,\n):\n    D=WO.shape[0]; ff=W2.shape[1]; V=WR.shape[0]\n    se=0; sm=0\n    for _ in range(nsteps):\n        # B_R: feature perturbation -> categorical forward response.\n        df=np.random.normal(0.0,sigma,D)\n        dlogit=np.zeros(V,np.float64)\n        for v in range(V):\n            for o in range(D): dlogit[v]+=WR[v,o]*df[o]\n        M,smi=p1a.fast_izh_step(vm_br,um_br,df,zm_br,p1a.G_M,p1a.CV_M,p1a.CU_M)\n        E,sei=p1a.fast_izh_step(ve_br,ue_br,dlogit,ze_br,p1a.G_E,p1a.CV_E,p1a.CU_E)\n        sm+=smi;se+=sei\n        if adapt:\n            for o in range(D):\n                for v in range(V): BR[o,v]=(1.0-leak)*BR[o,v]+eta_br*M[o]*E[v]\n\n        # B_O: attended-state perturbation -> z forward response through current W_O.\n        da=np.random.normal(0.0,sigma,D)\n        dz=np.zeros(D,np.float64)\n        for o in range(D):\n            for j in range(D): dz[o]+=WO[o,j]*da[j]\n        M,smi=p1a.fast_izh_step(vm_bo,um_bo,da,zm_bo,p1a.G_M,p1a.CV_M,p1a.CU_M)\n        E,sei=p1a.fast_izh_step(ve_bo,ue_bo,dz,ze_bo,p1a.G_E,p1a.CV_E,p1a.CU_E)\n        sm+=smi;se+=sei\n        if adapt:\n            for j in range(D):\n                for o in range(D): BO[j,o]=(1.0-leak)*BO[j,o]+eta_bo*M[j]*E[o]\n\n        # B_2: hidden perturbation -> output response through current W_2.\n        dh=np.random.normal(0.0,sigma,ff)\n        dy=np.zeros(D,np.float64)\n        for o in range(D):\n            for i in range(ff): dy[o]+=W2[o,i]*dh[i]\n        M,smi=p1a.fast_izh_step(vm_b2,um_b2,dh,zm_b2,p1a.G_M,p1a.CV_M,p1a.CU_M)\n        E,sei=p1a.fast_izh_step(ve_b2,ue_b2,dy,ze_b2,p1a.G_E,p1a.CV_E,p1a.CU_E)\n        sm+=smi;se+=sei\n        if adapt:\n            for i in range(ff):\n                for o in range(D): B2[i,o]=(1.0-leak)*B2[i,o]+eta_b2*M[i]*E[o]\n    return se,sm\n\n\n@njit(cache=True)\ndef train_p2a_continuous_feedback(\n    xn,xres,tpos,targets,masses,WR,BR,BO,B2,\n    WQ_init,bq,WK_init,bk,WV_init,bv,omega,\n    qlut,klut,lut_step,\n    WO_init,maskO,bo,gamma2,beta2,eps2,\n    W1_init,mask1,b1,theta,W2_init,mask2,b2,\n    seq_context_idx,seq_tokens,seq_probs,next_ctx,ctx_pos,root_ctx,static_policy_probs,\n    n_paths,lrq,lrk,lrv,lro,lr1,lr2,sigq,sigk,seed,p_self,p_iid,\n    adapt_feedback=False,mirror_per_force=1,mirror_leak=0.0,trace_every=100,\n    reset_every_force=False,m_off=False,feedback_sign=1.0,dynamic_self=False,\n):\n    np.random.seed(seed)\n    C=xn.shape[0];N=xn.shape[1];D=WQ_init.shape[0];H=omega.shape[0];hd=D//H;ff=W1_init.shape[0]\n    WQ=WQ_init.copy();WK=WK_init.copy();WV=WV_init.copy();WO=WO_init.copy();W1=W1_init.copy();W2=W2_init.copy()\n    BR=BR.copy();BO=BO.copy();B2=B2.copy()\n    Vcat=WR.shape[0]\n    # Persistent reciprocal-learning E/M populations.\n    vm_br=np.full(D,p1a.V0);um_br=np.full(D,p1a.U0);ve_br=np.full(Vcat,p1a.V0);ue_br=np.full(Vcat,p1a.U0);zm_br=np.zeros(D);ze_br=np.zeros(Vcat)\n    vm_bo=np.full(D,p1a.V0);um_bo=np.full(D,p1a.U0);ve_bo=np.full(D,p1a.V0);ue_bo=np.full(D,p1a.U0);zm_bo=np.zeros(D);ze_bo=np.zeros(D)\n    vm_b2=np.full(ff,p1a.V0);um_b2=np.full(ff,p1a.U0);ve_b2=np.full(D,p1a.V0);ue_b2=np.full(D,p1a.U0);zm_b2=np.zeros(ff);ze_b2=np.zeros(D)\n    mirrorE=0;mirrorM=0\n    ntrace=n_paths//trace_every+2\n    tr_path=np.full(ntrace,-1,np.int64)\n    tr_WQ=np.empty((ntrace,D,D),np.float64);tr_WK=np.empty((ntrace,D,D),np.float64);tr_WV=np.empty((ntrace,D,D),np.float64);tr_WO=np.empty((ntrace,D,D),np.float64)\n    tr_W1=np.empty((ntrace,ff,D),np.float64);tr_W2=np.empty((ntrace,D,ff),np.float64)\n    tr_BR=np.empty((ntrace,D,Vcat),np.float64);tr_BO=np.empty((ntrace,D,D),np.float64);tr_B2=np.empty((ntrace,ff,D),np.float64)\n    nti=0\n    tr_path[nti]=0;tr_WQ[nti]=WQ;tr_WK[nti]=WK;tr_WV[nti]=WV;tr_WO[nti]=WO;tr_W1[nti]=W1;tr_W2[nti]=W2;tr_BR[nti]=BR;tr_BO[nti]=BO;tr_B2[nti]=B2;nti+=1\n\n    # Independent E/M state pairs for the six plastic projection populations.\n    veq=np.full(D,p1a.V0);ueq=np.full(D,p1a.U0);vmq=np.full(D,p1a.V0);umq=np.full(D,p1a.U0);zeq=np.zeros(D);zmq=np.zeros(D)\n    vek=np.full(N*D,p1a.V0);uek=np.full(N*D,p1a.U0);vmk=np.full(N*D,p1a.V0);umk=np.full(N*D,p1a.U0);zek=np.zeros(N*D);zmk=np.zeros(N*D)\n    vev=np.full(H*D,p1a.V0);uev=np.full(H*D,p1a.U0);vmv=np.full(D,p1a.V0);umv=np.full(D,p1a.U0);zev=np.zeros(H*D);zmv=np.zeros(D)\n    veo=np.full(D,p1a.V0);ueo=np.full(D,p1a.U0);vmo=np.full(D,p1a.V0);umo=np.full(D,p1a.U0);zeo=np.zeros(D);zmo=np.zeros(D)\n    ve1=np.full(D,p1a.V0);ue1=np.full(D,p1a.U0);vm1=np.full(ff,p1a.V0);um1=np.full(ff,p1a.U0);ze1=np.zeros(D);zm1=np.zeros(ff)\n    ve2=np.full(ff,p1a.V0);ue2=np.full(ff,p1a.U0);vm2=np.full(D,p1a.V0);um2=np.full(D,p1a.U0);ze2=np.zeros(ff);zm2=np.zeros(D)\n\n    cdf=np.cumsum(masses);cdf[-1]=1.;scdf=np.cumsum(seq_probs);scdf[-1]=1.\n    sched=np.empty(p1a.FORCE_STEPS,np.int64);kk=0\n    for t in range(p1a.N):\n        for _ in range(p1d.POSITION_COUNTS[t]):sched[kk]=t;kk+=1\n    seqE=0;seqM=0\n\n    for _p in range(n_paths):\n        rr=np.random.random();is_self=rr<p_self;is_iid=(not is_self) and rr<p_self+p_iid;coherent=(not is_self) and not is_iid\n        si=-1\n        if coherent:si=e4._sample_index(scdf)\n        Q0=WQ.copy();K0=WK.copy();V0=WV.copy();O0=WO.copy();L10=W1.copy();L20=W2.copy()\n        aq=np.zeros_like(WQ);ak=np.zeros_like(WK);av=np.zeros_like(WV);ao=np.zeros_like(WO);a1=np.zeros_like(W1);a2=np.zeros_like(W2)\n        ci_self=root_ctx;rep_self=0\n\n        for sk in range(p1a.FORCE_STEPS):\n            # Reciprocal populations evolve continuously inside the same force stream.\n            mse,msm=reciprocal_microsteps(BR,BO,B2,WR,O0,L20,\n                vm_br,um_br,ve_br,ue_br,zm_br,ze_br,\n                vm_bo,um_bo,ve_bo,ue_bo,zm_bo,ze_bo,\n                vm_b2,um_b2,ve_b2,ue_b2,zm_b2,ze_b2,\n                mirror_per_force,MIRROR_SIGMA,ETA_BR,ETA_BO,ETA_B2,mirror_leak,adapt_feedback)\n            mirrorE+=mse;mirrorM+=msm\n            if reset_every_force:\n                for j in range(D):\n                    veq[j]=p1a.V0;ueq[j]=p1a.U0;vmq[j]=p1a.V0;umq[j]=p1a.U0;vmv[j]=p1a.V0;umv[j]=p1a.U0\n                    veo[j]=p1a.V0;ueo[j]=p1a.U0;vmo[j]=p1a.V0;umo[j]=p1a.U0;ve1[j]=p1a.V0;ue1[j]=p1a.U0;vm2[j]=p1a.V0;um2[j]=p1a.U0\n                for j in range(N*D):vek[j]=p1a.V0;uek[j]=p1a.U0;vmk[j]=p1a.V0;umk[j]=p1a.U0\n                for j in range(H*D):vev[j]=p1a.V0;uev[j]=p1a.U0\n                for j in range(ff):vm1[j]=p1a.V0;um1[j]=p1a.U0;ve2[j]=p1a.V0;ue2[j]=p1a.U0\n\n            if is_self:\n                ci=ci_self;target=p1a.sample_categorical_numba(targets[ci])\n            elif coherent:\n                tt=int(sched[sk]);ci=int(seq_context_idx[si,tt]);target=int(seq_tokens[si,tt])\n            else:\n                ci=e4._sample_index(cdf);target=p1a.sample_categorical_numba(targets[ci])\n            t=int(tpos[ci])\n\n            a,q,k,v,scores,num,den,alpha=joint_attention_state_lut(Q0,bq,K0,bk,V0,bv,xn[ci],t,omega,qlut,klut,lut_step)\n\n            # Current full tail under path-frozen O0/L10/L20.\n            z=np.empty(D)\n            for o in range(D):\n                val=xres[ci,o]+bo[o]\n                for j in range(D):val+=O0[o,j]*a[j]\n                z[o]=val\n            mu=0.0\n            for o in range(D):mu+=z[o]\n            mu/=D;var=0.0\n            for o in range(D):qq=z[o]-mu;var+=qq*qq\n            var/=D;inv=1.0/math.sqrt(var+eps2);u=np.empty(D)\n            for o in range(D):u[o]=(z[o]-mu)*inv*gamma2[o]+beta2[o]\n            hvec=np.empty(ff)\n            for i in range(ff):\n                val=b1[i]-theta[i]\n                for j in range(D):val+=L10[i,j]*u[j]\n                hvec[i]=val if val>0.0 else 0.0\n            y=z.copy()\n            for o in range(D):\n                val=b2[o]\n                for i in range(ff):val+=L20[o,i]*hvec[i]\n                y[o]+=val\n            ss=0.0\n            for o in range(D):ss+=y[o]*y[o]\n            rms=math.sqrt(ss/D)+1e-8;logits=np.empty(p1a.V)\n            for vv in range(p1a.V):\n                val=0.5*WR[vv,D]\n                for o in range(D):val+=WR[vv,o]*(0.5*y[o]/rms)\n                logits[vv]=val\n            probs=p1a.softmax_numba(logits);err=np.empty(p1a.V)\n            for vv in range(p1a.V):err[vv]=-probs[vv]\n            err[target]+=1.0\n\n            # Learned local mismatch-routing populations.\n            drive_y=np.zeros(D)\n            if not m_off:\n                for o in range(D):\n                    for vv in range(p1a.V):drive_y[o]+=feedback_sign*BR[o,vv]*err[vv]\n            drive_h=np.zeros(ff)\n            if not m_off:\n                for i in range(ff):\n                    for o in range(D):drive_h[i]+=B2[i,o]*drive_y[o]\n            # Same local z mismatch used in the independently validated W_O rule.\n            drive_z=drive_y.copy()\n            drive_a=np.zeros(D)\n            if not m_off:\n                for j in range(D):\n                    for o in range(D):drive_a[j]+=BO[j,o]*drive_z[o]\n\n            # W2: hidden -> block output\n            E2,se=p1a.fast_izh_step(ve2,ue2,hvec,ze2,p1a.G_E,p1a.CV_E,p1a.CU_E);seqE+=se\n            if m_off:M2=np.zeros(D)\n            else:\n                M2,sm=p1a.fast_izh_step(vm2,um2,drive_y,zm2,p1a.G_M,p1a.CV_M,p1a.CU_M);seqM+=sm\n            for o in range(D):\n                for i in range(ff):\n                    if mask2[o,i]!=0.0:a2[o,i]+=M2[o]*E2[i]\n\n            # W1: LN2 population -> hidden\n            E1,se=p1a.fast_izh_step(ve1,ue1,u,ze1,p1a.G_E,p1a.CV_E,p1a.CU_E);seqE+=se\n            if m_off:M1=np.zeros(ff)\n            else:\n                M1,sm=p1a.fast_izh_step(vm1,um1,drive_h,zm1,p1a.G_M,p1a.CV_M,p1a.CU_M);seqM+=sm\n            for i in range(ff):\n                for j in range(D):\n                    if mask1[i,j]!=0.0:a1[i,j]+=M1[i]*E1[j]\n\n            # W_O: attended state -> z population\n            EO,se=p1a.fast_izh_step(veo,ueo,a,zeo,p1a.G_E,p1a.CV_E,p1a.CU_E);seqE+=se\n            if m_off:MO=np.zeros(D)\n            else:\n                MO,sm=p1a.fast_izh_step(vmo,umo,drive_z,zmo,p1a.G_M,p1a.CV_M,p1a.CU_M);seqM+=sm\n            for o in range(D):\n                for j in range(D):\n                    if maskO[o,j]!=0.0:ao[o,j]+=MO[o]*EO[j]\n\n            # W_V: relation-weighted presynaptic population -> attended state\n            sinput=np.empty(H*D)\n            for hh in range(H):\n                for c in range(D):\n                    sv=0.0\n                    for n in range(N):sv+=alpha[hh,n]*xn[ci,n,c]\n                    sinput[hh*D+c]=sv\n            EV,se=p1a.fast_izh_step(vev,uev,sinput,zev,p1a.G_E,p1a.CV_E,p1a.CU_E);seqE+=se\n            if m_off:MV=np.zeros(D)\n            else:\n                MV,sm=p1a.fast_izh_step(vmv,umv,drive_a,zmv,p1a.G_M,p1a.CV_M,p1a.CU_M);seqM+=sm\n            for r in range(D):\n                base=(r//hd)*D\n                for c in range(D):av[r,c]+=MV[r]*EV[base+c]\n\n            # W_K: token-local relation-writing perturbation\n            drive_k=np.zeros(N*D)\n            for hh in range(H):\n                for n in range(N):\n                    xi=np.empty(hd);kp=np.empty(hd);km=np.empty(hd)\n                    for rrh in range(hd):\n                        dd=1.0 if np.random.random()<0.5 else -1.0;xi[rrh]=dd;kp[rrh]=k[hh,n,rrh]+sigk*dd;km[rrh]=k[hh,n,rrh]-sigk*dd\n                    sp,smm=score_pair_qk_lut(q[hh],kp,km,omega[hh],qlut[hh],klut[hh],lut_step);s0=scores[hh,n]\n                    dp=den[hh]+sp-s0;dm=den[hh]+smm-s0\n                    if dp<1e-8:dp=1e-8\n                    if dm<1e-8:dm=1e-8\n                    scalar=0.0\n                    if not m_off:\n                        for rrh in range(hd):\n                            ap=(num[hh,rrh]+(sp-s0)*v[hh,n,rrh])/dp\n                            am=(num[hh,rrh]+(smm-s0)*v[hh,n,rrh])/dm\n                            scalar+=drive_a[hh*hd+rrh]*(ap-am)/(2.0*sigk)\n                    for rrh in range(hd):drive_k[n*D+hh*hd+rrh]=scalar*xi[rrh]\n            ein=np.empty(N*D)\n            for n in range(N):\n                for c in range(D):ein[n*D+c]=xn[ci,n,c]\n            EK,se=p1a.fast_izh_step(vek,uek,ein,zek,p1a.G_E,p1a.CV_E,p1a.CU_E);seqE+=se\n            if m_off:MK=np.zeros(N*D)\n            else:\n                MK,sm=p1a.fast_izh_step(vmk,umk,drive_k,zmk,p1a.G_M,p1a.CV_M,p1a.CU_M);seqM+=sm\n            for r in range(D):\n                for c in range(D):\n                    val=0.0\n                    for n in range(N):val+=MK[n*D+r]*EK[n*D+c]\n                    ak[r,c]+=val/N\n\n            # W_Q: current relation-reading perturbation\n            drive_q=np.zeros(D)\n            for hh in range(H):\n                xi=np.empty(hd);qp=np.empty(hd);qm=np.empty(hd)\n                for rrh in range(hd):\n                    dd=1.0 if np.random.random()<0.5 else -1.0;xi[rrh]=dd;qp[rrh]=q[hh,rrh]+sigq*dd;qm[rrh]=q[hh,rrh]-sigq*dd\n                ap,am=read_pair_head_from_q_lut(qp,qm,k[hh],v[hh],omega[hh],qlut[hh],klut[hh],lut_step);scalar=0.0\n                if not m_off:\n                    for rrh in range(hd):scalar+=drive_a[hh*hd+rrh]*(ap[rrh]-am[rrh])/(2.0*sigq)\n                for rrh in range(hd):drive_q[hh*hd+rrh]=scalar*xi[rrh]\n            EQ,se=p1a.fast_izh_step(veq,ueq,xn[ci,t],zeq,p1a.G_E,p1a.CV_E,p1a.CU_E);seqE+=se\n            if m_off:MQ=np.zeros(D)\n            else:\n                MQ,sm=p1a.fast_izh_step(vmq,umq,drive_q,zmq,p1a.G_M,p1a.CV_M,p1a.CU_M);seqM+=sm\n            for r in range(D):\n                for c in range(D):aq[r,c]+=MQ[r]*EQ[c]\n\n            if is_self:\n                rep_self+=1;tcur=int(ctx_pos[ci_self]);need=int(p1d.POSITION_COUNTS[tcur])\n                if rep_self>=need:\n                    if dynamic_self:sampled=p1a.sample_categorical_numba(probs)\n                    else:sampled=e4._sample_index(np.cumsum(static_policy_probs[ci_self]))\n                    if tcur==p1a.N-1:ci_self=root_ctx;rep_self=0\n                    else:\n                        ni=next_ctx[ci_self,sampled];ci_self=int(ni) if ni>=0 else root_ctx;rep_self=0\n\n        invsteps=1.0/p1a.FORCE_STEPS\n        for r in range(D):\n            for c in range(D):\n                WQ[r,c]+=lrq*aq[r,c]*invsteps\n                WK[r,c]+=lrk*ak[r,c]*invsteps\n                WV[r,c]+=lrv*av[r,c]*invsteps\n                if maskO[r,c]!=0.0:WO[r,c]+=lro*ao[r,c]*invsteps\n                else:WO[r,c]=0.0\n        for i in range(ff):\n            for c in range(D):\n                if mask1[i,c]!=0.0:W1[i,c]+=lr1*a1[i,c]*invsteps\n                else:W1[i,c]=0.0\n        for r in range(D):\n            for i in range(ff):\n                if mask2[r,i]!=0.0:W2[r,i]+=lr2*a2[r,i]*invsteps\n                else:W2[r,i]=0.0\n        if ((_p+1)%trace_every)==0 or (_p+1)==n_paths:\n            tr_path[nti]=_p+1;tr_WQ[nti]=WQ;tr_WK[nti]=WK;tr_WV[nti]=WV;tr_WO[nti]=WO;tr_W1[nti]=W1;tr_W2[nti]=W2;tr_BR[nti]=BR;tr_BO[nti]=BO;tr_B2[nti]=B2;nti+=1\n    return WQ,WK,WV,WO,W1,W2,BR,BO,B2,seqE,seqM,mirrorE,mirrorM,tr_path[:nti],tr_WQ[:nti],tr_WK[:nti],tr_WV[:nti],tr_WO[:nti],tr_W1[:nti],tr_W2[:nti],tr_BR[:nti],tr_BO[:nti],tr_B2[:nti]\n\'\'\'\n\n# ========================= p2b_resident_state.py =========================\n_EMBEDDED[\'p2b_resident_state\'] = r\'\'\'#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n"""P2-B: resident event-updated Q/K/V + H/g state during MSDL learning.\n\nScientific purpose\n------------------\nP1/P2-A training reconstructed attention from each complete prefix.  Generation,\nhowever, uses the canonical event-cached persistent attention state.  P2-B makes\nlearning use the same resident-state semantics.\n\nCrucially, when W_Q/W_K/W_V change at a path boundary the candidate does NOT\nreproject unchanged cached tokens.  Old token contributions remain resident until\nthat token changes.  This is deliberate: it is the event-local semantics to be\ncompared against a global-reprojection oracle.\n"""\nfrom __future__ import annotations\nimport math\nimport numpy as np\nfrom numba import njit\n\nfrom p1g_izh_reintegration import phi_q_lut_vec, phi_k_lut_vec\n\n\n@njit(cache=True)\ndef resident_attention_step_lut(\n    WQ,bq,WK,bk,WV,bv,xn,t,omega,qlut,klut,step,\n    initialized,xcache,qraw,kraw,vcache,pqcache,pkcache,Hstate,gstate,\n):\n    """One canonical alpha=1 event update, then read target token t.\n\n    State arrays are mutated in place. `initialized` is an int flag (0/1).\n    Returns the same local objects used by P1 Q/K/V learning plus changed count.\n    """\n    D=WQ.shape[0]; Hh=omega.shape[0]; hd=D//Hh; N=xn.shape[0]; M=omega.shape[1]\n    changed_count=0\n\n    if initialized==0:\n        # Full initialization is the only allowed O(N) rebuild in the candidate:\n        # system startup (or explicit oracle/control reset).\n        for hh in range(Hh):\n            for m in range(M):\n                gstate[hh,m]=0.0\n                for rr in range(hd):Hstate[hh,m,rr]=0.0\n        for n in range(N):\n            for c in range(D):xcache[n,c]=xn[n,c]\n            # raw Q/K/V projection for this token\n            for r in range(D):\n                qq=bq[r]; kk=bk[r]; vv=bv[r]\n                for c in range(D):\n                    xx=xn[n,c]\n                    qq+=WQ[r,c]*xx; kk+=WK[r,c]*xx; vv+=WV[r,c]*xx\n                hh=r//hd; rr=r-hh*hd\n                qraw[hh,n,rr]=qq; kraw[hh,n,rr]=kk; vcache[hh,n,rr]=vv\n            for hh in range(Hh):\n                pqt=phi_q_lut_vec(qraw[hh,n],omega[hh],qlut[hh],step)\n                pkt=phi_k_lut_vec(kraw[hh,n],omega[hh],klut[hh],step)\n                for m in range(M):\n                    pqcache[hh,n,m]=pqt[m]; pkcache[hh,n,m]=pkt[m]\n                    gstate[hh,m]+=pkt[m]\n                    for rr in range(hd):Hstate[hh,m,rr]+=pkt[m]*vcache[hh,n,rr]\n        changed_count=N\n    else:\n        # Event update: only tokens whose current normalized input differs from\n        # the cached input are reprojected under the CURRENT path-frozen weights.\n        for n in range(N):\n            ch=False\n            for c in range(D):\n                if xn[n,c]!=xcache[n,c]:\n                    ch=True; break\n            if not ch: continue\n            changed_count+=1\n            # Remove old K/V contribution from resident H/g.\n            for hh in range(Hh):\n                for m in range(M):\n                    oldpk=pkcache[hh,n,m]\n                    gstate[hh,m]-=oldpk\n                    for rr in range(hd):Hstate[hh,m,rr]-=oldpk*vcache[hh,n,rr]\n            # Reproject changed token with current weights.\n            for r in range(D):\n                qq=bq[r]; kk=bk[r]; vv=bv[r]\n                for c in range(D):\n                    xx=xn[n,c]\n                    qq+=WQ[r,c]*xx; kk+=WK[r,c]*xx; vv+=WV[r,c]*xx\n                hh=r//hd; rr=r-hh*hd\n                qraw[hh,n,rr]=qq; kraw[hh,n,rr]=kk; vcache[hh,n,rr]=vv\n            for hh in range(Hh):\n                pqt=phi_q_lut_vec(qraw[hh,n],omega[hh],qlut[hh],step)\n                pkt=phi_k_lut_vec(kraw[hh,n],omega[hh],klut[hh],step)\n                for m in range(M):\n                    pqcache[hh,n,m]=pqt[m]; pkcache[hh,n,m]=pkt[m]\n                    gstate[hh,m]+=pkt[m]\n                    for rr in range(hd):Hstate[hh,m,rr]+=pkt[m]*vcache[hh,n,rr]\n            for c in range(D):xcache[n,c]=xn[n,c]\n\n    # Read target query from resident pq cache and resident H/g.\n    a=np.empty(D,np.float64)\n    q=np.empty((Hh,hd),np.float64)\n    k=np.empty((Hh,N,hd),np.float64)\n    v=np.empty((Hh,N,hd),np.float64)\n    scores=np.empty((Hh,N),np.float64)\n    num=np.empty((Hh,hd),np.float64)\n    den=np.empty(Hh,np.float64)\n    alpha=np.empty((Hh,N),np.float64)\n    for hh in range(Hh):\n        for rr in range(hd):\n            q[hh,rr]=qraw[hh,t,rr]\n            for n in range(N):\n                k[hh,n,rr]=kraw[hh,n,rr]\n                v[hh,n,rr]=vcache[hh,n,rr]\n        dd=0.0\n        for m in range(M):dd+=pqcache[hh,t,m]*gstate[hh,m]\n        if dd<1e-8:dd=1e-8\n        den[hh]=dd\n        for rr in range(hd):\n            z=0.0\n            for m in range(M):z+=pqcache[hh,t,m]*Hstate[hh,m,rr]\n            num[hh,rr]=z; a[hh*hd+rr]=z/dd\n        for n in range(N):\n            ss=0.0\n            for m in range(M):ss+=pqcache[hh,t,m]*pkcache[hh,n,m]\n            scores[hh,n]=ss; alpha[hh,n]=ss/dd\n    return a,q,k,v,scores,num,den,alpha,changed_count\n\n\n@njit(cache=True)\ndef fresh_state_from_context_lut(WQ,bq,WK,bk,WV,bv,xn,omega,qlut,klut,step,\n                                 xcache,qraw,kraw,vcache,pqcache,pkcache,Hstate,gstate):\n    """Explicit O(N) state rebuild, used only by the oracle/control and audits."""\n    # t is irrelevant for initialization; target 0 is a valid read.\n    return resident_attention_step_lut(WQ,bq,WK,bk,WV,bv,xn,0,omega,qlut,klut,step,\n                                       0,xcache,qraw,kraw,vcache,pqcache,pkcache,Hstate,gstate)\n\'\'\'\n\n# ========================= p2c_trainer_static.py =========================\n_EMBEDDED[\'p2c_trainer_static\'] = r\'\'\'#!/usr/bin/env python3\nimport math\nimport numpy as np\nfrom numba import njit\nimport p1a_msdl_token_generation as p1a\nimport p1e4_joint_qkv_msdl as e4\nimport p1d_attention_output_msdl as p1d\nfrom p1g_izh_reintegration import joint_attention_state_lut, score_pair_qk_lut, read_pair_head_from_q_lut\nfrom p2b_resident_state import resident_attention_step_lut\nMIRROR_SIGMA = 0.1\nETA_BR = 0.0338\nETA_BO = 0.0335\nETA_B2 = 0.0335\n\n@njit(cache=True)\ndef reciprocal_microsteps(\n    BR, BO, B2, WR, WO, W2,\n    vm_br,um_br,ve_br,ue_br,zm_br,ze_br,\n    vm_bo,um_bo,ve_bo,ue_bo,zm_bo,ze_bo,\n    vm_b2,um_b2,ve_b2,ue_b2,zm_b2,ze_b2,\n    nsteps,sigma,eta_br,eta_bo,eta_b2,leak,adapt,\n):\n    D=WO.shape[0]; ff=W2.shape[1]; V=WR.shape[0]\n    se=0; sm=0\n    for _ in range(nsteps):\n        # B_R: feature perturbation -> categorical forward response.\n        df=np.random.normal(0.0,sigma,D)\n        dlogit=np.zeros(V,np.float64)\n        for v in range(V):\n            for o in range(D): dlogit[v]+=WR[v,o]*df[o]\n        M,smi=p1a.fast_izh_step(vm_br,um_br,df,zm_br,p1a.G_M,p1a.CV_M,p1a.CU_M)\n        E,sei=p1a.fast_izh_step(ve_br,ue_br,dlogit,ze_br,p1a.G_E,p1a.CV_E,p1a.CU_E)\n        sm+=smi;se+=sei\n        if adapt:\n            for o in range(D):\n                for v in range(V): BR[o,v]=(1.0-leak)*BR[o,v]+eta_br*M[o]*E[v]\n\n        # B_O: attended-state perturbation -> z forward response through current W_O.\n        da=np.random.normal(0.0,sigma,D)\n        dz=np.zeros(D,np.float64)\n        for o in range(D):\n            for j in range(D): dz[o]+=WO[o,j]*da[j]\n        M,smi=p1a.fast_izh_step(vm_bo,um_bo,da,zm_bo,p1a.G_M,p1a.CV_M,p1a.CU_M)\n        E,sei=p1a.fast_izh_step(ve_bo,ue_bo,dz,ze_bo,p1a.G_E,p1a.CV_E,p1a.CU_E)\n        sm+=smi;se+=sei\n        if adapt:\n            for j in range(D):\n                for o in range(D): BO[j,o]=(1.0-leak)*BO[j,o]+eta_bo*M[j]*E[o]\n\n        # B_2: hidden perturbation -> output response through current W_2.\n        dh=np.random.normal(0.0,sigma,ff)\n        dy=np.zeros(D,np.float64)\n        for o in range(D):\n            for i in range(ff): dy[o]+=W2[o,i]*dh[i]\n        M,smi=p1a.fast_izh_step(vm_b2,um_b2,dh,zm_b2,p1a.G_M,p1a.CV_M,p1a.CU_M)\n        E,sei=p1a.fast_izh_step(ve_b2,ue_b2,dy,ze_b2,p1a.G_E,p1a.CV_E,p1a.CU_E)\n        sm+=smi;se+=sei\n        if adapt:\n            for i in range(ff):\n                for o in range(D): B2[i,o]=(1.0-leak)*B2[i,o]+eta_b2*M[i]*E[o]\n    return se,sm\n\n\n@njit(cache=True)\ndef train_p2c_continuous_readout(\n    xn,xres,tpos,targets,masses,WR,BR,BO,B2,\n    WQ_init,bq,WK_init,bk,WV_init,bv,omega,\n    qlut,klut,lut_step,\n    WO_init,maskO,bo,gamma2,beta2,eps2,\n    W1_init,mask1,b1,theta,W2_init,mask2,b2,\n    seq_context_idx,seq_tokens,seq_probs,next_ctx,ctx_pos,root_ctx,static_policy_probs,\n    n_paths,lrq,lrk,lrv,lro,lr1,lr2,lrr,sigq,sigk,seed,p_self,p_iid,\n    adapt_feedback=False,mirror_per_force=1,mirror_leak=0.0,trace_every=100,\n    state_mode=1,reproject_each_path=False,\n    reset_every_force=False,m_off=False,feedback_sign=1.0,dynamic_self=False,\n):\n    np.random.seed(seed)\n    C=xn.shape[0];N=xn.shape[1];D=WQ_init.shape[0];H=omega.shape[0];hd=D//H;ff=W1_init.shape[0]\n    WQ=WQ_init.copy();WK=WK_init.copy();WV=WV_init.copy();WO=WO_init.copy();W1=W1_init.copy();W2=W2_init.copy();WRc=WR.copy()\n    BR=BR.copy();BO=BO.copy();B2=B2.copy()\n    Vcat=WRc.shape[0]\n    # Persistent reciprocal-learning E/M populations.\n    vm_br=np.full(D,p1a.V0);um_br=np.full(D,p1a.U0);ve_br=np.full(Vcat,p1a.V0);ue_br=np.full(Vcat,p1a.U0);zm_br=np.zeros(D);ze_br=np.zeros(Vcat)\n    vm_bo=np.full(D,p1a.V0);um_bo=np.full(D,p1a.U0);ve_bo=np.full(D,p1a.V0);ue_bo=np.full(D,p1a.U0);zm_bo=np.zeros(D);ze_bo=np.zeros(D)\n    vm_b2=np.full(ff,p1a.V0);um_b2=np.full(ff,p1a.U0);ve_b2=np.full(D,p1a.V0);ue_b2=np.full(D,p1a.U0);zm_b2=np.zeros(ff);ze_b2=np.zeros(D)\n    mirrorE=0;mirrorM=0\n    ntrace=n_paths//trace_every+2\n    tr_path=np.full(ntrace,-1,np.int64)\n    tr_WQ=np.empty((ntrace,D,D),np.float64);tr_WK=np.empty((ntrace,D,D),np.float64);tr_WV=np.empty((ntrace,D,D),np.float64);tr_WO=np.empty((ntrace,D,D),np.float64)\n    tr_W1=np.empty((ntrace,ff,D),np.float64);tr_W2=np.empty((ntrace,D,ff),np.float64)\n    tr_BR=np.empty((ntrace,D,Vcat),np.float64);tr_BO=np.empty((ntrace,D,D),np.float64);tr_B2=np.empty((ntrace,ff,D),np.float64);tr_WR=np.empty((ntrace,Vcat,D+1),np.float64)\n    nti=0\n    tr_path[nti]=0;tr_WQ[nti]=WQ;tr_WK[nti]=WK;tr_WV[nti]=WV;tr_WO[nti]=WO;tr_W1[nti]=W1;tr_W2[nti]=W2;tr_WR[nti]=WRc;tr_BR[nti]=BR;tr_BO[nti]=BO;tr_B2[nti]=B2;nti+=1\n\n    # Independent E/M state pairs for the six plastic projection populations plus categorical readout.\n    ver=np.full(D+1,p1a.V0);uer=np.full(D+1,p1a.U0);vmr=np.full(Vcat,p1a.V0);umr=np.full(Vcat,p1a.U0);zer=np.zeros(D+1);zmr=np.zeros(Vcat)\n    veq=np.full(D,p1a.V0);ueq=np.full(D,p1a.U0);vmq=np.full(D,p1a.V0);umq=np.full(D,p1a.U0);zeq=np.zeros(D);zmq=np.zeros(D)\n    vek=np.full(N*D,p1a.V0);uek=np.full(N*D,p1a.U0);vmk=np.full(N*D,p1a.V0);umk=np.full(N*D,p1a.U0);zek=np.zeros(N*D);zmk=np.zeros(N*D)\n    vev=np.full(H*D,p1a.V0);uev=np.full(H*D,p1a.U0);vmv=np.full(D,p1a.V0);umv=np.full(D,p1a.U0);zev=np.zeros(H*D);zmv=np.zeros(D)\n    veo=np.full(D,p1a.V0);ueo=np.full(D,p1a.U0);vmo=np.full(D,p1a.V0);umo=np.full(D,p1a.U0);zeo=np.zeros(D);zmo=np.zeros(D)\n    ve1=np.full(D,p1a.V0);ue1=np.full(D,p1a.U0);vm1=np.full(ff,p1a.V0);um1=np.full(ff,p1a.U0);ze1=np.zeros(D);zm1=np.zeros(ff)\n    ve2=np.full(ff,p1a.V0);ue2=np.full(ff,p1a.U0);vm2=np.full(D,p1a.V0);um2=np.full(D,p1a.U0);ze2=np.zeros(ff);zm2=np.zeros(D)\n\n    # Resident canonical attention state used by learning as well as generation.\n    Mfeat=omega.shape[1]\n    xcache=np.zeros((N,D),np.float64)\n    qraw_cache=np.zeros((H,N,hd),np.float64);kraw_cache=np.zeros((H,N,hd),np.float64);v_cache=np.zeros((H,N,hd),np.float64)\n    pq_cache=np.zeros((H,N,Mfeat),np.float64);pk_cache=np.zeros((H,N,Mfeat),np.float64)\n    Hstate=np.zeros((H,Mfeat,hd),np.float64);gstate=np.zeros((H,Mfeat),np.float64)\n    attn_initialized=0\n    changed_total=0;attention_steps=0;rebuild_count=0\n\n    cdf=np.cumsum(masses);cdf[-1]=1.;scdf=np.cumsum(seq_probs);scdf[-1]=1.\n    sched=np.empty(p1a.FORCE_STEPS,np.int64);kk=0\n    for t in range(p1a.N):\n        for _ in range(p1d.POSITION_COUNTS[t]):sched[kk]=t;kk+=1\n    seqE=0;seqM=0\n    online_nll_sum=0.0;online_count=0\n\n    for _p in range(n_paths):\n        rr=np.random.random();is_self=rr<p_self;is_iid=(not is_self) and rr<p_self+p_iid;coherent=(not is_self) and not is_iid\n        si=-1\n        if coherent:si=e4._sample_index(scdf)\n        Q0=WQ.copy();K0=WK.copy();V0=WV.copy();O0=WO.copy();L10=W1.copy();L20=W2.copy();R0=WRc.copy()\n        aq=np.zeros_like(WQ);ak=np.zeros_like(WK);av=np.zeros_like(WV);ao=np.zeros_like(WO);a1=np.zeros_like(W1);a2=np.zeros_like(W2);ar=np.zeros_like(WRc)\n        ci_self=root_ctx;rep_self=0\n\n        for sk in range(p1a.FORCE_STEPS):\n            # Reciprocal populations evolve continuously inside the same force stream.\n            mse,msm=reciprocal_microsteps(BR,BO,B2,WRc,O0,L20,\n                vm_br,um_br,ve_br,ue_br,zm_br,ze_br,\n                vm_bo,um_bo,ve_bo,ue_bo,zm_bo,ze_bo,\n                vm_b2,um_b2,ve_b2,ue_b2,zm_b2,ze_b2,\n                mirror_per_force,MIRROR_SIGMA,ETA_BR,ETA_BO,ETA_B2,mirror_leak,adapt_feedback)\n            mirrorE+=mse;mirrorM+=msm\n            if reset_every_force:\n                for j in range(D):\n                    veq[j]=p1a.V0;ueq[j]=p1a.U0;vmq[j]=p1a.V0;umq[j]=p1a.U0;vmv[j]=p1a.V0;umv[j]=p1a.U0\n                    veo[j]=p1a.V0;ueo[j]=p1a.U0;vmo[j]=p1a.V0;umo[j]=p1a.U0;ve1[j]=p1a.V0;ue1[j]=p1a.U0;vm2[j]=p1a.V0;um2[j]=p1a.U0;ver[j]=p1a.V0;uer[j]=p1a.U0\n                for j in range(N*D):vek[j]=p1a.V0;uek[j]=p1a.U0;vmk[j]=p1a.V0;umk[j]=p1a.U0\n                for j in range(H*D):vev[j]=p1a.V0;uev[j]=p1a.U0\n                for j in range(ff):vm1[j]=p1a.V0;um1[j]=p1a.U0;ve2[j]=p1a.V0;ue2[j]=p1a.U0\n                ver[D]=p1a.V0;uer[D]=p1a.U0\n                for j in range(Vcat):vmr[j]=p1a.V0;umr[j]=p1a.U0\n\n            if is_self:\n                ci=ci_self;target=p1a.sample_categorical_numba(targets[ci])\n            elif coherent:\n                tt=int(sched[sk]);ci=int(seq_context_idx[si,tt]);target=int(seq_tokens[si,tt])\n            else:\n                ci=e4._sample_index(cdf);target=p1a.sample_categorical_numba(targets[ci])\n            t=int(tpos[ci])\n\n            # P2-B: learning reads the same event-resident attention state as generation.\n            # state_mode=0 is the matched fresh-reconstruction control.\n            if state_mode==0:\n                attn_initialized=0\n            was_init=attn_initialized\n            a,q,k,v,scores,num,den,alpha,nchanged=resident_attention_step_lut(\n                Q0,bq,K0,bk,V0,bv,xn[ci],t,omega,qlut,klut,lut_step,\n                attn_initialized,xcache,qraw_cache,kraw_cache,v_cache,pq_cache,pk_cache,Hstate,gstate)\n            if was_init==0:rebuild_count+=1\n            attn_initialized=1\n            changed_total+=nchanged;attention_steps+=1\n\n            # Current full tail under path-frozen O0/L10/L20.\n            z=np.empty(D)\n            for o in range(D):\n                val=xres[ci,o]+bo[o]\n                for j in range(D):val+=O0[o,j]*a[j]\n                z[o]=val\n            mu=0.0\n            for o in range(D):mu+=z[o]\n            mu/=D;var=0.0\n            for o in range(D):qq=z[o]-mu;var+=qq*qq\n            var/=D;inv=1.0/math.sqrt(var+eps2);u=np.empty(D)\n            for o in range(D):u[o]=(z[o]-mu)*inv*gamma2[o]+beta2[o]\n            hvec=np.empty(ff)\n            for i in range(ff):\n                val=b1[i]-theta[i]\n                for j in range(D):val+=L10[i,j]*u[j]\n                hvec[i]=val if val>0.0 else 0.0\n            y=z.copy()\n            for o in range(D):\n                val=b2[o]\n                for i in range(ff):val+=L20[o,i]*hvec[i]\n                y[o]+=val\n            ss=0.0\n            for o in range(D):ss+=y[o]*y[o]\n            rms=math.sqrt(ss/D)+1e-8;logits=np.empty(p1a.V)\n            for vv in range(p1a.V):\n                val=0.5*R0[vv,D]\n                for o in range(D):val+=R0[vv,o]*(0.5*y[o]/rms)\n                logits[vv]=val\n            probs=p1a.softmax_numba(logits);err=np.empty(p1a.V)\n            pt=probs[target]\n            if pt<1e-12:pt=1e-12\n            online_nll_sum-=math.log(pt);online_count+=1\n            for vv in range(p1a.V):err[vv]=-probs[vv]\n            err[target]+=1.0\n\n            # W_R: normalized block output + constant local bias feature -> categorical population.\n            rfeat=np.empty(D+1)\n            for o in range(D):rfeat[o]=0.5*y[o]/rms\n            rfeat[D]=0.5\n            ER,se=p1a.fast_izh_step(ver,uer,rfeat,zer,p1a.G_E,p1a.CV_E,p1a.CU_E);seqE+=se\n            if m_off:MR=np.zeros(Vcat)\n            else:\n                one=np.zeros(Vcat);one[target]=1.0\n                MR,sm=p1a.fast_izh_step(vmr,umr,one,probs,p1a.G_M,p1a.CV_M,p1a.CU_M);seqM+=sm\n            for vv in range(Vcat):\n                for j in range(D+1):ar[vv,j]+=MR[vv]*ER[j]\n\n            # Learned local mismatch-routing populations.\n            drive_y=np.zeros(D)\n            if not m_off:\n                for o in range(D):\n                    for vv in range(p1a.V):drive_y[o]+=feedback_sign*BR[o,vv]*err[vv]\n            drive_h=np.zeros(ff)\n            if not m_off:\n                for i in range(ff):\n                    for o in range(D):drive_h[i]+=B2[i,o]*drive_y[o]\n            # Same local z mismatch used in the independently validated W_O rule.\n            drive_z=drive_y.copy()\n            drive_a=np.zeros(D)\n            if not m_off:\n                for j in range(D):\n                    for o in range(D):drive_a[j]+=BO[j,o]*drive_z[o]\n\n            # W2: hidden -> block output\n            E2,se=p1a.fast_izh_step(ve2,ue2,hvec,ze2,p1a.G_E,p1a.CV_E,p1a.CU_E);seqE+=se\n            if m_off:M2=np.zeros(D)\n            else:\n                M2,sm=p1a.fast_izh_step(vm2,um2,drive_y,zm2,p1a.G_M,p1a.CV_M,p1a.CU_M);seqM+=sm\n            for o in range(D):\n                for i in range(ff):\n                    if mask2[o,i]!=0.0:a2[o,i]+=M2[o]*E2[i]\n\n            # W1: LN2 population -> hidden\n            E1,se=p1a.fast_izh_step(ve1,ue1,u,ze1,p1a.G_E,p1a.CV_E,p1a.CU_E);seqE+=se\n            if m_off:M1=np.zeros(ff)\n            else:\n                M1,sm=p1a.fast_izh_step(vm1,um1,drive_h,zm1,p1a.G_M,p1a.CV_M,p1a.CU_M);seqM+=sm\n            for i in range(ff):\n                for j in range(D):\n                    if mask1[i,j]!=0.0:a1[i,j]+=M1[i]*E1[j]\n\n            # W_O: attended state -> z population\n            EO,se=p1a.fast_izh_step(veo,ueo,a,zeo,p1a.G_E,p1a.CV_E,p1a.CU_E);seqE+=se\n            if m_off:MO=np.zeros(D)\n            else:\n                MO,sm=p1a.fast_izh_step(vmo,umo,drive_z,zmo,p1a.G_M,p1a.CV_M,p1a.CU_M);seqM+=sm\n            for o in range(D):\n                for j in range(D):\n                    if maskO[o,j]!=0.0:ao[o,j]+=MO[o]*EO[j]\n\n            # W_V: relation-weighted presynaptic population -> attended state\n            sinput=np.empty(H*D)\n            for hh in range(H):\n                for c in range(D):\n                    sv=0.0\n                    for n in range(N):sv+=alpha[hh,n]*xn[ci,n,c]\n                    sinput[hh*D+c]=sv\n            EV,se=p1a.fast_izh_step(vev,uev,sinput,zev,p1a.G_E,p1a.CV_E,p1a.CU_E);seqE+=se\n            if m_off:MV=np.zeros(D)\n            else:\n                MV,sm=p1a.fast_izh_step(vmv,umv,drive_a,zmv,p1a.G_M,p1a.CV_M,p1a.CU_M);seqM+=sm\n            for r in range(D):\n                base=(r//hd)*D\n                for c in range(D):av[r,c]+=MV[r]*EV[base+c]\n\n            # W_K: token-local relation-writing perturbation\n            drive_k=np.zeros(N*D)\n            for hh in range(H):\n                for n in range(N):\n                    xi=np.empty(hd);kp=np.empty(hd);km=np.empty(hd)\n                    for rrh in range(hd):\n                        dd=1.0 if np.random.random()<0.5 else -1.0;xi[rrh]=dd;kp[rrh]=k[hh,n,rrh]+sigk*dd;km[rrh]=k[hh,n,rrh]-sigk*dd\n                    sp,smm=score_pair_qk_lut(q[hh],kp,km,omega[hh],qlut[hh],klut[hh],lut_step);s0=scores[hh,n]\n                    dp=den[hh]+sp-s0;dm=den[hh]+smm-s0\n                    if dp<1e-8:dp=1e-8\n                    if dm<1e-8:dm=1e-8\n                    scalar=0.0\n                    if not m_off:\n                        for rrh in range(hd):\n                            ap=(num[hh,rrh]+(sp-s0)*v[hh,n,rrh])/dp\n                            am=(num[hh,rrh]+(smm-s0)*v[hh,n,rrh])/dm\n                            scalar+=drive_a[hh*hd+rrh]*(ap-am)/(2.0*sigk)\n                    for rrh in range(hd):drive_k[n*D+hh*hd+rrh]=scalar*xi[rrh]\n            ein=np.empty(N*D)\n            for n in range(N):\n                for c in range(D):ein[n*D+c]=xn[ci,n,c]\n            EK,se=p1a.fast_izh_step(vek,uek,ein,zek,p1a.G_E,p1a.CV_E,p1a.CU_E);seqE+=se\n            if m_off:MK=np.zeros(N*D)\n            else:\n                MK,sm=p1a.fast_izh_step(vmk,umk,drive_k,zmk,p1a.G_M,p1a.CV_M,p1a.CU_M);seqM+=sm\n            for r in range(D):\n                for c in range(D):\n                    val=0.0\n                    for n in range(N):val+=MK[n*D+r]*EK[n*D+c]\n                    ak[r,c]+=val/N\n\n            # W_Q: current relation-reading perturbation\n            drive_q=np.zeros(D)\n            for hh in range(H):\n                xi=np.empty(hd);qp=np.empty(hd);qm=np.empty(hd)\n                for rrh in range(hd):\n                    dd=1.0 if np.random.random()<0.5 else -1.0;xi[rrh]=dd;qp[rrh]=q[hh,rrh]+sigq*dd;qm[rrh]=q[hh,rrh]-sigq*dd\n                ap,am=read_pair_head_from_q_lut(qp,qm,k[hh],v[hh],omega[hh],qlut[hh],klut[hh],lut_step);scalar=0.0\n                if not m_off:\n                    for rrh in range(hd):scalar+=drive_a[hh*hd+rrh]*(ap[rrh]-am[rrh])/(2.0*sigq)\n                for rrh in range(hd):drive_q[hh*hd+rrh]=scalar*xi[rrh]\n            EQ,se=p1a.fast_izh_step(veq,ueq,xn[ci,t],zeq,p1a.G_E,p1a.CV_E,p1a.CU_E);seqE+=se\n            if m_off:MQ=np.zeros(D)\n            else:\n                MQ,sm=p1a.fast_izh_step(vmq,umq,drive_q,zmq,p1a.G_M,p1a.CV_M,p1a.CU_M);seqM+=sm\n            for r in range(D):\n                for c in range(D):aq[r,c]+=MQ[r]*EQ[c]\n\n            if is_self:\n                rep_self+=1;tcur=int(ctx_pos[ci_self]);need=int(p1d.POSITION_COUNTS[tcur])\n                if rep_self>=need:\n                    if dynamic_self:sampled=p1a.sample_categorical_numba(probs)\n                    else:sampled=e4._sample_index(np.cumsum(static_policy_probs[ci_self]))\n                    if tcur==p1a.N-1:ci_self=root_ctx;rep_self=0\n                    else:\n                        ni=next_ctx[ci_self,sampled];ci_self=int(ni) if ni>=0 else root_ctx;rep_self=0\n\n        invsteps=1.0/p1a.FORCE_STEPS\n        for vv in range(Vcat):\n            for j in range(D+1):WRc[vv,j]+=lrr*ar[vv,j]*invsteps\n        for r in range(D):\n            for c in range(D):\n                WQ[r,c]+=lrq*aq[r,c]*invsteps\n                WK[r,c]+=lrk*ak[r,c]*invsteps\n                WV[r,c]+=lrv*av[r,c]*invsteps\n                if maskO[r,c]!=0.0:WO[r,c]+=lro*ao[r,c]*invsteps\n                else:WO[r,c]=0.0\n        for i in range(ff):\n            for c in range(D):\n                if mask1[i,c]!=0.0:W1[i,c]+=lr1*a1[i,c]*invsteps\n                else:W1[i,c]=0.0\n        for r in range(D):\n            for i in range(ff):\n                if mask2[r,i]!=0.0:W2[r,i]+=lr2*a2[r,i]*invsteps\n                else:W2[r,i]=0.0\n        # Oracle only: globally invalidate/reproject state after each synaptic update.\n        # Candidate keeps resident state; unchanged token traces can therefore be older than W(t).\n        if reproject_each_path:\n            attn_initialized=0\n        if ((_p+1)%trace_every)==0 or (_p+1)==n_paths:\n            tr_path[nti]=_p+1;tr_WQ[nti]=WQ;tr_WK[nti]=WK;tr_WV[nti]=WV;tr_WO[nti]=WO;tr_W1[nti]=W1;tr_W2[nti]=W2;tr_WR[nti]=WRc;tr_BR[nti]=BR;tr_BO[nti]=BO;tr_B2[nti]=B2;nti+=1\n    return WQ,WK,WV,WO,W1,W2,WRc,BR,BO,B2,seqE,seqM,mirrorE,mirrorM,tr_path[:nti],tr_WQ[:nti],tr_WK[:nti],tr_WV[:nti],tr_WO[:nti],tr_W1[:nti],tr_W2[:nti],tr_WR[:nti],tr_BR[:nti],tr_BO[:nti],tr_B2[:nti],changed_total,attention_steps,rebuild_count,xcache,Hstate,gstate,pq_cache,pk_cache,v_cache,online_nll_sum,online_count\n\'\'\'\n\n# ========================= p2d_reciprocal.py =========================\n_EMBEDDED[\'p2d_reciprocal\'] = r\'\'\'#!/usr/bin/env python3\nimport numpy as np\nfrom numba import njit\nimport p1a_msdl_token_generation as p1a\nMIRROR_SIGMA=0.1\nETA_BR=0.0338\nETA_BO=0.0335\nETA_B2=0.0335\n\n@njit(cache=True)\ndef reciprocal_microsteps(BR,BO,B2,WR,WO,W2,\n    vm_br,um_br,ve_br,ue_br,zm_br,ze_br,\n    vm_bo,um_bo,ve_bo,ue_bo,zm_bo,ze_bo,\n    vm_b2,um_b2,ve_b2,ue_b2,zm_b2,ze_b2,\n    nsteps,sigma,eta_br,eta_bo,eta_b2,leak,adapt):\n    D=WO.shape[0];ff=W2.shape[1];V=WR.shape[0];se=0;sm=0\n    for _ in range(nsteps):\n        df=np.random.normal(0.0,sigma,D);dlogit=np.zeros(V,np.float64)\n        for v in range(V):\n            for o in range(D):dlogit[v]+=WR[v,o]*df[o]\n        M,smi=p1a.fast_izh_step(vm_br,um_br,df,zm_br,p1a.G_M,p1a.CV_M,p1a.CU_M);E,sei=p1a.fast_izh_step(ve_br,ue_br,dlogit,ze_br,p1a.G_E,p1a.CV_E,p1a.CU_E);sm+=smi;se+=sei\n        if adapt:\n            for o in range(D):\n                for v in range(V):BR[o,v]=(1.0-leak)*BR[o,v]+eta_br*M[o]*E[v]\n        da=np.random.normal(0.0,sigma,D);dz=np.zeros(D,np.float64)\n        for o in range(D):\n            for j in range(D):dz[o]+=WO[o,j]*da[j]\n        M,smi=p1a.fast_izh_step(vm_bo,um_bo,da,zm_bo,p1a.G_M,p1a.CV_M,p1a.CU_M);E,sei=p1a.fast_izh_step(ve_bo,ue_bo,dz,ze_bo,p1a.G_E,p1a.CV_E,p1a.CU_E);sm+=smi;se+=sei\n        if adapt:\n            for j in range(D):\n                for o in range(D):BO[j,o]=(1.0-leak)*BO[j,o]+eta_bo*M[j]*E[o]\n        dh=np.random.normal(0.0,sigma,ff);dy=np.zeros(D,np.float64)\n        for o in range(D):\n            for i in range(ff):dy[o]+=W2[o,i]*dh[i]\n        M,smi=p1a.fast_izh_step(vm_b2,um_b2,dh,zm_b2,p1a.G_M,p1a.CV_M,p1a.CU_M);E,sei=p1a.fast_izh_step(ve_b2,ue_b2,dy,ze_b2,p1a.G_E,p1a.CV_E,p1a.CU_E);sm+=smi;se+=sei\n        if adapt:\n            for i in range(ff):\n                for o in range(D):B2[i,o]=(1.0-leak)*B2[i,o]+eta_b2*M[i]*E[o]\n    return se,sm\n\'\'\'\n\n# ========================= p2d_system.py =========================\n_EMBEDDED[\'p2d_system\'] = r\'\'\'#!/usr/bin/env python3\nfrom __future__ import annotations\nimport math\nfrom dataclasses import dataclass\nimport numpy as np\nfrom numba import njit\n\nimport p1a_msdl_token_generation as p1a\nfrom p1g_izh_reintegration import score_pair_qk_lut, read_pair_head_from_q_lut\nfrom p2b_resident_state import resident_attention_step_lut\nfrom p2d_reciprocal import reciprocal_microsteps, MIRROR_SIGMA, ETA_BR, ETA_BO, ETA_B2\n\n@njit(cache=True)\ndef seed_numba(seed:int):\n    np.random.seed(seed)\n\n@dataclass\nclass StepOutput:\n    probs: np.ndarray\n    sampled: int\n    nchanged: int\n    had_observation: bool\n\nclass ContinuousP2DSystem:\n    """One continuously running system.\n\n    There is no train/generate mode. `step(xn, xres, t, observed_target)` always:\n      1) updates/reads the resident attention state,\n      2) predicts a categorical distribution,\n      3) advances reciprocal and E/M populations,\n      4) accumulates the same synaptic plasticity rule,\n      5) applies the slow synaptic update every FORCE_STEPS events.\n\n    `observed_target=None` means the environment did not provide an observation.\n    The mismatch drive is then exactly zero, but all states continue to evolve.\n    """\n    def __init__(self,d,lut,weights,seed:int,lr_r:float=0.001,mirror_per_event:int=4,mirror_leak:float=0.0):\n        self.d=d; self.qlut,self.klut,self.lut_step=lut\n        (self.WQ,self.WK,self.WV,self.WO,self.W1,self.W2,self.WR,self.BR,self.BO,self.B2)=[np.array(x,dtype=np.float64,copy=True) for x in weights]\n        self.bq=d[\'bq\']; self.bk=d[\'bk\']; self.bv=d[\'bv\']; self.omega=d[\'omega\']\n        self.maskO=d[\'maskO\']; self.bo=d[\'bo\']; self.gamma2=d[\'gamma2\']; self.beta2=d[\'beta2\']; self.eps2=d[\'eps2\']\n        self.mask1=d[\'mask1\']; self.b1=d[\'b1\']; self.theta=d[\'theta\']; self.mask2=d[\'mask2\']; self.b2=d[\'b2\']\n        self.D=self.WQ.shape[0]; self.N=d[\'xn\'].shape[1]; self.H=self.omega.shape[0]; self.hd=self.D//self.H; self.ff=self.W1.shape[0]; self.V=self.WR.shape[0]; self.Mfeat=self.omega.shape[1]\n        self.lrq=d[\'lrq\'];self.lrk=d[\'lrk\'];self.lrv=d[\'lrv\'];self.lro=d[\'lro\'];self.lr1=d[\'lr1\'];self.lr2=d[\'lr2\'];self.lrr=lr_r\n        self.sigq=d[\'sigq\'];self.sigk=d[\'sigk\'];self.mirror_per_event=mirror_per_event;self.mirror_leak=mirror_leak\n        self.rng=np.random.default_rng(seed); seed_numba(seed+98731)\n        # Reciprocal learning populations\n        D=self.D;ff=self.ff;V=self.V\n        self.vm_br=np.full(D,p1a.V0);self.um_br=np.full(D,p1a.U0);self.ve_br=np.full(V,p1a.V0);self.ue_br=np.full(V,p1a.U0);self.zm_br=np.zeros(D);self.ze_br=np.zeros(V)\n        self.vm_bo=np.full(D,p1a.V0);self.um_bo=np.full(D,p1a.U0);self.ve_bo=np.full(D,p1a.V0);self.ue_bo=np.full(D,p1a.U0);self.zm_bo=np.zeros(D);self.ze_bo=np.zeros(D)\n        self.vm_b2=np.full(ff,p1a.V0);self.um_b2=np.full(ff,p1a.U0);self.ve_b2=np.full(D,p1a.V0);self.ue_b2=np.full(D,p1a.U0);self.zm_b2=np.zeros(ff);self.ze_b2=np.zeros(D)\n        # Forward/readout E/M populations\n        self.ver=np.full(D+1,p1a.V0);self.uer=np.full(D+1,p1a.U0);self.vmr=np.full(V,p1a.V0);self.umr=np.full(V,p1a.U0);self.zer=np.zeros(D+1);self.zmr=np.zeros(V)\n        self.veq=np.full(D,p1a.V0);self.ueq=np.full(D,p1a.U0);self.vmq=np.full(D,p1a.V0);self.umq=np.full(D,p1a.U0);self.zeq=np.zeros(D);self.zmq=np.zeros(D)\n        self.vek=np.full(self.N*D,p1a.V0);self.uek=np.full(self.N*D,p1a.U0);self.vmk=np.full(self.N*D,p1a.V0);self.umk=np.full(self.N*D,p1a.U0);self.zek=np.zeros(self.N*D);self.zmk=np.zeros(self.N*D)\n        self.vev=np.full(self.H*D,p1a.V0);self.uev=np.full(self.H*D,p1a.U0);self.vmv=np.full(D,p1a.V0);self.umv=np.full(D,p1a.U0);self.zev=np.zeros(self.H*D);self.zmv=np.zeros(D)\n        self.veo=np.full(D,p1a.V0);self.ueo=np.full(D,p1a.U0);self.vmo=np.full(D,p1a.V0);self.umo=np.full(D,p1a.U0);self.zeo=np.zeros(D);self.zmo=np.zeros(D)\n        self.ve1=np.full(D,p1a.V0);self.ue1=np.full(D,p1a.U0);self.vm1=np.full(ff,p1a.V0);self.um1=np.full(ff,p1a.U0);self.ze1=np.zeros(D);self.zm1=np.zeros(ff)\n        self.ve2=np.full(ff,p1a.V0);self.ue2=np.full(ff,p1a.U0);self.vm2=np.full(D,p1a.V0);self.um2=np.full(D,p1a.U0);self.ze2=np.zeros(ff);self.zm2=np.zeros(D)\n        # Resident attention state\n        self.xcache=np.zeros((self.N,D));self.qraw=np.zeros((self.H,self.N,self.hd));self.kraw=np.zeros_like(self.qraw);self.vcache=np.zeros_like(self.qraw)\n        self.pq=np.zeros((self.H,self.N,self.Mfeat));self.pk=np.zeros_like(self.pq);self.Hstate=np.zeros((self.H,self.Mfeat,self.hd));self.gstate=np.zeros((self.H,self.Mfeat));self.initialized=0\n        # Slow update accumulators\n        self._clear_accum(); self.event_count=0;self.update_count=0;self.rebuild_count=0;self.changed_total=0;self.obs_count=0;self.free_count=0;self.obs_nll_sum=0.0\n    def _clear_accum(self):\n        self.aq=np.zeros_like(self.WQ);self.ak=np.zeros_like(self.WK);self.av=np.zeros_like(self.WV);self.ao=np.zeros_like(self.WO);self.a1=np.zeros_like(self.W1);self.a2=np.zeros_like(self.W2);self.ar=np.zeros_like(self.WR);self.accum_steps=0\n    def weight_tuple(self): return tuple(np.array(x,copy=True) for x in (self.WQ,self.WK,self.WV,self.WO,self.W1,self.W2,self.WR,self.BR,self.BO,self.B2))\n    def _apply_update(self):\n        inv=1.0/max(1,self.accum_steps)\n        self.WR += self.lrr*self.ar*inv\n        self.WQ += self.lrq*self.aq*inv; self.WK += self.lrk*self.ak*inv; self.WV += self.lrv*self.av*inv\n        self.WO += self.lro*self.ao*inv; self.WO *= self.maskO\n        self.W1 += self.lr1*self.a1*inv; self.W1 *= self.mask1\n        self.W2 += self.lr2*self.a2*inv; self.W2 *= self.mask2\n        self.update_count+=1; self._clear_accum()\n    def step(self,xn:np.ndarray,xres:np.ndarray,t:int,observed_target:int|None=None)->StepOutput:\n        # Reciprocal populations are always alive, independent of external observation availability.\n        reciprocal_microsteps(self.BR,self.BO,self.B2,self.WR,self.WO,self.W2,\n            self.vm_br,self.um_br,self.ve_br,self.ue_br,self.zm_br,self.ze_br,\n            self.vm_bo,self.um_bo,self.ve_bo,self.ue_bo,self.zm_bo,self.ze_bo,\n            self.vm_b2,self.um_b2,self.ve_b2,self.ue_b2,self.zm_b2,self.ze_b2,\n            self.mirror_per_event,MIRROR_SIGMA,ETA_BR,ETA_BO,ETA_B2,self.mirror_leak,True)\n        was=self.initialized\n        a,q,k,v,scores,num,den,alpha,nchanged=resident_attention_step_lut(\n            self.WQ,self.bq,self.WK,self.bk,self.WV,self.bv,xn,int(t),self.omega,self.qlut,self.klut,self.lut_step,\n            self.initialized,self.xcache,self.qraw,self.kraw,self.vcache,self.pq,self.pk,self.Hstate,self.gstate)\n        if was==0:self.rebuild_count+=1\n        self.initialized=1;self.changed_total+=int(nchanged)\n        # Tail/readout\n        z=xres+self.bo+self.WO@a\n        mu=z.mean();inv=1.0/math.sqrt(float(np.mean((z-mu)**2))+self.eps2);u=(z-mu)*inv*self.gamma2+self.beta2\n        h=np.maximum(0.0,self.W1@u+self.b1-self.theta)\n        y=z+self.W2@h+self.b2\n        rms=math.sqrt(float(np.mean(y*y)))+1e-8;rfeat=np.empty(self.D+1);rfeat[:self.D]=0.5*y/rms;rfeat[self.D]=0.5\n        probs=p1a.softmax_numba(self.WR@rfeat)\n        sampled=int(self.rng.choice(self.V,p=probs/probs.sum()))\n        has_obs=observed_target is not None\n        err=np.zeros(self.V)\n        if has_obs:\n            target=int(observed_target);err[:]=-probs;err[target]+=1.0\n            self.obs_nll_sum-=math.log(max(float(probs[target]),1e-12));self.obs_count+=1\n        else:self.free_count+=1\n        # Readout local E/M\n        ER,_=p1a.fast_izh_step(self.ver,self.uer,rfeat,self.zer,p1a.G_E,p1a.CV_E,p1a.CU_E)\n        if has_obs:\n            one=np.zeros(self.V);one[int(observed_target)]=1.0;MR,_=p1a.fast_izh_step(self.vmr,self.umr,one,probs,p1a.G_M,p1a.CV_M,p1a.CU_M)\n        else:\n            zero=np.zeros(self.V);MR,_=p1a.fast_izh_step(self.vmr,self.umr,zero,zero,p1a.G_M,p1a.CV_M,p1a.CU_M)\n        self.ar += np.outer(MR,ER)\n        drive_y=self.BR@err;drive_h=self.B2@drive_y;drive_a=self.BO@drive_y\n        E2,_=p1a.fast_izh_step(self.ve2,self.ue2,h,self.ze2,p1a.G_E,p1a.CV_E,p1a.CU_E);M2,_=p1a.fast_izh_step(self.vm2,self.um2,drive_y,self.zm2,p1a.G_M,p1a.CV_M,p1a.CU_M);self.a2 += np.outer(M2,E2)*self.mask2\n        E1,_=p1a.fast_izh_step(self.ve1,self.ue1,u,self.ze1,p1a.G_E,p1a.CV_E,p1a.CU_E);M1,_=p1a.fast_izh_step(self.vm1,self.um1,drive_h,self.zm1,p1a.G_M,p1a.CV_M,p1a.CU_M);self.a1 += np.outer(M1,E1)*self.mask1\n        EO,_=p1a.fast_izh_step(self.veo,self.ueo,a,self.zeo,p1a.G_E,p1a.CV_E,p1a.CU_E);MO,_=p1a.fast_izh_step(self.vmo,self.umo,drive_y,self.zmo,p1a.G_M,p1a.CV_M,p1a.CU_M);self.ao += np.outer(MO,EO)*self.maskO\n        sinput=np.concatenate([alpha[hh]@xn for hh in range(self.H)])\n        EV,_=p1a.fast_izh_step(self.vev,self.uev,sinput,self.zev,p1a.G_E,p1a.CV_E,p1a.CU_E);MV,_=p1a.fast_izh_step(self.vmv,self.umv,drive_a,self.zmv,p1a.G_M,p1a.CV_M,p1a.CU_M)\n        for r in range(self.D):\n            hh=r//self.hd;self.av[r]+=MV[r]*EV[hh*self.D:(hh+1)*self.D]\n        # K local perturbation; mismatch-free events have drive_a=0 but the M population itself still evolves.\n        drive_k=np.zeros((self.N,self.D))\n        for hh in range(self.H):\n            for n in range(self.N):\n                xi=self.rng.choice(np.array([-1.0,1.0]),size=self.hd);kp=k[hh,n]+self.sigk*xi;km=k[hh,n]-self.sigk*xi\n                sp,sm=score_pair_qk_lut(q[hh],kp,km,self.omega[hh],self.qlut[hh],self.klut[hh],self.lut_step);s0=scores[hh,n];dp=max(1e-8,den[hh]+sp-s0);dm=max(1e-8,den[hh]+sm-s0)\n                ap=(num[hh]+(sp-s0)*v[hh,n])/dp;am=(num[hh]+(sm-s0)*v[hh,n])/dm\n                scalar=float(np.dot(drive_a[hh*self.hd:(hh+1)*self.hd],ap-am)/(2*self.sigk));drive_k[n,hh*self.hd:(hh+1)*self.hd]=scalar*xi\n        EK,_=p1a.fast_izh_step(self.vek,self.uek,xn.reshape(-1),self.zek,p1a.G_E,p1a.CV_E,p1a.CU_E);MK,_=p1a.fast_izh_step(self.vmk,self.umk,drive_k.reshape(-1),self.zmk,p1a.G_M,p1a.CV_M,p1a.CU_M)\n        self.ak += (MK.reshape(self.N,self.D).T@EK.reshape(self.N,self.D))/self.N\n        # Q local perturbation\n        drive_q=np.zeros(self.D)\n        for hh in range(self.H):\n            xi=self.rng.choice(np.array([-1.0,1.0]),size=self.hd);qp=q[hh]+self.sigq*xi;qm=q[hh]-self.sigq*xi\n            ap,am=read_pair_head_from_q_lut(qp,qm,k[hh],v[hh],self.omega[hh],self.qlut[hh],self.klut[hh],self.lut_step)\n            scalar=float(np.dot(drive_a[hh*self.hd:(hh+1)*self.hd],ap-am)/(2*self.sigq));drive_q[hh*self.hd:(hh+1)*self.hd]=scalar*xi\n        EQ,_=p1a.fast_izh_step(self.veq,self.ueq,xn[t],self.zeq,p1a.G_E,p1a.CV_E,p1a.CU_E);MQ,_=p1a.fast_izh_step(self.vmq,self.umq,drive_q,self.zmq,p1a.G_M,p1a.CV_M,p1a.CU_M);self.aq += np.outer(MQ,EQ)\n        self.event_count+=1;self.accum_steps+=1\n        if self.accum_steps>=p1a.FORCE_STEPS:self._apply_update()\n        return StepOutput(np.asarray(probs,dtype=np.float64),sampled,int(nchanged),has_obs)\n\n    def flush(self):\n        """Diagnostic only. Not used at phase boundaries in P2-D."""\n        if self.accum_steps:self._apply_update()\n\'\'\'\n\n# ========================= p2e_domains.py =========================\n_EMBEDDED[\'p2e_domains\'] = r\'\'\'#!/usr/bin/env python3\nfrom __future__ import annotations\nimport itertools\nfrom collections import defaultdict\nfrom dataclasses import dataclass\nfrom typing import Dict, List, Tuple\nimport numpy as np\nimport torch\nfrom numba import njit\n\nimport p1a_msdl_token_generation as p1a\nimport p1d_attention_output_msdl as p1d\nimport p1e4_joint_qkv_msdl as e4\nimport p1g_izh_reintegration as p1g\n\n@dataclass\nclass Domain:\n    name: str\n    true_dist: List[Tuple[Tuple[int,...], float]]\n    keys: list\n    arrays: np.ndarray\n    targets: np.ndarray\n    masses: np.ndarray\n    xn: np.ndarray\n    xres: np.ndarray\n    tpos: np.ndarray\n    key_to_i: Dict\n\n# A is the already validated grammar. B/C deliberately use the SAME token\n# support and the same latent-mode token space (x0 in {0,1}) but different\n# stochastic conditional laws. Thus this is a genuine nonstationary-distribution\n# benchmark, not a context-labelled multi-task benchmark. Old and current laws\n# can conflict on the same prefix, so simultaneous low loss on all A/B/C is NOT\n# required; adaptation, bounded forgetting, and A reacquisition are the targets.\ndef enumerate_domain(name:str):\n    name=name.upper(); dd=defaultdict(float)\n    if name==\'A\':\n        cue0=0; p_mode=(0.45,0.55)\n    elif name==\'B\':\n        cue0=0; p_mode=(0.50,0.50)\n    elif name==\'C\':\n        cue0=0; p_mode=(0.60,0.40)\n    else: raise ValueError(name)\n    for m,pm in enumerate(p_mode):\n        for bits in itertools.product((0,1), repeat=7):\n            b1,b2,b3,b4,b5,b6,b7=bits\n            if name==\'A\':\n                ps=[0.20 if m==0 else 0.75,\n                    0.65 if m==0 else 0.35,\n                    0.20+0.60*b1,\n                    0.20+0.60*b2,\n                    0.25+0.50*m,\n                    0.20+0.60*b1,\n                    0.20+0.60*b3]\n            elif name==\'B\':\n                ps=[0.80 if m==0 else 0.25,\n                    0.25 if m==0 else 0.75,\n                    0.20+0.60*b2,\n                    0.75-0.50*b1,\n                    0.70-0.40*m,\n                    0.25+0.50*b2,\n                    0.20+0.60*b4]\n            else: # C strong shift, same support/cue space.\n                ps=[0.30 if m==0 else 0.80,\n                    0.80 if m==0 else 0.20,\n                    0.80-0.60*b1,\n                    0.20+0.60*b3,\n                    0.20+0.60*b2,\n                    0.75-0.50*m,\n                    0.20+0.60*b1]\n            p=pm\n            for b,pr in zip(bits,ps): p*=pr if b else (1.0-pr)\n            seq=(cue0+m,\n                 3 if b1 else 2,\n                 5 if b2 else 4,\n                 7 if b3 else 6,\n                 3 if b4 else 2,\n                 5 if b5 else 4,\n                 7 if b6 else 6,\n                 3 if b7 else 2)\n            dd[seq]+=p\n    items=sorted(dd.items()); total=sum(p for _,p in items)\n    assert len(items)==256 and abs(total-1.0)<1e-12\n    return items\n\ndef build_domain(base_d,name:str)->Domain:\n    dist=enumerate_domain(name)\n    keys,arrays,targets,masses,xn,xres,tpos=e4.build_joint_dataset(base_d[\'block\'],base_d[\'tok\'],base_d[\'pos\'],dist)\n    return Domain(name,dist,keys,arrays,targets,masses,xn,xres,tpos,{k:i for i,k in enumerate(keys)})\n\n@njit(cache=True)\ndef batch_attended_lut(WQ,bq,WK,bk,WV,bv,xn,tpos,omega,qlut,klut,step):\n    C=xn.shape[0]; A=np.empty((C,WQ.shape[0]),np.float64)\n    for i in range(C):\n        A[i]=p1g.joint_attention_state_lut(WQ,bq,WK,bk,WV,bv,xn[i],int(tpos[i]),omega,qlut,klut,step)[0]\n    return A\n\ndef evaluate_domain(base_d,lut,weights,dom:Domain):\n    qlut,klut,step=lut\n    WQ,WK,WV,WO,W1,W2,WR=weights[:7]\n    A=batch_attended_lut(WQ,base_d[\'bq\'],WK,base_d[\'bk\'],WV,base_d[\'bv\'],dom.xn,dom.tpos,base_d[\'omega\'],qlut,klut,step)\n    f=p1d.forward_features_wo(WO,A,dom.xres,base_d[\'bo\'],base_d[\'gamma2\'],base_d[\'beta2\'],base_d[\'eps2\'],W1,base_d[\'b1\'],base_d[\'theta\'],W2,base_d[\'b2\'])\n    P=p1a.probs_from_W(WR,f)\n    full_nll=p1a.expected_nll(P,dom.targets,dom.masses)\n    full_js=p1a.conditional_js(P,dom.targets,dom.masses)\n    mask=dom.tpos>0\n    mm=dom.masses[mask].copy(); mm/=mm.sum()\n    cond_nll=p1a.expected_nll(P[mask],dom.targets[mask],mm)\n    cond_js=p1a.conditional_js(P[mask],dom.targets[mask],mm)\n    # Position-wise NLL is useful to distinguish the unavoidable domain-prior\n    # conflict at t=0 from cue-conditioned memory at positions 1..7.\n    pos_nll={}\n    for t in range(p1a.N):\n        ix=dom.tpos==t; mt=dom.masses[ix].copy(); mt/=mt.sum()\n        pos_nll[str(t)]=p1a.expected_nll(P[ix],dom.targets[ix],mt)\n    return {\'full_nll\':float(full_nll),\'full_js\':float(full_js),\n            \'conditional_nll_t1_7\':float(cond_nll),\'conditional_js_t1_7\':float(cond_js),\'position_nll\':pos_nll}\n\ndef sample_sequence(dom:Domain,rng:np.random.Generator):\n    p=np.fromiter((x[1] for x in dom.true_dist),dtype=np.float64);p/=p.sum()\n    i=int(rng.choice(len(dom.true_dist),p=p));return dom.true_dist[i][0]\n\ndef empirical_js(samples:np.ndarray,dom:Domain):\n    return p1a.empirical_js_with_invalid_bucket(samples,dom.true_dist)\n\'\'\'\n\n\n# ========================= single-file runner =========================\n\ndef _load_embedded_modules():\n    td = tempfile.TemporaryDirectory(prefix="snn_transform_p2e_")\n    root = Path(td.name)\n    for name, source in _EMBEDDED.items():\n        (root / f"{name}.py").write_text(source, encoding="utf-8")\n    sys.path.insert(0, str(root))\n    loaded = {name: importlib.import_module(name) for name in _EMBEDDED}\n    return td, loaded\n\n\ndef _make_p2c_args(d, lut, p1a):\n    qlut, klut, step = lut\n    BR = np.zeros((p1a.D, p1a.V), np.float64)\n    BO = np.zeros_like(d["WO"].T)\n    B2 = np.zeros_like(d["W2"].T)\n    return (\n        d["xn"], d["xres"], d["tpos"], d["targets"], d["masses"], d["WR"], BR, BO, B2,\n        d["WQ"], d["bq"], d["WK"], d["bk"], d["WV"], d["bv"], d["omega"], qlut, klut, step,\n        d["WO"], d["maskO"], d["bo"], d["gamma2"], d["beta2"], d["eps2"],\n        d["W1"], d["mask1"], d["b1"], d["theta"], d["W2"], d["mask2"], d["b2"],\n        d["sci"], d["st"], d["sp"], d["nxt"], d["cpos"], d["root"], d["static"],\n    )\n\n\ndef _train_from_zero_to_p2c(d, lut, seed, paths, lr_r, M):\n    p1a=M["p1a_msdl_token_generation"]\n    p1f=M["p1f_full_block_msdl"]\n    p1g=M["p1g_izh_reintegration"]\n    p2a=M["p2a_continuous_reciprocal"]\n    trainer=M["p2c_trainer_static"]\n    return trainer.train_p2c_continuous_readout(\n        *_make_p2c_args(d, lut, p1a),\n        int(paths),\n        p1f.BASE_LR_Q*p1g.MULTIPLIER,\n        p1f.BASE_LR_K*p1g.MULTIPLIER,\n        p1f.BASE_LR_V*p1g.MULTIPLIER,\n        p1f.BASE_LR_O*p1g.MULTIPLIER,\n        p1f.BASE_LR_1*p1g.MULTIPLIER,\n        p1f.BASE_LR_2*p1g.MULTIPLIER,\n        float(lr_r),\n        p1f.SIGMA_Q, p1f.SIGMA_K,\n        int(seed), p1f.P_SELF, p1f.P_IID,\n        True, 4, p2a.MIRROR_LEAK, 100,\n        1, False,\n        False, False, 1.0, False,\n    )\n\n\ndef _eval_all(d, lut, domains, system, M):\n    ev=M["p2e_domains"].evaluate_domain\n    w=system.weight_tuple()\n    return {name: ev(d, lut, w, domains[name]) for name in ("A","B","C")}\n\n\ndef _run_observed_phase(system, domain, n_events, seed, eval_every, d, lut, domains, M):\n    p1a=M["p1a_msdl_token_generation"]\n    p2e=M["p2e_domains"]\n    rng=np.random.default_rng(seed)\n    seq=None; t=0\n    curve=[{"events":0,"metrics":_eval_all(d,lut,domains,system,M)}]\n    for ev in range(1, n_events+1):\n        if seq is None or t==p1a.N:\n            seq=p2e.sample_sequence(domain,rng); t=0\n        ci=domain.key_to_i[(t,tuple(seq[:t]))]\n        system.step(domain.xn[ci],domain.xres[ci],t,int(seq[t]))\n        t+=1\n        if ev % eval_every == 0 or ev == n_events:\n            curve.append({"events":ev,"metrics":_eval_all(d,lut,domains,system,M)})\n    return curve\n\n\ndef _reset_fast_learning_population_state(s, p1a):\n    pairs=(\n        (\'ver\',\'uer\'),(\'vmr\',\'umr\'),(\'veq\',\'ueq\'),(\'vmq\',\'umq\'),(\'vek\',\'uek\'),(\'vmk\',\'umk\'),\n        (\'vev\',\'uev\'),(\'vmv\',\'umv\'),(\'veo\',\'ueo\'),(\'vmo\',\'umo\'),(\'ve1\',\'ue1\'),(\'vm1\',\'um1\'),\n        (\'ve2\',\'ue2\'),(\'vm2\',\'um2\'),(\'vm_br\',\'um_br\'),(\'ve_br\',\'ue_br\'),(\'vm_bo\',\'um_bo\'),\n        (\'ve_bo\',\'ue_bo\'),(\'vm_b2\',\'um_b2\'),(\'ve_b2\',\'ue_b2\'))\n    zstates=(\'zer\',\'zmr\',\'zeq\',\'zmq\',\'zek\',\'zmk\',\'zev\',\'zmv\',\'zeo\',\'zmo\',\'ze1\',\'zm1\',\'ze2\',\'zm2\',\n             \'zm_br\',\'ze_br\',\'zm_bo\',\'ze_bo\',\'zm_b2\',\'ze_b2\')\n    for va,ua in pairs:\n        getattr(s,va).fill(p1a.V0); getattr(s,ua).fill(p1a.U0)\n    for z in zstates:\n        getattr(s,z).fill(0.0)\n    s._clear_accum()\n\n\ndef _static_generation(d, cal, weights, domain, n, seed, M):\n    p1a=M["p1a_msdl_token_generation"]\n    p1g=M["p1g_izh_reintegration"]\n    block=p1g.make_block_izh(d,cal,*weights[:6])\n    samples=p1a.autonomous_generate(block,d[\'tok\'],d[\'pos\'],weights[6],n,seed,p1a.GEN_BATCH)\n    js,val,_,cov=p1a.empirical_js_with_invalid_bucket(samples,domain.true_dist)\n    return {\n        \'joint_js\':float(js), \'valid_fraction\':float(val), \'coverage\':int(cov),\n        \'token_support\':float(p1a.generated_support_rate(samples)),\n    }\n\n\ndef _adaptation_time(curve, domain_name, fraction=.8):\n    key=\'conditional_nll_t1_7\'\n    l0=curve[0][\'metrics\'][domain_name][key]\n    lf=curve[-1][\'metrics\'][domain_name][key]\n    if lf >= l0: return None\n    threshold=l0-fraction*(l0-lf)\n    for pt in curve:\n        if pt[\'metrics\'][domain_name][key] <= threshold:\n            return int(pt[\'events\'])\n    return None\n\n\ndef _offmask(d, w):\n    vals=[]\n    for W,mask in ((w[3],d[\'maskO\']),(w[4],d[\'mask1\']),(w[5],d[\'mask2\'])):\n        if np.any(mask==0): vals.append(float(np.max(np.abs(W[mask==0]))))\n    return max(vals) if vals else 0.0\n\n\ndef _write_curve_csv(path, curves):\n    rows=[]\n    for phase,curve in curves.items():\n        for pt in curve:\n            for dom,m in pt[\'metrics\'].items():\n                rows.append({\n                    \'phase\':phase,\'events\':pt[\'events\'],\'domain\':dom,\n                    \'full_nll\':m[\'full_nll\'],\'full_js\':m[\'full_js\'],\n                    \'conditional_nll_t1_7\':m[\'conditional_nll_t1_7\'],\n                    \'conditional_js_t1_7\':m[\'conditional_js_t1_7\'],\n                })\n    with open(path,\'w\',newline=\'\',encoding=\'utf-8\') as f:\n        w=csv.DictWriter(f,fieldnames=list(rows[0].keys())); w.writeheader(); w.writerows(rows)\n\n\ndef run(args):\n    temp_modules, M = _load_embedded_modules()\n    try:\n        p1a=M[\'p1a_msdl_token_generation\']; p1d=M[\'p1d_attention_output_msdl\']\n        p1f=M[\'p1f_full_block_msdl\']; p1g=M[\'p1g_izh_reintegration\']\n        p2a=M[\'p2a_continuous_reciprocal\']; p2d=M[\'p2d_system\']; p2e=M[\'p2e_domains\']\n\n        torch.set_num_threads(args.threads)\n        np.random.seed(args.seed); torch.manual_seed(p1a.TORCH_INIT_SEED)\n\n        if args.quick:\n            # Only shorten exposure; no mechanism is changed.\n            p1d.READOUT_PATHS=min(int(p1d.READOUT_PATHS), 20)\n            p1f.MIRROR_STEPS=min(int(p1f.MIRROR_STEPS), 20)\n            p2c_paths=1\n            phase_events=8\n            eval_every=4\n            n_generate=0\n        else:\n            p2c_paths=args.p2c_paths\n            phase_events=args.phase_events\n            eval_every=args.eval_every\n            n_generate=args.generate\n\n        t0=time.time()\n\n        print(\'[1/4] from-zero scaffold + readout\', flush=True)\n        # From-zero scaffold + MSDL categorical readout.\n        d=p1f.setup()\n        d.update(\n            lrq=p1f.BASE_LR_Q*p1g.MULTIPLIER,\n            lrk=p1f.BASE_LR_K*p1g.MULTIPLIER,\n            lrv=p1f.BASE_LR_V*p1g.MULTIPLIER,\n            lro=p1f.BASE_LR_O*p1g.MULTIPLIER,\n            lr1=p1f.BASE_LR_1*p1g.MULTIPLIER,\n            lr2=p1f.BASE_LR_2*p1g.MULTIPLIER,\n            sigq=p1f.SIGMA_Q, sigk=p1f.SIGMA_K,\n        )\n\n        print(\'[2/4] calibrate neuronal Q/K interface\', flush=True)\n        # Fixed pre-learning neuronal Q/K interface, created from the initial state only.\n        cal=p1g.calibrate_initial_interface(d)\n        lut=p1g.build_luts(cal)\n\n        print(\'[3/4] continuous full-block/readout/reciprocal learning\', flush=True)\n        # P2-A/B/C functionality from zero: resident attention, continuously adapting\n        # reciprocal populations, and continuous readout/full-block plasticity.\n        p2c=_train_from_zero_to_p2c(d,lut,args.seed,p2c_paths,args.readout_lr,M)\n        weights=tuple(np.array(x,copy=True) for x in p2c[:10])\n\n        print(\'[4/4] continual A->B->C->A stream\', flush=True)\n        # P2-D/P2-E continuous system. No checkpoint or saved state is loaded.\n        system=p2d.ContinuousP2DSystem(d,lut,weights,args.seed+50000,args.readout_lr,4,p2a.MIRROR_LEAK)\n        domains={name:p2e.build_domain(d,name) for name in (\'A\',\'B\',\'C\')}\n\n        curves={}\n        curves[\'A_initial\']=_run_observed_phase(system,domains[\'A\'],phase_events,args.seed+61000,eval_every,d,lut,domains,M)\n        snap_A=_eval_all(d,lut,domains,system,M); w_A=system.weight_tuple()\n        curves[\'B\']=_run_observed_phase(system,domains[\'B\'],phase_events,args.seed+62000,eval_every,d,lut,domains,M)\n        snap_B=_eval_all(d,lut,domains,system,M); w_B=system.weight_tuple()\n        curves[\'C\']=_run_observed_phase(system,domains[\'C\'],phase_events,args.seed+63000,eval_every,d,lut,domains,M)\n        snap_C=_eval_all(d,lut,domains,system,M); w_C=system.weight_tuple()\n\n        reset_control=copy.deepcopy(system)\n        _reset_fast_learning_population_state(reset_control,p1a)\n\n        curves[\'A_return\']=_run_observed_phase(system,domains[\'A\'],phase_events,args.seed+64000,eval_every,d,lut,domains,M)\n        snap_AR=_eval_all(d,lut,domains,system,M); w_final=system.weight_tuple()\n        reset_curve=_run_observed_phase(reset_control,domains[\'A\'],phase_events,args.seed+64000,eval_every,d,lut,domains,M)\n        snap_reset=_eval_all(d,lut,domains,reset_control,M)\n\n        generation={}\n        if n_generate > 0:\n            generation={\n                \'after_A\':_static_generation(d,cal,w_A,domains[\'A\'],n_generate,args.seed+71000,M),\n                \'after_B\':_static_generation(d,cal,w_B,domains[\'B\'],n_generate,args.seed+72000,M),\n                \'after_C\':_static_generation(d,cal,w_C,domains[\'C\'],n_generate,args.seed+73000,M),\n                \'after_A_return\':_static_generation(d,cal,w_final,domains[\'A\'],n_generate,args.seed+74000,M),\n            }\n\n        k=\'conditional_nll_t1_7\'\n        A0=snap_A[\'A\'][k]; AB=snap_B[\'A\'][k]; AC=snap_C[\'A\'][k]; AR=snap_AR[\'A\'][k]\n        B0=snap_A[\'B\'][k]; BB=snap_B[\'B\'][k]; BC=snap_C[\'B\'][k]\n        C0=snap_B[\'C\'][k]; CC=snap_C[\'C\'][k]\n\n        result={\n            \'stage\':\'CURRENT_IMPLEMENTATION_THROUGH_P2E_FROM_ZERO\',\n            \'seed\':int(args.seed),\n            \'quick\':bool(args.quick),\n            \'from_zero\':True,\n            \'p2c_paths\':int(p2c_paths),\n            \'phase_events\':int(phase_events),\n            \'phase_order\':[\'A\',\'B\',\'C\',\'A\'],\n            \'initial_scaffold_baseline\':d[\'baseline\'],\n            \'snapshots\':{\'after_A\':snap_A,\'after_B\':snap_B,\'after_C\':snap_C,\'after_A_return\':snap_AR},\n            \'continual_metrics\':{\n                \'B_improvement\':float(B0-BB),\n                \'C_improvement\':float(C0-CC),\n                \'A_forgetting_after_B\':float(AB-A0),\n                \'A_forgetting_after_C\':float(AC-A0),\n                \'B_forgetting_after_C\':float(BC-BB),\n                \'A_return_recovery\':float(AC-AR),\n                \'A_final_gap_vs_pre_switch\':float(AR-A0),\n            },\n            \'adaptation_events_80pct\':{\n                \'B\':_adaptation_time(curves[\'B\'],\'B\'),\n                \'C\':_adaptation_time(curves[\'C\'],\'C\'),\n                \'A_return\':_adaptation_time(curves[\'A_return\'],\'A\'),\n            },\n            \'reset_learning_population_control\':{\n                \'final_A\':snap_reset[\'A\'],\n                \'continuous_minus_reset_final_A_nll\':float(AR-snap_reset[\'A\'][k]),\n                \'reset_adapt_events_80pct\':_adaptation_time(reset_curve,\'A\'),\n            },\n            \'generation_current_domain\':generation,\n            \'resident_state\':{\n                \'rebuild_count\':int(system.rebuild_count),\n                \'events\':int(system.event_count),\n                \'slow_updates\':int(system.update_count),\n                \'changed_fraction\':float(system.changed_total/(max(1,system.event_count)*p1a.N)),\n            },\n            \'off_mask_max_abs\':float(_offmask(d,w_final)),\n            \'runtime_s\':float(time.time()-t0),\n        }\n\n        out=Path(args.out); out.mkdir(parents=True,exist_ok=True)\n        (out/\'P2E_FROM_ZERO_RESULTS.json\').write_text(json.dumps(result,indent=2),encoding=\'utf-8\')\n        np.savez_compressed(\n            out/\'P2E_FROM_ZERO_FINAL_STATE.npz\',\n            **{n:w for n,w in zip((\'WQ\',\'WK\',\'WV\',\'WO\',\'W1\',\'W2\',\'WR\',\'BR\',\'BO\',\'B2\'),w_final)},\n            H=system.Hstate,g=system.gstate,pq=system.pq,pk=system.pk,v=system.vcache,xcache=system.xcache,\n        )\n        _write_curve_csv(out/\'P2E_FROM_ZERO_CURVES.csv\',curves)\n\n        print(json.dumps(result,indent=2),flush=True)\n        return result\n    finally:\n        temp_modules.cleanup()\n\n\ndef main():\n    ap=argparse.ArgumentParser()\n    ap.add_argument(\'--out\',default=\'run_p2e_from_zero\')\n    ap.add_argument(\'--seed\',type=int,default=14123)\n    ap.add_argument(\'--threads\',type=int,default=4)\n    ap.add_argument(\'--readout-lr\',type=float,default=0.001)\n    ap.add_argument(\'--p2c-paths\',type=int,default=1200)\n    ap.add_argument(\'--phase-events\',type=int,default=2592)\n    ap.add_argument(\'--eval-every\',type=int,default=432)\n    ap.add_argument(\'--generate\',type=int,default=5000)\n    ap.add_argument(\'--quick\',action=\'store_true\')\n    run(ap.parse_args())\n\nif __name__==\'__main__\':\n    main()\n',
    'p3b_width_plasticity.py': "#!/usr/bin/env python3\nfrom __future__ import annotations\nimport argparse, importlib.util, json, math, os, platform, time, csv\nfrom pathlib import Path\nimport numpy as np\n\nHEAD_DIM = 12\nFEATURES_PER_HEAD = 24\nFF_MULT = 2\nVOCAB = 8\nMASK = VOCAB\nSPARSE_DENSITY = 0.25\nN_DEFAULT = 16\n# P1-F/P1-G/P2 frozen local rates; deliberately NOT rescaled with width.\nLRQ = 0.135\nLRK = 0.1125\nLRV = 0.039375\nLRO = 0.1125\nLR1 = 0.225\nLR2 = 0.225\nLRR = 0.001\nSIGQ = 0.05\nSIGK = 0.05\n\n\ndef load_snapshot(path: Path):\n    spec = importlib.util.spec_from_file_location('snn_p2e_snapshot', str(path))\n    mod = importlib.util.module_from_spec(spec)\n    assert spec.loader is not None\n    spec.loader.exec_module(mod)\n    td, M = mod._load_embedded_modules()\n    return mod, td, M\n\n\ndef build_baseline_lut(M):\n    p1f=M['p1f_full_block_msdl']; p1g=M['p1g_izh_reintegration']\n    d0=p1f.setup()\n    cal=p1g.calibrate_initial_interface(d0)\n    return p1g.build_luts(cal)\n\n\ndef tile_lut(lut0, H):\n    q0,k0,step=lut0\n    q=np.empty((H,q0.shape[1]),np.float64); k=np.empty((H,k0.shape[1]),np.float64)\n    for h in range(H):\n        q[h]=q0[h % q0.shape[0]]; k[h]=k0[h % k0.shape[0]]\n    return q,k,float(step)\n\n\ndef sparse_mask(rng, shape, density=SPARSE_DENSITY):\n    # Fixed per-row fan-in fraction, matching the structural sparsity intent.\n    out=np.zeros(shape,np.float64)\n    k=max(1,int(round(shape[1]*density)))\n    for i in range(shape[0]):\n        ix=rng.choice(shape[1],size=k,replace=False); out[i,ix]=1.0\n    return out\n\n\ndef init_case(D,N,seed,lut0,M):\n    assert D % HEAD_DIM == 0\n    H=D//HEAD_DIM; ff=FF_MULT*D\n    rng=np.random.default_rng(seed + 1009*D)\n    def W(o,i): return rng.normal(0.0,1.0/math.sqrt(i),size=(o,i)).astype(np.float64)\n    WQ,WK,WV=W(D,D),W(D,D),W(D,D)\n    maskO=sparse_mask(rng,(D,D)); mask1=sparse_mask(rng,(ff,D)); mask2=sparse_mask(rng,(D,ff))\n    WO=W(D,D)*maskO; W1=W(ff,D)*mask1; W2=W(D,ff)*mask2\n    WR=np.zeros((VOCAB,D+1),np.float64)\n    BR=np.zeros((D,VOCAB),np.float64); BO=np.zeros((D,D),np.float64); B2=np.zeros((ff,D),np.float64)\n    omega=rng.normal(size=(H,FEATURES_PER_HEAD,HEAD_DIM)).astype(np.float64)\n    omega/=np.linalg.norm(omega,axis=2,keepdims=True)+1e-12; omega*=math.sqrt(HEAD_DIM)\n    d={\n      'xn':np.zeros((1,N,D),np.float64),\n      'bq':np.zeros(D),'bk':np.zeros(D),'bv':np.zeros(D),'omega':omega,\n      'maskO':maskO,'bo':np.zeros(D),'gamma2':np.ones(D),'beta2':np.zeros(D),'eps2':1e-5,\n      'mask1':mask1,'b1':np.zeros(ff),'theta':np.zeros(ff),'mask2':mask2,'b2':np.zeros(D),\n      'lrq':LRQ,'lrk':LRK,'lrv':LRV,'lro':LRO,'lr1':LR1,'lr2':LR2,'sigq':SIGQ,'sigk':SIGK,\n    }\n    weights=(WQ,WK,WV,WO,W1,W2,WR,BR,BO,B2)\n    return d,weights,tile_lut(lut0,H),rng\n\n\ndef build_embeddings(D,N,seed):\n    rng=np.random.default_rng(seed+17*D)\n    tok=rng.normal(size=(VOCAB+1,D)); tok/=np.linalg.norm(tok,axis=1,keepdims=True)+1e-12;tok*=math.sqrt(D)*0.70\n    pos=rng.normal(size=(N,D)); pos/=np.linalg.norm(pos,axis=1,keepdims=True)+1e-12;pos*=math.sqrt(D)*0.35\n    return tok.astype(np.float64),pos.astype(np.float64)\n\n\ndef high_token(tok): return int(tok in (1,3,5,7))\n\n\ndef sample_sequence(N,rng):\n    s=np.empty(N,np.int64)\n    s[0]=1 if rng.random()<0.55 else 0\n    for t in range(1,N):\n        pair=((2,3),(4,5),(6,7))[(t-1)%3]\n        mode=int(s[0]==1)\n        branch=t%4\n        if branch==1:\n            cond=mode\n        elif branch==2:\n            cond=high_token(s[t-1])\n        elif branch==3:\n            cond=high_token(s[max(1,t-3)])\n        else:\n            cond=high_token(s[t-N//2]) if t>=N//2 else mode\n        p_hi=0.80 if cond else 0.20\n        s[t]=pair[1] if rng.random()<p_hi else pair[0]\n    return s\n\n\ndef make_sequences(N,n_events,seed):\n    rng=np.random.default_rng(seed)\n    nseq=(n_events+N-1)//N\n    return [sample_sequence(N,rng) for _ in range(nseq)]\n\n\ndef context_arrays(seq,t,tok,pos):\n    N=pos.shape[0]\n    arr=np.full(N,MASK,np.int64); arr[:t]=seq[:t]\n    x=tok[arr]+pos\n    mu=x.mean(axis=1,keepdims=True); var=np.mean((x-mu)**2,axis=1,keepdims=True)\n    xn=(x-mu)/np.sqrt(var+1e-5)\n    return xn.astype(np.float64),x[t].astype(np.float64)\n\n\ndef eff_rank(A):\n    if not np.any(A): return 0.0\n    s=np.linalg.svd(A,compute_uv=False)\n    sm=float(s.sum())\n    if sm<=1e-30:return 0.0\n    p=s/sm\n    return float(np.exp(-np.sum(p*np.log(p+1e-300))))\n\n\ndef stable_rank(A):\n    if not np.any(A): return 0.0\n    s=np.linalg.svd(A,compute_uv=False)\n    return float(np.sum(s*s)/(s[0]*s[0]+1e-300))\n\n\ndef part_ratio(x):\n    x=np.asarray(x,dtype=np.float64).ravel(); q=x*x\n    den=float(np.sum(q*q))\n    return 0.0 if den<=1e-300 else float(np.sum(q)**2/den)\n\n\ndef population_readouts(s,p1a):\n    def rd(v,u,E=True):\n        if E:return p1a.CV_E*(v-p1a.V0)+p1a.CU_E*(u-p1a.U0)\n        return p1a.CV_M*(v-p1a.V0)+p1a.CU_M*(u-p1a.U0)\n    return {\n      'R_E':rd(s.ver,s.uer,True),'R_M':rd(s.vmr,s.umr,False),\n      'Q_E':rd(s.veq,s.ueq,True),'Q_M':rd(s.vmq,s.umq,False),\n      'K_E':rd(s.vek,s.uek,True),'K_M':rd(s.vmk,s.umk,False),\n      'V_E':rd(s.vev,s.uev,True),'V_M':rd(s.vmv,s.umv,False),\n      'O_E':rd(s.veo,s.ueo,True),'O_M':rd(s.vmo,s.umo,False),\n      'W1_E':rd(s.ve1,s.ue1,True),'W1_M':rd(s.vm1,s.um1,False),\n      'W2_E':rd(s.ve2,s.ue2,True),'W2_M':rd(s.vm2,s.um2,False),\n    }\n\n\ndef summarize(vals):\n    a=np.asarray(vals,float)\n    return {'mean':float(a.mean()),'std':float(a.std()),'min':float(a.min()),'max':float(a.max())}\n\n\ndef fit_power(rows,key,xkey='D'):\n    x=np.array([r[xkey] for r in rows],float);y=np.array([r[key] for r in rows],float)\n    good=(x>0)&(y>0);x=x[good];y=y[good]\n    if len(x)<2:return {'exponent':float('nan'),'r2_log':float('nan')}\n    p=np.polyfit(np.log(x),np.log(y),1);pred=np.polyval(p,np.log(x));ssr=np.sum((np.log(y)-pred)**2);sst=np.sum((np.log(y)-np.log(y).mean())**2)\n    return {'exponent':float(p[0]),'prefactor':float(math.exp(p[1])),'r2_log':float(1-ssr/sst if sst>0 else 1)}\n\n\ndef run_width(D,N,n_events,seed,lut0,M,seqs,rank_stride=1):\n    p1a=M['p1a_msdl_token_generation'];p2d=M['p2d_system'];p2a=M['p2a_continuous_reciprocal']\n    d,weights,lut,rng=init_case(D,N,seed,lut0,M)\n    tok,pos=build_embeddings(D,N,seed+9000)\n    # Compile the generic Numba step path outside the measured interval. Use a throwaway\n    # system, then recreate the scientific state so the warm-up does not alter learning.\n    sw=p2d.ContinuousP2DSystem(d,lut,weights,seed+49999,LRR,4,p2a.MIRROR_LEAK)\n    _seqw=seqs[0]; _xnw,_xrw=context_arrays(_seqw,0,tok,pos); sw.step(_xnw,_xrw,0,int(_seqw[0]))\n    s=p2d.ContinuousP2DSystem(d,lut,weights,seed+50000,LRR,4,p2a.MIRROR_LEAK)\n    names=('WQ','WK','WV','WO','W1','W2','WR')\n    initW={n:np.array(w,copy=True) for n,w in zip(names,s.weight_tuple()[:7])}\n    prev={n:np.array(w,copy=True) for n,w in zip(names,s.weight_tuple()[:7])}\n    rank_rows=[]; pr_rows=[]; pop_traj={}; nll=[]; prev_updates=0\n    t0=time.perf_counter()\n    ev=0\n    for seq in seqs:\n        for t in range(N):\n            if ev>=n_events:break\n            xn,xres=context_arrays(seq,t,tok,pos)\n            out=s.step(xn,xres,t,int(seq[t]))\n            nll.append(-math.log(max(float(out.probs[int(seq[t])]),1e-12)))\n            ev+=1\n            if s.update_count>prev_updates:\n                prev_updates=s.update_count\n                cur={n:np.array(w,copy=True) for n,w in zip(names,s.weight_tuple()[:7])}\n                if (s.update_count % rank_stride)==0:\n                    rr={'update':int(s.update_count)}\n                    for n in names:\n                        dw=cur[n]-prev[n]\n                        rr[n+'_eff_rank']=eff_rank(dw);rr[n+'_stable_rank']=stable_rank(dw)\n                        rr[n+'_rel_step']=float(np.linalg.norm(dw)/(np.linalg.norm(prev[n])+1e-30))\n                    rank_rows.append(rr)\n                    pops=population_readouts(s,p1a); pr={'update':int(s.update_count)}\n                    for n,x in pops.items():\n                        pr[n+'_PR']=part_ratio(x);pr[n+'_PR_frac']=pr[n+'_PR']/max(1,x.size)\n                        pop_traj.setdefault(n,[]).append(np.asarray(x,dtype=np.float64).ravel().copy())\n                    pr_rows.append(pr)\n                prev=cur\n        if ev>=n_events:break\n    runtime=time.perf_counter()-t0\n    finalW={n:np.array(w,copy=True) for n,w in zip(names,s.weight_tuple()[:7])}\n    cumulative={}\n    for n in names:\n        dw=finalW[n]-initW[n]\n        cumulative[n+'_eff_rank']=eff_rank(dw);cumulative[n+'_stable_rank']=stable_rank(dw)\n        cumulative[n+'_rel_move']=float(np.linalg.norm(dw)/(np.linalg.norm(initW[n])+1e-30)) if np.linalg.norm(initW[n])>0 else float(np.linalg.norm(dw))\n        cumulative[n+'_shape']=list(dw.shape)\n        cumulative[n+'_eff_rank_frac']=cumulative[n+'_eff_rank']/min(dw.shape)\n    # active parameter count honors masks for sparse tail; WR all possible.\n    raw_params=sum(w.size for w in initW.values())\n    active_params=(initW['WQ'].size+initW['WK'].size+initW['WV'].size+\n                   int(d['maskO'].sum())+int(d['mask1'].sum())+int(d['mask2'].sum())+initW['WR'].size)\n    q=len(nll)//5\n    first=float(np.mean(nll[:q])) if q else float(np.mean(nll));last=float(np.mean(nll[-q:])) if q else float(np.mean(nll))\n    inst={}\n    for n in names:\n        vals=[r[n+'_eff_rank'] for r in rank_rows]; inst[n+'_eff_rank']=summarize(vals) if vals else {}\n        vals=[r[n+'_rel_step'] for r in rank_rows]; inst[n+'_rel_step']=summarize(vals) if vals else {}\n    prsum={}\n    if pr_rows:\n        for key in [k for k in pr_rows[0] if k.endswith('_PR_frac')]: prsum[key]=summarize([r[key] for r in pr_rows])\n    temporal={}\n    for key,vals in pop_traj.items():\n        X=np.stack(vals,axis=0)\n        X=X-X.mean(axis=0,keepdims=True)\n        er=eff_rank(X); sr=stable_rank(X); cap=max(1,min(X.shape[0]-1,X.shape[1]))\n        temporal[key]={'effective_rank':er,'stable_rank':sr,'rank_fraction_of_sample_cap':float(er/cap),'samples':int(X.shape[0]),'population_dim':int(X.shape[1])}\n    return {\n      'D':D,'N':N,'heads':D//HEAD_DIM,'head_dim':HEAD_DIM,'features_per_head':FEATURES_PER_HEAD,'ff':FF_MULT*D,\n      'events':ev,'slow_updates':int(s.update_count),'raw_forward_params':int(raw_params),'active_forward_synapses':int(active_params),\n      'runtime_s':float(runtime),'runtime_per_event_s':float(runtime/max(1,ev)),\n      'nll_first20':first,'nll_last20':last,'nll_improvement':first-last,\n      'cumulative':cumulative,'instantaneous':inst,'population_participation':prsum,'population_temporal_modes':temporal,\n      'rank_rows':rank_rows,'participation_rows':pr_rows,\n      'fixed_learning_rates':{'WQ':LRQ,'WK':LRK,'WV':LRV,'WO':LRO,'W1':LR1,'W2':LR2,'WR':LRR},\n      'resident_changed_fraction':float(s.changed_total/(max(1,s.event_count)*N)),\n      'rebuild_count':int(s.rebuild_count),\n    }\n\n\ndef main():\n    ap=argparse.ArgumentParser()\n    ap.add_argument('--Ds',default='24,48,96,192')\n    ap.add_argument('--N',type=int,default=N_DEFAULT)\n    ap.add_argument('--events',type=int,default=2700)\n    ap.add_argument('--seed',type=int,default=15101)\n    ap.add_argument('--rank-stride',type=int,default=1)\n    ap.add_argument('--snapshot',default='SNN_TRANSFORM_P2E_FROM_ZERO_20261015.py')\n    ap.add_argument('--lut-npz',default='')\n    ap.add_argument('--out',default='P3B_RESULTS')\n    args=ap.parse_args()\n    out=Path(args.out);out.mkdir(parents=True,exist_ok=True)\n    snapshot=Path(args.snapshot)\n    if not snapshot.exists(): snapshot=Path(__file__).resolve().parent/args.snapshot\n    snap,td,M=load_snapshot(snapshot)\n    try:\n        if args.lut_npz:\n            lp=Path(args.lut_npz)\n            if not lp.exists(): lp=Path(__file__).resolve().parent/args.lut_npz\n            zz=np.load(lp); lut0=(np.asarray(zz['q']),np.asarray(zz['k']),float(np.asarray(zz['step'])))\n            print(f'loaded frozen baseline Izh Q/K transfer LUT: {lp}',flush=True)\n        else:\n            print('building frozen baseline Izh Q/K transfer LUT...',flush=True)\n            lut0=build_baseline_lut(M)\n        Ds=[int(x) for x in args.Ds.split(',') if x.strip()]\n        seqs=make_sequences(args.N,args.events,args.seed+333)\n        rows=[]\n        for D in Ds:\n            print(f'P3-B D={D} N={args.N} events={args.events}',flush=True)\n            r=run_width(D,args.N,args.events,args.seed,lut0,M,seqs,args.rank_stride)\n            rows.append(r)\n            print(json.dumps({k:r[k] for k in ('D','raw_forward_params','active_forward_synapses','runtime_s','nll_first20','nll_last20','nll_improvement')},indent=2),flush=True)\n        flat=[]\n        for r in rows:\n            z={k:r[k] for k in ('D','N','heads','ff','events','slow_updates','raw_forward_params','active_forward_synapses','runtime_s','runtime_per_event_s','nll_first20','nll_last20','nll_improvement','resident_changed_fraction','rebuild_count')}\n            for n in ('WQ','WK','WV','WO','W1','W2','WR'):\n                z[n+'_cum_eff_rank']=r['cumulative'][n+'_eff_rank'];z[n+'_cum_eff_rank_frac']=r['cumulative'][n+'_eff_rank_frac'];z[n+'_rel_move']=r['cumulative'][n+'_rel_move']\n            flat.append(z)\n        fitkeys=['raw_forward_params','active_forward_synapses','runtime_per_event_s']+[n+'_cum_eff_rank' for n in ('WQ','WK','WV','WO','W1','W2','WR')]\n        fits={k:fit_power(flat,k) for k in fitkeys}\n        obj={\n          'stage':'P3-B width scaling and effective plastic dimensionality',\n          'scope':'fixed N; same local rates/timescales for all widths; current P2 local learning mechanisms; baseline calibrated reset-per-call Izh Q/K transfer LUT tiled across heads; no width-specific retuning',\n          'N':args.N,'Ds':Ds,'events_per_width':args.events,'seed':args.seed,\n          'rows':rows,'fits_vs_D':fits,\n          'environment':{'python':platform.python_version(),'platform':platform.platform(),'cpu_count':os.cpu_count()},\n        }\n        (out/'P3B_RESULTS.json').write_text(json.dumps(obj,indent=2),encoding='utf-8')\n        with open(out/'P3B_RESULTS.csv','w',newline='',encoding='utf-8') as f:\n            w=csv.DictWriter(f,fieldnames=list(flat[0].keys()));w.writeheader();w.writerows(flat)\n        # Long-form ranks/participation for audit.\n        ranklong=[];prlong=[]\n        for r in rows:\n            for x in r['rank_rows']:ranklong.append({'D':r['D'],**x})\n            for x in r['participation_rows']:prlong.append({'D':r['D'],**x})\n        if ranklong:\n            with open(out/'P3B_UPDATE_RANKS.csv','w',newline='',encoding='utf-8') as f:\n                w=csv.DictWriter(f,fieldnames=list(ranklong[0].keys()));w.writeheader();w.writerows(ranklong)\n        if prlong:\n            with open(out/'P3B_POPULATION_PARTICIPATION.csv','w',newline='',encoding='utf-8') as f:\n                w=csv.DictWriter(f,fieldnames=list(prlong[0].keys()));w.writeheader();w.writerows(prlong)\n        print('FITS',json.dumps(fits,indent=2),flush=True)\n    finally:\n        td.cleanup()\n\nif __name__=='__main__':main()\n",
    'p3c2b_factorised_ek.py': '#!/usr/bin/env python3\nfrom __future__ import annotations\nimport argparse, copy, csv, json, math, sys, time\nfrom pathlib import Path\nimport numpy as np\nHERE=Path(__file__).resolve().parent\nsys.path.insert(0,str(HERE))\nimport p3b_width_plasticity as p3b\n\n\ndef softmax(z):\n    z=np.asarray(z,float); e=np.exp(z-z.max()); return e/e.sum()\n\ndef summarize(vals):\n    a=np.asarray(vals,float); return {\'mean\':float(a.mean()),\'std\':float(a.std()),\'min\':float(a.min()),\'max\':float(a.max())}\n\ndef downstream_drive(d,a,target,BR,BO):\n    z=d[\'xres_cur\'] + d[\'bo\'] + d[\'WO\']@a\n    mu=z.mean(); inv=1.0/math.sqrt(float(np.mean((z-mu)**2))+d[\'eps2\'])\n    u=(z-mu)*inv*d[\'gamma2\']+d[\'beta2\']\n    h=np.maximum(0.0,d[\'W1\']@u+d[\'b1\']-d[\'theta\'])\n    y=z+d[\'W2\']@h+d[\'b2\']\n    rms=math.sqrt(float(np.mean(y*y)))+1e-8\n    rf=np.empty(y.size+1); rf[:-1]=0.5*y/rms; rf[-1]=0.5\n    probs=softmax(d[\'WR\']@rf)\n    err=-probs; err=err.copy(); err[int(target)]+=1.0\n    drive_z=BR@err; drive_a=BO@drive_z\n    return probs,drive_a\n\ndef project_kv(WK,bk,WV,bv,x,H,hd):\n    k=(WK@x+bk).reshape(H,hd)\n    v=(WV@x+bv).reshape(H,hd)\n    return k,v\n\ndef rotating_groups(N,R,phase):\n    if N%R!=0: raise ValueError(\'R must divide N\')\n    g=np.empty(N,np.int64)\n    if R==N:\n        g[:]=np.arange(N)\n    elif N==8 and R==2:\n        bit=phase%3\n        for n in range(N):g[n]=(n>>bit)&1\n    elif N==8 and R==4:\n        pairs=((0,1),(1,2),(0,2));b0,b1=pairs[phase%3]\n        for n in range(N):g[n]=((n>>b0)&1)+2*((n>>b1)&1)\n    else:\n        # balanced cyclic rotation; sequence-boundary remapping costs O(N) once per N events.\n        shift=phase%N\n        for n in range(N):g[n]=((n+shift)%N)%R\n    return g\n\ndef make_dirs(rng,R,H,hd):\n    # Rademacher directions, one D-dimensional K-output mode per collective eligibility population.\n    return np.where(rng.random((R,H,hd))<0.5,-1.0,1.0).astype(np.float64)\n\ndef token_pert_contrib(e4,k_h,v_h,xi_h,omega_h,sig):\n    kp=k_h+sig*xi_h; km=k_h-sig*xi_h\n    pk=e4.phi_k_vec(k_h,omega_h); pp=e4.phi_k_vec(kp,omega_h); pm=e4.phi_k_vec(km,omega_h)\n    dp=pp-pk; dm=pm-pk\n    return dp[:,None]*v_h[None,:], dp, dm[:,None]*v_h[None,:], dm\n\ndef build_eligibility_context(e4,d,WK0,xctx,groups,dirs,sig,norm_e=1.0):\n    N,D=xctx.shape;H=d[\'omega\'].shape[0];hd=D//H;R=dirs.shape[0];M=d[\'omega\'].shape[1];gcount=N//R\n    xgrp=np.zeros((R,D));Hp=np.zeros((R,H,M,hd));Gp=np.zeros((R,H,M));Hm=np.zeros_like(Hp);Gm=np.zeros_like(Gp)\n    kcache=np.zeros((H,N,hd));vcache=np.zeros_like(kcache)\n    for n in range(N):\n        k,v=project_kv(WK0,d[\'bk\'],d[\'WV\'],d[\'bv\'],xctx[n],H,hd); kcache[:,n]=k; vcache[:,n]=v\n        r=int(groups[n]); xgrp[r]+=xctx[n]/(gcount**norm_e)\n        for h in range(H):\n            hp,gp,hm,gm=token_pert_contrib(e4,k[h],v[h],dirs[r,h],d[\'omega\'][h],sig)\n            Hp[r,h]+=hp;Gp[r,h]+=gp;Hm[r,h]+=hm;Gm[r,h]+=gm\n    return xgrp,Hp,Gp,Hm,Gm,kcache,vcache\n\ndef update_eligibility_token(e4,d,WK0,n,oldx,newx,groups,dirs,sig,state,norm_e=1.0):\n    xgrp,Hp,Gp,Hm,Gm,kcache,vcache=state;H=d[\'omega\'].shape[0];hd=oldx.size//H;R=dirs.shape[0];gcount=oldx.shape[0]*0+len(groups)//R\n    r=int(groups[n]); xgrp[r]+=(newx-oldx)/(gcount**norm_e)\n    oldk,oldv=project_kv(WK0,d[\'bk\'],d[\'WV\'],d[\'bv\'],oldx,H,hd)\n    newk,newv=project_kv(WK0,d[\'bk\'],d[\'WV\'],d[\'bv\'],newx,H,hd)\n    for h in range(H):\n        hp,gp,hm,gm=token_pert_contrib(e4,oldk[h],oldv[h],dirs[r,h],d[\'omega\'][h],sig)\n        Hp[r,h]-=hp;Gp[r,h]-=gp;Hm[r,h]-=hm;Gm[r,h]-=gm\n        hp,gp,hm,gm=token_pert_contrib(e4,newk[h],newv[h],dirs[r,h],d[\'omega\'][h],sig)\n        Hp[r,h]+=hp;Gp[r,h]+=gp;Hm[r,h]+=hm;Gm[r,h]+=gm\n    kcache[:,n]=newk;vcache[:,n]=newv\n\ndef candidate_drive(e4,d,q,num,den,drive_a,dirs,state,sig,norm_m=1.0):\n    xgrp,Hp,Gp,Hm,Gm,_,_=state;R,H,hd=dirs.shape;D=H*hd;out=np.zeros((R,D));gcount=d[\'N\']//R\n    for r in range(R):\n        for h in range(H):\n            pq=e4.phi_q_vec(q[h],d[\'omega\'][h])\n            dgp=float(pq@Gp[r,h]); dgm=float(pq@Gm[r,h])\n            dHp=pq@Hp[r,h]; dHm=pq@Hm[r,h]\n            dp=max(1e-8,float(den[h]+dgp)); dm=max(1e-8,float(den[h]+dgm))\n            ap=(num[h]+dHp)/dp; am=(num[h]+dHm)/dm\n            scalar=float(drive_a[h*hd:(h+1)*hd]@(ap-am))/(2.0*sig*(gcount**norm_m))\n            out[r,h*hd:(h+1)*hd]=scalar*dirs[r,h]\n    return out\n\ndef sample_seq_index(sp,rng):\n    return int(rng.choice(len(sp),p=np.asarray(sp)/np.sum(sp)))\n\ndef train_stream(d,M,BR,BO,seed,n_updates,lrk,sigk,R=None,candidate=False,norm_e=1.0,norm_m=1.0,dir_schedule="sequence",group_schedule="sequence"):\n    p1a=M[\'p1a_msdl_token_generation\'];e4=M[\'p1e4_joint_qkv_msdl\']\n    N=d[\'N\'];D=d[\'D\'];H=d[\'H\'];hd=d[\'hd\'];R=N if R is None else int(R)\n    rng=np.random.default_rng(seed); np.random.seed(seed+12345)\n    WK=d[\'WK\'].copy(); WV=d[\'WV\'];WQ=d[\'WQ\']; total_events=n_updates*p1a.FORCE_STEPS\n    fixed_dirs=make_dirs(np.random.default_rng(seed+9876543),R,H,hd) if candidate and dir_schedule==\'fixed\' else None\n    phase_dirs={}\n    # K E/M populations. Candidate has R populations rather than N.\n    P=R if candidate else N\n    vek=np.full(P*D,p1a.V0);uek=np.full(P*D,p1a.U0);vmk=np.full(P*D,p1a.V0);umk=np.full(P*D,p1a.U0);zek=np.zeros(P*D);zmk=np.zeros(P*D)\n    accum=np.zeros_like(WK);accsteps=0;updates=0;online=[];seq_count=0;scan_tokens=0;write_tokens=0\n    current_seq=None;t=0;si=-1;WK0=WK.copy();elig=None;xcache=None;groups=None;dirs=None\n    t0=time.perf_counter()\n    for ev in range(total_events):\n        if current_seq is None or t>=N:\n            si=sample_seq_index(d[\'sp\'],rng);current_seq=d[\'st\'][si].copy();t=0;seq_count+=1\n            ci=int(d[\'sci\'][si,0]);xctx=d[\'xn\'][ci].copy();xcache=xctx.copy()\n            if candidate:\n                phase=(updates if group_schedule==\'slow\' else seq_count-1)\n                groups=rotating_groups(N,R,phase)\n                if dir_schedule==\'fixed\':\n                    dirs=fixed_dirs\n                elif dir_schedule==\'slow\':\n                    if updates not in phase_dirs: phase_dirs[updates]=make_dirs(np.random.default_rng(seed+777777+updates),R,H,hd)\n                    dirs=phase_dirs[updates]\n                else:\n                    dirs=make_dirs(rng,R,H,hd)\n                elig=build_eligibility_context(e4,d,WK0,xctx,groups,dirs,sigk,norm_e);scan_tokens+=N # one O(N) boundary rebuild\n        ci=int(d[\'sci\'][si,t]);target=int(d[\'st\'][si,t]);xn=d[\'xn\'][ci];d[\'xres_cur\']=d[\'xres\'][ci]\n        # Candidate forward still uses accepted fresh attention for a clean functional gate.\n        a,q,k,v,scores,num,den,alpha=e4.joint_attention_state(WQ,d[\'bq\'],WK0,d[\'bk\'],WV,d[\'bv\'],xn,t,d[\'omega\'])\n        probs,drive_a=downstream_drive(d,a,target,BR,BO);online.append(-math.log(max(float(probs[target]),1e-12)))\n        if candidate:\n            # Context t contains the newly observed token at t-1. Update EK only on that write.\n            if t>0:\n                n=t-1; old=xcache[n].copy();new=xn[n].copy()\n                if np.any(old!=new):\n                    update_eligibility_token(e4,d,WK0,n,old,new,groups,dirs,sigk,elig,norm_e);xcache[n]=new;write_tokens+=1\n            ein=elig[0].reshape(-1)\n            drive=candidate_drive(e4,d,q,num,den,drive_a,dirs,elig,sigk,norm_m).reshape(-1)\n            EK,_=p1a.fast_izh_step(vek,uek,ein,zek,p1a.G_E,p1a.CV_E,p1a.CU_E)\n            MK,_=p1a.fast_izh_step(vmk,umk,drive,zmk,p1a.G_M,p1a.CV_M,p1a.CU_M)\n            E2=EK.reshape(R,D);M2=MK.reshape(R,D)\n            accum += (M2.T@E2)/R\n            # mismatch read touches R modes, not N token keys\n            scan_tokens += R\n        else:\n            drive=np.zeros((N,D))\n            for h in range(H):\n                for n in range(N):\n                    xi=np.where(rng.random(hd)<0.5,-1.0,1.0)\n                    kp=k[h,n]+sigk*xi;km=k[h,n]-sigk*xi\n                    sp=e4.score_qk(q[h],kp,d[\'omega\'][h]);sm=e4.score_qk(q[h],km,d[\'omega\'][h]);s0=scores[h,n]\n                    dp=max(1e-8,float(den[h]+sp-s0));dm=max(1e-8,float(den[h]+sm-s0))\n                    ap=(num[h]+(sp-s0)*v[h,n])/dp;am=(num[h]+(sm-s0)*v[h,n])/dm\n                    sc=float(drive_a[h*hd:(h+1)*hd]@(ap-am))/(2.0*sigk)\n                    drive[n,h*hd:(h+1)*hd]=sc*xi\n            EK,_=p1a.fast_izh_step(vek,uek,xn.reshape(-1),zek,p1a.G_E,p1a.CV_E,p1a.CU_E)\n            MK,_=p1a.fast_izh_step(vmk,umk,drive.reshape(-1),zmk,p1a.G_M,p1a.CV_M,p1a.CU_M)\n            accum += (MK.reshape(N,D).T@EK.reshape(N,D))/N\n            scan_tokens += N\n        accsteps+=1;t+=1\n        if accsteps>=p1a.FORCE_STEPS:\n            WK += lrk*accum/accsteps; accum.fill(0.0);accsteps=0;updates+=1;WK0=WK.copy()\n    runtime=time.perf_counter()-t0\n    return WK,{\'runtime_s\':runtime,\'events\':total_events,\'runtime_per_event_s\':runtime/total_events,\'online_nll_first20\':float(np.mean(online[:max(1,len(online)//5)])),\'online_nll_last20\':float(np.mean(online[-max(1,len(online)//5):])),\'online_improvement\':float(np.mean(online[:max(1,len(online)//5)])-np.mean(online[-max(1,len(online)//5):])),\'token_equivalent_touches\':int(scan_tokens),\'touches_per_event\':float(scan_tokens/total_events),\'write_updates\':int(write_tokens),\'sequences\':seq_count}\n\ndef build_d(M):\n    e4=M[\'p1e4_joint_qkv_msdl\'];d=e4.setup();\n    d[\'N\']=d[\'xn\'].shape[1];d[\'D\']=d[\'WQ\'].shape[0];d[\'H\']=d[\'omega\'].shape[0];d[\'hd\']=d[\'D\']//d[\'H\']\n    return d\n\ndef eval_k(d,M,WK):\n    e4=M[\'p1e4_joint_qkv_msdl\'];return e4.evaluate(d,d[\'WQ\'],WK,d[\'WV\'])\n\ndef gen_k(d,M,WK,n,seed):\n    e4=M[\'p1e4_joint_qkv_msdl\'];p1b=M[\'p1b_internal_w2_msdl\'];s=e4.generation(d,d[\'WQ\'],WK,d[\'WV\'],n,seed);return p1b.generation_metrics(s,d[\'true_dist\'])\n\ndef main():\n    ap=argparse.ArgumentParser();ap.add_argument(\'--snapshot\',default=\'SNN_TRANSFORM_P2E_FROM_ZERO_20261015.py\');ap.add_argument(\'--updates\',type=int,default=300);ap.add_argument(\'--seeds\',default=\'8501,8513,8521\');ap.add_argument(\'--Rs\',default=\'2,4,8\');ap.add_argument(\'--generate\',type=int,default=3000);ap.add_argument(\'--lrk\',type=float,default=1.0);ap.add_argument(\'--sigk\',type=float,default=.05);ap.add_argument(\'--out\',default=\'P3C2_RESULTS\')\n    args=ap.parse_args();out=Path(args.out);out.mkdir(parents=True,exist_ok=True)\n    sp=Path(args.snapshot);sp=sp if sp.exists() else HERE/sp\n    snap,td,M=p3b.load_snapshot(sp)\n    try:\n        d=build_d(M);e4=M[\'p1e4_joint_qkv_msdl\'];p1c=M[\'p1c_deep_local_mismatch\'];e1=M[\'p1e1_value_msdl\']\n        seeds=[int(x) for x in args.seeds.split(\',\')];Rs=[int(x) for x in args.Rs.split(\',\')]\n        rows=[]\n        for seed in seeds:\n            BR,_,_=p1c.learn_feedback_BR_msdl(d[\'WR\'],e4.MIRROR_STEPS,e4.MIRROR_SIGMA,e4.MIRROR_ETA_BR,200000+seed)\n            BO,_,_=e1.learn_feedback_matrix_msdl(d[\'WO\'],e4.MIRROR_STEPS,e4.MIRROR_SIGMA,e4.MIRROR_ETA_BO,210000+seed)\n            print(\'seed\',seed,\'token baseline\',flush=True)\n            WK,prof=train_stream(d,M,BR,BO,seed,args.updates,args.lrk,args.sigk,None,False);met=eval_k(d,M,WK);gm=gen_k(d,M,WK,args.generate,600000+seed)\n            rows.append({\'seed\':seed,\'kind\':\'token_scan\',\'R\':d[\'N\'],\'nll\':met[\'expected_nll\'],\'js\':met[\'conditional_js\'],\'long_range_mae\':met[\'exact_long_range_branch_mae\'],\'gen_js\':gm[\'joint_js_with_invalid_bucket\'],\'gen_valid\':gm[\'valid_sequence_fraction\'],\'gen_lr_mae\':gm[\'long_range_branch_mae\'],\'WK_rel_move\':float(np.linalg.norm(WK-d[\'WK\'])/(np.linalg.norm(d[\'WK\'])+1e-30)),\'WK_eff_rank\':p3b.eff_rank(WK-d[\'WK\']),**prof})\n            for R in Rs:\n                print(\'seed\',seed,\'EK candidate R\',R,flush=True)\n                WK,prof=train_stream(d,M,BR,BO,seed,args.updates,args.lrk,args.sigk,R,True);met=eval_k(d,M,WK);gm=gen_k(d,M,WK,args.generate,700000+seed+R)\n                rows.append({\'seed\':seed,\'kind\':\'EK_write_state\',\'R\':R,\'nll\':met[\'expected_nll\'],\'js\':met[\'conditional_js\'],\'long_range_mae\':met[\'exact_long_range_branch_mae\'],\'gen_js\':gm[\'joint_js_with_invalid_bucket\'],\'gen_valid\':gm[\'valid_sequence_fraction\'],\'gen_lr_mae\':gm[\'long_range_branch_mae\'],\'WK_rel_move\':float(np.linalg.norm(WK-d[\'WK\'])/(np.linalg.norm(d[\'WK\'])+1e-30)),\'WK_eff_rank\':p3b.eff_rank(WK-d[\'WK\']),**prof})\n        agg={}\n        for kind,R in sorted(set((r[\'kind\'],r[\'R\']) for r in rows)):\n            rr=[x for x in rows if x[\'kind\']==kind and x[\'R\']==R];agg[f\'{kind}_R{R}\']={k:summarize([x[k] for x in rr]) for k in (\'nll\',\'js\',\'long_range_mae\',\'gen_js\',\'gen_valid\',\'gen_lr_mae\',\'WK_rel_move\',\'WK_eff_rank\',\'runtime_per_event_s\',\'touches_per_event\',\'online_improvement\')}\n        base=agg[f\'token_scan_R{d["N"]}\'];frozen=d[\'baseline\'][\'expected_nll\'];bgain=frozen-base[\'nll\'][\'mean\']\n        cand={}\n        for R in Rs:\n            a=agg[f\'EK_write_state_R{R}\'];gain=frozen-a[\'nll\'][\'mean\'];cand[str(R)]={\'nll_gain_retention\':float(gain/(bgain+1e-30)),\'runtime_reduction_vs_scan\':float(1-a[\'runtime_per_event_s\'][\'mean\']/base[\'runtime_per_event_s\'][\'mean\']),\'touch_reduction_vs_scan\':float(1-a[\'touches_per_event\'][\'mean\']/base[\'touches_per_event\'][\'mean\'])}\n        obj={\'stage\':\'P3-C2 upgraded EK write-state eligibility; K-only functional gate\',\'mechanism\':\'R persistent K eligibility populations cache current write-state input and +/- relation-write sufficient statistics; only changed token updates EK; current mismatch reads R modes without rescanning historical keys\',\'N\':d[\'N\'],\'D\':d[\'D\'],\'updates\':args.updates,\'events\':args.updates*M[\'p1a_msdl_token_generation\'].FORCE_STEPS,\'seeds\':seeds,\'Rs\':Rs,\'lrk\':args.lrk,\'sigk\':args.sigk,\'frozen\':d[\'baseline\'],\'rows\':rows,\'aggregate\':agg,\'candidate_vs_token\':cand}\n        (out/\'P3C2_RESULTS.json\').write_text(json.dumps(obj,indent=2))\n        with open(out/\'P3C2_RESULTS.csv\',\'w\',newline=\'\') as f:\n            w=csv.DictWriter(f,fieldnames=list(rows[0].keys()));w.writeheader();w.writerows(rows)\n        print(json.dumps({\'frozen_nll\':frozen,\'aggregate\':agg,\'candidate\':cand},indent=2))\n    finally:td.cleanup()\nif __name__==\'__main__\':main()\n',
    'p3d_joint_scaling.py': '#!/usr/bin/env python3\nfrom __future__ import annotations\nimport argparse, csv, json, math, time, importlib.util, sys\nfrom pathlib import Path\nimport numpy as np\n\nHERE=Path(__file__).resolve().parent\n# Reuse accepted helpers/snapshot loader only; scientific system below is explicit.\nP3B_DIR=HERE\nP3C2B_DIR=HERE\nsys.path[:0]=[str(P3B_DIR),str(P3C2B_DIR)]\nimport p3b_width_plasticity as p3b\nimport p3c2b_factorised_ek as c2b\n\nVOCAB=8; MASK=8; R_K=4; NORM_EXP=0.5\n\n\ndef support_pair(t:int):\n    if t==0: return (0,1)\n    return ((2,3),(4,5),(6,7))[(t-1)%3]\n\ndef hi(tok:int)->int:\n    return int(tok in (1,3,5,7))\n\ndef _block_indices(t:int):\n    # positions 1.. are repeated 7-position motifs; returns motif offset 1..7 and block start\n    off=((t-1)%7)+1; bs=t-off\n    return off,bs\n\ndef p_high(domain:str, prefix, t:int)->float:\n    if t==0:\n        return {\'A\':0.55,\'B\':0.50,\'C\':0.40}[domain]\n    m=int(prefix[0]==1)\n    off,bs=_block_indices(t)\n    def bit(pos): return hi(prefix[pos]) if pos < len(prefix) else 0\n    if domain==\'A\':\n        if off==1: return 0.75 if m else 0.20\n        if off==2: return 0.35 if m else 0.65\n        if off==3: return 0.20+0.60*bit(bs+1)\n        if off==4: return 0.20+0.60*bit(bs+2)\n        if off==5: return 0.25+0.50*m\n        if off==6: return 0.20+0.60*bit(bs+1)\n        return 0.20+0.60*bit(bs+3)\n    if domain==\'B\':\n        if off==1: return 0.25 if m else 0.80\n        if off==2: return 0.75 if m else 0.25\n        if off==3: return 0.20+0.60*bit(bs+2)\n        if off==4: return 0.75-0.50*bit(bs+1)\n        if off==5: return 0.70-0.40*m\n        if off==6: return 0.25+0.50*bit(bs+2)\n        return 0.20+0.60*bit(bs+4)\n    if domain==\'C\':\n        if off==1: return 0.80 if m else 0.30\n        if off==2: return 0.20 if m else 0.80\n        if off==3: return 0.80-0.60*bit(bs+1)\n        if off==4: return 0.20+0.60*bit(bs+3)\n        if off==5: return 0.20+0.60*bit(bs+2)\n        if off==6: return 0.75-0.50*m\n        return 0.20+0.60*bit(bs+1)\n    raise ValueError(domain)\n\ndef sample_sequence(domain,N,rng):\n    s=np.empty(N,np.int64)\n    for t in range(N):\n        p=p_high(domain,s[:t],t); lo,hh=support_pair(t)\n        s[t]=hh if rng.random()<p else lo\n    return s\n\ndef build_embeddings_from_p1(d0,N):\n    # Preserve the accepted N=8 embedding geometry. Positions >7 reuse the 7-step\n    # motif positions; this isolates context-length scaling from a new position learner.\n    tok=np.asarray(d0[\'tok\'],dtype=np.float64)\n    p0=np.asarray(d0[\'pos\'],dtype=np.float64)\n    D=tok.shape[1]; pos=np.empty((N,D),np.float64)\n    pos[0]=p0[0]\n    for t in range(1,N): pos[t]=p0[1+(t-1)%7]\n    return tok,pos\n\ndef context_arrays(seq,t,tok,pos):\n    N=len(seq); arr=np.full(N,MASK,np.int64); arr[:t]=seq[:t]\n    x=tok[arr]+pos\n    mu=x.mean(axis=1,keepdims=True); var=np.mean((x-mu)**2,axis=1,keepdims=True)\n    xn=(x-mu)/np.sqrt(var+1e-5)\n    return xn.astype(np.float64),x[t].astype(np.float64)\n\nclass ScalableSystem:\n    """P2 continuous 7-weight learner with P3 scalable credit path.\n\n    - resident H/g computation; O(N) only at natural sequence-boundary context rewrite\n    - resident Xphi state for exact V eligibility read without alpha@all_tokens\n    - Q credit reads H/g directly (no historical key scan)\n    - K write eligibility: fixed R_K collective populations, factorised 1/sqrt(g)\n    - all seven forward groups + reciprocal populations remain live\n    """\n    def __init__(self,d,lut,weights,seed,M,R=R_K,reciprocal_scale=1.0):\n        p2d=M[\'p2d_system\']; p2a=M[\'p2a_continuous_reciprocal\']; p1a=M[\'p1a_msdl_token_generation\']\n        self.Mmods=M; self.p1a=p1a; self.p2d=p2d; self.p1g=M[\'p1g_izh_reintegration\']\n        self.base=p2d.ContinuousP2DSystem(d,lut,weights,seed,0.001,4,p2a.MIRROR_LEAK)\n        # Alias all base state; methods below access through b for clarity.\n        b=self.base; self.R=int(R); self.seq_count=0; self.reciprocal_scale=float(reciprocal_scale)\n        if b.N%self.R: raise ValueError(\'R must divide N\')\n        self.gcount=b.N//self.R\n        # Replace token-wise K E/M populations by R collective populations.\n        D=b.D; P=self.R\n        b.vek=np.full(P*D,p1a.V0);b.uek=np.full(P*D,p1a.U0);b.vmk=np.full(P*D,p1a.V0);b.umk=np.full(P*D,p1a.U0);b.zek=np.zeros(P*D);b.zmk=np.zeros(P*D)\n        # V sufficient state: Xphi[h,m,c] = sum_n pk[h,n,m] x[n,c]\n        self.Xphi=np.zeros((b.H,b.Mfeat,b.D),np.float64)\n        # K eligibility sufficient state, allocated independent of N except token resident cache already in base.\n        self.groups=np.zeros(b.N,np.int64); self.dirs=np.ones((P,b.H,b.hd),np.float64)\n        self.xgrp=np.zeros((P,b.D),np.float64)\n        self.Hp=np.zeros((P,b.H,b.Mfeat,b.hd),np.float64); self.Gp=np.zeros((P,b.H,b.Mfeat),np.float64)\n        self.Hm=np.zeros_like(self.Hp); self.Gm=np.zeros_like(self.Gp)\n        self.kelig_ready=False\n        self.boundary_rebuild_tokens=0; self.event_local_writes=0\n        self.q_history_scans=0; self.k_history_scans=0; self.v_history_scans=0\n        self.rng=np.random.default_rng(seed+31337)\n    def __getattr__(self,name):\n        if name in (\'base\',\'Mmods\',\'p1a\',\'p2d\',\'p1g\'): raise AttributeError(name)\n        return getattr(self.base,name)\n    def weight_tuple(self): return self.base.weight_tuple()\n    def _phi_q(self,h,q): return self.p1g.phi_q_lut_vec(q,self.base.omega[h],self.base.qlut[h],self.base.lut_step)\n    def _phi_k(self,h,k): return self.p1g.phi_k_lut_vec(k,self.base.omega[h],self.base.klut[h],self.base.lut_step)\n    def _project(self,x):\n        b=self.base; qq=b.WQ@x+b.bq; kk=b.WK@x+b.bk; vv=b.WV@x+b.bv\n        return qq.reshape(b.H,b.hd),kk.reshape(b.H,b.hd),vv.reshape(b.H,b.hd)\n    def _token_rel_delta(self,h,k,v,xi):\n        b=self.base; pk=self._phi_k(h,k); pp=self._phi_k(h,k+b.sigk*xi); pm=self._phi_k(h,k-b.sigk*xi)\n        dp=pp-pk; dm=pm-pk\n        return dp[:,None]*v[None,:],dp,dm[:,None]*v[None,:],dm\n    def _new_groups_dirs(self):\n        b=self.base; self.groups=c2b.rotating_groups(b.N,self.R,self.seq_count)\n        self.dirs=c2b.make_dirs(self.rng,self.R,b.H,b.hd)\n    def _rebuild_resident_and_elig(self,xn):\n        b=self.base; self._new_groups_dirs(); self.seq_count+=1\n        b.Hstate.fill(0);b.gstate.fill(0);self.Xphi.fill(0);self.xgrp.fill(0);self.Hp.fill(0);self.Gp.fill(0);self.Hm.fill(0);self.Gm.fill(0)\n        norm=math.sqrt(self.gcount)\n        for n in range(b.N):\n            x=np.asarray(xn[n],float); q,k,v=self._project(x); b.xcache[n]=x\n            r=int(self.groups[n]); self.xgrp[r]+=x/norm\n            for h in range(b.H):\n                b.qraw[h,n]=q[h];b.kraw[h,n]=k[h];b.vcache[h,n]=v[h]\n                pq=self._phi_q(h,q[h]);pk=self._phi_k(h,k[h]);b.pq[h,n]=pq;b.pk[h,n]=pk\n                b.gstate[h]+=pk;b.Hstate[h]+=pk[:,None]*v[h][None,:];self.Xphi[h]+=pk[:,None]*x[None,:]\n                hp,gp,hm,gm=self._token_rel_delta(h,k[h],v[h],self.dirs[r,h])\n                self.Hp[r,h]+=hp;self.Gp[r,h]+=gp;self.Hm[r,h]+=hm;self.Gm[r,h]+=gm\n        b.initialized=1;b.rebuild_count+=1;b.changed_total+=b.N;self.boundary_rebuild_tokens+=b.N;self.kelig_ready=True\n    def _update_token(self,n,newx):\n        b=self.base; oldx=b.xcache[n].copy();\n        if np.array_equal(oldx,newx): return 0\n        r=int(self.groups[n]); norm=math.sqrt(self.gcount);self.xgrp[r]+=(newx-oldx)/norm\n        # remove old resident and old eligibility contribution\n        for h in range(b.H):\n            oldpk=b.pk[h,n].copy();oldv=b.vcache[h,n].copy();oldk=b.kraw[h,n].copy()\n            b.gstate[h]-=oldpk;b.Hstate[h]-=oldpk[:,None]*oldv[None,:];self.Xphi[h]-=oldpk[:,None]*oldx[None,:]\n            hp,gp,hm,gm=self._token_rel_delta(h,oldk,oldv,self.dirs[r,h]);self.Hp[r,h]-=hp;self.Gp[r,h]-=gp;self.Hm[r,h]-=hm;self.Gm[r,h]-=gm\n        q,k,v=self._project(newx)\n        for h in range(b.H):\n            pq=self._phi_q(h,q[h]);pk=self._phi_k(h,k[h])\n            b.qraw[h,n]=q[h];b.kraw[h,n]=k[h];b.vcache[h,n]=v[h];b.pq[h,n]=pq;b.pk[h,n]=pk\n            b.gstate[h]+=pk;b.Hstate[h]+=pk[:,None]*v[h][None,:];self.Xphi[h]+=pk[:,None]*newx[None,:]\n            hp,gp,hm,gm=self._token_rel_delta(h,k[h],v[h],self.dirs[r,h]);self.Hp[r,h]+=hp;self.Gp[r,h]+=gp;self.Hm[r,h]+=hm;self.Gm[r,h]+=gm\n        b.xcache[n]=newx;b.changed_total+=1;self.event_local_writes+=1;return 1\n    def _read(self,t):\n        b=self.base; a=np.empty(b.D);q=np.empty((b.H,b.hd));num=np.empty((b.H,b.hd));den=np.empty(b.H)\n        for h in range(b.H):\n            q[h]=b.qraw[h,t]; pq=b.pq[h,t]; dd=max(1e-8,float(pq@b.gstate[h]));den[h]=dd;nn=pq@b.Hstate[h];num[h]=nn;a[h*b.hd:(h+1)*b.hd]=nn/dd\n        return a,q,num,den\n    def _q_drive(self,q,drive_a):\n        b=self.base; out=np.zeros(b.D)\n        for h in range(b.H):\n            xi=np.where(self.rng.random(b.hd)<0.5,-1.0,1.0);pqp=self._phi_q(h,q[h]+b.sigq*xi);pqm=self._phi_q(h,q[h]-b.sigq*xi)\n            dp=max(1e-8,float(pqp@b.gstate[h]));dm=max(1e-8,float(pqm@b.gstate[h]));ap=(pqp@b.Hstate[h])/dp;am=(pqm@b.Hstate[h])/dm\n            sc=float(drive_a[h*b.hd:(h+1)*b.hd]@(ap-am))/(2*b.sigq);out[h*b.hd:(h+1)*b.hd]=sc*xi\n        return out\n    def _k_drive(self,q,num,den,drive_a):\n        b=self.base; out=np.zeros((self.R,b.D));norm=math.sqrt(self.gcount)\n        for r in range(self.R):\n            for h in range(b.H):\n                pq=self._phi_q(h,q[h]); dgp=float(pq@self.Gp[r,h]);dgm=float(pq@self.Gm[r,h]);dHp=pq@self.Hp[r,h];dHm=pq@self.Hm[r,h]\n                dp=max(1e-8,float(den[h]+dgp));dm=max(1e-8,float(den[h]+dgm));ap=(num[h]+dHp)/dp;am=(num[h]+dHm)/dm\n                sc=float(drive_a[h*b.hd:(h+1)*b.hd]@(ap-am))/(2*b.sigk*norm);out[r,h*b.hd:(h+1)*b.hd]=sc*self.dirs[r,h]\n        return out\n    def _v_input(self,t,den):\n        b=self.base; s=np.empty(b.H*b.D)\n        for h in range(b.H): s[h*b.D:(h+1)*b.D]=(b.pq[h,t]@self.Xphi[h])/max(1e-8,float(den[h]))\n        return s\n    def forward_only(self,xn,xres,t):\n        b=self.base\n        if t==0 or not b.initialized:self._rebuild_resident_and_elig(xn)\n        elif t>0:self._update_token(t-1,np.asarray(xn[t-1],float))\n        a,q,num,den=self._read(int(t));z=xres+b.bo+b.WO@a;mu=z.mean();inv=1.0/math.sqrt(float(np.mean((z-mu)**2))+b.eps2);u=(z-mu)*inv*b.gamma2+b.beta2;h=np.maximum(0,b.W1@u+b.b1-b.theta);y=z+b.W2@h+b.b2;rms=math.sqrt(float(np.mean(y*y)))+1e-8;rf=np.empty(b.D+1);rf[:b.D]=0.5*y/rms;rf[b.D]=0.5\n        return self.p1a.softmax_numba(b.WR@rf)\n    def step(self,xn,xres,t,observed_target):\n        b=self.base;p1a=self.p1a;p2d=self.p2d\n        # reciprocal slow populations remain continuously live\n        p2d.reciprocal_microsteps(b.BR,b.BO,b.B2,b.WR,b.WO,b.W2,b.vm_br,b.um_br,b.ve_br,b.ue_br,b.zm_br,b.ze_br,b.vm_bo,b.um_bo,b.ve_bo,b.ue_bo,b.zm_bo,b.ze_bo,b.vm_b2,b.um_b2,b.ve_b2,b.ue_b2,b.zm_b2,b.ze_b2,b.mirror_per_event,p2d.MIRROR_SIGMA,p2d.ETA_BR*self.reciprocal_scale,p2d.ETA_BO*self.reciprocal_scale,p2d.ETA_B2*self.reciprocal_scale,b.mirror_leak,True)\n        if t==0 or not b.initialized:self._rebuild_resident_and_elig(xn)\n        else:self._update_token(t-1,np.asarray(xn[t-1],float))\n        a,q,num,den=self._read(int(t))\n        z=xres+b.bo+b.WO@a;mu=z.mean();inv=1.0/math.sqrt(float(np.mean((z-mu)**2))+b.eps2);u=(z-mu)*inv*b.gamma2+b.beta2;h=np.maximum(0,b.W1@u+b.b1-b.theta);y=z+b.W2@h+b.b2;rms=math.sqrt(float(np.mean(y*y)))+1e-8;rfeat=np.empty(b.D+1);rfeat[:b.D]=0.5*y/rms;rfeat[b.D]=0.5\n        probs=p1a.softmax_numba(b.WR@rfeat);target=int(observed_target);err=-np.asarray(probs).copy();err[target]+=1.0;b.obs_nll_sum-=math.log(max(float(probs[target]),1e-12));b.obs_count+=1\n        ER,_=p1a.fast_izh_step(b.ver,b.uer,rfeat,b.zer,p1a.G_E,p1a.CV_E,p1a.CU_E);one=np.zeros(b.V);one[target]=1;MR,_=p1a.fast_izh_step(b.vmr,b.umr,one,probs,p1a.G_M,p1a.CV_M,p1a.CU_M);b.ar+=np.outer(MR,ER)\n        drive_y=b.BR@err;drive_h=b.B2@drive_y;drive_a=b.BO@drive_y\n        E2,_=p1a.fast_izh_step(b.ve2,b.ue2,h,b.ze2,p1a.G_E,p1a.CV_E,p1a.CU_E);M2,_=p1a.fast_izh_step(b.vm2,b.um2,drive_y,b.zm2,p1a.G_M,p1a.CV_M,p1a.CU_M);b.a2+=np.outer(M2,E2)*b.mask2\n        E1,_=p1a.fast_izh_step(b.ve1,b.ue1,u,b.ze1,p1a.G_E,p1a.CV_E,p1a.CU_E);M1,_=p1a.fast_izh_step(b.vm1,b.um1,drive_h,b.zm1,p1a.G_M,p1a.CV_M,p1a.CU_M);b.a1+=np.outer(M1,E1)*b.mask1\n        EO,_=p1a.fast_izh_step(b.veo,b.ueo,a,b.zeo,p1a.G_E,p1a.CV_E,p1a.CU_E);MO,_=p1a.fast_izh_step(b.vmo,b.umo,drive_y,b.zmo,p1a.G_M,p1a.CV_M,p1a.CU_M);b.ao+=np.outer(MO,EO)*b.maskO\n        # V eligibility from resident sufficient statistic, no alpha@all-token scan.\n        sinput=self._v_input(int(t),den);EV,_=p1a.fast_izh_step(b.vev,b.uev,sinput,b.zev,p1a.G_E,p1a.CV_E,p1a.CU_E);MV,_=p1a.fast_izh_step(b.vmv,b.umv,drive_a,b.zmv,p1a.G_M,p1a.CV_M,p1a.CU_M)\n        for rr in range(b.D):\n            hh=rr//b.hd;b.av[rr]+=MV[rr]*EV[hh*b.D:(hh+1)*b.D]\n        # K collective write eligibility, fixed R independent of N.\n        EK,_=p1a.fast_izh_step(b.vek,b.uek,self.xgrp.reshape(-1),b.zek,p1a.G_E,p1a.CV_E,p1a.CU_E);kd=self._k_drive(q,num,den,drive_a);MK,_=p1a.fast_izh_step(b.vmk,b.umk,kd.reshape(-1),b.zmk,p1a.G_M,p1a.CV_M,p1a.CU_M);b.ak+=(MK.reshape(self.R,b.D).T@EK.reshape(self.R,b.D))/self.R\n        # Q direct resident H/g read.\n        qd=self._q_drive(q,drive_a);EQ,_=p1a.fast_izh_step(b.veq,b.ueq,xn[t],b.zeq,p1a.G_E,p1a.CV_E,p1a.CU_E);MQ,_=p1a.fast_izh_step(b.vmq,b.umq,qd,b.zmq,p1a.G_M,p1a.CV_M,p1a.CU_M);b.aq+=np.outer(MQ,EQ)\n        b.event_count+=1;b.accum_steps+=1\n        if b.accum_steps>=p1a.FORCE_STEPS:b._apply_update()\n        return np.asarray(probs,float)\n\n\n\ndef fresh_readout_feature(d,lut,weights,xn,xres,t,p1g):\n    WQ,WK,WV,WO,W1,W2,WR,BR,BO,B2=weights\n    qlut,klut,step=lut\n    a=p1g.joint_attention_state_lut(WQ,d[\'bq\'],WK,d[\'bk\'],WV,d[\'bv\'],xn,int(t),d[\'omega\'],qlut,klut,step)[0]\n    z=xres+d[\'bo\']+WO@a;mu=z.mean();inv=1.0/math.sqrt(float(np.mean((z-mu)**2))+d[\'eps2\']);u=(z-mu)*inv*d[\'gamma2\']+d[\'beta2\'];hh=np.maximum(0,W1@u+d[\'b1\']-d[\'theta\']);y=z+W2@hh+d[\'b2\'];rms=math.sqrt(float(np.mean(y*y)))+1e-8\n    return np.r_[0.5*y/rms,0.5]\n\ndef train_readout_scaffold(d,lut,weights,tok,pos,N,seed,M,nctx=3000,npaths=8000,lr=0.6):\n    p1a=M[\'p1a_msdl_token_generation\'];p1g=M[\'p1g_izh_reintegration\'];rng=np.random.default_rng(seed+123456)\n    D=weights[0].shape[0];F=np.empty((nctx,D+1),np.float64);T=np.zeros((nctx,VOCAB),np.float64);masses=np.full(nctx,1.0/nctx)\n    for i in range(nctx):\n        seq=sample_sequence(\'A\',N,rng);t=int(rng.integers(N));xn,xr=p3b.context_arrays(seq,t,tok,pos);F[i]=fresh_readout_feature(d,lut,weights,xn,xr,t,p1g);T[i,int(seq[t])]=1.0\n    WR,_,_=p1a.train_msdl_readout(F,T,masses,npaths,lr,seed+654321,False)\n    z=F@WR.T;z-=z.max(axis=1,keepdims=True);P=np.exp(z);P/=P.sum(axis=1,keepdims=True);nll=float(-np.sum(T*np.log(P+1e-30))/nctx)\n    ww=list(weights);ww[6]=WR;return tuple(ww),{\'contexts\':nctx,\'paths\':npaths,\'train_nll\':nll}\n\ndef evaluate_conditioned(system,tok,pos,N,domain,seed,nseq=16):\n    rng=np.random.default_rng(seed);nll=[];validmass=[];d=system.base.d;lut=(system.base.qlut,system.base.klut,system.base.lut_step);s=ScalableSystem(d,lut,system.weight_tuple(),seed+900000,system.Mmods,system.R,system.reciprocal_scale)\n    for _ in range(nseq):\n        seq=sample_sequence(domain,N,rng)\n        for t in range(N):\n            xn,xr=p3b.context_arrays(seq,t,tok,pos);pp=s.forward_only(xn,xr,t);nll.append(-math.log(max(float(pp[seq[t]]),1e-12)));lo,hh=support_pair(t);validmass.append(float(pp[lo]+pp[hh]))\n    return {\'nll\':float(np.mean(nll)),\'support_mass\':float(np.mean(validmass))}\n\ndef generate(system,tok,pos,N,seed,nseq=100):\n    rng=np.random.default_rng(seed);d=system.base.d;lut=(system.base.qlut,system.base.klut,system.base.lut_step);s=ScalableSystem(d,lut,system.weight_tuple(),seed+910000,system.Mmods,system.R,system.reciprocal_scale);valid_seq=0;support=[]\n    for _ in range(nseq):\n        seq=np.zeros(N,np.int64);ok=True\n        for t in range(N):\n            xn,xr=p3b.context_arrays(seq,t,tok,pos);pp=s.forward_only(xn,xr,t);x=int(rng.choice(VOCAB,p=pp/pp.sum()));seq[t]=x;lo,hh=support_pair(t);good=x in (lo,hh);support.append(good);ok &= good\n        valid_seq+=int(ok)\n    return {\'valid_sequence_fraction\':valid_seq/nseq,\'token_support_rate\':float(np.mean(support))}\n\ndef run_case(N,D,seed,lut0,M,phase_events=2592,eval_seq=12,gen_seq=100,R=4,readout_ctx=3000,readout_paths=8000):\n    d,weights,lut,_=p3b.init_case(D,N,seed,lut0,M);rate_scale=math.sqrt(24.0/D)\n    for _k in (\'lrq\',\'lrk\',\'lrv\',\'lro\',\'lr1\',\'lr2\'): d[_k]*=rate_scale\n    tok,pos=p3b.build_embeddings(D,N,seed+9000)\n    weights,scaf=train_readout_scaffold(d,lut,weights,tok,pos,N,seed,M,readout_ctx,readout_paths,0.6)\n    # JIT warm-up outside measured interval; discard all warm state.\n    sw=ScalableSystem(d,lut,weights,seed+49999,M,R,rate_scale); wrng=np.random.default_rng(seed+4242); wseq=sample_sequence(\'A\',N,wrng); wxn,wxr=p3b.context_arrays(wseq,0,tok,pos); sw.step(wxn,wxr,0,int(wseq[0]))\n    s=ScalableSystem(d,lut,weights,seed+50000,M,R,rate_scale);snaps={};runtime=0.0\n    for pi,dom in enumerate((\'A\',\'B\',\'C\',\'A\')):\n        name=(\'A_initial\',\'B\',\'C\',\'A_return\')[pi];before=evaluate_conditioned(s,tok,pos,N,dom,seed+1000*pi,eval_seq);rng=np.random.default_rng(seed+10000+pi);vals=[];t0=time.perf_counter()\n        pev=0\n        while pev < phase_events:\n            seq=sample_sequence(dom,N,rng)\n            for t in range(N):\n                if pev>=phase_events: break\n                xn,xr=p3b.context_arrays(seq,t,tok,pos);pp=s.step(xn,xr,t,int(seq[t]));vals.append(-math.log(max(float(pp[seq[t]]),1e-12)));pev+=1\n        runtime+=time.perf_counter()-t0;after=evaluate_conditioned(s,tok,pos,N,dom,seed+2000*pi,eval_seq);snaps[name]={\'before\':before,\'after\':after,\'online_nll\':float(np.mean(vals))}\n    gen=generate(s,tok,pos,N,seed+777777,gen_seq);b=s.base\n    return {\'N\':N,\'D\':D,\'R_K\':R,\'seed\':seed,\'internal_lr_scale\':rate_scale,\'scaffold\':scaf,\'phase_events\':phase_events,\'events\':int(b.event_count),\'slow_updates\':int(b.update_count),\'runtime_s\':runtime,\'runtime_per_event_s\':runtime/max(1,b.event_count),\'snapshots\':snaps,\'generation_final_A\':gen,\'resident\':{\'boundary_rebuild_tokens\':s.boundary_rebuild_tokens,\'event_local_writes\':s.event_local_writes,\'history_scans\':s.q_history_scans+s.k_history_scans+s.v_history_scans},\'offmask\':float(max(np.max(np.abs(b.WO[b.maskO==0])) if np.any(b.maskO==0) else 0,np.max(np.abs(b.W1[b.mask1==0])) if np.any(b.mask1==0) else 0,np.max(np.abs(b.W2[b.mask2==0])) if np.any(b.mask2==0) else 0))}\n\ndef fit_power(rows,key,xkey=\'N\'):\n    x=np.array([r[xkey] for r in rows],float);y=np.array([r[key] for r in rows],float)\n    if len(x)<2:return {\'exponent\':float(\'nan\'),\'r2_log\':float(\'nan\')}\n    p=np.polyfit(np.log(x),np.log(y),1);pred=np.polyval(p,np.log(x));ss=np.sum((np.log(y)-pred)**2);sst=np.sum((np.log(y)-np.log(y).mean())**2);return {\'exponent\':float(p[0]),\'r2_log\':float(1-ss/sst if sst else 1)}\n\ndef main():\n    ap=argparse.ArgumentParser();ap.add_argument(\'--scales\',default=\'8x24,16x48,32x96\');ap.add_argument(\'--seeds\',default=\'16101,16123\');ap.add_argument(\'--phase-events\',type=int,default=2592);ap.add_argument(\'--eval-sequences\',type=int,default=12);ap.add_argument(\'--generate\',type=int,default=100);ap.add_argument(\'--R\',type=int,default=4);ap.add_argument(\'--readout-contexts\',type=int,default=3000);ap.add_argument(\'--readout-paths\',type=int,default=8000);ap.add_argument(\'--snapshot\',default=str(HERE/\'SNN_TRANSFORM_P2E_FROM_ZERO_20261015.py\'));ap.add_argument(\'--out\',default=\'/mnt/data/P3D_FULL_SCALING_20261015\');args=ap.parse_args()\n    out=Path(args.out);out.mkdir(parents=True,exist_ok=True);snap,td,M=p3b.load_snapshot(Path(args.snapshot))\n    try:\n        lut0=p3b.build_baseline_lut(M);scales=[tuple(map(int,x.split(\'x\'))) for x in args.scales.split(\',\')];seeds=[int(x) for x in args.seeds.split(\',\')];rows=[]\n        for seed in seeds:\n            for N,D in scales:\n                print(\'P3D joint\',seed,N,D,flush=True);r=run_case(N,D,seed,lut0,M,args.phase_events,args.eval_sequences,args.generate,args.R,args.readout_contexts,args.readout_paths);rows.append(r);print(json.dumps({\'seed\':seed,\'N\':N,\'D\':D,\'scaffold\':r[\'scaffold\'],\'runtime_per_event_s\':r[\'runtime_per_event_s\'],\'A0\':r[\'snapshots\'][\'A_initial\'][\'after\'][\'nll\'],\'B\':r[\'snapshots\'][\'B\'][\'after\'][\'nll\'],\'C\':r[\'snapshots\'][\'C\'][\'after\'][\'nll\'],\'AR\':r[\'snapshots\'][\'A_return\'][\'after\'][\'nll\'],\'gen\':r[\'generation_final_A\']},indent=2),flush=True)\n        agg=[]\n        for N,D in scales:\n            rr=[r for r in rows if r[\'N\']==N and r[\'D\']==D];rec={\'N\':N,\'D\':D,\'seeds\':len(rr)}\n            def sm(path):\n                z=[]\n                for r in rr:\n                    x=r\n                    for q in path:x=x[q]\n                    z.append(float(x))\n                return float(np.mean(z)),float(np.std(z))\n            for name,path in {\'runtime_per_event_s\':[\'runtime_per_event_s\'],\'scaffold_nll\':[\'scaffold\',\'train_nll\'],\'A_initial_nll\':[\'snapshots\',\'A_initial\',\'after\',\'nll\'],\'B_nll\':[\'snapshots\',\'B\',\'after\',\'nll\'],\'C_nll\':[\'snapshots\',\'C\',\'after\',\'nll\'],\'A_return_nll\':[\'snapshots\',\'A_return\',\'after\',\'nll\'],\'gen_valid\':[\'generation_final_A\',\'valid_sequence_fraction\'],\'gen_token_support\':[\'generation_final_A\',\'token_support_rate\']}.items():rec[name],rec[name+\'_std\']=sm(path)\n            for name in (\'A_initial\',\'B\',\'C\',\'A_return\'):\n                vals=[r[\'snapshots\'][name][\'before\'][\'nll\']-r[\'snapshots\'][name][\'after\'][\'nll\'] for r in rr];rec[name+\'_improvement\']=float(np.mean(vals));rec[name+\'_improvement_std\']=float(np.std(vals))\n            rec[\'history_scans\']=max(r[\'resident\'][\'history_scans\'] for r in rr);rec[\'offmask_max\']=max(r[\'offmask\'] for r in rr);agg.append(rec)\n        # joint-scale runtime exponent s where s=N/8=D/24\n        xx=np.array([a[\'N\']/8 for a in agg],float);yy=np.array([a[\'runtime_per_event_s\'] for a in agg],float);runtime_fit={\'joint_scale_exponent\':float(np.polyfit(np.log(xx),np.log(yy),1)[0])} if len(agg)>1 else {\'joint_scale_exponent\':float(\'nan\')}\n        gates={\'no_qkv_history_scans\':all(a[\'history_scans\']==0 for a in agg),\'sparse_masks_exact\':all(a[\'offmask_max\']==0 for a in agg),\'scaffold_supporting_nll_lt_1p2\':all(a[\'scaffold_nll\']<1.2 for a in agg),\'all_scales_adapt_B\':all(a[\'B_improvement\']>0 for a in agg),\'all_scales_adapt_C\':all(a[\'C_improvement\']>0 for a in agg),\'all_scales_recover_A\':all(a[\'A_return_improvement\']>0 for a in agg),\'generation_token_support_gt_0p90\':all(a[\'gen_token_support\']>0.90 for a in agg)}\n        obj={\'stage\':\'P3-D joint context/width full-system scaling\',\'scope\':\'from-random core initialization plus MSDL readout scaffold at each scale; full seven forward groups and reciprocal dynamics; fixed R_K=4; no Q/K/V historical scan; procedural A-B-C-A task\',\'scales\':scales,\'seeds\':seeds,\'rows\':rows,\'aggregate\':agg,\'runtime_fit\':runtime_fit,\'gates\':gates,\'pass\':bool(all(gates.values()))}\n        (out/\'P3D_RESULTS.json\').write_text(json.dumps(obj,indent=2),encoding=\'utf-8\')\n        with open(out/\'P3D_SUMMARY.csv\',\'w\',newline=\'\',encoding=\'utf-8\') as f:w=csv.DictWriter(f,fieldnames=list(agg[0].keys()));w.writeheader();w.writerows(agg)\n        print(\'FINAL\',json.dumps({\'pass\':obj[\'pass\'],\'runtime_fit\':runtime_fit,\'aggregate\':agg,\'gates\':gates},indent=2),flush=True)\n    finally:td.cleanup()\nif __name__==\'__main__\':main()\n'
}


def _write_runtime_tree():
    td = tempfile.TemporaryDirectory(prefix='snn_transform_p3_final_')
    root = Path(td.name)
    for name, text in _EMBEDDED_FILES.items():
        (root / name).write_text(text, encoding='utf-8')
    sys.path.insert(0, str(root))
    return td, root


def _load_runtime(root: Path):
    p3b = importlib.import_module('p3b_width_plasticity')
    c2b = importlib.import_module('p3c2b_factorised_ek')
    p3d = importlib.import_module('p3d_joint_scaling')
    snapshot_path = root / 'SNN_TRANSFORM_P2E_FROM_ZERO_20261015.py'
    snapshot, inner_td, M = p3b.load_snapshot(snapshot_path)
    lut0 = p3b.build_baseline_lut(M)
    return p3b, c2b, p3d, snapshot, inner_td, M, lut0


def _summary(vals):
    a = np.asarray(vals, dtype=float)
    return {
        'mean': float(a.mean()),
        'std': float(a.std()),
        'min': float(a.min()),
        'max': float(a.max()),
    }


def _parse_scales(text):
    out = []
    for part in text.split(','):
        n, d = part.lower().split('x')
        out.append((int(n), int(d)))
    return out


def _parse_ints(text):
    return [int(x.strip()) for x in text.split(',') if x.strip()]


def _raw_forward_params(D: int):
    ff = 2 * D
    V = 8
    # WQ, WK, WV, WO, W1, W2, WR. Count raw matrix entries, as in P3-B/P3-D.
    return int(3*D*D + D*D + ff*D + D*ff + V*(D+1))


def run_parity(p3d, p3b, M, lut0, scales=((8,24),(16,48),(32,96)), R=4):
    rows = []
    rng_master = np.random.default_rng(777)
    for N, D in scales:
        d, w, lut, _ = p3b.init_case(D, N, 18101, lut0, M)
        tok, pos = p3b.build_embeddings(D, N, 19101)
        s = p3d.ScalableSystem(d, lut, w, 20000+N, M, R, 1.0)
        rng = np.random.default_rng(int(rng_master.integers(1, 2**31-1)) + N)
        seq = p3d.sample_sequence('A', N, rng)
        target_t = min(N-1, max(1, N//2))
        for t in range(target_t+1):
            xn, xr = p3b.context_arrays(seq, t, tok, pos)
            s.forward_only(xn, xr, t)
        b = s.base
        a, q, num, den = s._read(target_t)

        # V sufficient-state parity: Xphi vs explicit alpha-weighted resident tokens.
        verr = 0.0
        vin = s._v_input(target_t, den)
        for h in range(b.H):
            scores = np.array([float(b.pq[h,target_t] @ b.pk[h,n]) for n in range(b.N)])
            direct = (scores[:,None] * b.xcache).sum(0) / max(1e-8, float(scores.sum()))
            verr = max(verr, float(np.max(np.abs(direct - vin[h*b.D:(h+1)*b.D]))))

        # Q sufficient-state parity: H/g vs explicit resident-token sum.
        qerr = 0.0
        for h in range(b.H):
            xi = np.where(rng.random(b.hd) < .5, -1.0, 1.0)
            for qq in (q[h] + b.sigq*xi, q[h] - b.sigq*xi):
                pq = s._phi_q(h, qq)
                ap = (pq @ b.Hstate[h]) / max(1e-8, float(pq @ b.gstate[h]))
                scores = np.array([float(pq @ b.pk[h,n]) for n in range(b.N)])
                direct = (scores[:,None] * b.vcache[h]).sum(0) / max(1e-8, float(scores.sum()))
                qerr = max(qerr, float(np.max(np.abs(ap-direct))))

        # K sufficient-state parity: cached collective write eligibility vs explicit group perturbation.
        kerr = 0.0
        for r in range(s.R):
            for h in range(b.H):
                pq = s._phi_q(h, q[h])
                ap = (num[h] + pq @ s.Hp[r,h]) / max(1e-8, float(den[h] + pq @ s.Gp[r,h]))
                am = (num[h] + pq @ s.Hm[r,h]) / max(1e-8, float(den[h] + pq @ s.Gm[r,h]))
                Hplus = b.Hstate[h].copy(); gplus = b.gstate[h].copy()
                Hminus = b.Hstate[h].copy(); gminus = b.gstate[h].copy()
                for n in range(b.N):
                    if int(s.groups[n]) != r:
                        continue
                    k = b.kraw[h,n]; v = b.vcache[h,n]; pk = b.pk[h,n]
                    pp = s._phi_k(h, k + b.sigk*s.dirs[r,h])
                    pm = s._phi_k(h, k - b.sigk*s.dirs[r,h])
                    dp = pp-pk; dm = pm-pk
                    Hplus += dp[:,None]*v; gplus += dp
                    Hminus += dm[:,None]*v; gminus += dm
                ap2 = (pq @ Hplus) / max(1e-8, float(pq @ gplus))
                am2 = (pq @ Hminus) / max(1e-8, float(pq @ gminus))
                kerr = max(kerr, float(np.max(np.abs(ap-ap2))), float(np.max(np.abs(am-am2))))
        rows.append({'N':N,'D':D,'V_Xphi_max_abs':verr,'Q_Hg_max_abs':qerr,'K_EK_max_abs':kerr})
    return {
        'stage':'P3-D sufficient-state exactness audit',
        'rows':rows,
        'max_any':max(max(r['V_Xphi_max_abs'], r['Q_Hg_max_abs'], r['K_EK_max_abs']) for r in rows),
    }


def run_n_scaling(p3d, p3b, M, lut0, Ns=(8,16,32,64), events=2048, D=24, R=4, seed=17101):
    rows = []
    for N in Ns:
        d, w, lut, _ = p3b.init_case(D, N, seed, lut0, M)
        tok, pos = p3b.build_embeddings(D, N, 19000+N)
        rng = np.random.default_rng(333+N)
        # JIT warm-up on disposable system.
        sw = p3d.ScalableSystem(d, lut, w, 777+N, M, R, 1.0)
        seq = p3d.sample_sequence('A', N, rng)
        xn, xr = p3b.context_arrays(seq, 0, tok, pos)
        sw.step(xn, xr, 0, int(seq[0]))
        # Scientific timing on fresh state.
        s = p3d.ScalableSystem(d, lut, w, 1777+N, M, R, 1.0)
        ev = 0
        t0 = time.perf_counter()
        while ev < events:
            seq = p3d.sample_sequence('A', N, rng)
            for t in range(N):
                if ev >= events:
                    break
                xn, xr = p3b.context_arrays(seq, t, tok, pos)
                s.step(xn, xr, t, int(seq[t]))
                ev += 1
        dt = time.perf_counter() - t0
        rows.append({
            'N':N,'D':D,'events':ev,'runtime_s':dt,'runtime_per_event_s':dt/ev,
            'boundary_tokens_per_event':s.boundary_rebuild_tokens/ev,
            'local_writes_per_event':s.event_local_writes/ev,
            'history_scans':s.q_history_scans+s.k_history_scans+s.v_history_scans,
        })
    x = np.asarray([r['N'] for r in rows], float)
    y = np.asarray([r['runtime_per_event_s'] for r in rows], float)
    exponent = float(np.polyfit(np.log(x), np.log(y), 1)[0]) if len(rows) > 1 else float('nan')
    return {
        'stage':'P3-D fixed-width sequence-length scaling',
        'D':D,'R_K':R,'rows':rows,
        'runtime_exponent_vs_N':exponent,
        'derived_sequence_exponent_vs_N':float(exponent+1.0),
    }


def run_full_scaling(p3d, p3b, M, lut0, scales, seeds, phase_events, eval_sequences,
                     generate_sequences, R, readout_contexts, readout_paths):
    rows = []
    for seed in seeds:
        for N, D in scales:
            print(f'[full] seed={seed} N={N} D={D}', flush=True)
            r = p3d.run_case(
                N, D, seed, lut0, M,
                phase_events=phase_events,
                eval_seq=eval_sequences,
                gen_seq=generate_sequences,
                R=R,
                readout_ctx=readout_contexts,
                readout_paths=readout_paths,
            )
            r['raw_forward_params'] = _raw_forward_params(D)
            rows.append(r)
            print(json.dumps({
                'seed':seed,'N':N,'D':D,
                'runtime_per_event_s':r['runtime_per_event_s'],
                'A':r['snapshots']['A_initial']['after']['nll'],
                'B':r['snapshots']['B']['after']['nll'],
                'C':r['snapshots']['C']['after']['nll'],
                'A_return':r['snapshots']['A_return']['after']['nll'],
                'generation':r['generation_final_A'],
            }, indent=2), flush=True)

    aggregate = []
    for N, D in scales:
        rr = [r for r in rows if r['N']==N and r['D']==D]
        rec = {'N':N,'D':D,'raw_forward_params':_raw_forward_params(D),
               'internal_lr_scale':math.sqrt(24.0/D),'seeds':[int(r['seed']) for r in rr]}
        metrics = {
            'runtime_per_event_s': lambda r:r['runtime_per_event_s'],
            'scaffold_train_nll': lambda r:r['scaffold']['train_nll'],
            'A_initial_nll': lambda r:r['snapshots']['A_initial']['after']['nll'],
            'B_nll': lambda r:r['snapshots']['B']['after']['nll'],
            'C_nll': lambda r:r['snapshots']['C']['after']['nll'],
            'A_return_nll': lambda r:r['snapshots']['A_return']['after']['nll'],
            'gen_valid': lambda r:r['generation_final_A']['valid_sequence_fraction'],
            'gen_token_support': lambda r:r['generation_final_A']['token_support_rate'],
        }
        for name, fn in metrics.items():
            s = _summary([fn(r) for r in rr])
            rec[name] = s['mean']; rec[name+'_std'] = s['std']; rec[name+'_min'] = s['min']; rec[name+'_max'] = s['max']
        for name in ('A_initial','B','C','A_return'):
            vals = [r['snapshots'][name]['before']['nll'] - r['snapshots'][name]['after']['nll'] for r in rr]
            s = _summary(vals)
            rec[name+'_improvement'] = s['mean']; rec[name+'_improvement_std'] = s['std']; rec[name+'_improvement_min'] = s['min']
        gaps = [r['snapshots']['A_return']['after']['nll'] - r['snapshots']['A_initial']['after']['nll'] for r in rr]
        rec['A_final_gap_vs_initial_A'] = float(np.mean(gaps))
        rec['A_final_gap_max_seed'] = float(np.max(gaps))
        rec['history_scans_max'] = int(max(r['resident']['history_scans'] for r in rr))
        rec['offmask_max'] = float(max(r['offmask'] for r in rr))
        aggregate.append(rec)

    s = np.asarray([a['N']/8.0 for a in aggregate],float)
    runtime = np.asarray([a['runtime_per_event_s'] for a in aggregate],float)
    params = np.asarray([a['raw_forward_params'] for a in aggregate],float)
    fits = {
        'joint_scale_runtime_exponent': float(np.polyfit(np.log(s),np.log(runtime),1)[0]) if len(s)>1 else float('nan'),
        'joint_scale_raw_parameter_exponent': float(np.polyfit(np.log(s),np.log(params),1)[0]) if len(s)>1 else float('nan'),
    }
    gates = {
        'no_history_scans': all(a['history_scans_max']==0 for a in aggregate),
        'sparse_masks_exact': all(a['offmask_max']==0.0 for a in aggregate),
        'scaffold_nll_lt_1p2_all_scales': all(a['scaffold_train_nll']<1.2 for a in aggregate),
        'mean_B_adaptation_positive_all_scales': all(a['B_improvement']>0.0 for a in aggregate),
        'mean_C_adaptation_positive_all_scales': all(a['C_improvement']>0.0 for a in aggregate),
        'token_support_gt_0p95_all_scales': all(a['gen_token_support']>0.95 for a in aggregate),
        'A_final_gap_mean_lt_0p06_all_scales': all(a['A_final_gap_vs_initial_A']<0.06 for a in aggregate),
        'A_final_gap_each_seed_lt_0p06_all_scales': all(a['A_final_gap_max_seed']<0.06 for a in aggregate),
    }
    return {
        'stage':'P3-D full-system joint context/width scaling',
        'from_zero':True,
        'from_zero_definition':'random internal core initialization + runtime-built neuronal Q/K LUT + MSDL readout scaffold; no saved learned checkpoint; then full seven-weight continual local learning',
        'scales':[list(x) for x in scales], 'seeds':seeds, 'R_K':R,
        'phase_events_per_domain':phase_events,
        'width_learning_normalization':'eta(D)=eta(24)*sqrt(24/D) for internal and reciprocal rates; WR online rate unscaled',
        'rows':rows, 'aggregate':aggregate, 'fits':fits, 'gates':gates,
        'functional_pass':bool(all(gates.values())),
    }


def _write_csv(path: Path, rows):
    if not rows:
        return
    keys = []
    for r in rows:
        for k in r:
            if k not in keys:
                keys.append(k)
    with path.open('w',newline='',encoding='utf-8') as f:
        w = csv.DictWriter(f,fieldnames=keys)
        w.writeheader()
        for r in rows:
            row = dict(r)
            for k,v in list(row.items()):
                if isinstance(v,(list,dict,tuple)):
                    row[k]=json.dumps(v,separators=(',',':'))
            w.writerow(row)


def main():
    ap = argparse.ArgumentParser(description='Standalone SNN-Transform/MSDL reproduction through P3-D')
    ap.add_argument('--task', choices=('all','parity','n-scaling','full'), default='all')
    ap.add_argument('--out', default='SNN_TRANSFORM_P3_FINAL_RUN')
    ap.add_argument('--scales', default='8x24,16x48,32x96')
    ap.add_argument('--seeds', default='16101,16123')
    ap.add_argument('--phase-events', type=int, default=2592)
    ap.add_argument('--eval-sequences', type=int, default=12)
    ap.add_argument('--generate', type=int, default=100)
    ap.add_argument('--R', type=int, default=4)
    ap.add_argument('--readout-contexts', type=int, default=3000)
    ap.add_argument('--readout-paths', type=int, default=8000)
    ap.add_argument('--n-profile', default='8,16,32,64')
    ap.add_argument('--profile-events', type=int, default=2048)
    ap.add_argument('--threads', type=int, default=4)
    ap.add_argument('--quick', action='store_true', help='smoke test only; overrides scientific exposure sizes and does not evaluate final gates')
    args = ap.parse_args()

    out = Path(args.out).resolve(); out.mkdir(parents=True, exist_ok=True)
    scales = _parse_scales(args.scales); seeds = _parse_ints(args.seeds); Ns = _parse_ints(args.n_profile)
    if args.quick:
        scales = [(8,24),(16,48)]
        seeds = [16101]
        Ns = [8,16]
        args.phase_events = min(args.phase_events, 54)
        args.eval_sequences = min(args.eval_sequences, 2)
        args.generate = min(args.generate, 5)
        args.readout_contexts = min(args.readout_contexts, 100)
        args.readout_paths = min(args.readout_paths, 100)
        args.profile_events = min(args.profile_events, 64)

    # Limit torch CPU threads without requiring direct use elsewhere.
    try:
        import torch
        torch.set_num_threads(args.threads)
    except Exception:
        pass

    runtime_td, root = _write_runtime_tree()
    inner_td = None
    try:
        p3b, c2b, p3d, snapshot, inner_td, M, lut0 = _load_runtime(root)
        config = {
            'task':args.task,'quick':args.quick,'scales':[list(x) for x in scales],'seeds':seeds,
            'phase_events':args.phase_events,'eval_sequences':args.eval_sequences,'generate':args.generate,
            'R_K':args.R,'readout_contexts':args.readout_contexts,'readout_paths':args.readout_paths,
            'n_profile':Ns,'profile_events':args.profile_events,'threads':args.threads,
            'checkpoint_free':True,
        }
        (out/'RUN_CONFIG.json').write_text(json.dumps(config,indent=2),encoding='utf-8')
        final = {'stage':'SNN-Transform/MSDL final standalone snapshot through P3-D','config':config}

        if args.task in ('all','parity'):
            print('[1] sufficient-state parity', flush=True)
            parity = run_parity(p3d,p3b,M,lut0,scales=scales,R=args.R)
            final['parity']=parity
            (out/'P3D_PARITY.json').write_text(json.dumps(parity,indent=2),encoding='utf-8')

        if args.task in ('all','n-scaling'):
            print('[2] fixed-width N scaling', flush=True)
            ns = run_n_scaling(p3d,p3b,M,lut0,Ns=Ns,events=args.profile_events,D=24,R=args.R)
            final['n_scaling']=ns
            (out/'P3D_N_SCALING.json').write_text(json.dumps(ns,indent=2),encoding='utf-8')
            _write_csv(out/'P3D_N_SCALING.csv',ns['rows'])

        if args.task in ('all','full'):
            print('[3] full learning / generation / joint scaling', flush=True)
            full = run_full_scaling(p3d,p3b,M,lut0,scales,seeds,args.phase_events,args.eval_sequences,args.generate,args.R,args.readout_contexts,args.readout_paths)
            final['full']=full
            (out/'P3D_FULL_RESULTS.json').write_text(json.dumps(full,indent=2),encoding='utf-8')
            _write_csv(out/'P3D_FULL_SUMMARY.csv',full['aggregate'])

        if not args.quick and args.task=='all':
            gates = {
                'exact_sufficient_state_parity_lt_1e-12': final['parity']['max_any'] < 1e-12,
                'fixed_D_learning_event_near_O1_in_N': abs(final['n_scaling']['runtime_exponent_vs_N']) < 0.15,
                **final['full']['gates'],
            }
            final['gates']=gates
            final['pass']=bool(all(gates.values()))
        elif args.quick:
            final['pass']=None
            final['note']='Quick mode is a smoke test only; final scientific gates are intentionally not evaluated.'
        else:
            final['pass']=None
            final['note']='Run --task all with canonical defaults for the complete frozen P3-D gate.'

        (out/'FINAL_RESULTS.json').write_text(json.dumps(final,indent=2),encoding='utf-8')
        print(json.dumps({'out':str(out),'pass':final.get('pass'),'task':args.task,'quick':args.quick},indent=2),flush=True)
    finally:
        if inner_td is not None:
            inner_td.cleanup()
        runtime_td.cleanup()


if __name__ == '__main__':
    main()
